INSERT INTO `problem_solution` (`problem_id`, `language`, `code`, `note`, `verified`) VALUES
(206, 'C', '#include <stdio.h>\n\nint climbStairs(int n) {\n    if (n <= 2) {\n        return n;\n    }\n    int a = 1;\n    int b = 2;\n    for (int i = 3; i <= n; i++) {\n        int c = a + b;\n        a = b;\n        b = c;\n    }\n    return b;\n}\n\nint main() {\n    int n;\n    scanf(\"%d\", &n);\n    printf(\"%d\\n\", climbStairs(n));\n    return 0;\n}', NULL, 1),
(206, 'CPP', '#include <iostream>\nusing namespace std;\n\nint climbStairs(int n) {\n    if (n <= 2) {\n        return n;\n    }\n    int a = 1;\n    int b = 2;\n    for (int i = 3; i <= n; i++) {\n        int c = a + b;\n        a = b;\n        b = c;\n    }\n    return b;\n}\n\nint main() {\n    int n;\n    cin >> n;\n    cout << climbStairs(n) << endl;\n    return 0;\n}', NULL, 1),
(206, 'JAVA', 'import java.util.Scanner;\n\npublic class Main {\n    public static void main(String[] args) {\n        Scanner sc = new Scanner(System.in);\n        int n = sc.nextInt();\n        if (n <= 2) {\n            System.out.println(n);\n            return;\n        }\n        int a = 1, b = 2;\n        for (int i = 3; i <= n; i++) {\n            int c = a + b;\n            a = b;\n            b = c;\n        }\n        System.out.println(b);\n    }\n}', NULL, 1),
(206, 'JAVASCRIPT', 'const readline = require(\'readline\');\n\nconst rl = readline.createInterface({\n    input: process.stdin,\n    output: process.stdout\n});\n\nrl.on(\'line\', (line) => {\n    const n = parseInt(line.trim(), 10);\n    console.log(climbStairs(n));\n    rl.close();\n});\n\nfunction climbStairs(n) {\n    if (n <= 2) {\n        return n;\n    }\n    let a = 1;\n    let b = 2;\n    for (let i = 3; i <= n; i++) {\n        const c = a + b;\n        a = b;\n        b = c;\n    }\n    return b;\n}', NULL, 1),
(206, 'PYTHON', 'n = int(input())\nif n <= 2:\n    print(n)\nelse:\n    a, b = 1, 2\n    for i in range(3, n + 1):\n        a, b = b, a + b\n    print(b)', NULL, 1),
(207, 'C', '#include <stdio.h>\n#include <string.h>\n#include <stdlib.h>\n\nint main(void) {\n    char text1[1005];\n    char text2[1005];\n    if (fgets(text1, sizeof(text1), stdin) == NULL) return 0;\n    if (fgets(text2, sizeof(text2), stdin) == NULL) return 0;\n\n    size_t len1 = strlen(text1);\n    size_t len2 = strlen(text2);\n    if (len1 > 0 && text1[len1 - 1] == \'\\n\') text1[--len1] = \'\\0\';\n    if (len2 > 0 && text2[len2 - 1] == \'\\n\') text2[--len2] = \'\\0\';\n\n    int m = (int)len1;\n    int n = (int)len2;\n\n    int *prev = (int *)calloc((size_t)n + 1, sizeof(int));\n    int *cur = (int *)calloc((size_t)n + 1, sizeof(int));\n    if (prev == NULL || cur == NULL) {\n        free(prev);\n        free(cur);\n        return 0;\n    }\n\n    for (int i = 1; i <= m; i++) {\n        for (int j = 1; j <= n; j++) {\n            if (text1[i - 1] == text2[j - 1]) {\n                cur[j] = prev[j - 1] + 1;\n            } else {\n                cur[j] = (prev[j] > cur[j - 1]) ? prev[j] : cur[j - 1];\n            }\n        }\n        int *tmp = prev;\n        prev = cur;\n        cur = tmp;\n        for (int j = 0; j <= n; j++) cur[j] = 0;\n    }\n\n    printf(\"%d\\n\", prev[n]);\n\n    free(prev);\n    free(cur);\n    return 0;\n}', NULL, 1),
(207, 'CPP', '#include <iostream>\n#include <string>\n#include <vector>\n#include <algorithm>\n\nint main() {\n    std::string text1, text2;\n    std::getline(std::cin, text1);\n    std::getline(std::cin, text2);\n    int m = text1.length();\n    int n = text2.length();\n    std::vector<std::vector<int>> dp(m + 1, std::vector<int>(n + 1, 0));\n    for (int i = 1; i <= m; i++) {\n        for (int j = 1; j <= n; j++) {\n            if (text1[i - 1] == text2[j - 1]) {\n                dp[i][j] = dp[i - 1][j - 1] + 1;\n            } else {\n                dp[i][j] = std::max(dp[i - 1][j], dp[i][j - 1]);\n            }\n        }\n    }\n    std::cout << dp[m][n] << std::endl;\n    return 0;\n}', NULL, 1),
(207, 'JAVA', 'import java.util.Scanner;\n\npublic class Main {\n    public static void main(String[] args) {\n        Scanner scanner = new Scanner(System.in);\n        String text1 = scanner.nextLine();\n        String text2 = scanner.nextLine();\n        int m = text1.length();\n        int n = text2.length();\n        int[][] dp = new int[m + 1][n + 1];\n        for (int i = 1; i <= m; i++) {\n            for (int j = 1; j <= n; j++) {\n                if (text1.charAt(i - 1) == text2.charAt(j - 1)) {\n                    dp[i][j] = dp[i - 1][j - 1] + 1;\n                } else {\n                    dp[i][j] = Math.max(dp[i - 1][j], dp[i][j - 1]);\n                }\n            }\n        }\n        System.out.println(dp[m][n]);\n    }\n}', NULL, 1),
(207, 'JAVASCRIPT', 'const readline = require(\'readline\');\n\nconst rl = readline.createInterface({\n    input: process.stdin,\n    output: process.stdout\n});\n\nlet lines = [];\nrl.on(\'line\', (line) => {\n    lines.push(line);\n    if (lines.length === 2) {\n        const text1 = lines[0];\n        const text2 = lines[1];\n        const m = text1.length;\n        const n = text2.length;\n        const dp = Array.from({ length: m + 1 }, () => new Array(n + 1).fill(0));\n        for (let i = 1; i <= m; i++) {\n            for (let j = 1; j <= n; j++) {\n                if (text1[i - 1] === text2[j - 1]) {\n                    dp[i][j] = dp[i - 1][j - 1] + 1;\n                } else {\n                    dp[i][j] = Math.max(dp[i - 1][j], dp[i][j - 1]);\n                }\n            }\n        }\n        console.log(dp[m][n]);\n        rl.close();\n    }\n});', NULL, 1),
(207, 'PYTHON', 'text1 = input()\ntext2 = input()\nm = len(text1)\nn = len(text2)\ndp = [[0] * (n + 1) for _ in range(m + 1)]\nfor i in range(1, m + 1):\n    for j in range(1, n + 1):\n        if text1[i - 1] == text2[j - 1]:\n            dp[i][j] = dp[i - 1][j - 1] + 1\n        else:\n            dp[i][j] = max(dp[i - 1][j], dp[i][j - 1])\nprint(dp[m][n])', NULL, 1),
(208, 'C', '#include <stdio.h>\n\nint main() {\n    int n, W;\n    scanf(\"%d %d\", &n, &W);\n    int values[n], weights[n];\n    for (int i = 0; i < n; i++) {\n        scanf(\"%d\", &values[i]);\n    }\n    for (int i = 0; i < n; i++) {\n        scanf(\"%d\", &weights[i]);\n    }\n    int dp[W + 1];\n    for (int i = 0; i <= W; i++) {\n        dp[i] = 0;\n    }\n    for (int i = 0; i < n; i++) {\n        for (int j = W; j >= weights[i]; j--) {\n            int candidate = dp[j - weights[i]] + values[i];\n            if (candidate > dp[j]) {\n                dp[j] = candidate;\n            }\n        }\n    }\n    printf(\"%d\\n\", dp[W]);\n    return 0;\n}', NULL, 1),
(208, 'CPP', '#include <iostream>\n#include <vector>\n#include <algorithm>\nusing namespace std;\n\nint main() {\n    int n, W;\n    cin >> n >> W;\n    vector<int> values(n), weights(n);\n    for (int i = 0; i < n; i++) {\n        cin >> values[i];\n    }\n    for (int i = 0; i < n; i++) {\n        cin >> weights[i];\n    }\n    vector<int> dp(W + 1, 0);\n    for (int i = 0; i < n; i++) {\n        for (int j = W; j >= weights[i]; j--) {\n            dp[j] = max(dp[j], dp[j - weights[i]] + values[i]);\n        }\n    }\n    cout << dp[W] << endl;\n    return 0;\n}', NULL, 1),
(208, 'JAVA', 'import java.util.Scanner;\n\npublic class Main {\n    public static void main(String[] args) {\n        Scanner sc = new Scanner(System.in);\n        if (!sc.hasNextInt()) return;\n        int n = sc.nextInt();\n        int W = sc.nextInt();\n        int[] values = new int[n];\n        int[] weights = new int[n];\n        for (int i = 0; i < n; i++) {\n            values[i] = sc.nextInt();\n        }\n        for (int i = 0; i < n; i++) {\n            weights[i] = sc.nextInt();\n        }\n        int[] dp = new int[W + 1];\n        for (int i = 0; i < n; i++) {\n            for (int j = W; j >= weights[i]; j--) {\n                dp[j] = Math.max(dp[j], dp[j - weights[i]] + values[i]);\n            }\n        }\n        System.out.println(dp[W]);\n    }\n}', NULL, 1),
(208, 'JAVASCRIPT', 'const readline = require(\'readline\');\n\nconst rl = readline.createInterface({\n    input: process.stdin,\n    output: process.stdout\n});\n\nlet lines = [];\nrl.on(\'line\', (line) => {\n    lines.push(line.trim());\n});\n\nrl.on(\'close\', () => {\n    const first = lines[0].split(/\\s+/).map(Number);\n    const n = first[0];\n    const W = first[1];\n    const values = lines[1].split(/\\s+/).map(Number);\n    const weights = lines[2].split(/\\s+/).map(Number);\n\n    const dp = new Array(W + 1).fill(0);\n    for (let i = 0; i < n; i++) {\n        for (let j = W; j >= weights[i]; j--) {\n            dp[j] = Math.max(dp[j], dp[j - weights[i]] + values[i]);\n        }\n    }\n    console.log(dp[W]);\n});', NULL, 1),
(208, 'PYTHON', 'import sys\n\ndef main():\n    data = sys.stdin.read().split()\n    if not data:\n        return\n    n = int(data[0])\n    W = int(data[1])\n    values = list(map(int, data[2:2+n]))\n    weights = list(map(int, data[2+n:2+2*n]))\n    dp = [0] * (W + 1)\n    for i in range(n):\n        for j in range(W, weights[i] - 1, -1):\n            dp[j] = max(dp[j], dp[j - weights[i]] + values[i])\n    print(dp[W])\n\nif __name__ == \"__main__\":\n    main()', NULL, 1),
(209, 'C', '#include <stdio.h>\n\nint main() {\n    int n;\n    scanf(\"%d\", &n);\n    int nums[n];\n    for (int i = 0; i < n; i++) {\n        scanf(\"%d\", &nums[i]);\n    }\n\n    int tails[n];\n    int len = 0;\n\n    for (int i = 0; i < n; i++) {\n        int x = nums[i];\n        int left = 0, right = len;\n        while (left < right) {\n            int mid = left + (right - left) / 2;\n            if (tails[mid] < x) {\n                left = mid + 1;\n            } else {\n                right = mid;\n            }\n        }\n        tails[left] = x;\n        if (left == len) {\n            len++;\n        }\n    }\n\n    printf(\"%d\\n\", len);\n    return 0;\n}', NULL, 1),
(209, 'CPP', '#include <iostream>\n#include <vector>\nusing namespace std;\n\nint main() {\n    int n;\n    cin >> n;\n    vector<int> nums(n);\n    for (int i = 0; i < n; i++) {\n        cin >> nums[i];\n    }\n\n    vector<int> tails(n);\n    int len = 0;\n\n    for (int x : nums) {\n        int left = 0, right = len;\n        while (left < right) {\n            int mid = left + (right - left) / 2;\n            if (tails[mid] < x) {\n                left = mid + 1;\n            } else {\n                right = mid;\n            }\n        }\n        tails[left] = x;\n        if (left == len) {\n            len++;\n        }\n    }\n\n    cout << len << endl;\n    return 0;\n}', NULL, 1),
(209, 'JAVA', 'import java.util.*;\n\npublic class Main {\n    public static void main(String[] args) {\n        Scanner sc = new Scanner(System.in);\n        int n = sc.nextInt();\n        int[] nums = new int[n];\n        for (int i = 0; i < n; i++) {\n            nums[i] = sc.nextInt();\n        }\n\n        int[] tails = new int[n];\n        int size = 0;\n        for (int x : nums) {\n            int l = 0, r = size;\n            while (l < r) {\n                int mid = l + (r - l) / 2;\n                if (tails[mid] < x) {\n                    l = mid + 1;\n                } else {\n                    r = mid;\n                }\n            }\n            tails[l] = x;\n            if (l == size) {\n                size++;\n            }\n        }\n\n        System.out.println(size);\n    }\n}', NULL, 1),
(209, 'JAVASCRIPT', 'const readline = require(\'readline\');\n\nconst rl = readline.createInterface({\n    input: process.stdin,\n    output: process.stdout\n});\n\nlet lines = [];\nrl.on(\'line\', (line) => {\n    lines.push(line.trim());\n});\n\nrl.on(\'close\', () => {\n    const n = parseInt(lines[0]);\n    const nums = lines[1].split(\' \').map(Number);\n\n    const tails = new Array(n);\n    let len = 0;\n\n    for (const x of nums) {\n        let left = 0, right = len;\n        while (left < right) {\n            const mid = left + Math.floor((right - left) / 2);\n            if (tails[mid] < x) {\n                left = mid + 1;\n            } else {\n                right = mid;\n            }\n        }\n        tails[left] = x;\n        if (left === len) {\n            len++;\n        }\n    }\n\n    console.log(len);\n});', NULL, 1),
(209, 'PYTHON', 'import sys\n\ndef main():\n    data = sys.stdin.read().strip().split()\n    if not data:\n        return\n    n = int(data[0])\n    nums = list(map(int, data[1:1+n]))\n\n    tails = [0] * n\n    length = 0\n\n    for x in nums:\n        left, right = 0, length\n        while left < right:\n            mid = left + (right - left) // 2\n            if tails[mid] < x:\n                left = mid + 1\n            else:\n                right = mid\n        tails[left] = x\n        if left == length:\n            length += 1\n\n    print(length)\n\nif __name__ == \"__main__\":\n    main()', NULL, 1),
(210, 'C', '#include <stdio.h>\n#include <limits.h>\n\nint main() {\n    int n;\n    scanf(\"%d\", &n);\n    int prices[n];\n    for (int i = 0; i < n; i++) {\n        scanf(\"%d\", &prices[i]);\n    }\n    int minPrice = INT_MAX;\n    int maxProfit = 0;\n    for (int i = 0; i < n; i++) {\n        int price = prices[i];\n        if (price < minPrice) {\n            minPrice = price;\n        } else if (price - minPrice > maxProfit) {\n            maxProfit = price - minPrice;\n        }\n    }\n    printf(\"%d\\n\", maxProfit);\n    return 0;\n}', NULL, 1),
(210, 'CPP', '#include <iostream>\n#include <vector>\n#include <climits>\nusing namespace std;\n\nint main() {\n    int n;\n    cin >> n;\n    vector<int> prices(n);\n    for (int i = 0; i < n; i++) {\n        cin >> prices[i];\n    }\n    int minPrice = INT_MAX;\n    int maxProfit = 0;\n    for (int price : prices) {\n        if (price < minPrice) {\n            minPrice = price;\n        } else if (price - minPrice > maxProfit) {\n            maxProfit = price - minPrice;\n        }\n    }\n    cout << maxProfit << endl;\n    return 0;\n}', NULL, 1),
(210, 'JAVA', 'import java.util.Scanner;\n\npublic class Main {\n    public static void main(String[] args) {\n        Scanner sc = new Scanner(System.in);\n        int n = sc.nextInt();\n        int[] prices = new int[n];\n        for (int i = 0; i < n; i++) {\n            prices[i] = sc.nextInt();\n        }\n        int minPrice = Integer.MAX_VALUE;\n        int maxProfit = 0;\n        for (int price : prices) {\n            if (price < minPrice) {\n                minPrice = price;\n            } else if (price - minPrice > maxProfit) {\n                maxProfit = price - minPrice;\n            }\n        }\n        System.out.println(maxProfit);\n    }\n}', NULL, 1),
(210, 'JAVASCRIPT', 'const readline = require(\'readline\');\n\nconst rl = readline.createInterface({\n    input: process.stdin,\n    output: process.stdout\n});\n\nlet lines = [];\nrl.on(\'line\', (line) => {\n    lines.push(line.trim());\n});\n\nrl.on(\'close\', () => {\n    const n = parseInt(lines[0]);\n    const prices = lines[1].split(\' \').map(Number);\n    let minPrice = Infinity;\n    let maxProfit = 0;\n    for (let price of prices) {\n        if (price < minPrice) {\n            minPrice = price;\n        } else if (price - minPrice > maxProfit) {\n            maxProfit = price - minPrice;\n        }\n    }\n    console.log(maxProfit);\n});', NULL, 1),
(210, 'PYTHON', 'n = int(input())\nprices = list(map(int, input().split()))\nmin_price = float(\'inf\')\nmax_profit = 0\nfor price in prices:\n    if price < min_price:\n        min_price = price\n    elif price - min_price > max_profit:\n        max_profit = price - min_price\nprint(max_profit)', NULL, 1),
(211, 'C', '#include <stdio.h>\n#include <stdlib.h>\n\nint main() {\n    int n;\n    scanf(\"%d\", &n);\n    int *nums = (int *)malloc(n * sizeof(int));\n    for (int i = 0; i < n; i++) {\n        scanf(\"%d\", &nums[i]);\n    }\n    int target;\n    scanf(\"%d\", &target);\n\n    int left = 0, right = n - 1;\n    int result = -1;\n    while (left <= right) {\n        int mid = left + (right - left) / 2;\n        if (nums[mid] == target) {\n            result = mid;\n            break;\n        } else if (nums[mid] < target) {\n            left = mid + 1;\n        } else {\n            right = mid - 1;\n        }\n    }\n\n    printf(\"%d\\n\", result);\n    free(nums);\n    return 0;\n}', NULL, 1),
(211, 'CPP', '#include <iostream>\n#include <vector>\nusing namespace std;\n\nint main() {\n    int n;\n    cin >> n;\n    vector<int> nums(n);\n    for (int i = 0; i < n; i++) {\n        cin >> nums[i];\n    }\n    int target;\n    cin >> target;\n\n    int left = 0, right = n - 1;\n    int result = -1;\n    while (left <= right) {\n        int mid = left + (right - left) / 2;\n        if (nums[mid] == target) {\n            result = mid;\n            break;\n        } else if (nums[mid] < target) {\n            left = mid + 1;\n        } else {\n            right = mid - 1;\n        }\n    }\n\n    cout << result << endl;\n    return 0;\n}', NULL, 1),
(211, 'JAVA', 'import java.util.Scanner;\n\npublic class Main {\n    public static void main(String[] args) {\n        Scanner sc = new Scanner(System.in);\n        int n = sc.nextInt();\n        int[] nums = new int[n];\n        for (int i = 0; i < n; i++) {\n            nums[i] = sc.nextInt();\n        }\n        int target = sc.nextInt();\n\n        int left = 0, right = n - 1;\n        int ans = -1;\n        while (left <= right) {\n            int mid = left + (right - left) / 2;\n            if (nums[mid] == target) {\n                ans = mid;\n                break;\n            } else if (nums[mid] < target) {\n                left = mid + 1;\n            } else {\n                right = mid - 1;\n            }\n        }\n        System.out.println(ans);\n    }\n}', NULL, 1),
(211, 'JAVASCRIPT', 'const readline = require(\'readline\');\n\nconst rl = readline.createInterface({\n    input: process.stdin,\n    output: process.stdout\n});\n\nlet lines = [];\nrl.on(\'line\', (line) => {\n    lines.push(line.trim());\n});\n\nrl.on(\'close\', () => {\n    const n = parseInt(lines[0]);\n    const nums = lines[1].split(\' \').map(Number);\n    const target = parseInt(lines[2]);\n\n    let left = 0, right = n - 1;\n    let result = -1;\n    while (left <= right) {\n        const mid = left + Math.floor((right - left) / 2);\n        if (nums[mid] === target) {\n            result = mid;\n            break;\n        } else if (nums[mid] < target) {\n            left = mid + 1;\n        } else {\n            right = mid - 1;\n        }\n    }\n\n    console.log(result);\n});', NULL, 1),
(211, 'PYTHON', 'n = int(input())\nnums = list(map(int, input().split()))\ntarget = int(input())\n\nleft, right = 0, n - 1\nresult = -1\nwhile left <= right:\n    mid = left + (right - left) // 2\n    if nums[mid] == target:\n        result = mid\n        break\n    elif nums[mid] < target:\n        left = mid + 1\n    else:\n        right = mid - 1\n\nprint(result)', NULL, 1),
(212, 'C', '#include <stdio.h>\n\nint main() {\n    int n, target;\n    scanf(\"%d %d\", &n, &target);\n    int nums[n];\n    for (int i = 0; i < n; i++) {\n        scanf(\"%d\", &nums[i]);\n    }\n    int left = 0, right = n - 1;\n    while (left <= right) {\n        int mid = left + (right - left) / 2;\n        if (nums[mid] == target) {\n            printf(\"%d\\n\", mid);\n            return 0;\n        } else if (nums[mid] < target) {\n            left = mid + 1;\n        } else {\n            right = mid - 1;\n        }\n    }\n    printf(\"%d\\n\", left);\n    return 0;\n}', NULL, 1),
(212, 'CPP', '#include <iostream>\n#include <vector>\nusing namespace std;\n\nint main() {\n    int n, target;\n    cin >> n >> target;\n    vector<int> nums(n);\n    for (int i = 0; i < n; i++) {\n        cin >> nums[i];\n    }\n    int left = 0, right = n - 1;\n    while (left <= right) {\n        int mid = left + (right - left) / 2;\n        if (nums[mid] == target) {\n            cout << mid << endl;\n            return 0;\n        } else if (nums[mid] < target) {\n            left = mid + 1;\n        } else {\n            right = mid - 1;\n        }\n    }\n    cout << left << endl;\n    return 0;\n}', NULL, 1),
(212, 'JAVA', 'import java.util.Scanner;\n\npublic class Main {\n    public static void main(String[] args) {\n        Scanner sc = new Scanner(System.in);\n        int n = sc.nextInt();\n        int target = sc.nextInt();\n        int[] nums = new int[n];\n        for (int i = 0; i < n; i++) {\n            nums[i] = sc.nextInt();\n        }\n        int left = 0, right = n - 1;\n        while (left <= right) {\n            int mid = left + (right - left) / 2;\n            if (nums[mid] == target) {\n                System.out.println(mid);\n                return;\n            } else if (nums[mid] < target) {\n                left = mid + 1;\n            } else {\n                right = mid - 1;\n            }\n        }\n        System.out.println(left);\n    }\n}', NULL, 1),
(212, 'JAVASCRIPT', 'const readline = require(\'readline\');\n\nconst rl = readline.createInterface({\n    input: process.stdin,\n    output: process.stdout\n});\n\nlet lines = [];\nrl.on(\'line\', (line) => {\n    lines.push(line.trim());\n    if (lines.length === 2) {\n        const [n, target] = lines[0].split(\' \').map(Number);\n        const nums = lines[1].split(\' \').map(Number);\n        let left = 0, right = n - 1;\n        while (left <= right) {\n            const mid = left + Math.floor((right - left) / 2);\n            if (nums[mid] === target) {\n                console.log(mid);\n                rl.close();\n                return;\n            } else if (nums[mid] < target) {\n                left = mid + 1;\n            } else {\n                right = mid - 1;\n            }\n        }\n        console.log(left);\n        rl.close();\n    }\n});', NULL, 1),
(212, 'PYTHON', 'n, target = map(int, input().split())\nnums = list(map(int, input().split()))\n\nleft, right = 0, n - 1\nwhile left <= right:\n    mid = left + (right - left) // 2\n    if nums[mid] == target:\n        print(mid)\n        break\n    elif nums[mid] < target:\n        left = mid + 1\n    else:\n        right = mid - 1\nelse:\n    print(left)', NULL, 1),
(213, 'C', '#include <stdio.h>\n#include <stdlib.h>\n\nint findFirst(int nums[], int n, int target) {\n    int left = 0, right = n - 1;\n    int ans = -1;\n    while (left <= right) {\n        int mid = left + (right - left) / 2;\n        if (nums[mid] >= target) {\n            if (nums[mid] == target) ans = mid;\n            right = mid - 1;\n        } else {\n            left = mid + 1;\n        }\n    }\n    return ans;\n}\n\nint findLast(int nums[], int n, int target) {\n    int left = 0, right = n - 1;\n    int ans = -1;\n    while (left <= right) {\n        int mid = left + (right - left) / 2;\n        if (nums[mid] <= target) {\n            if (nums[mid] == target) ans = mid;\n            left = mid + 1;\n        } else {\n            right = mid - 1;\n        }\n    }\n    return ans;\n}\n\nint main() {\n    int n;\n    scanf(\"%d\", &n);\n    int *nums = (int *)malloc(n * sizeof(int));\n    for (int i = 0; i < n; i++) {\n        scanf(\"%d\", &nums[i]);\n    }\n    int target;\n    scanf(\"%d\", &target);\n\n    int left = findFirst(nums, n, target);\n    int right = findLast(nums, n, target);\n\n    printf(\"[%d,%d]\\n\", left, right);\n\n    free(nums);\n    return 0;\n}', NULL, 1),
(213, 'CPP', '#include <iostream>\n#include <vector>\nusing namespace std;\n\nint findFirst(const vector<int>& nums, int target) {\n    int left = 0, right = nums.size() - 1;\n    int ans = -1;\n    while (left <= right) {\n        int mid = left + (right - left) / 2;\n        if (nums[mid] >= target) {\n            if (nums[mid] == target) ans = mid;\n            right = mid - 1;\n        } else {\n            left = mid + 1;\n        }\n    }\n    return ans;\n}\n\nint findLast(const vector<int>& nums, int target) {\n    int left = 0, right = nums.size() - 1;\n    int ans = -1;\n    while (left <= right) {\n        int mid = left + (right - left) / 2;\n        if (nums[mid] <= target) {\n            if (nums[mid] == target) ans = mid;\n            left = mid + 1;\n        } else {\n            right = mid - 1;\n        }\n    }\n    return ans;\n}\n\nint main() {\n    int n;\n    cin >> n;\n    vector<int> nums(n);\n    for (int i = 0; i < n; i++) {\n        cin >> nums[i];\n    }\n    int target;\n    cin >> target;\n\n    int left = findFirst(nums, target);\n    int right = findLast(nums, target);\n\n    cout << \"[\" << left << \",\" << right << \"]\" << endl;\n    return 0;\n}', NULL, 1),
(213, 'JAVA', 'import java.util.Scanner;\n\npublic class Main {\n    public static void main(String[] args) {\n        Scanner sc = new Scanner(System.in);\n        int n = sc.nextInt();\n        int[] nums = new int[n];\n        for (int i = 0; i < n; i++) {\n            nums[i] = sc.nextInt();\n        }\n        int target = sc.nextInt();\n\n        int left = findFirst(nums, target);\n        int right = findLast(nums, target);\n\n        System.out.println(\"[\" + left + \",\" + right + \"]\");\n    }\n\n    private static int findFirst(int[] nums, int target) {\n        int left = 0, right = nums.length - 1;\n        while (left <= right) {\n            int mid = left + (right - left) / 2;\n            if (nums[mid] >= target) {\n                right = mid - 1;\n            } else {\n                left = mid + 1;\n            }\n        }\n        if (left < nums.length && nums[left] == target) {\n            return left;\n        }\n        return -1;\n    }\n\n    private static int findLast(int[] nums, int target) {\n        int left = 0, right = nums.length - 1;\n        while (left <= right) {\n            int mid = left + (right - left) / 2;\n            if (nums[mid] <= target) {\n                left = mid + 1;\n            } else {\n                right = mid - 1;\n            }\n        }\n        if (right >= 0 && nums[right] == target) {\n            return right;\n        }\n        return -1;\n    }\n}', NULL, 1),
(213, 'JAVASCRIPT', 'const readline = require(\'readline\');\n\nconst rl = readline.createInterface({\n    input: process.stdin,\n    output: process.stdout\n});\n\nlet lines = [];\nrl.on(\'line\', (line) => {\n    lines.push(line.trim());\n});\n\nrl.on(\'close\', () => {\n    const n = parseInt(lines[0]);\n    const nums = lines[1].split(\' \').map(Number);\n    const target = parseInt(lines[2]);\n\n    const left = findFirst(nums, target);\n    const right = findLast(nums, target);\n\n    console.log(`[${left},${right}]`);\n});\n\nfunction findFirst(nums, target) {\n    let left = 0, right = nums.length - 1;\n    let ans = -1;\n    while (left <= right) {\n        const mid = left + Math.floor((right - left) / 2);\n        if (nums[mid] >= target) {\n            if (nums[mid] === target) ans = mid;\n            right = mid - 1;\n        } else {\n            left = mid + 1;\n        }\n    }\n    return ans;\n}\n\nfunction findLast(nums, target) {\n    let left = 0, right = nums.length - 1;\n    let ans = -1;\n    while (left <= right) {\n        const mid = left + Math.floor((right - left) / 2);\n        if (nums[mid] <= target) {\n            if (nums[mid] === target) ans = mid;\n            left = mid + 1;\n        } else {\n            right = mid - 1;\n        }\n    }\n    return ans;\n}', NULL, 1),
(213, 'PYTHON', 'import sys\n\ndef find_first(nums, target):\n    left, right = 0, len(nums) - 1\n    ans = -1\n    while left <= right:\n        mid = left + (right - left) // 2\n        if nums[mid] >= target:\n            if nums[mid] == target:\n                ans = mid\n            right = mid - 1\n        else:\n            left = mid + 1\n    return ans\n\ndef find_last(nums, target):\n    left, right = 0, len(nums) - 1\n    ans = -1\n    while left <= right:\n        mid = left + (right - left) // 2\n        if nums[mid] <= target:\n            if nums[mid] == target:\n                ans = mid\n            left = mid + 1\n        else:\n            right = mid - 1\n    return ans\n\ndef main():\n    data = sys.stdin.read().strip().split()\n    if not data:\n        return\n    n = int(data[0])\n    nums = list(map(int, data[1:1 + n]))\n    target = int(data[1 + n])\n    left = find_first(nums, target)\n    right = find_last(nums, target)\n    print(f\"[{left},{right}]\")\n\nif __name__ == \"__main__\":\n    main()', NULL, 1),
(214, 'C', '#include <stdio.h>\n\nint search(int nums[], int n, int target) {\n    int left = 0, right = n - 1;\n    while (left <= right) {\n        int mid = left + (right - left) / 2;\n        if (nums[mid] == target) {\n            return mid;\n        }\n        if (nums[left] <= nums[mid]) {\n            if (target >= nums[left] && target < nums[mid]) {\n                right = mid - 1;\n            } else {\n                left = mid + 1;\n            }\n        } else {\n            if (target > nums[mid] && target <= nums[right]) {\n                left = mid + 1;\n            } else {\n                right = mid - 1;\n            }\n        }\n    }\n    return -1;\n}\n\nint main() {\n    int n;\n    scanf(\"%d\", &n);\n    int nums[n];\n    for (int i = 0; i < n; i++) {\n        scanf(\"%d\", &nums[i]);\n    }\n    int target;\n    scanf(\"%d\", &target);\n    printf(\"%d\\n\", search(nums, n, target));\n    return 0;\n}', NULL, 1),
(214, 'CPP', '#include <iostream>\n#include <vector>\nusing namespace std;\n\nint search(vector<int>& nums, int target) {\n    int left = 0, right = nums.size() - 1;\n    while (left <= right) {\n        int mid = left + (right - left) / 2;\n        if (nums[mid] == target) {\n            return mid;\n        }\n        if (nums[left] <= nums[mid]) {\n            if (target >= nums[left] && target < nums[mid]) {\n                right = mid - 1;\n            } else {\n                left = mid + 1;\n            }\n        } else {\n            if (target > nums[mid] && target <= nums[right]) {\n                left = mid + 1;\n            } else {\n                right = mid - 1;\n            }\n        }\n    }\n    return -1;\n}\n\nint main() {\n    int n;\n    cin >> n;\n    vector<int> nums(n);\n    for (int i = 0; i < n; i++) {\n        cin >> nums[i];\n    }\n    int target;\n    cin >> target;\n    cout << search(nums, target) << endl;\n    return 0;\n}', NULL, 1),
(214, 'JAVA', 'import java.util.Scanner;\n\npublic class Main {\n    public static void main(String[] args) {\n        Scanner sc = new Scanner(System.in);\n        int n = sc.nextInt();\n        int[] nums = new int[n];\n        for (int i = 0; i < n; i++) {\n            nums[i] = sc.nextInt();\n        }\n        int target = sc.nextInt();\n        System.out.println(search(nums, target));\n    }\n\n    public static int search(int[] nums, int target) {\n        int left = 0, right = nums.length - 1;\n        while (left <= right) {\n            int mid = left + (right - left) / 2;\n            if (nums[mid] == target) {\n                return mid;\n            }\n            if (nums[left] <= nums[mid]) {\n                if (target >= nums[left] && target < nums[mid]) {\n                    right = mid - 1;\n                } else {\n                    left = mid + 1;\n                }\n            } else {\n                if (target > nums[mid] && target <= nums[right]) {\n                    left = mid + 1;\n                } else {\n                    right = mid - 1;\n                }\n            }\n        }\n        return -1;\n    }\n}', NULL, 1),
(214, 'JAVASCRIPT', 'const readline = require(\'readline\');\n\nconst rl = readline.createInterface({\n    input: process.stdin,\n    output: process.stdout\n});\n\nlet lines = [];\nrl.on(\'line\', (line) => {\n    lines.push(line.trim());\n});\n\nrl.on(\'close\', () => {\n    const n = parseInt(lines[0]);\n    const nums = lines[1].split(\' \').map(Number);\n    const target = parseInt(lines[2]);\n    console.log(search(nums, target));\n});\n\nfunction search(nums, target) {\n    let left = 0, right = nums.length - 1;\n    while (left <= right) {\n        let mid = left + Math.floor((right - left) / 2);\n        if (nums[mid] === target) {\n            return mid;\n        }\n        if (nums[left] <= nums[mid]) {\n            if (target >= nums[left] && target < nums[mid]) {\n                right = mid - 1;\n            } else {\n                left = mid + 1;\n            }\n        } else {\n            if (target > nums[mid] && target <= nums[right]) {\n                left = mid + 1;\n            } else {\n                right = mid - 1;\n            }\n        }\n    }\n    return -1;\n}', NULL, 1),
(214, 'PYTHON', 'import sys\n\ndef search(nums, target):\n    left, right = 0, len(nums) - 1\n    while left <= right:\n        mid = left + (right - left) // 2\n        if nums[mid] == target:\n            return mid\n        if nums[left] <= nums[mid]:\n            if nums[left] <= target < nums[mid]:\n                right = mid - 1\n            else:\n                left = mid + 1\n        else:\n            if nums[mid] < target <= nums[right]:\n                left = mid + 1\n            else:\n                right = mid - 1\n    return -1\n\ndef main():\n    data = sys.stdin.read().strip().split()\n    if not data:\n        return\n    n = int(data[0])\n    nums = list(map(int, data[1:1 + n]))\n    target = int(data[1 + n])\n    print(search(nums, target))\n\nif __name__ == \"__main__\":\n    main()', NULL, 1),
(215, 'C', '#include <stdio.h>\n\nint mySqrt(int x) {\n    if (x == 0) return 0;\n    int left = 1, right = x;\n    while (left <= right) {\n        int mid = left + (right - left) / 2;\n        if (mid <= x / mid) {\n            left = mid + 1;\n        } else {\n            right = mid - 1;\n        }\n    }\n    return right;\n}\n\nint main() {\n    int x;\n    scanf(\"%d\", &x);\n    printf(\"%d\\n\", mySqrt(x));\n    return 0;\n}', NULL, 1),
(215, 'CPP', '#include <iostream>\nusing namespace std;\n\nint mySqrt(int x) {\n    if (x == 0) return 0;\n    int left = 1, right = x;\n    while (left <= right) {\n        int mid = left + (right - left) / 2;\n        if (mid <= x / mid) {\n            left = mid + 1;\n        } else {\n            right = mid - 1;\n        }\n    }\n    return right;\n}\n\nint main() {\n    int x;\n    cin >> x;\n    cout << mySqrt(x) << endl;\n    return 0;\n}', NULL, 1),
(215, 'JAVA', 'import java.util.Scanner;\n\npublic class Main {\n    public static void main(String[] args) {\n        Scanner sc = new Scanner(System.in);\n        int x = sc.nextInt();\n        System.out.println(mySqrt(x));\n    }\n\n    public static int mySqrt(int x) {\n        if (x == 0) return 0;\n        int left = 1, right = x, ans = 0;\n        while (left <= right) {\n            int mid = left + (right - left) / 2;\n            if (mid <= x / mid) {\n                ans = mid;\n                left = mid + 1;\n            } else {\n                right = mid - 1;\n            }\n        }\n        return ans;\n    }\n}', NULL, 1),
(215, 'JAVASCRIPT', 'const readline = require(\'readline\');\n\nconst rl = readline.createInterface({\n    input: process.stdin,\n    output: process.stdout\n});\n\nrl.on(\'line\', (line) => {\n    const x = parseInt(line.trim(), 10);\n    console.log(mySqrt(x));\n    rl.close();\n});\n\nfunction mySqrt(x) {\n    if (x === 0) return 0;\n    let left = 1, right = x;\n    while (left <= right) {\n        let mid = left + Math.floor((right - left) / 2);\n        if (mid <= Math.floor(x / mid)) {\n            left = mid + 1;\n        } else {\n            right = mid - 1;\n        }\n    }\n    return right;\n}', NULL, 1),
(215, 'PYTHON', 'import sys\n\ndef mySqrt(x):\n    if x == 0:\n        return 0\n    left, right = 1, x\n    while left <= right:\n        mid = left + (right - left) // 2\n        if mid <= x // mid:\n            left = mid + 1\n        else:\n            right = mid - 1\n    return right\n\ndef main():\n    data = sys.stdin.read().strip().split()\n    if not data:\n        return\n    x = int(data[0])\n    print(mySqrt(x))\n\nif __name__ == \"__main__\":\n    main()', NULL, 1),
(216, 'C', '#include <stdio.h>\n#include <stdlib.h>\n\nint cmp(const void *a, const void *b) {\n    return (*(int *)a - *(int *)b);\n}\n\nint main() {\n    int gn, sn;\n    scanf(\"%d %d\", &gn, &sn);\n    int *g = (int *)malloc(gn * sizeof(int));\n    int *s = (int *)malloc(sn * sizeof(int));\n    for (int i = 0; i < gn; i++) {\n        scanf(\"%d\", &g[i]);\n    }\n    for (int i = 0; i < sn; i++) {\n        scanf(\"%d\", &s[i]);\n    }\n    qsort(g, gn, sizeof(int), cmp);\n    qsort(s, sn, sizeof(int), cmp);\n    int i = 0, j = 0;\n    while (i < gn && j < sn) {\n        if (s[j] >= g[i]) {\n            i++;\n        }\n        j++;\n    }\n    printf(\"%d\\n\", i);\n    free(g);\n    free(s);\n    return 0;\n}', NULL, 1),
(216, 'CPP', '#include <iostream>\n#include <vector>\n#include <algorithm>\nusing namespace std;\n\nint main() {\n    int gn, sn;\n    cin >> gn >> sn;\n    vector<int> g(gn), s(sn);\n    for (int i = 0; i < gn; i++) {\n        cin >> g[i];\n    }\n    for (int i = 0; i < sn; i++) {\n        cin >> s[i];\n    }\n    sort(g.begin(), g.end());\n    sort(s.begin(), s.end());\n    int i = 0, j = 0;\n    while (i < gn && j < sn) {\n        if (s[j] >= g[i]) {\n            i++;\n        }\n        j++;\n    }\n    cout << i << endl;\n    return 0;\n}', NULL, 1),
(216, 'JAVA', 'import java.util.Arrays;\nimport java.util.Scanner;\n\npublic class Main {\n    public static void main(String[] args) {\n        Scanner sc = new Scanner(System.in);\n        if (!sc.hasNextInt()) return;\n        int gn = sc.nextInt();\n        int sn = sc.nextInt();\n        int[] g = new int[gn];\n        int[] s = new int[sn];\n        for (int i = 0; i < gn; i++) g[i] = sc.nextInt();\n        for (int i = 0; i < sn; i++) s[i] = sc.nextInt();\n        Arrays.sort(g);\n        Arrays.sort(s);\n        int i = 0, j = 0, count = 0;\n        while (i < gn && j < sn) {\n            if (s[j] >= g[i]) {\n                count++;\n                i++;\n                j++;\n            } else {\n                j++;\n            }\n        }\n        System.out.println(count);\n    }\n}', NULL, 1),
(216, 'JAVASCRIPT', 'const readline = require(\'readline\');\n\nconst rl = readline.createInterface({\n    input: process.stdin,\n    output: process.stdout\n});\n\nlet lines = [];\nrl.on(\'line\', (line) => {\n    lines.push(line.trim());\n});\n\nrl.on(\'close\', () => {\n    const first = lines[0].split(/\\s+/).map(Number);\n    const gn = first[0];\n    const sn = first[1];\n    const g = lines[1].split(/\\s+/).map(Number);\n    const s = lines[2].split(/\\s+/).map(Number);\n\n    g.sort((a, b) => a - b);\n    s.sort((a, b) => a - b);\n\n    let i = 0, j = 0;\n    while (i < gn && j < sn) {\n        if (s[j] >= g[i]) {\n            i++;\n        }\n        j++;\n    }\n    console.log(i);\n});', NULL, 1),
(216, 'PYTHON', 'import sys\n\ndef main():\n    data = sys.stdin.read().split()\n    if not data:\n        return\n    gn = int(data[0])\n    sn = int(data[1])\n    g = list(map(int, data[2:2 + gn]))\n    s = list(map(int, data[2 + gn:2 + gn + sn]))\n    g.sort()\n    s.sort()\n    i = j = 0\n    while i < gn and j < sn:\n        if s[j] >= g[i]:\n            i += 1\n        j += 1\n    print(i)\n\nif __name__ == \"__main__\":\n    main()', NULL, 1),
(217, 'C', '#include <stdio.h>\n\nint main() {\n    int n;\n    scanf(\"%d\", &n);\n    int nums[n];\n    for (int i = 0; i < n; i++) {\n        scanf(\"%d\", &nums[i]);\n    }\n    int maxReach = 0;\n    int canReach = 1;\n    for (int i = 0; i < n; i++) {\n        if (i > maxReach) {\n            canReach = 0;\n            break;\n        }\n        if (i + nums[i] > maxReach) {\n            maxReach = i + nums[i];\n        }\n        if (maxReach >= n - 1) {\n            break;\n        }\n    }\n    if (canReach) {\n        printf(\"true\\n\");\n    } else {\n        printf(\"false\\n\");\n    }\n    return 0;\n}', NULL, 1),
(217, 'CPP', '#include <iostream>\n#include <vector>\n#include <algorithm>\nusing namespace std;\n\nint main() {\n    int n;\n    cin >> n;\n    vector<int> nums(n);\n    for (int i = 0; i < n; i++) {\n        cin >> nums[i];\n    }\n    int maxReach = 0;\n    bool canReach = true;\n    for (int i = 0; i < n; i++) {\n        if (i > maxReach) {\n            canReach = false;\n            break;\n        }\n        maxReach = max(maxReach, i + nums[i]);\n        if (maxReach >= n - 1) {\n            break;\n        }\n    }\n    cout << (canReach ? \"true\" : \"false\") << endl;\n    return 0;\n}', NULL, 1),
(217, 'JAVA', 'import java.util.Scanner;\n\npublic class Main {\n    public static void main(String[] args) {\n        Scanner sc = new Scanner(System.in);\n        int n = sc.nextInt();\n        int[] nums = new int[n];\n        for (int i = 0; i < n; i++) {\n            nums[i] = sc.nextInt();\n        }\n        int maxReach = 0;\n        boolean canReach = true;\n        for (int i = 0; i < n; i++) {\n            if (i > maxReach) {\n                canReach = false;\n                break;\n            }\n            maxReach = Math.max(maxReach, i + nums[i]);\n            if (maxReach >= n - 1) {\n                break;\n            }\n        }\n        System.out.println(canReach && maxReach >= n - 1);\n    }\n}', NULL, 1),
