(218, 'C', '#include <stdio.h>\n#include <stdbool.h>\n\nint main() {\n    int n;\n    scanf(\"%d\", &n);\n    int five = 0, ten = 0;\n    bool ok = true;\n    for (int i = 0; i < n; i++) {\n        int bill;\n        scanf(\"%d\", &bill);\n        if (bill == 5) {\n            five++;\n        } else if (bill == 10) {\n            if (five > 0) {\n                five--;\n                ten++;\n            } else {\n                ok = false;\n                break;\n            }\n        } else {\n            if (ten > 0 && five > 0) {\n                ten--;\n                five--;\n            } else if (five >= 3) {\n                five -= 3;\n            } else {\n                ok = false;\n                break;\n            }\n        }\n    }\n    printf(ok ? \"true\\n\" : \"false\\n\");\n    return 0;\n}', NULL, 1),
(218, 'CPP', '#include <iostream>\nusing namespace std;\n\nint main() {\n    int n;\n    cin >> n;\n    int five = 0, ten = 0;\n    bool ok = true;\n    for (int i = 0; i < n; i++) {\n        int bill;\n        cin >> bill;\n        if (bill == 5) {\n            five++;\n        } else if (bill == 10) {\n            if (five > 0) {\n                five--;\n                ten++;\n            } else {\n                ok = false;\n                break;\n            }\n        } else {\n            if (ten > 0 && five > 0) {\n                ten--;\n                five--;\n            } else if (five >= 3) {\n                five -= 3;\n            } else {\n                ok = false;\n                break;\n            }\n        }\n    }\n    cout << (ok ? \"true\" : \"false\") << endl;\n    return 0;\n}', NULL, 1),
