(218, 'JAVASCRIPT', 'const readline = require(\'readline\');\n\nconst rl = readline.createInterface({\n    input: process.stdin,\n    output: process.stdout\n});\n\nlet lines = [];\nrl.on(\'line\', (line) => {\n    lines.push(line.trim());\n});\n\nrl.on(\'close\', () => {\n    const n = parseInt(lines[0]);\n    const bills = lines[1].split(/\\s+/).map(Number);\n    let five = 0, ten = 0;\n    let ok = true;\n    for (let i = 0; i < n; i++) {\n        const bill = bills[i];\n        if (bill === 5) {\n            five++;\n        } else if (bill === 10) {\n            if (five > 0) {\n                five--;\n                ten++;\n            } else {\n                ok = false;\n                break;\n            }\n        } else {\n            if (ten > 0 && five > 0) {\n                ten--;\n                five--;\n            } else if (five >= 3) {\n                five -= 3;\n            } else {\n                ok = false;\n                break;\n            }\n        }\n    }\n    console.log(ok);\n});', NULL, 1),
(218, 'PYTHON', 'n = int(input())\nbills = list(map(int, input().split()))\nfive = 0\nten = 0\nok = True\nfor bill in bills:\n    if bill == 5:\n        five += 1\n    elif bill == 10:\n        if five > 0:\n            five -= 1\n            ten += 1\n        else:\n            ok = False\n            break\n    else:\n        if ten > 0 and five > 0:\n            ten -= 1\n            five -= 1\n        elif five >= 3:\n            five -= 3\n        else:\n            ok = False\n            break\nprint(\"true\" if ok else \"false\")', NULL, 1),
