(220, 'C', '#include <stdio.h>\n#include <stdlib.h>\n\nint main() {\n    int n;\n    scanf(\"%d\", &n);\n    int *ratings = (int *)malloc(n * sizeof(int));\n    for (int i = 0; i < n; i++) {\n        scanf(\"%d\", &ratings[i]);\n    }\n\n    int *candies = (int *)malloc(n * sizeof(int));\n    for (int i = 0; i < n; i++) {\n        candies[i] = 1;\n    }\n\n    for (int i = 1; i < n; i++) {\n        if (ratings[i] > ratings[i - 1]) {\n            candies[i] = candies[i - 1] + 1;\n        }\n    }\n\n    for (int i = n - 2; i >= 0; i--) {\n        if (ratings[i] > ratings[i + 1]) {\n            int need = candies[i + 1] + 1;\n            if (need > candies[i]) {\n                candies[i] = need;\n            }\n        }\n    }\n\n    int total = 0;\n    for (int i = 0; i < n; i++) {\n        total += candies[i];\n    }\n\n    printf(\"%d\\n\", total);\n\n    free(ratings);\n    free(candies);\n    return 0;\n}', NULL, 1),
(220, 'CPP', '#include <iostream>\n#include <vector>\n#include <algorithm>\nusing namespace std;\n\nint main() {\n    int n;\n    cin >> n;\n    vector<int> ratings(n);\n    for (int i = 0; i < n; i++) {\n        cin >> ratings[i];\n    }\n\n    vector<int> candies(n, 1);\n\n    for (int i = 1; i < n; i++) {\n        if (ratings[i] > ratings[i - 1]) {\n            candies[i] = candies[i - 1] + 1;\n        }\n    }\n\n    for (int i = n - 2; i >= 0; i--) {\n        if (ratings[i] > ratings[i + 1]) {\n            candies[i] = max(candies[i], candies[i + 1] + 1);\n        }\n    }\n\n    int total = 0;\n    for (int c : candies) {\n        total += c;\n    }\n\n    cout << total << endl;\n    return 0;\n}', NULL, 1),
(220, 'JAVA', 'import java.util.*;\n\npublic class Main {\n    public static void main(String[] args) {\n        Scanner sc = new Scanner(System.in);\n        int n = sc.nextInt();\n        int[] ratings = new int[n];\n        for (int i = 0; i < n; i++) {\n            ratings[i] = sc.nextInt();\n        }\n        int[] candies = new int[n];\n        Arrays.fill(candies, 1);\n        for (int i = 1; i < n; i++) {\n            if (ratings[i] > ratings[i - 1]) {\n                candies[i] = candies[i - 1] + 1;\n            }\n        }\n        for (int i = n - 2; i >= 0; i--) {\n            if (ratings[i] > ratings[i + 1]) {\n                candies[i] = Math.max(candies[i], candies[i + 1] + 1);\n            }\n        }\n        int sum = 0;\n        for (int c : candies) {\n            sum += c;\n        }\n        System.out.println(sum);\n    }\n}', NULL, 1),
(220, 'JAVASCRIPT', 'const readline = require(\'readline\');\n\nconst rl = readline.createInterface({\n    input: process.stdin,\n    output: process.stdout\n});\n\nlet lines = [];\nrl.on(\'line\', (line) => {\n    lines.push(line.trim());\n});\n\nrl.on(\'close\', () => {\n    const n = parseInt(lines[0]);\n    const ratings = lines[1].split(\' \').map(Number);\n    \n    const candies = new Array(n).fill(1);\n    \n    for (let i = 1; i < n; i++) {\n        if (ratings[i] > ratings[i - 1]) {\n            candies[i] = candies[i - 1] + 1;\n        }\n    }\n    \n    for (let i = n - 2; i >= 0; i--) {\n        if (ratings[i] > ratings[i + 1]) {\n            candies[i] = Math.max(candies[i], candies[i + 1] + 1);\n        }\n    }\n    \n    let total = 0;\n    for (const c of candies) {\n        total += c;\n    }\n    \n    console.log(total);\n});', NULL, 1),
(220, 'PYTHON', 'n = int(input())\nratings = list(map(int, input().split()))\n\ncandies = [1] * n\n\nfor i in range(1, n):\n    if ratings[i] > ratings[i - 1]:\n        candies[i] = candies[i - 1] + 1\n\nfor i in range(n - 2, -1, -1):\n    if ratings[i] > ratings[i + 1]:\n        candies[i] = max(candies[i], candies[i + 1] + 1)\n\nprint(sum(candies))', NULL, 1),
(221, 'C', '#include <stdio.h>\n#include <stdlib.h>\n\nint n;\nint nums[100];\nint used[100];\nint path[100];\nint res[10000][100];\nint resCount = 0;\n\nvoid backtrack(int depth) {\n    if (depth == n) {\n        for (int i = 0; i < n; i++) {\n            res[resCount][i] = path[i];\n        }\n        resCount++;\n        return;\n    }\n    for (int i = 0; i < n; i++) {\n        if (used[i]) continue;\n        used[i] = 1;\n        path[depth] = nums[i];\n        backtrack(depth + 1);\n        used[i] = 0;\n    }\n}\n\nint main() {\n    scanf(\"%d\", &n);\n    for (int i = 0; i < n; i++) {\n        scanf(\"%d\", &nums[i]);\n    }\n    backtrack(0);\n    printf(\"[\");\n    for (int i = 0; i < resCount; i++) {\n        printf(\"[\");\n        for (int j = 0; j < n; j++) {\n            printf(\"%d\", res[i][j]);\n            if (j != n - 1) printf(\",\");\n        }\n        printf(\"]\");\n        if (i != resCount - 1) printf(\",\");\n    }\n    printf(\"]\\n\");\n    return 0;\n}', NULL, 1),
(221, 'CPP', '#include <iostream>\n#include <vector>\n#include <string>\nusing namespace std;\n\nvoid backtrack(vector<int>& nums, vector<bool>& used, vector<int>& path, vector<vector<int>>& res) {\n    if (path.size() == nums.size()) {\n        res.push_back(path);\n        return;\n    }\n    for (int i = 0; i < (int)nums.size(); i++) {\n        if (used[i]) continue;\n        used[i] = true;\n        path.push_back(nums[i]);\n        backtrack(nums, used, path, res);\n        path.pop_back();\n        used[i] = false;\n    }\n}\n\nstring format(vector<vector<int>>& res) {\n    string sb;\n    sb += \"[\";\n    for (int i = 0; i < (int)res.size(); i++) {\n        sb += \"[\";\n        vector<int>& list = res[i];\n        for (int j = 0; j < (int)list.size(); j++) {\n            sb += to_string(list[j]);\n            if (j != (int)list.size() - 1) sb += \",\";\n        }\n        sb += \"]\";\n        if (i != (int)res.size() - 1) sb += \",\";\n    }\n    sb += \"]\";\n    return sb;\n}\n\nint main() {\n    int n;\n    cin >> n;\n    vector<int> nums(n);\n    for (int i = 0; i < n; i++) {\n        cin >> nums[i];\n    }\n    vector<vector<int>> res;\n    vector<bool> used(n, false);\n    vector<int> path;\n    backtrack(nums, used, path, res);\n    cout << format(res) << endl;\n    return 0;\n}', NULL, 1),
(221, 'JAVA', 'import java.util.*;\n\npublic class Main {\n    public static void main(String[] args) {\n        Scanner sc = new Scanner(System.in);\n        int n = sc.nextInt();\n        int[] nums = new int[n];\n        for (int i = 0; i < n; i++) {\n            nums[i] = sc.nextInt();\n        }\n        List<List<Integer>> result = new ArrayList<>();\n        boolean[] used = new boolean[n];\n        backtrack(nums, used, new ArrayList<>(), result);\n        StringBuilder sb = new StringBuilder();\n        sb.append(\"[\");\n        for (int i = 0; i < result.size(); i++) {\n            sb.append(\"[\");\n            List<Integer> perm = result.get(i);\n            for (int j = 0; j < perm.size(); j++) {\n                sb.append(perm.get(j));\n                if (j < perm.size() - 1) {\n                    sb.append(\",\");\n                }\n            }\n            sb.append(\"]\");\n            if (i < result.size() - 1) {\n                sb.append(\",\");\n            }\n        }\n        sb.append(\"]\");\n        System.out.println(sb.toString());\n    }\n\n    private static void backtrack(int[] nums, boolean[] used, List<Integer> path, List<List<Integer>> result) {\n        if (path.size() == nums.length) {\n            result.add(new ArrayList<>(path));\n            return;\n        }\n        for (int i = 0; i < nums.length; i++) {\n            if (used[i]) continue;\n            used[i] = true;\n            path.add(nums[i]);\n            backtrack(nums, used, path, result);\n            path.remove(path.size() - 1);\n            used[i] = false;\n        }\n    }\n}', NULL, 1),
(221, 'JAVASCRIPT', 'const readline = require(\'readline\');\n\nconst rl = readline.createInterface({\n    input: process.stdin,\n    output: process.stdout\n});\n\nlet lines = [];\nrl.on(\'line\', (line) => {\n    lines.push(line.trim());\n});\n\nrl.on(\'close\', () => {\n    const n = parseInt(lines[0]);\n    const nums = lines[1].split(\' \').map(Number);\n    const res = [];\n    const used = new Array(n).fill(false);\n    backtrack(nums, used, [], res);\n    console.log(format(res));\n});\n\nfunction backtrack(nums, used, path, res) {\n    if (path.length === nums.length) {\n        res.push([...path]);\n        return;\n    }\n    for (let i = 0; i < nums.length; i++) {\n        if (used[i]) continue;\n        used[i] = true;\n        path.push(nums[i]);\n        backtrack(nums, used, path, res);\n        path.pop();\n        used[i] = false;\n    }\n}\n\nfunction format(res) {\n    let sb = \'\';\n    sb += \'[\';\n    for (let i = 0; i < res.length; i++) {\n        sb += \'[\';\n        const list = res[i];\n        for (let j = 0; j < list.length; j++) {\n            sb += list[j];\n            if (j !== list.length - 1) sb += \',\';\n        }\n        sb += \']\';\n        if (i !== res.length - 1) sb += \',\';\n    }\n    sb += \']\';\n    return sb;\n}', NULL, 1),
(221, 'PYTHON', 'import sys\n\ndef main():\n    data = sys.stdin.read().strip().split()\n    if not data:\n        return\n    n = int(data[0])\n    nums = list(map(int, data[1:1+n]))\n    res = []\n    used = [False] * n\n    path = []\n\n    def backtrack():\n        if len(path) == n:\n            res.append(path[:])\n            return\n        for i in range(n):\n            if used[i]:\n                continue\n            used[i] = True\n            path.append(nums[i])\n            backtrack()\n            path.pop()\n            used[i] = False\n\n    backtrack()\n\n    parts = []\n    for perm in res:\n        parts.append(\"[\" + \",\".join(map(str, perm)) + \"]\")\n    print(\"[\" + \",\".join(parts) + \"]\")\n\nif __name__ == \"__main__\":\n    main()', NULL, 1),
(222, 'C', '#include <stdio.h>\n\nint main() {\n    int n;\n    scanf(\"%d\", &n);\n    int nums[20];\n    for (int i = 0; i < n; i++) {\n        scanf(\"%d\", &nums[i]);\n    }\n\n    int total = 1 << n;\n    printf(\"[\");\n    for (int mask = 0; mask < total; mask++) {\n        if (mask > 0) printf(\",\");\n        printf(\"[\");\n        int first = 1;\n        for (int i = 0; i < n; i++) {\n            if (mask & (1 << i)) {\n                if (!first) printf(\",\");\n                printf(\"%d\", nums[i]);\n                first = 0;\n            }\n        }\n        printf(\"]\");\n    }\n    printf(\"]\\n\");\n    return 0;\n}', NULL, 1),
(222, 'CPP', '#include <iostream>\n#include <vector>\n#include <string>\nusing namespace std;\n\nint main() {\n    int n;\n    cin >> n;\n    vector<int> nums(n);\n    for (int i = 0; i < n; i++) {\n        cin >> nums[i];\n    }\n\n    vector<vector<int>> result;\n    int total = 1 << n;\n    for (int mask = 0; mask < total; mask++) {\n        vector<int> subset;\n        for (int i = 0; i < n; i++) {\n            if ((mask & (1 << i)) != 0) {\n                subset.push_back(nums[i]);\n            }\n        }\n        result.push_back(subset);\n    }\n\n    string sb;\n    sb += \"[\";\n    for (int i = 0; i < (int)result.size(); i++) {\n        if (i > 0) sb += \",\";\n        sb += \"[\";\n        const vector<int>& subset = result[i];\n        for (int j = 0; j < (int)subset.size(); j++) {\n            if (j > 0) sb += \",\";\n            sb += to_string(subset[j]);\n        }\n        sb += \"]\";\n    }\n    sb += \"]\";\n    cout << sb << endl;\n\n    return 0;\n}', NULL, 1),
(222, 'JAVA', 'import java.util.*;\n\npublic class Main {\n    public static void main(String[] args) {\n        Scanner sc = new Scanner(System.in);\n        int n = sc.nextInt();\n        int[] nums = new int[n];\n        for (int i = 0; i < n; i++) {\n            nums[i] = sc.nextInt();\n        }\n\n        List<List<Integer>> result = new ArrayList<>();\n        int total = 1 << n;\n        for (int mask = 0; mask < total; mask++) {\n            List<Integer> subset = new ArrayList<>();\n            for (int i = 0; i < n; i++) {\n                if ((mask & (1 << i)) != 0) {\n                    subset.add(nums[i]);\n                }\n            }\n            result.add(subset);\n        }\n\n        StringBuilder sb = new StringBuilder();\n        sb.append(\"[\");\n        for (int i = 0; i < result.size(); i++) {\n            if (i > 0) sb.append(\",\");\n            sb.append(\"[\");\n            List<Integer> subset = result.get(i);\n            for (int j = 0; j < subset.size(); j++) {\n                if (j > 0) sb.append(\",\");\n                sb.append(subset.get(j));\n            }\n            sb.append(\"]\");\n        }\n        sb.append(\"]\");\n        System.out.println(sb.toString());\n    }\n}', NULL, 1),
(222, 'JAVASCRIPT', 'const readline = require(\'readline\');\n\nconst rl = readline.createInterface({\n    input: process.stdin,\n    output: process.stdout\n});\n\nlet input = [];\nrl.on(\'line\', (line) => {\n    input.push(line.trim());\n});\n\nrl.on(\'close\', () => {\n    const n = parseInt(input[0]);\n    const nums = input[1].split(\' \').map(Number);\n\n    const result = [];\n    const total = 1 << n;\n    for (let mask = 0; mask < total; mask++) {\n        const subset = [];\n        for (let i = 0; i < n; i++) {\n            if ((mask & (1 << i)) !== 0) {\n                subset.push(nums[i]);\n            }\n        }\n        result.push(subset);\n    }\n\n    let sb = \'\';\n    sb += \'[\';\n    for (let i = 0; i < result.length; i++) {\n        if (i > 0) sb += \',\';\n        sb += \'[\';\n        const subset = result[i];\n        for (let j = 0; j < subset.length; j++) {\n            if (j > 0) sb += \',\';\n            sb += subset[j];\n        }\n        sb += \']\';\n    }\n    sb += \']\';\n    console.log(sb);\n});', NULL, 1),
(222, 'PYTHON', 'n = int(input())\nnums = list(map(int, input().split()))\n\nresult = []\ntotal = 1 << n\nfor mask in range(total):\n    subset = []\n    for i in range(n):\n        if mask & (1 << i):\n            subset.append(nums[i])\n    result.append(subset)\n\nsb = []\nsb.append(\"[\")\nfor i in range(len(result)):\n    if i > 0:\n        sb.append(\",\")\n    sb.append(\"[\")\n    subset = result[i]\n    for j in range(len(subset)):\n        if j > 0:\n            sb.append(\",\")\n        sb.append(str(subset[j]))\n    sb.append(\"]\")\nsb.append(\"]\")\nprint(\"\".join(sb))', NULL, 1),
(223, 'C', '#include <stdio.h>\n#include <stdlib.h>\n\nint cmp(const void *a, const void *b) {\n    return (*(int *)a - *(int *)b);\n}\n\nvoid backtrack(int *candidates, int n, int target, int start, int *current, int curLen, int **result, int *resultSize, int **resultColSize) {\n    if (target == 0) {\n        result[*resultSize] = (int *)malloc(curLen * sizeof(int));\n        for (int i = 0; i < curLen; i++) {\n            result[*resultSize][i] = current[i];\n        }\n        (*resultColSize)[*resultSize] = curLen;\n        (*resultSize)++;\n        return;\n    }\n    for (int i = start; i < n; i++) {\n        if (candidates[i] > target) {\n            break;\n        }\n        current[curLen] = candidates[i];\n        backtrack(candidates, n, target - candidates[i], i, current, curLen + 1, result, resultSize, resultColSize);\n    }\n}\n\nint main() {\n    int n, target;\n    scanf(\"%d %d\", &n, &target);\n    int *candidates = (int *)malloc(n * sizeof(int));\n    for (int i = 0; i < n; i++) {\n        scanf(\"%d\", &candidates[i]);\n    }\n    qsort(candidates, n, sizeof(int), cmp);\n\n    int maxSize = 10000;\n    int **result = (int **)malloc(maxSize * sizeof(int *));\n    int *resultColSize = (int *)malloc(maxSize * sizeof(int));\n    int resultSize = 0;\n\n    int *current = (int *)malloc(1000 * sizeof(int));\n    backtrack(candidates, n, target, 0, current, 0, result, &resultSize, &resultColSize);\n\n    printf(\"[\");\n    for (int i = 0; i < resultSize; i++) {\n        printf(\"[\");\n        for (int j = 0; j < resultColSize[i]; j++) {\n            printf(\"%d\", result[i][j]);\n            if (j < resultColSize[i] - 1) {\n                printf(\",\");\n            }\n        }\n        printf(\"]\");\n        if (i < resultSize - 1) {\n            printf(\",\");\n        }\n    }\n    printf(\"]\\n\");\n\n    for (int i = 0; i < resultSize; i++) {\n        free(result[i]);\n    }\n    free(result);\n    free(resultColSize);\n    free(current);\n    free(candidates);\n\n    return 0;\n}', NULL, 1),
(223, 'CPP', '#include <iostream>\n#include <vector>\n#include <algorithm>\nusing namespace std;\n\nvoid backtrack(vector<int>& candidates, int target, int start, vector<int>& current, vector<vector<int>>& result) {\n    if (target == 0) {\n        result.push_back(current);\n        return;\n    }\n    for (int i = start; i < (int)candidates.size(); i++) {\n        if (candidates[i] > target) {\n            break;\n        }\n        current.push_back(candidates[i]);\n        backtrack(candidates, target - candidates[i], i, current, result);\n        current.pop_back();\n    }\n}\n\nstring format(vector<vector<int>>& result) {\n    string sb = \"[\";\n    for (int i = 0; i < (int)result.size(); i++) {\n        sb += \"[\";\n        vector<int>& list = result[i];\n        for (int j = 0; j < (int)list.size(); j++) {\n            sb += to_string(list[j]);\n            if (j < (int)list.size() - 1) {\n                sb += \",\";\n            }\n        }\n        sb += \"]\";\n        if (i < (int)result.size() - 1) {\n            sb += \",\";\n        }\n    }\n    sb += \"]\";\n    return sb;\n}\n\nint main() {\n    int n, target;\n    cin >> n >> target;\n    vector<int> candidates(n);\n    for (int i = 0; i < n; i++) {\n        cin >> candidates[i];\n    }\n    sort(candidates.begin(), candidates.end());\n    vector<vector<int>> result;\n    vector<int> current;\n    backtrack(candidates, target, 0, current, result);\n    cout << format(result) << endl;\n    return 0;\n}', NULL, 1),
(223, 'JAVA', 'import java.util.*;\n\npublic class Main {\n    public static void main(String[] args) {\n        Scanner sc = new Scanner(System.in);\n        int n = sc.nextInt();\n        int target = sc.nextInt();\n        int[] candidates = new int[n];\n        for (int i = 0; i < n; i++) {\n            candidates[i] = sc.nextInt();\n        }\n        Arrays.sort(candidates);\n        List<List<Integer>> result = new ArrayList<>();\n        backtrack(candidates, target, 0, new ArrayList<>(), result);\n        System.out.println(format(result));\n    }\n\n    private static void backtrack(int[] candidates, int remain, int start, List<Integer> path, List<List<Integer>> result) {\n        if (remain == 0) {\n            result.add(new ArrayList<>(path));\n            return;\n        }\n        for (int i = start; i < candidates.length; i++) {\n            if (candidates[i] > remain) {\n                break;\n            }\n            path.add(candidates[i]);\n            backtrack(candidates, remain - candidates[i], i, path, result);\n            path.remove(path.size() - 1);\n        }\n    }\n\n    private static String format(List<List<Integer>> result) {\n        StringBuilder sb = new StringBuilder();\n        sb.append(\"[\");\n        for (int i = 0; i < result.size(); i++) {\n            sb.append(\"[\");\n            List<Integer> list = result.get(i);\n            for (int j = 0; j < list.size(); j++) {\n                sb.append(list.get(j));\n                if (j < list.size() - 1) {\n                    sb.append(\",\");\n                }\n            }\n            sb.append(\"]\");\n            if (i < result.size() - 1) {\n                sb.append(\",\");\n            }\n        }\n        sb.append(\"]\");\n        return sb.toString();\n    }\n}', NULL, 1),
(223, 'JAVASCRIPT', 'const readline = require(\'readline\');\n\nconst rl = readline.createInterface({\n    input: process.stdin,\n    output: process.stdout\n});\n\nlet lines = [];\nrl.on(\'line\', (line) => {\n    lines.push(line.trim());\n    if (lines.length === 2) {\n        const [n, target] = lines[0].split(\' \').map(Number);\n        const candidates = lines[1].split(\' \').map(Number);\n        candidates.sort((a, b) => a - b);\n        const result = [];\n        backtrack(candidates, target, 0, [], result);\n        console.log(format(result));\n        rl.close();\n    }\n});\n\nfunction backtrack(candidates, target, start, current, result) {\n    if (target === 0) {\n        result.push([...current]);\n        return;\n    }\n    for (let i = start; i < candidates.length; i++) {\n        if (candidates[i] > target) {\n            break;\n        }\n        current.push(candidates[i]);\n        backtrack(candidates, target - candidates[i], i, current, result);\n        current.pop();\n    }\n}\n\nfunction format(result) {\n    let sb = \'\';\n    sb += \'[\';\n    for (let i = 0; i < result.length; i++) {\n        sb += \'[\';\n        const list = result[i];\n        for (let j = 0; j < list.length; j++) {\n            sb += list[j];\n            if (j < list.length - 1) {\n                sb += \',\';\n            }\n        }\n        sb += \']\';\n        if (i < result.length - 1) {\n            sb += \',\';\n        }\n    }\n    sb += \']\';\n    return sb;\n}', NULL, 1),
(223, 'PYTHON', 'import sys\n\ndef main():\n    data = sys.stdin.read().strip().split()\n    if not data:\n        return\n    n = int(data[0])\n    target = int(data[1])\n    candidates = list(map(int, data[2:2 + n]))\n    candidates.sort()\n    result = []\n    \n    def backtrack(start, remaining, current):\n        if remaining == 0:\n            result.append(current[:])\n            return\n        for i in range(start, len(candidates)):\n            if candidates[i] > remaining:\n                break\n            current.append(candidates[i])\n            backtrack(i, remaining - candidates[i], current)\n            current.pop()\n    \n    backtrack(0, target, [])\n    \n    parts = []\n    for lst in result:\n        parts.append(\"[\" + \",\".join(map(str, lst)) + \"]\")\n    print(\"[\" + \",\".join(parts) + \"]\")\n\nif __name__ == \"__main__\":\n    main()', NULL, 1),
(224, 'C', '#include <stdio.h>\n#include <stdlib.h>\n#include <string.h>\n\nvoid backtrack(char ***res, int *returnSize, char *cur, int len, int open, int close, int n) {\n    if (len == n * 2) {\n        cur[len] = \'\\0\';\n        *res = (char **)realloc(*res, (*returnSize + 1) * sizeof(char *));\n        (*res)[*returnSize] = (char *)malloc((n * 2 + 1) * sizeof(char));\n        strcpy((*res)[*returnSize], cur);\n        (*returnSize)++;\n        return;\n    }\n    if (open < n) {\n        cur[len] = \'(\';\n        backtrack(res, returnSize, cur, len + 1, open + 1, close, n);\n    }\n    if (close < open) {\n        cur[len] = \')\';\n        backtrack(res, returnSize, cur, len + 1, open, close + 1, n);\n    }\n}\n\nint main() {\n    int n;\n    scanf(\"%d\", &n);\n\n    char **res = NULL;\n    int returnSize = 0;\n    char *cur = (char *)malloc((n * 2 + 1) * sizeof(char));\n\n    backtrack(&res, &returnSize, cur, 0, 0, 0, n);\n\n    printf(\"[\");\n    for (int i = 0; i < returnSize; i++) {\n        if (i > 0) printf(\",\");\n        printf(\"\'%s\'\", res[i]);\n    }\n    printf(\"]\\n\");\n\n    for (int i = 0; i < returnSize; i++) {\n        free(res[i]);\n    }\n    free(res);\n    free(cur);\n\n    return 0;\n}', NULL, 1),
(224, 'CPP', '#include <iostream>\n#include <vector>\n#include <string>\nusing namespace std;\n\nvoid backtrack(vector<string>& res, string& cur, int open, int close, int n) {\n    if ((int)cur.length() == n * 2) {\n        res.push_back(cur);\n        return;\n    }\n    if (open < n) {\n        cur.push_back(\'(\');\n        backtrack(res, cur, open + 1, close, n);\n        cur.pop_back();\n    }\n    if (close < open) {\n        cur.push_back(\')\');\n        backtrack(res, cur, open, close + 1, n);\n        cur.pop_back();\n    }\n}\n\nint main() {\n    int n;\n    cin >> n;\n    vector<string> res;\n    string cur;\n    backtrack(res, cur, 0, 0, n);\n    cout << \"[\";\n    for (int i = 0; i < (int)res.size(); i++) {\n        if (i > 0) cout << \",\";\n        cout << \"\'\" << res[i] << \"\'\";\n    }\n    cout << \"]\" << endl;\n    return 0;\n}', NULL, 1),
(224, 'JAVA', 'import java.util.*;\n\npublic class Main {\n    public static void main(String[] args) {\n        Scanner sc = new Scanner(System.in);\n        int n = sc.nextInt();\n        List<String> res = new ArrayList<>();\n        backtrack(res, new StringBuilder(), 0, 0, n);\n        StringBuilder sb = new StringBuilder();\n        sb.append(\'[\');\n        for (int i = 0; i < res.size(); i++) {\n            if (i > 0) sb.append(\',\');\n            sb.append(\'\\\'\').append(res.get(i)).append(\'\\\'\');\n        }\n        sb.append(\']\');\n        System.out.println(sb.toString());\n    }\n\n    private static void backtrack(List<String> res, StringBuilder cur, int open, int close, int n) {\n        if (cur.length() == n * 2) {\n            res.add(cur.toString());\n            return;\n        }\n        if (open < n) {\n            cur.append(\'(\');\n            backtrack(res, cur, open + 1, close, n);\n            cur.deleteCharAt(cur.length() - 1);\n        }\n        if (close < open) {\n            cur.append(\')\');\n            backtrack(res, cur, open, close + 1, n);\n            cur.deleteCharAt(cur.length() - 1);\n        }\n    }\n}', NULL, 1),
(224, 'JAVASCRIPT', 'const readline = require(\'readline\');\n\nconst rl = readline.createInterface({\n    input: process.stdin,\n    output: process.stdout\n});\n\nrl.on(\'line\', (line) => {\n    const n = parseInt(line.trim(), 10);\n    const res = [];\n    backtrack(res, \'\', 0, 0, n);\n    let output = \'[\';\n    for (let i = 0; i < res.length; i++) {\n        if (i > 0) output += \',\';\n        output += \"\'\" + res[i] + \"\'\";\n    }\n    output += \']\';\n    console.log(output);\n    rl.close();\n});\n\nfunction backtrack(res, cur, open, close, n) {\n    if (cur.length === n * 2) {\n        res.push(cur);\n        return;\n    }\n    if (open < n) {\n        backtrack(res, cur + \'(\', open + 1, close, n);\n    }\n    if (close < open) {\n        backtrack(res, cur + \')\', open, close + 1, n);\n    }\n}', NULL, 1),
(224, 'PYTHON', 'n = int(input())\nres = []\n\ndef backtrack(cur, open_count, close_count):\n    if len(cur) == n * 2:\n        res.append(cur)\n        return\n    if open_count < n:\n        backtrack(cur + \'(\', open_count + 1, close_count)\n    if close_count < open_count:\n        backtrack(cur + \')\', open_count, close_count + 1)\n\nbacktrack(\'\', 0, 0)\nprint(\'[\' + \',\'.join(\"\'\" + s + \"\'\" for s in res) + \']\')', NULL, 1),
(225, 'C', '#include <stdio.h>\n#include <stdbool.h>\n#include <string.h>\n\nint m, n;\nchar board[100][100];\nchar word[1000];\n\nbool dfs(int i, int j, int k) {\n    if (i < 0 || i >= m || j < 0 || j >= n || board[i][j] != word[k]) {\n        return false;\n    }\n    if (k == (int)strlen(word) - 1) {\n        return true;\n    }\n    char temp = board[i][j];\n    board[i][j] = \'#\';\n    bool found = dfs(i + 1, j, k + 1)\n            || dfs(i - 1, j, k + 1)\n            || dfs(i, j + 1, k + 1)\n            || dfs(i, j - 1, k + 1);\n    board[i][j] = temp;\n    return found;\n}\n\nint main() {\n    scanf(\"%d %d\", &m, &n);\n    for (int i = 0; i < m; i++) {\n        scanf(\"%s\", board[i]);\n    }\n    scanf(\"%s\", word);\n    bool result = false;\n    for (int i = 0; i < m && !result; i++) {\n        for (int j = 0; j < n && !result; j++) {\n            if (dfs(i, j, 0)) {\n                result = true;\n            }\n        }\n    }\n    if (result) {\n        printf(\"true\\n\");\n    } else {\n        printf(\"false\\n\");\n    }\n    return 0;\n}', NULL, 1),
(225, 'CPP', '#include <iostream>\n#include <vector>\n#include <string>\nusing namespace std;\n\nbool dfs(vector<vector<char>>& board, const string& word, int i, int j, int k) {\n    if (i < 0 || i >= (int)board.size() || j < 0 || j >= (int)board[0].size() || board[i][j] != word[k]) {\n        return false;\n    }\n    if (k == (int)word.length() - 1) {\n        return true;\n    }\n    char temp = board[i][j];\n    board[i][j] = \'#\';\n    bool found = dfs(board, word, i + 1, j, k + 1)\n            || dfs(board, word, i - 1, j, k + 1)\n            || dfs(board, word, i, j + 1, k + 1)\n            || dfs(board, word, i, j - 1, k + 1);\n    board[i][j] = temp;\n    return found;\n}\n\nint main() {\n    int m, n;\n    cin >> m >> n;\n    cin.ignore();\n    vector<vector<char>> board(m, vector<char>(n));\n    for (int i = 0; i < m; i++) {\n        string line;\n        getline(cin, line);\n        for (int j = 0; j < n; j++) {\n            board[i][j] = line[j];\n        }\n    }\n    string word;\n    getline(cin, word);\n    bool result = false;\n    for (int i = 0; i < m && !result; i++) {\n        for (int j = 0; j < n && !result; j++) {\n            if (dfs(board, word, i, j, 0)) {\n                result = true;\n            }\n        }\n    }\n    cout << (result ? \"true\" : \"false\") << endl;\n    return 0;\n}', NULL, 1),
(225, 'JAVA', 'import java.util.Scanner;\n\npublic class Main {\n    public static void main(String[] args) {\n        Scanner sc = new Scanner(System.in);\n        int m = sc.nextInt();\n        int n = sc.nextInt();\n        sc.nextLine();\n        char[][] board = new char[m][n];\n        for (int i = 0; i < m; i++) {\n            String line = sc.nextLine();\n            for (int j = 0; j < n; j++) {\n                board[i][j] = line.charAt(j);\n            }\n        }\n        String word = sc.nextLine();\n        boolean result = false;\n        for (int i = 0; i < m && !result; i++) {\n            for (int j = 0; j < n && !result; j++) {\n                if (dfs(board, word, i, j, 0)) {\n                    result = true;\n                }\n            }\n        }\n        System.out.println(result);\n    }\n\n    private static boolean dfs(char[][] board, String word, int i, int j, int k) {\n        if (i < 0 || i >= board.length || j < 0 || j >= board[0].length || board[i][j] != word.charAt(k)) {\n            return false;\n        }\n        if (k == word.length() - 1) {\n            return true;\n        }\n        char temp = board[i][j];\n        board[i][j] = \'#\';\n        boolean found = dfs(board, word, i + 1, j, k + 1)\n                || dfs(board, word, i - 1, j, k + 1)\n                || dfs(board, word, i, j + 1, k + 1)\n                || dfs(board, word, i, j - 1, k + 1);\n        board[i][j] = temp;\n        return found;\n    }\n}', NULL, 1),
(225, 'JAVASCRIPT', 'const readline = require(\'readline\');\n\nconst rl = readline.createInterface({\n    input: process.stdin,\n    output: process.stdout\n});\n\nlet lines = [];\nrl.on(\'line\', (line) => {\n    lines.push(line);\n});\n\nrl.on(\'close\', () => {\n    let idx = 0;\n    const [m, n] = lines[idx++].trim().split(/\\s+/).map(Number);\n    const board = [];\n    for (let i = 0; i < m; i++) {\n        board.push(lines[idx++].trim().split(\'\'));\n    }\n    const word = lines[idx++].trim();\n\n    function dfs(i, j, k) {\n        if (i < 0 || i >= board.length || j < 0 || j >= board[0].length || board[i][j] !== word[k]) {\n            return false;\n        }\n        if (k === word.length - 1) {\n            return true;\n        }\n        const temp = board[i][j];\n        board[i][j] = \'#\';\n        const found = dfs(i + 1, j, k + 1)\n            || dfs(i - 1, j, k + 1)\n            || dfs(i, j + 1, k + 1)\n            || dfs(i, j - 1, k + 1);\n        board[i][j] = temp;\n        return found;\n    }\n\n    let result = false;\n    for (let i = 0; i < m && !result; i++) {\n        for (let j = 0; j < n && !result; j++) {\n            if (dfs(i, j, 0)) {\n                result = true;\n            }\n        }\n    }\n    console.log(result);\n});', NULL, 1),
(225, 'PYTHON', 'import sys\n\ndef main():\n    data = sys.stdin.read().splitlines()\n    if not data:\n        return\n    first = data[0].split()\n    m, n = int(first[0]), int(first[1])\n    board = []\n    for i in range(1, 1 + m):\n        board.append(list(data[i]))\n    word = data[1 + m]\n\n    def dfs(i, j, k):\n        if i < 0 or i >= m or j < 0 or j >= n or board[i][j] != word[k]:\n            return False\n        if k == len(word) - 1:\n            return True\n        temp = board[i][j]\n        board[i][j] = \'#\'\n        found = (dfs(i + 1, j, k + 1) or\n                 dfs(i - 1, j, k + 1) or\n                 dfs(i, j + 1, k + 1) or\n                 dfs(i, j - 1, k + 1))\n        board[i][j] = temp\n        return found\n\n    result = False\n    for i in range(m):\n        for j in range(n):\n            if dfs(i, j, 0):\n                result = True\n                break\n        if result:\n            break\n\n    print(\"true\" if result else \"false\")\n\nif __name__ == \"__main__\":\n    main()', NULL, 1),
(226, 'C', '#include <stdio.h>\n#include <stdlib.h>\n\nvoid swap(int *a, int *b) {\n    int tmp = *a;\n    *a = *b;\n    *b = tmp;\n}\n\nint partition(int arr[], int left, int right) {\n    int mid = left + (right - left) / 2;\n    int pivotValue = arr[mid];\n    swap(&arr[mid], &arr[right]);\n    int storeIndex = left;\n    for (int i = left; i < right; i++) {\n        if (arr[i] < pivotValue) {\n            swap(&arr[i], &arr[storeIndex]);\n            storeIndex++;\n        }\n    }\n    swap(&arr[storeIndex], &arr[right]);\n    return storeIndex;\n}\n\nvoid quickSort(int arr[], int left, int right) {\n    if (left >= right) return;\n    int pivot = partition(arr, left, right);\n    quickSort(arr, left, pivot - 1);\n    quickSort(arr, pivot + 1, right);\n}\n\nint main() {\n    int n;\n    if (scanf(\"%d\", &n) != 1) return 0;\n    int *arr = (int *)malloc(n * sizeof(int));\n    for (int i = 0; i < n; i++) {\n        scanf(\"%d\", &arr[i]);\n    }\n    quickSort(arr, 0, n - 1);\n    for (int i = 0; i < n; i++) {\n        if (i > 0) printf(\" \");\n        printf(\"%d\", arr[i]);\n    }\n    printf(\"\\n\");\n    free(arr);\n    return 0;\n}', NULL, 1),
(226, 'CPP', '#include <iostream>\n#include <vector>\nusing namespace std;\n\nvoid quickSort(vector<int>& arr, int left, int right);\nint partition(vector<int>& arr, int left, int right);\nvoid swap(int& a, int& b);\n\nint main() {\n    int n;\n    if (!(cin >> n)) return 0;\n    vector<int> arr(n);\n    for (int i = 0; i < n; i++) {\n        cin >> arr[i];\n    }\n    quickSort(arr, 0, n - 1);\n    for (int i = 0; i < n; i++) {\n        if (i > 0) cout << \' \';\n        cout << arr[i];\n    }\n    cout << endl;\n    return 0;\n}\n\nvoid quickSort(vector<int>& arr, int left, int right) {\n    if (left >= right) return;\n    int pivot = partition(arr, left, right);\n    quickSort(arr, left, pivot - 1);\n    quickSort(arr, pivot + 1, right);\n}\n\nint partition(vector<int>& arr, int left, int right) {\n    int mid = left + (right - left) / 2;\n    int pivotValue = arr[mid];\n    swap(arr[mid], arr[right]);\n    int storeIndex = left;\n    for (int i = left; i < right; i++) {\n        if (arr[i] < pivotValue) {\n            swap(arr[i], arr[storeIndex]);\n            storeIndex++;\n        }\n    }\n    swap(arr[storeIndex], arr[right]);\n    return storeIndex;\n}\n\nvoid swap(int& a, int& b) {\n    int tmp = a;\n    a = b;\n    b = tmp;\n}', NULL, 1),
(226, 'JAVA', 'import java.util.Scanner;\n\npublic class Main {\n    public static void main(String[] args) {\n        Scanner sc = new Scanner(System.in);\n        if (!sc.hasNextInt()) return;\n        int n = sc.nextInt();\n        int[] arr = new int[n];\n        for (int i = 0; i < n; i++) {\n            arr[i] = sc.nextInt();\n        }\n        quickSort(arr, 0, n - 1);\n        StringBuilder sb = new StringBuilder();\n        for (int i = 0; i < n; i++) {\n            if (i > 0) sb.append(\' \');\n            sb.append(arr[i]);\n        }\n        System.out.println(sb.toString());\n    }\n\n    private static void quickSort(int[] arr, int left, int right) {\n        if (left >= right) return;\n        int pivot = arr[left + (right - left) / 2];\n        int i = left, j = right;\n        while (i <= j) {\n            while (arr[i] < pivot) i++;\n            while (arr[j] > pivot) j--;\n            if (i <= j) {\n                int temp = arr[i];\n                arr[i] = arr[j];\n                arr[j] = temp;\n                i++;\n                j--;\n            }\n        }\n        quickSort(arr, left, j);\n        quickSort(arr, i, right);\n    }\n}', NULL, 1),
(226, 'JAVASCRIPT', 'const readline = require(\'readline\');\n\nconst rl = readline.createInterface({\n    input: process.stdin,\n    output: process.stdout\n});\n\nlet input = [];\n\nrl.on(\'line\', (line) => {\n    input.push(line.trim());\n});\n\nrl.on(\'close\', () => {\n    if (input.length === 0) return;\n    const n = parseInt(input[0]);\n    if (isNaN(n)) return;\n    const arr = input[1].split(\' \').map(Number);\n    quickSort(arr, 0, n - 1);\n    console.log(arr.join(\' \'));\n});\n\nfunction quickSort(arr, left, right) {\n    if (left >= right) return;\n    const pivot = partition(arr, left, right);\n    quickSort(arr, left, pivot - 1);\n    quickSort(arr, pivot + 1, right);\n}\n\nfunction partition(arr, left, right) {\n    const mid = left + Math.floor((right - left) / 2);\n    const pivotValue = arr[mid];\n    swap(arr, mid, right);\n    let storeIndex = left;\n    for (let i = left; i < right; i++) {\n        if (arr[i] < pivotValue) {\n            swap(arr, i, storeIndex);\n            storeIndex++;\n        }\n    }\n    swap(arr, storeIndex, right);\n    return storeIndex;\n}\n\nfunction swap(arr, i, j) {\n    const tmp = arr[i];\n    arr[i] = arr[j];\n    arr[j] = tmp;\n}', NULL, 1),
(226, 'PYTHON', 'import sys\n\ndef quick_sort(arr, left, right):\n    if left >= right:\n        return\n    pivot = partition(arr, left, right)\n    quick_sort(arr, left, pivot - 1)\n    quick_sort(arr, pivot + 1, right)\n\ndef partition(arr, left, right):\n    mid = left + (right - left) // 2\n    pivot_value = arr[mid]\n    arr[mid], arr[right] = arr[right], arr[mid]\n    store_index = left\n    for i in range(left, right):\n        if arr[i] < pivot_value:\n            arr[i], arr[store_index] = arr[store_index], arr[i]\n            store_index += 1\n    arr[store_index], arr[right] = arr[right], arr[store_index]\n    return store_index\n\ndef main():\n    data = sys.stdin.read().strip().split()\n    if not data:\n        return\n    n = int(data[0])\n    arr = list(map(int, data[1:1 + n]))\n    quick_sort(arr, 0, n - 1)\n    print(\' \'.join(map(str, arr)))\n\nif __name__ == \"__main__\":\n    main()', NULL, 1),
(227, 'C', '#include <stdio.h>\n#include <stdlib.h>\n\nvoid merge(int arr[], int left, int mid, int right) {\n    int n1 = mid - left + 1;\n    int n2 = right - mid;\n    int *L = (int *)malloc(n1 * sizeof(int));\n    int *R = (int *)malloc(n2 * sizeof(int));\n    for (int i = 0; i < n1; i++) L[i] = arr[left + i];\n    for (int j = 0; j < n2; j++) R[j] = arr[mid + 1 + j];\n    int i = 0, j = 0, k = left;\n    while (i < n1 && j < n2) {\n        if (L[i] <= R[j]) arr[k++] = L[i++];\n        else arr[k++] = R[j++];\n    }\n    while (i < n1) arr[k++] = L[i++];\n    while (j < n2) arr[k++] = R[j++];\n    free(L);\n    free(R);\n}\n\nvoid mergeSort(int arr[], int left, int right) {\n    if (left >= right) return;\n    int mid = left + (right - left) / 2;\n    mergeSort(arr, left, mid);\n    mergeSort(arr, mid + 1, right);\n    merge(arr, left, mid, right);\n}\n\nint main() {\n    int n;\n    if (scanf(\"%d\", &n) != 1) return 0;\n    int *arr = (int *)malloc(n * sizeof(int));\n    for (int i = 0; i < n; i++) {\n        scanf(\"%d\", &arr[i]);\n    }\n    mergeSort(arr, 0, n - 1);\n    for (int i = 0; i < n; i++) {\n        if (i > 0) printf(\" \");\n        printf(\"%d\", arr[i]);\n    }\n    printf(\"\\n\");\n    free(arr);\n    return 0;\n}', NULL, 1),
(227, 'CPP', '#include <iostream>\n#include <vector>\nusing namespace std;\n\nvoid merge(vector<int>& arr, int left, int mid, int right) {\n    vector<int> temp(right - left + 1);\n    int i = left, j = mid + 1, k = 0;\n    while (i <= mid && j <= right) {\n        if (arr[i] <= arr[j]) {\n            temp[k++] = arr[i++];\n        } else {\n            temp[k++] = arr[j++];\n        }\n    }\n    while (i <= mid) temp[k++] = arr[i++];\n    while (j <= right) temp[k++] = arr[j++];\n    for (int p = 0; p < temp.size(); p++) {\n        arr[left + p] = temp[p];\n    }\n}\n\nvoid mergeSort(vector<int>& arr, int left, int right) {\n    if (left >= right) return;\n    int mid = left + (right - left) / 2;\n    mergeSort(arr, left, mid);\n    mergeSort(arr, mid + 1, right);\n    merge(arr, left, mid, right);\n}\n\nint main() {\n    int n;\n    if (!(cin >> n)) return 0;\n    vector<int> arr(n);\n    for (int i = 0; i < n; i++) {\n        cin >> arr[i];\n    }\n    mergeSort(arr, 0, n - 1);\n    for (int i = 0; i < n; i++) {\n        if (i > 0) cout << \' \';\n        cout << arr[i];\n    }\n    cout << endl;\n    return 0;\n}', NULL, 1),
(227, 'JAVA', 'import java.util.Scanner;\n\npublic class Main {\n    public static void main(String[] args) {\n        Scanner sc = new Scanner(System.in);\n        if (!sc.hasNextInt()) return;\n        int n = sc.nextInt();\n        int[] arr = new int[n];\n        for (int i = 0; i < n; i++) {\n            arr[i] = sc.nextInt();\n        }\n        mergeSort(arr, 0, n - 1);\n        StringBuilder sb = new StringBuilder();\n        for (int i = 0; i < n; i++) {\n            if (i > 0) sb.append(\' \');\n            sb.append(arr[i]);\n        }\n        System.out.println(sb.toString());\n    }\n\n    private static void mergeSort(int[] arr, int left, int right) {\n        if (left >= right) return;\n        int mid = left + (right - left) / 2;\n        mergeSort(arr, left, mid);\n        mergeSort(arr, mid + 1, right);\n        merge(arr, left, mid, right);\n    }\n\n    private static void merge(int[] arr, int left, int mid, int right) {\n        int[] temp = new int[right - left + 1];\n        int i = left, j = mid + 1, k = 0;\n        while (i <= mid && j <= right) {\n            if (arr[i] <= arr[j]) {\n                temp[k++] = arr[i++];\n            } else {\n                temp[k++] = arr[j++];\n            }\n        }\n        while (i <= mid) temp[k++] = arr[i++];\n        while (j <= right) temp[k++] = arr[j++];\n        System.arraycopy(temp, 0, arr, left, temp.length);\n    }\n}', NULL, 1),
(227, 'JAVASCRIPT', 'const readline = require(\'readline\');\n\nconst rl = readline.createInterface({\n    input: process.stdin,\n    output: process.stdout\n});\n\nlet input = [];\n\nrl.on(\'line\', (line) => {\n    input.push(line.trim());\n});\n\nrl.on(\'close\', () => {\n    if (input.length === 0) return;\n    const tokens = input.join(\' \').split(/\\s+/).filter(s => s.length > 0);\n    if (tokens.length === 0) return;\n    const n = parseInt(tokens[0], 10);\n    const arr = [];\n    for (let i = 0; i < n; i++) {\n        arr.push(parseInt(tokens[i + 1], 10));\n    }\n    mergeSort(arr, 0, n - 1);\n    console.log(arr.join(\' \'));\n});\n\nfunction mergeSort(arr, left, right) {\n    if (left >= right) return;\n    const mid = left + Math.floor((right - left) / 2);\n    mergeSort(arr, left, mid);\n    mergeSort(arr, mid + 1, right);\n    merge(arr, left, mid, right);\n}\n\nfunction merge(arr, left, mid, right) {\n    const temp = new Array(right - left + 1);\n    let i = left, j = mid + 1, k = 0;\n    while (i <= mid && j <= right) {\n        if (arr[i] <= arr[j]) {\n            temp[k++] = arr[i++];\n        } else {\n            temp[k++] = arr[j++];\n        }\n    }\n    while (i <= mid) temp[k++] = arr[i++];\n    while (j <= right) temp[k++] = arr[j++];\n    for (let t = 0; t < temp.length; t++) {\n        arr[left + t] = temp[t];\n    }\n}', NULL, 1),
(227, 'PYTHON', 'import sys\n\ndef merge_sort(arr, left, right):\n    if left >= right:\n        return\n    mid = left + (right - left) // 2\n    merge_sort(arr, left, mid)\n    merge_sort(arr, mid + 1, right)\n    merge(arr, left, mid, right)\n\ndef merge(arr, left, mid, right):\n    temp = []\n    i, j = left, mid + 1\n    while i <= mid and j <= right:\n        if arr[i] <= arr[j]:\n            temp.append(arr[i])\n            i += 1\n        else:\n            temp.append(arr[j])\n            j += 1\n    while i <= mid:\n        temp.append(arr[i])\n        i += 1\n    while j <= right:\n        temp.append(arr[j])\n        j += 1\n    arr[left:right + 1] = temp\n\ndef main():\n    data = sys.stdin.read().split()\n    if not data:\n        return\n    n = int(data[0])\n    arr = list(map(int, data[1:1 + n]))\n    merge_sort(arr, 0, n - 1)\n    print(\' \'.join(map(str, arr)))\n\nif __name__ == \"__main__\":\n    main()', NULL, 1),
(228, 'C', '#include <stdio.h>\n\nint main() {\n    int n;\n    scanf(\"%d\", &n);\n    int arr[n];\n    for (int i = 0; i < n; i++) {\n        scanf(\"%d\", &arr[i]);\n    }\n    for (int i = 0; i < n - 1; i++) {\n        for (int j = 0; j < n - 1 - i; j++) {\n            if (arr[j] > arr[j + 1]) {\n                int temp = arr[j];\n                arr[j] = arr[j + 1];\n                arr[j + 1] = temp;\n            }\n        }\n    }\n    for (int i = 0; i < n; i++) {\n        if (i > 0) {\n            printf(\" \");\n        }\n        printf(\"%d\", arr[i]);\n    }\n    printf(\"\\n\");\n    return 0;\n}', NULL, 1),
