(237, 'C', '#include <stdio.h>\n#include <string.h>\n\nint getValue(char c) {\n    switch (c) {\n        case \'I\': return 1;\n        case \'V\': return 5;\n        case \'X\': return 10;\n        case \'L\': return 50;\n        case \'C\': return 100;\n        case \'D\': return 500;\n        case \'M\': return 1000;\n        default: return 0;\n    }\n}\n\nint main() {\n    char s[1000];\n    if (fgets(s, sizeof(s), stdin) == NULL) return 0;\n    s[strcspn(s, \"\\n\")] = \'\\0\';\n    int result = 0;\n    int prev = 0;\n    int len = strlen(s);\n    for (int i = len - 1; i >= 0; i--) {\n        int value = getValue(s[i]);\n        if (value < prev) {\n            result -= value;\n        } else {\n            result += value;\n            prev = value;\n        }\n    }\n    printf(\"%d\\n\", result);\n    return 0;\n}', NULL, 1),
(237, 'CPP', '#include <iostream>\n#include <string>\nusing namespace std;\n\nint getValue(char c) {\n    switch (c) {\n        case \'I\': return 1;\n        case \'V\': return 5;\n        case \'X\': return 10;\n        case \'L\': return 50;\n        case \'C\': return 100;\n        case \'D\': return 500;\n        case \'M\': return 1000;\n        default: return 0;\n    }\n}\n\nint main() {\n    string s;\n    getline(cin, s);\n    int result = 0;\n    int prev = 0;\n    for (int i = s.length() - 1; i >= 0; i--) {\n        int value = getValue(s[i]);\n        if (value < prev) {\n            result -= value;\n        } else {\n            result += value;\n            prev = value;\n        }\n    }\n    cout << result << endl;\n    return 0;\n}', NULL, 1),
(237, 'JAVA', 'import java.util.Scanner;\n\npublic class Main {\n    public static void main(String[] args) {\n        Scanner scanner = new Scanner(System.in);\n        String s = scanner.nextLine().trim();\n        int result = 0;\n        int prev = 0;\n        for (int i = s.length() - 1; i >= 0; i--) {\n            int curr = value(s.charAt(i));\n            if (curr < prev) {\n                result -= curr;\n            } else {\n                result += curr;\n            }\n            prev = curr;\n        }\n        System.out.println(result);\n    }\n\n    private static int value(char c) {\n        switch (c) {\n            case \'I\': return 1;\n            case \'V\': return 5;\n            case \'X\': return 10;\n            case \'L\': return 50;\n            case \'C\': return 100;\n            case \'D\': return 500;\n            case \'M\': return 1000;\n            default: return 0;\n        }\n    }\n}', NULL, 1),
(237, 'JAVASCRIPT', 'const readline = require(\'readline\');\n\nconst rl = readline.createInterface({\n    input: process.stdin,\n    output: process.stdout\n});\n\nrl.on(\'line\', (input) => {\n    const s = input.trim();\n    let result = 0;\n    let prev = 0;\n    for (let i = s.length - 1; i >= 0; i--) {\n        const value = getValue(s[i]);\n        if (value < prev) {\n            result -= value;\n        } else {\n            result += value;\n            prev = value;\n        }\n    }\n    console.log(result);\n    rl.close();\n});\n\nfunction getValue(c) {\n    switch (c) {\n        case \'I\': return 1;\n        case \'V\': return 5;\n        case \'X\': return 10;\n        case \'L\': return 50;\n        case \'C\': return 100;\n        case \'D\': return 500;\n        case \'M\': return 1000;\n        default: return 0;\n    }\n}', NULL, 1),
(237, 'PYTHON', 's = input().strip()\nresult = 0\nprev = 0\nvalues = {\'I\': 1, \'V\': 5, \'X\': 10, \'L\': 50, \'C\': 100, \'D\': 500, \'M\': 1000}\nfor c in reversed(s):\n    value = values.get(c, 0)\n    if value < prev:\n        result -= value\n    else:\n        result += value\n        prev = value\nprint(result)', NULL, 1),
(238, 'C', '#include <stdio.h>\n#include <limits.h>\n\nint main() {\n    int x;\n    scanf(\"%d\", &x);\n    int rev = 0;\n    while (x != 0) {\n        int pop = x % 10;\n        x /= 10;\n        if (rev > INT_MAX / 10 || (rev == INT_MAX / 10 && pop > 7)) {\n            printf(\"0\\n\");\n            return 0;\n        }\n        if (rev < INT_MIN / 10 || (rev == INT_MIN / 10 && pop < -8)) {\n            printf(\"0\\n\");\n            return 0;\n        }\n        rev = rev * 10 + pop;\n    }\n    printf(\"%d\\n\", rev);\n    return 0;\n}', NULL, 1),
(238, 'CPP', '#include <iostream>\n#include <climits>\n\nint main() {\n    int x;\n    std::cin >> x;\n    int rev = 0;\n    while (x != 0) {\n        int pop = x % 10;\n        x /= 10;\n        if (rev > INT_MAX / 10 || (rev == INT_MAX / 10 && pop > 7)) {\n            std::cout << 0 << std::endl;\n            return 0;\n        }\n        if (rev < INT_MIN / 10 || (rev == INT_MIN / 10 && pop < -8)) {\n            std::cout << 0 << std::endl;\n            return 0;\n        }\n        rev = rev * 10 + pop;\n    }\n    std::cout << rev << std::endl;\n    return 0;\n}', NULL, 1),
(238, 'JAVA', 'import java.util.Scanner;\n\npublic class Main {\n    public static void main(String[] args) {\n        Scanner sc = new Scanner(System.in);\n        int x = sc.nextInt();\n        int rev = 0;\n        while (x != 0) {\n            int pop = x % 10;\n            x /= 10;\n            if (rev > Integer.MAX_VALUE / 10 || (rev == Integer.MAX_VALUE / 10 && pop > 7)) {\n                System.out.println(0);\n                return;\n            }\n            if (rev < Integer.MIN_VALUE / 10 || (rev == Integer.MIN_VALUE / 10 && pop < -8)) {\n                System.out.println(0);\n                return;\n            }\n            rev = rev * 10 + pop;\n        }\n        System.out.println(rev);\n    }\n}', NULL, 1),
(238, 'JAVASCRIPT', 'const readline = require(\'readline\');\n\nconst rl = readline.createInterface({\n    input: process.stdin,\n    output: process.stdout\n});\n\nrl.on(\'line\', (line) => {\n    let x = parseInt(line.trim(), 10);\n    let rev = 0;\n    while (x !== 0) {\n        let pop = x % 10;\n        x = Math.trunc(x / 10);\n        if (rev > 214748364 || (rev === 214748364 && pop > 7)) {\n            console.log(0);\n            rl.close();\n            return;\n        }\n        if (rev < -214748364 || (rev === -214748364 && pop < -8)) {\n            console.log(0);\n            rl.close();\n            return;\n        }\n        rev = rev * 10 + pop;\n    }\n    console.log(rev);\n    rl.close();\n});', NULL, 1),
(238, 'PYTHON', 'import sys\n\ndef main():\n    data = sys.stdin.read().strip().split()\n    if not data:\n        return\n    x = int(data[0])\n    rev = 0\n    INT_MAX = 2**31 - 1\n    INT_MIN = -2**31\n    while x != 0:\n        pop = x % 10\n        x = int(x / 10)\n        if rev > INT_MAX // 10 or (rev == INT_MAX // 10 and pop > 7):\n            print(0)\n            return\n        if rev < INT_MIN // 10 or (rev == INT_MIN // 10 and pop < -8):\n            print(0)\n            return\n        rev = rev * 10 + pop\n    print(rev)\n\nif __name__ == \"__main__\":\n    main()', NULL, 1),
(239, 'C', '#include <stdio.h>\n#include <stdbool.h>\n\nbool isPalindrome(int x) {\n    if (x < 0 || (x % 10 == 0 && x != 0)) {\n        return false;\n    }\n    int reversed = 0;\n    while (x > reversed) {\n        reversed = reversed * 10 + x % 10;\n        x /= 10;\n    }\n    return x == reversed || x == reversed / 10;\n}\n\nint main() {\n    int x;\n    if (scanf(\"%d\", &x) == 1) {\n        if (isPalindrome(x)) {\n            printf(\"true\\n\");\n        } else {\n            printf(\"false\\n\");\n        }\n    }\n    return 0;\n}', NULL, 1),
(239, 'CPP', '#include <iostream>\nusing namespace std;\n\nbool isPalindrome(int x) {\n    if (x < 0 || (x % 10 == 0 && x != 0)) {\n        return false;\n    }\n    int reversed = 0;\n    while (x > reversed) {\n        reversed = reversed * 10 + x % 10;\n        x /= 10;\n    }\n    return x == reversed || x == reversed / 10;\n}\n\nint main() {\n    int x;\n    if (cin >> x) {\n        cout << (isPalindrome(x) ? \"true\" : \"false\") << endl;\n    }\n    return 0;\n}', NULL, 1),
(239, 'JAVA', 'import java.util.Scanner;\n\npublic class Main {\n    public static void main(String[] args) {\n        Scanner scanner = new Scanner(System.in);\n        int x = scanner.nextInt();\n        System.out.println(isPalindrome(x));\n    }\n\n    private static boolean isPalindrome(int x) {\n        if (x < 0 || (x % 10 == 0 && x != 0)) {\n            return false;\n        }\n        int reversed = 0;\n        while (x > reversed) {\n            reversed = reversed * 10 + x % 10;\n            x /= 10;\n        }\n        return x == reversed || x == reversed / 10;\n    }\n}', NULL, 1),
(239, 'JAVASCRIPT', 'const readline = require(\'readline\');\n\nconst rl = readline.createInterface({\n    input: process.stdin,\n    output: process.stdout\n});\n\nrl.on(\'line\', (line) => {\n    const x = parseInt(line.trim(), 10);\n    if (!isNaN(x)) {\n        console.log(isPalindrome(x));\n    }\n    rl.close();\n});\n\nfunction isPalindrome(x) {\n    if (x < 0 || (x % 10 === 0 && x !== 0)) {\n        return false;\n    }\n    let reversed = 0;\n    while (x > reversed) {\n        reversed = reversed * 10 + x % 10;\n        x = Math.floor(x / 10);\n    }\n    return x === reversed || x === Math.floor(reversed / 10);\n}', NULL, 1),
(239, 'PYTHON', 'import sys\n\ndef is_palindrome(x):\n    if x < 0 or (x % 10 == 0 and x != 0):\n        return False\n    reversed_num = 0\n    while x > reversed_num:\n        reversed_num = reversed_num * 10 + x % 10\n        x //= 10\n    return x == reversed_num or x == reversed_num // 10\n\ndef main():\n    data = sys.stdin.read().strip().split()\n    if data:\n        x = int(data[0])\n        print(\"true\" if is_palindrome(x) else \"false\")\n\nif __name__ == \"__main__\":\n    main()', NULL, 1),
(240, 'C', '#include <stdio.h>\n#include <stdlib.h>\n#include <string.h>\n\nchar* multiply(char* num1, char* num2) {\n    if (strcmp(num1, \"0\") == 0 || strcmp(num2, \"0\") == 0) {\n        char* zero = (char*)malloc(2);\n        zero[0] = \'0\';\n        zero[1] = \'\\0\';\n        return zero;\n    }\n    int m = strlen(num1);\n    int n = strlen(num2);\n    int* res = (int*)calloc(m + n, sizeof(int));\n    for (int i = m - 1; i >= 0; i--) {\n        for (int j = n - 1; j >= 0; j--) {\n            int mul = (num1[i] - \'0\') * (num2[j] - \'0\');\n            int p1 = i + j;\n            int p2 = i + j + 1;\n            int sum = mul + res[p2];\n            res[p2] = sum % 10;\n            res[p1] += sum / 10;\n        }\n    }\n    char* result = (char*)malloc(m + n + 1);\n    int idx = 0;\n    int i = 0;\n    while (i < m + n && res[i] == 0) i++;\n    while (i < m + n) {\n        result[idx++] = res[i] + \'0\';\n        i++;\n    }\n    result[idx] = \'\\0\';\n    free(res);\n    return result;\n}\n\nint main() {\n    char num1[1000], num2[1000];\n    scanf(\"%s %s\", num1, num2);\n    char* result = multiply(num1, num2);\n    printf(\"%s\\n\", result);\n    free(result);\n    return 0;\n}', NULL, 1),
(240, 'CPP', '#include <iostream>\n#include <string>\n#include <vector>\n\nusing namespace std;\n\nstring multiply(string num1, string num2) {\n    if (num1 == \"0\" || num2 == \"0\") {\n        return \"0\";\n    }\n    int m = num1.length();\n    int n = num2.length();\n    vector<int> res(m + n, 0);\n    for (int i = m - 1; i >= 0; i--) {\n        int x = num1[i] - \'0\';\n        for (int j = n - 1; j >= 0; j--) {\n            int y = num2[j] - \'0\';\n            int sum = res[i + j + 1] + x * y;\n            res[i + j + 1] = sum % 10;\n            res[i + j] += sum / 10;\n        }\n    }\n    string sb;\n    for (int i = 0; i < (int)res.size(); i++) {\n        if (sb.empty() && res[i] == 0) {\n            continue;\n        }\n        sb += to_string(res[i]);\n    }\n    return sb;\n}\n\nint main() {\n    string num1, num2;\n    cin >> num1 >> num2;\n    cout << multiply(num1, num2) << endl;\n    return 0;\n}', NULL, 1),
(240, 'JAVA', 'import java.util.Scanner;\n\npublic class Main {\n    public static void main(String[] args) {\n        Scanner sc = new Scanner(System.in);\n        String num1 = sc.next();\n        String num2 = sc.next();\n        System.out.println(multiply(num1, num2));\n    }\n\n    public static String multiply(String num1, String num2) {\n        if (\"0\".equals(num1) || \"0\".equals(num2)) {\n            return \"0\";\n        }\n        int m = num1.length();\n        int n = num2.length();\n        int[] res = new int[m + n];\n        for (int i = m - 1; i >= 0; i--) {\n            int x = num1.charAt(i) - \'0\';\n            for (int j = n - 1; j >= 0; j--) {\n                int y = num2.charAt(j) - \'0\';\n                int sum = res[i + j + 1] + x * y;\n                res[i + j + 1] = sum % 10;\n                res[i + j] += sum / 10;\n            }\n        }\n        StringBuilder sb = new StringBuilder();\n        for (int i = 0; i < res.length; i++) {\n            if (sb.length() == 0 && res[i] == 0) {\n                continue;\n            }\n            sb.append(res[i]);\n        }\n        return sb.toString();\n    }\n}', NULL, 1),
(240, 'JAVASCRIPT', 'const readline = require(\'readline\');\n\nconst rl = readline.createInterface({\n    input: process.stdin,\n    output: process.stdout\n});\n\nlet input = [];\nrl.on(\'line\', (line) => {\n    input.push(line.trim());\n});\n\nrl.on(\'close\', () => {\n    const [num1, num2] = input[0].split(\' \');\n    console.log(multiply(num1, num2));\n});\n\nfunction multiply(num1, num2) {\n    if (num1 === \"0\" || num2 === \"0\") {\n        return \"0\";\n    }\n    const m = num1.length;\n    const n = num2.length;\n    const res = new Array(m + n).fill(0);\n    for (let i = m - 1; i >= 0; i--) {\n        const x = num1.charCodeAt(i) - \'0\'.charCodeAt(0);\n        for (let j = n - 1; j >= 0; j--) {\n            const y = num2.charCodeAt(j) - \'0\'.charCodeAt(0);\n            const sum = res[i + j + 1] + x * y;\n            res[i + j + 1] = sum % 10;\n            res[i + j] += Math.floor(sum / 10);\n        }\n    }\n    let sb = \"\";\n    for (let i = 0; i < res.length; i++) {\n        if (sb.length === 0 && res[i] === 0) {\n            continue;\n        }\n        sb += res[i];\n    }\n    return sb;\n}', NULL, 1),
(240, 'PYTHON', 'import sys\n\ndef multiply(num1, num2):\n    if num1 == \"0\" or num2 == \"0\":\n        return \"0\"\n    m, n = len(num1), len(num2)\n    res = [0] * (m + n)\n    for i in range(m - 1, -1, -1):\n        x = ord(num1[i]) - ord(\'0\')\n        for j in range(n - 1, -1, -1):\n            y = ord(num2[j]) - ord(\'0\')\n            total = res[i + j + 1] + x * y\n            res[i + j + 1] = total % 10\n            res[i + j] += total // 10\n    result = []\n    for num in res:\n        if not result and num == 0:\n            continue\n        result.append(str(num))\n    return \'\'.join(result)\n\ndef main():\n    data = sys.stdin.read().split()\n    num1, num2 = data[0], data[1]\n    print(multiply(num1, num2))\n\nif __name__ == \"__main__\":\n    main()', NULL, 1),
(241, 'C', '#include <stdio.h>\n#include <stdlib.h>\n#include <string.h>\n\nstruct TreeNode {\n    int val;\n    struct TreeNode *left;\n    struct TreeNode *right;\n};\n\nstatic int maxDepth(struct TreeNode* root) {\n    if (root == NULL) return 0;\n    int left = maxDepth(root->left);\n    int right = maxDepth(root->right);\n    return 1 + (left > right ? left : right);\n}\n\nstatic struct TreeNode* newNode(int val) {\n    struct TreeNode* node = (struct TreeNode*)malloc(sizeof(struct TreeNode));\n    node->val = val;\n    node->left = NULL;\n    node->right = NULL;\n    return node;\n}\n\nint main(void) {\n    char line[1000000];\n    if (fgets(line, sizeof(line), stdin) == NULL) return 0;\n\n    size_t len = strlen(line);\n    while (len > 0 && (line[len - 1] == \'\\n\' || line[len - 1] == \'\\r\')) {\n        line[--len] = \'\\0\';\n    }\n\n    char *start = line;\n    while (*start == \' \' || *start == \'\\t\') start++;\n    char *end = start + strlen(start);\n    while (end > start && (end[-1] == \' \' || end[-1] == \'\\t\')) {\n        *--end = \'\\0\';\n    }\n\n    if (*start == \'[\') {\n        start++;\n        if (end > start && end[-1] == \']\') {\n            end[-1] = \'\\0\';\n        }\n    }\n\n    if (*start == \'\\0\') {\n        printf(\"0\\n\");\n        return 0;\n    }\n\n    int capacity = 1024;\n    int *nums = (int*)malloc(sizeof(int) * capacity);\n    int *isNull = (int*)malloc(sizeof(int) * capacity);\n    int count = 0;\n\n    char *token = strtok(start, \",\");\n    while (token != NULL) {\n        while (*token == \' \' || *token == \'\\t\') token++;\n        char *tend = token + strlen(token);\n        while (tend > token && (tend[-1] == \' \' || tend[-1] == \'\\t\')) {\n            *--tend = \'\\0\';\n        }\n\n        if (count >= capacity) {\n            capacity *= 2;\n            nums = (int*)realloc(nums, sizeof(int) * capacity);\n            isNull = (int*)realloc(isNull, sizeof(int) * capacity);\n        }\n\n        if (strcmp(token, \"null\") == 0) {\n            isNull[count] = 1;\n            nums[count] = 0;\n        } else {\n            isNull[count] = 0;\n            nums[count] = atoi(token);\n        }\n        count++;\n        token = strtok(NULL, \",\");\n    }\n\n    if (count == 0 || isNull[0]) {\n        printf(\"0\\n\");\n        free(nums);\n        free(isNull);\n        return 0;\n    }\n\n    struct TreeNode **queue = (struct TreeNode**)malloc(sizeof(struct TreeNode*) * (count + 1));\n    int head = 0, tail = 0;\n\n    struct TreeNode *root = newNode(nums[0]);\n    queue[tail++] = root;\n    int i = 1;\n\n    while (head < tail && i < count) {\n        struct TreeNode *node = queue[head++];\n\n        if (i < count && !isNull[i]) {\n            node->left = newNode(nums[i]);\n            queue[tail++] = node->left;\n        }\n        i++;\n\n        if (i < count && !isNull[i]) {\n            node->right = newNode(nums[i]);\n            queue[tail++] = node->right;\n        }\n        i++;\n    }\n\n    printf(\"%d\\n\", maxDepth(root));\n\n    free(queue);\n    free(nums);\n    free(isNull);\n    return 0;\n}', NULL, 1),
(241, 'CPP', '#include <iostream>\n#include <string>\n#include <vector>\n#include <queue>\n#include <sstream>\n#include <algorithm>\n\nusing namespace std;\n\nstruct TreeNode {\n    int val;\n    TreeNode *left;\n    TreeNode *right;\n    TreeNode(int x) : val(x), left(nullptr), right(nullptr) {}\n};\n\nTreeNode* buildTree(vector<string>& nums) {\n    if (nums.empty() || nums[0] == \"null\") return nullptr;\n    TreeNode* root = new TreeNode(stoi(nums[0]));\n    queue<TreeNode*> q;\n    q.push(root);\n    int i = 1;\n    while (!q.empty() && i < (int)nums.size()) {\n        TreeNode* node = q.front();\n        q.pop();\n        if (i < (int)nums.size() && nums[i] != \"null\") {\n            node->left = new TreeNode(stoi(nums[i]));\n            q.push(node->left);\n        }\n        i++;\n        if (i < (int)nums.size() && nums[i] != \"null\") {\n            node->right = new TreeNode(stoi(nums[i]));\n            q.push(node->right);\n        }\n        i++;\n    }\n    return root;\n}\n\nint maxDepth(TreeNode* root) {\n    if (root == nullptr) return 0;\n    return 1 + max(maxDepth(root->left), maxDepth(root->right));\n}\n\nint main() {\n    string line;\n    getline(cin, line);\n    while (!line.empty() && (line.front() == \' \' || line.front() == \'\\t\')) line.erase(line.begin());\n    while (!line.empty() && (line.back() == \' \' || line.back() == \'\\t\' || line.back() == \'\\r\')) line.pop_back();\n    if (!line.empty() && line.front() == \'[\') {\n        line = line.substr(1, line.size() - 2);\n    }\n    if (line.empty()) {\n        cout << 0 << endl;\n        return 0;\n    }\n    vector<string> parts;\n    stringstream ss(line);\n    string token;\n    while (getline(ss, token, \',\')) {\n        size_t start = token.find_first_not_of(\" \\t\");\n        size_t end = token.find_last_not_of(\" \\t\");\n        if (start == string::npos) {\n            parts.push_back(\"\");\n        } else {\n            parts.push_back(token.substr(start, end - start + 1));\n        }\n    }\n    TreeNode* root = buildTree(parts);\n    cout << maxDepth(root) << endl;\n    return 0;\n}', NULL, 1),
(241, 'JAVA', 'import java.util.*;\n\npublic class Main {\n    public static void main(String[] args) {\n        Scanner sc = new Scanner(System.in);\n        String line = sc.nextLine().trim();\n        if (line.startsWith(\"[\")) {\n            line = line.substring(1, line.length() - 1);\n        }\n        if (line.isEmpty()) {\n            System.out.println(0);\n            return;\n        }\n        String[] parts = line.split(\",\");\n        Integer[] nums = new Integer[parts.length];\n        for (int i = 0; i < parts.length; i++) {\n            String s = parts[i].trim();\n            if (s.equals(\"null\")) {\n                nums[i] = null;\n            } else {\n                nums[i] = Integer.parseInt(s);\n            }\n        }\n        TreeNode root = buildTree(nums);\n        System.out.println(maxDepth(root));\n    }\n\n    private static TreeNode buildTree(Integer[] nums) {\n        if (nums == null || nums.length == 0 || nums[0] == null) {\n            return null;\n        }\n        TreeNode root = new TreeNode(nums[0]);\n        Queue<TreeNode> queue = new LinkedList<>();\n        queue.offer(root);\n        int i = 1;\n        while (!queue.isEmpty() && i < nums.length) {\n            TreeNode node = queue.poll();\n            if (i < nums.length && nums[i] != null) {\n                node.left = new TreeNode(nums[i]);\n                queue.offer(node.left);\n            }\n            i++;\n            if (i < nums.length && nums[i] != null) {\n                node.right = new TreeNode(nums[i]);\n                queue.offer(node.right);\n            }\n            i++;\n        }\n        return root;\n    }\n\n    private static int maxDepth(TreeNode root) {\n        if (root == null) {\n            return 0;\n        }\n        return 1 + Math.max(maxDepth(root.left), maxDepth(root.right));\n    }\n\n    static class TreeNode {\n        int val;\n        TreeNode left;\n        TreeNode right;\n        TreeNode(int val) {\n            this.val = val;\n        }\n    }\n}', NULL, 1),
(241, 'JAVASCRIPT', 'const readline = require(\'readline\');\n\nconst rl = readline.createInterface({\n    input: process.stdin,\n    output: process.stdout\n});\n\nrl.on(\'line\', (input) => {\n    let line = input.trim();\n    if (line.startsWith(\'[\')) {\n        line = line.substring(1, line.length - 1);\n    }\n    if (line.length === 0) {\n        console.log(0);\n        rl.close();\n        return;\n    }\n    const parts = line.split(\',\');\n    const nums = parts.map(s => {\n        s = s.trim();\n        return s === \'null\' ? null : parseInt(s, 10);\n    });\n\n    const root = buildTree(nums);\n    console.log(maxDepth(root));\n    rl.close();\n});\n\nclass TreeNode {\n    constructor(val) {\n        this.val = val;\n        this.left = null;\n        this.right = null;\n    }\n}\n\nfunction buildTree(nums) {\n    if (!nums || nums.length === 0 || nums[0] === null) return null;\n    const root = new TreeNode(nums[0]);\n    const queue = [root];\n    let i = 1;\n    while (queue.length > 0 && i < nums.length) {\n        const node = queue.shift();\n        if (i < nums.length && nums[i] !== null) {\n            node.left = new TreeNode(nums[i]);\n            queue.push(node.left);\n        }\n        i++;\n        if (i < nums.length && nums[i] !== null) {\n            node.right = new TreeNode(nums[i]);\n            queue.push(node.right);\n        }\n        i++;\n    }\n    return root;\n}\n\nfunction maxDepth(root) {\n    if (root === null) return 0;\n    return 1 + Math.max(maxDepth(root.left), maxDepth(root.right));\n}', NULL, 1),
(241, 'PYTHON', 'import sys\nfrom collections import deque\n\nclass TreeNode:\n    def __init__(self, val=0, left=None, right=None):\n        self.val = val\n        self.left = left\n        self.right = right\n\ndef build_tree(nums):\n    if not nums or nums[0] is None:\n        return None\n    root = TreeNode(nums[0])\n    queue = deque([root])\n    i = 1\n    while queue and i < len(nums):\n        node = queue.popleft()\n        if i < len(nums) and nums[i] is not None:\n            node.left = TreeNode(nums[i])\n            queue.append(node.left)\n        i += 1\n        if i < len(nums) and nums[i] is not None:\n            node.right = TreeNode(nums[i])\n            queue.append(node.right)\n        i += 1\n    return root\n\ndef max_depth(root):\n    if root is None:\n        return 0\n    return 1 + max(max_depth(root.left), max_depth(root.right))\n\ndef main():\n    line = sys.stdin.readline().strip()\n    if line.startswith(\"[\"):\n        line = line[1:-1]\n    if not line:\n        print(0)\n        return\n    parts = line.split(\",\")\n    nums = []\n    for s in parts:\n        s = s.strip()\n        if s == \"null\":\n            nums.append(None)\n        else:\n            nums.append(int(s))\n    root = build_tree(nums)\n    print(max_depth(root))\n\nif __name__ == \"__main__\":\n    main()', NULL, 1),
(242, 'C', '#include <stdio.h>\n#include <stdlib.h>\n#include <string.h>\n#include <ctype.h>\n\ntypedef struct TreeNode {\n    int val;\n    struct TreeNode *left;\n    struct TreeNode *right;\n} TreeNode;\n\ntypedef struct {\n    TreeNode **data;\n    int front;\n    int rear;\n    int size;\n} Queue;\n\nvoid initQueue(Queue *q, int size) {\n    q->data = (TreeNode **)malloc(sizeof(TreeNode *) * size);\n    q->front = 0;\n    q->rear = 0;\n    q->size = size;\n}\n\nvoid enqueue(Queue *q, TreeNode *node) {\n    q->data[q->rear++] = node;\n}\n\nTreeNode *dequeue(Queue *q) {\n    return q->data[q->front++];\n}\n\nint isEmpty(Queue *q) {\n    return q->front == q->rear;\n}\n\nTreeNode *newNode(int val) {\n    TreeNode *node = (TreeNode *)malloc(sizeof(TreeNode));\n    node->val = val;\n    node->left = NULL;\n    node->right = NULL;\n    return node;\n}\n\nTreeNode *buildTree(char *s) {\n    int len = strlen(s);\n    while (len > 0 && isspace(s[len - 1])) {\n        s[--len] = \'\\0\';\n    }\n    int start = 0;\n    while (start < len && isspace(s[start])) {\n        start++;\n    }\n    if (len - start <= 2) return NULL;\n    char *content = (char *)malloc(sizeof(char) * (len - start));\n    strncpy(content, s + start + 1, len - start - 2);\n    content[len - start - 2] = \'\\0\';\n\n    char *trimmed = content;\n    while (*trimmed && isspace(*trimmed)) trimmed++;\n    if (*trimmed == \'\\0\') {\n        free(content);\n        return NULL;\n    }\n\n    char *parts[10000];\n    int partCount = 0;\n    char *token = strtok(content, \",\");\n    while (token != NULL) {\n        parts[partCount++] = token;\n        token = strtok(NULL, \",\");\n    }\n\n    char *first = parts[0];\n    while (*first && isspace(*first)) first++;\n    if (strcmp(first, \"null\") == 0) {\n        free(content);\n        return NULL;\n    }\n\n    TreeNode *root = newNode(atoi(first));\n    Queue q;\n    initQueue(&q, partCount + 1);\n    enqueue(&q, root);\n    int i = 1;\n    while (!isEmpty(&q) && i < partCount) {\n        TreeNode *node = dequeue(&q);\n        if (i < partCount) {\n            char *leftVal = parts[i];\n            while (*leftVal && isspace(*leftVal)) leftVal++;\n            if (strcmp(leftVal, \"null\") != 0) {\n                node->left = newNode(atoi(leftVal));\n                enqueue(&q, node->left);\n            }\n            i++;\n        }\n        if (i < partCount) {\n            char *rightVal = parts[i];\n            while (*rightVal && isspace(*rightVal)) rightVal++;\n            if (strcmp(rightVal, \"null\") != 0) {\n                node->right = newNode(atoi(rightVal));\n                enqueue(&q, node->right);\n            }\n            i++;\n        }\n    }\n    free(q.data);\n    free(content);\n    return root;\n}\n\nint **levelOrder(TreeNode *root, int **columnSizes, int *returnSize) {\n    *returnSize = 0;\n    if (root == NULL) {\n        *columnSizes = NULL;\n        return NULL;\n    }\n\n    int capacity = 10000;\n    int **result = (int **)malloc(sizeof(int *) * capacity);\n    *columnSizes = (int *)malloc(sizeof(int) * capacity);\n\n    Queue q;\n    initQueue(&q, capacity);\n    enqueue(&q, root);\n\n    while (!isEmpty(&q)) {\n        int size = q.rear - q.front;\n        int *level = (int *)malloc(sizeof(int) * size);\n        for (int i = 0; i < size; i++) {\n            TreeNode *node = dequeue(&q);\n            level[i] = node->val;\n            if (node->left != NULL) enqueue(&q, node->left);\n            if (node->right != NULL) enqueue(&q, node->right);\n        }\n        result[*returnSize] = level;\n        (*columnSizes)[*returnSize] = size;\n        (*returnSize)++;\n    }\n\n    free(q.data);\n    return result;\n}\n\nvoid printResult(int **result, int *columnSizes, int returnSize) {\n    printf(\"[\");\n    for (int i = 0; i < returnSize; i++) {\n        printf(\"[\");\n        for (int j = 0; j < columnSizes[i]; j++) {\n            printf(\"%d\", result[i][j]);\n            if (j < columnSizes[i] - 1) printf(\",\");\n        }\n        printf(\"]\");\n        if (i < returnSize - 1) printf(\",\");\n    }\n    printf(\"]\\n\");\n}\n\nint main() {\n    char s[100000];\n    if (fgets(s, sizeof(s), stdin) == NULL) return 0;\n    int len = strlen(s);\n    while (len > 0 && (s[len - 1] == \'\\n\' || s[len - 1] == \'\\r\')) {\n        s[--len] = \'\\0\';\n    }\n\n    TreeNode *root = buildTree(s);\n    int *columnSizes;\n    int returnSize;\n    int **result = levelOrder(root, &columnSizes, &returnSize);\n    printResult(result, columnSizes, returnSize);\n\n    return 0;\n}', NULL, 1),
(242, 'CPP', '#include <iostream>\n#include <string>\n#include <vector>\n#include <queue>\n#include <sstream>\n\nusing namespace std;\n\nstruct TreeNode {\n    int val;\n    TreeNode* left;\n    TreeNode* right;\n    TreeNode(int x) : val(x), left(nullptr), right(nullptr) {}\n};\n\nTreeNode* buildTree(const string& s) {\n    string str = s;\n    size_t start = str.find_first_not_of(\" \\t\\n\\r\");\n    size_t end = str.find_last_not_of(\" \\t\\n\\r\");\n    if (start == string::npos) return nullptr;\n    str = str.substr(start, end - start + 1);\n    if (str.length() <= 2) return nullptr;\n    string content = str.substr(1, str.length() - 2);\n    size_t cstart = content.find_first_not_of(\" \\t\\n\\r\");\n    size_t cend = content.find_last_not_of(\" \\t\\n\\r\");\n    if (cstart == string::npos) return nullptr;\n    content = content.substr(cstart, cend - cstart + 1);\n    if (content.empty()) return nullptr;\n\n    vector<string> parts;\n    stringstream ss(content);\n    string item;\n    while (getline(ss, item, \',\')) {\n        size_t istart = item.find_first_not_of(\" \\t\\n\\r\");\n        size_t iend = item.find_last_not_of(\" \\t\\n\\r\");\n        if (istart == string::npos) {\n            parts.push_back(\"\");\n        } else {\n            parts.push_back(item.substr(istart, iend - istart + 1));\n        }\n    }\n\n    if (parts.empty() || parts[0] == \"null\") return nullptr;\n\n    TreeNode* root = new TreeNode(stoi(parts[0]));\n    queue<TreeNode*> q;\n    q.push(root);\n    int i = 1;\n    while (!q.empty() && i < (int)parts.size()) {\n        TreeNode* node = q.front();\n        q.pop();\n        if (i < (int)parts.size()) {\n            string leftVal = parts[i];\n            if (leftVal != \"null\") {\n                node->left = new TreeNode(stoi(leftVal));\n                q.push(node->left);\n            }\n            i++;\n        }\n        if (i < (int)parts.size()) {\n            string rightVal = parts[i];\n            if (rightVal != \"null\") {\n                node->right = new TreeNode(stoi(rightVal));\n                q.push(node->right);\n            }\n            i++;\n        }\n    }\n    return root;\n}\n\nvector<vector<int>> levelOrder(TreeNode* root) {\n    vector<vector<int>> result;\n    if (root == nullptr) return result;\n    queue<TreeNode*> q;\n    q.push(root);\n    while (!q.empty()) {\n        int size = q.size();\n        vector<int> level;\n        for (int i = 0; i < size; i++) {\n            TreeNode* node = q.front();\n            q.pop();\n            level.push_back(node->val);\n            if (node->left != nullptr) q.push(node->left);\n            if (node->right != nullptr) q.push(node->right);\n        }\n        result.push_back(level);\n    }\n    return result;\n}\n\nstring format(const vector<vector<int>>& result) {\n    string sb;\n    sb += \"[\";\n    for (int i = 0; i < (int)result.size(); i++) {\n        sb += \"[\";\n        const vector<int>& level = result[i];\n        for (int j = 0; j < (int)level.size(); j++) {\n            sb += to_string(level[j]);\n            if (j < (int)level.size() - 1) sb += \",\";\n        }\n        sb += \"]\";\n        if (i < (int)result.size() - 1) sb += \",\";\n    }\n    sb += \"]\";\n    return sb;\n}\n\nint main() {\n    string s;\n    getline(cin, s);\n    TreeNode* root = buildTree(s);\n    vector<vector<int>> result = levelOrder(root);\n    cout << format(result) << endl;\n    return 0;\n}', NULL, 1),
(242, 'JAVA', 'import java.util.*;\n\npublic class Main {\n    public static void main(String[] args) {\n        Scanner sc = new Scanner(System.in);\n        String s = sc.nextLine().trim();\n        if (s.startsWith(\"[\")) s = s.substring(1, s.length() - 1);\n        String[] parts = s.isEmpty() ? new String[0] : s.split(\",\");\n        TreeNode root = buildTree(parts);\n        List<List<Integer>> res = levelOrder(root);\n        System.out.println(format(res));\n    }\n\n    static TreeNode buildTree(String[] parts) {\n        if (parts.length == 0 || parts[0].trim().equals(\"null\")) return null;\n        TreeNode root = new TreeNode(Integer.parseInt(parts[0].trim()));\n        Queue<TreeNode> q = new LinkedList<>();\n        q.offer(root);\n        int i = 1;\n        while (!q.isEmpty() && i < parts.length) {\n            TreeNode cur = q.poll();\n            if (i < parts.length) {\n                String left = parts[i++].trim();\n                if (!left.equals(\"null\")) {\n                    cur.left = new TreeNode(Integer.parseInt(left));\n                    q.offer(cur.left);\n                }\n            }\n            if (i < parts.length) {\n                String right = parts[i++].trim();\n                if (!right.equals(\"null\")) {\n                    cur.right = new TreeNode(Integer.parseInt(right));\n                    q.offer(cur.right);\n                }\n            }\n        }\n        return root;\n    }\n\n    static List<List<Integer>> levelOrder(TreeNode root) {\n        List<List<Integer>> res = new ArrayList<>();\n        if (root == null) return res;\n        Queue<TreeNode> q = new LinkedList<>();\n        q.offer(root);\n        while (!q.isEmpty()) {\n            int size = q.size();\n            List<Integer> level = new ArrayList<>();\n            for (int i = 0; i < size; i++) {\n                TreeNode node = q.poll();\n                level.add(node.val);\n                if (node.left != null) q.offer(node.left);\n                if (node.right != null) q.offer(node.right);\n            }\n            res.add(level);\n        }\n        return res;\n    }\n\n    static String format(List<List<Integer>> res) {\n        StringBuilder sb = new StringBuilder();\n        sb.append(\"[\");\n        for (int i = 0; i < res.size(); i++) {\n            sb.append(\"[\");\n            List<Integer> level = res.get(i);\n            for (int j = 0; j < level.size(); j++) {\n                sb.append(level.get(j));\n                if (j < level.size() - 1) sb.append(\",\");\n            }\n            sb.append(\"]\");\n            if (i < res.size() - 1) sb.append(\",\");\n        }\n        sb.append(\"]\");\n        return sb.toString();\n    }\n\n    static class TreeNode {\n        int val;\n        TreeNode left;\n        TreeNode right;\n        TreeNode(int val) { this.val = val; }\n    }\n}', NULL, 1),
(242, 'JAVASCRIPT', 'const readline = require(\'readline\');\n\nclass TreeNode {\n    constructor(val) {\n        this.val = val;\n        this.left = null;\n        this.right = null;\n    }\n}\n\nfunction buildTree(s) {\n    s = s.trim();\n    if (s.length <= 2) return null;\n    const content = s.substring(1, s.length - 1).trim();\n    if (content.length === 0) return null;\n    const parts = content.split(\',\');\n    if (parts.length === 0 || parts[0].trim() === \'null\') return null;\n    const root = new TreeNode(parseInt(parts[0].trim(), 10));\n    const queue = [root];\n    let i = 1;\n    while (queue.length > 0 && i < parts.length) {\n        const node = queue.shift();\n        if (i < parts.length) {\n            const leftVal = parts[i].trim();\n            if (leftVal !== \'null\') {\n                node.left = new TreeNode(parseInt(leftVal, 10));\n                queue.push(node.left);\n            }\n            i++;\n        }\n        if (i < parts.length) {\n            const rightVal = parts[i].trim();\n            if (rightVal !== \'null\') {\n                node.right = new TreeNode(parseInt(rightVal, 10));\n                queue.push(node.right);\n            }\n            i++;\n        }\n    }\n    return root;\n}\n\nfunction levelOrder(root) {\n    const result = [];\n    if (root === null) return result;\n    const queue = [root];\n    while (queue.length > 0) {\n        const size = queue.length;\n        const level = [];\n        for (let i = 0; i < size; i++) {\n            const node = queue.shift();\n            level.push(node.val);\n            if (node.left !== null) queue.push(node.left);\n            if (node.right !== null) queue.push(node.right);\n        }\n        result.push(level);\n    }\n    return result;\n}\n\nfunction format(result) {\n    let sb = \'\';\n    sb += \'[\';\n    for (let i = 0; i < result.length; i++) {\n        sb += \'[\';\n        const level = result[i];\n        for (let j = 0; j < level.length; j++) {\n            sb += level[j];\n            if (j < level.length - 1) sb += \',\';\n        }\n        sb += \']\';\n        if (i < result.length - 1) sb += \',\';\n    }\n    sb += \']\';\n    return sb;\n}\n\nconst rl = readline.createInterface({\n    input: process.stdin,\n    output: process.stdout\n});\n\nrl.on(\'line\', (line) => {\n    const s = line.trim();\n    const root = buildTree(s);\n    const result = levelOrder(root);\n    console.log(format(result));\n    rl.close();\n});', NULL, 1),
(242, 'PYTHON', 'import sys\nfrom collections import deque\n\nclass TreeNode:\n    def __init__(self, val=0, left=None, right=None):\n        self.val = val\n        self.left = left\n        self.right = right\n\ndef build_tree(s):\n    s = s.strip()\n    if len(s) <= 2:\n        return None\n    content = s[1:-1].strip()\n    if not content:\n        return None\n    parts = content.split(\',\')\n    if not parts or parts[0].strip() == \'null\':\n        return None\n    root = TreeNode(int(parts[0].strip()))\n    queue = deque([root])\n    i = 1\n    while queue and i < len(parts):\n        node = queue.popleft()\n        if i < len(parts):\n            left_val = parts[i].strip()\n            if left_val != \'null\':\n                node.left = TreeNode(int(left_val))\n                queue.append(node.left)\n            i += 1\n        if i < len(parts):\n            right_val = parts[i].strip()\n            if right_val != \'null\':\n                node.right = TreeNode(int(right_val))\n                queue.append(node.right)\n            i += 1\n    return root\n\ndef level_order(root):\n    result = []\n    if root is None:\n        return result\n    queue = deque([root])\n    while queue:\n        size = len(queue)\n        level = []\n        for _ in range(size):\n            node = queue.popleft()\n            level.append(node.val)\n            if node.left:\n                queue.append(node.left)\n            if node.right:\n                queue.append(node.right)\n        result.append(level)\n    return result\n\ndef format_result(result):\n    sb = []\n    sb.append(\'[\')\n    for i, level in enumerate(result):\n        sb.append(\'[\')\n        for j, val in enumerate(level):\n            sb.append(str(val))\n            if j < len(level) - 1:\n                sb.append(\',\')\n        sb.append(\']\')\n        if i < len(result) - 1:\n            sb.append(\',\')\n    sb.append(\']\')\n    return \'\'.join(sb)\n\ndef main():\n    s = sys.stdin.readline().strip()\n    root = build_tree(s)\n    result = level_order(root)\n    print(format_result(result))\n\nif __name__ == \'__main__\':\n    main()', NULL, 1),
(243, 'C', '#include <stdio.h>\n#include <stdlib.h>\n#include <string.h>\n\ntypedef struct TreeNode {\n    int val;\n    struct TreeNode *left;\n    struct TreeNode *right;\n} TreeNode;\n\nTreeNode* createNode(int val) {\n    TreeNode* node = (TreeNode*)malloc(sizeof(TreeNode));\n    node->val = val;\n    node->left = NULL;\n    node->right = NULL;\n    return node;\n}\n\nTreeNode* buildTree(char** parts, int partsSize) {\n    if (partsSize == 0 || strcmp(parts[0], \"null\") == 0) {\n        return NULL;\n    }\n    TreeNode* root = createNode(atoi(parts[0]));\n    TreeNode** queue = (TreeNode**)malloc(sizeof(TreeNode*) * partsSize);\n    int front = 0, rear = 0;\n    queue[rear++] = root;\n    int i = 1;\n    while (front < rear && i < partsSize) {\n        TreeNode* node = queue[front++];\n        if (i < partsSize && strcmp(parts[i], \"null\") != 0) {\n            node->left = createNode(atoi(parts[i]));\n            queue[rear++] = node->left;\n        }\n        i++;\n        if (i < partsSize && strcmp(parts[i], \"null\") != 0) {\n            node->right = createNode(atoi(parts[i]));\n            queue[rear++] = node->right;\n        }\n        i++;\n    }\n    free(queue);\n    return root;\n}\n\nint* preorderTraversal(TreeNode* root, int* returnSize) {\n    int* result = (int*)malloc(sizeof(int) * 10000);\n    *returnSize = 0;\n    if (root == NULL) {\n        return result;\n    }\n    TreeNode** stack = (TreeNode**)malloc(sizeof(TreeNode*) * 10000);\n    int top = 0;\n    stack[top++] = root;\n    while (top > 0) {\n        TreeNode* node = stack[--top];\n        result[(*returnSize)++] = node->val;\n        if (node->right != NULL) {\n            stack[top++] = node->right;\n        }\n        if (node->left != NULL) {\n            stack[top++] = node->left;\n        }\n    }\n    free(stack);\n    return result;\n}\n\nint main() {\n    char line[100000];\n    if (fgets(line, sizeof(line), stdin) == NULL) {\n        printf(\"[]\\n\");\n        return 0;\n    }\n    int len = strlen(line);\n    while (len > 0 && (line[len-1] == \'\\n\' || line[len-1] == \'\\r\')) {\n        line[--len] = \'\\0\';\n    }\n    if (len == 0) {\n        printf(\"[]\\n\");\n        return 0;\n    }\n    char* content = line;\n    if (line[0] == \'[\' && line[len-1] == \']\') {\n        line[len-1] = \'\\0\';\n        content = line + 1;\n    }\n    char* parts[10000];\n    int partsSize = 0;\n    char* token = strtok(content, \",\");\n    while (token != NULL) {\n        while (*token == \' \') token++;\n        int tlen = strlen(token);\n        while (tlen > 0 && token[tlen-1] == \' \') {\n            token[--tlen] = \'\\0\';\n        }\n        parts[partsSize++] = token;\n        token = strtok(NULL, \",\");\n    }\n    TreeNode* root = buildTree(parts, partsSize);\n    int returnSize = 0;\n    int* result = preorderTraversal(root, &returnSize);\n    printf(\"[\");\n    for (int i = 0; i < returnSize; i++) {\n        if (i > 0) printf(\",\");\n        printf(\"%d\", result[i]);\n    }\n    printf(\"]\\n\");\n    free(result);\n    return 0;\n}', NULL, 1),
(243, 'CPP', '#include <iostream>\n#include <string>\n#include <vector>\n#include <queue>\n#include <stack>\n#include <sstream>\n\nusing namespace std;\n\nstruct TreeNode {\n    int val;\n    TreeNode *left;\n    TreeNode *right;\n    TreeNode(int x) : val(x), left(nullptr), right(nullptr) {}\n};\n\nTreeNode* buildTree(const vector<string>& parts) {\n    if (parts.empty() || parts[0] == \"null\") {\n        return nullptr;\n    }\n    TreeNode* root = new TreeNode(stoi(parts[0]));\n    queue<TreeNode*> q;\n    q.push(root);\n    int i = 1;\n    while (!q.empty() && i < (int)parts.size()) {\n        TreeNode* node = q.front();\n        q.pop();\n        if (i < (int)parts.size() && parts[i] != \"null\") {\n            node->left = new TreeNode(stoi(parts[i]));\n            q.push(node->left);\n        }\n        i++;\n        if (i < (int)parts.size() && parts[i] != \"null\") {\n            node->right = new TreeNode(stoi(parts[i]));\n            q.push(node->right);\n        }\n        i++;\n    }\n    return root;\n}\n\nvector<int> preorderTraversal(TreeNode* root) {\n    vector<int> result;\n    if (root == nullptr) {\n        return result;\n    }\n    stack<TreeNode*> st;\n    st.push(root);\n    while (!st.empty()) {\n        TreeNode* node = st.top();\n        st.pop();\n        result.push_back(node->val);\n        if (node->right != nullptr) {\n            st.push(node->right);\n        }\n        if (node->left != nullptr) {\n            st.push(node->left);\n        }\n    }\n    return result;\n}\n\nint main() {\n    string line;\n    getline(cin, line);\n    while (!line.empty() && (line.back() == \'\\r\' || line.back() == \'\\n\')) {\n        line.pop_back();\n    }\n    if (line.empty()) {\n        cout << \"[]\" << endl;\n        return 0;\n    }\n    line = line.substr(1, line.length() - 2);\n    vector<string> parts;\n    stringstream ss(line);\n    string item;\n    while (getline(ss, item, \',\')) {\n        size_t start = item.find_first_not_of(\" \\t\");\n        size_t end = item.find_last_not_of(\" \\t\");\n        if (start == string::npos) {\n            parts.push_back(\"\");\n        } else {\n            parts.push_back(item.substr(start, end - start + 1));\n        }\n    }\n    TreeNode* root = buildTree(parts);\n    vector<int> result = preorderTraversal(root);\n    cout << \"[\";\n    for (size_t i = 0; i < result.size(); i++) {\n        if (i > 0) cout << \",\";\n        cout << result[i];\n    }\n    cout << \"]\" << endl;\n    return 0;\n}', NULL, 1),
(243, 'JAVA', 'import java.util.*;\n\npublic class Main {\n    public static void main(String[] args) {\n        Scanner sc = new Scanner(System.in);\n        String line = sc.nextLine().trim();\n        if (line.isEmpty()) {\n            System.out.println(\"[]\");\n            return;\n        }\n        line = line.substring(1, line.length() - 1).trim();\n        if (line.isEmpty()) {\n            System.out.println(\"[]\");\n            return;\n        }\n        String[] parts = line.split(\",\");\n        Integer[] nums = new Integer[parts.length];\n        for (int i = 0; i < parts.length; i++) {\n            String s = parts[i].trim();\n            if (s.equals(\"null\")) {\n                nums[i] = null;\n            } else {\n                nums[i] = Integer.parseInt(s);\n            }\n        }\n        TreeNode root = buildTree(nums);\n        List<Integer> res = new ArrayList<>();\n        preorder(root, res);\n        StringBuilder sb = new StringBuilder();\n        sb.append(\"[\");\n        for (int i = 0; i < res.size(); i++) {\n            if (i > 0) sb.append(\",\");\n            sb.append(res.get(i));\n        }\n        sb.append(\"]\");\n        System.out.println(sb.toString());\n    }\n\n    private static TreeNode buildTree(Integer[] nums) {\n        if (nums == null || nums.length == 0 || nums[0] == null) return null;\n        TreeNode root = new TreeNode(nums[0]);\n        Queue<TreeNode> queue = new LinkedList<>();\n        queue.offer(root);\n        int i = 1;\n        while (!queue.isEmpty() && i < nums.length) {\n            TreeNode node = queue.poll();\n            if (i < nums.length && nums[i] != null) {\n                node.left = new TreeNode(nums[i]);\n                queue.offer(node.left);\n            }\n            i++;\n            if (i < nums.length && nums[i] != null) {\n                node.right = new TreeNode(nums[i]);\n                queue.offer(node.right);\n            }\n            i++;\n        }\n        return root;\n    }\n\n    private static void preorder(TreeNode root, List<Integer> res) {\n        if (root == null) return;\n        res.add(root.val);\n        preorder(root.left, res);\n        preorder(root.right, res);\n    }\n\n    static class TreeNode {\n        int val;\n        TreeNode left;\n        TreeNode right;\n        TreeNode(int val) {\n            this.val = val;\n        }\n    }\n}', NULL, 1),
(243, 'JAVASCRIPT', 'const readline = require(\'readline\');\n\nconst rl = readline.createInterface({\n    input: process.stdin,\n    output: process.stdout\n});\n\nrl.on(\'line\', (line) => {\n    line = line.trim();\n    if (line === \'\') {\n        console.log(\'[]\');\n        rl.close();\n        return;\n    }\n    line = line.substring(1, line.length - 1);\n    const parts = line.split(\',\');\n    const root = buildTree(parts);\n    const result = preorderTraversal(root);\n    console.log(\'[\' + result.join(\',\') + \']\');\n    rl.close();\n});\n\nfunction buildTree(parts) {\n    if (parts.length === 0 || parts[0].trim() === \'null\') {\n        return null;\n    }\n    const root = new TreeNode(parseInt(parts[0].trim()));\n    const queue = [root];\n    let i = 1;\n    while (queue.length > 0 && i < parts.length) {\n        const node = queue.shift();\n        if (i < parts.length && parts[i].trim() !== \'null\') {\n            node.left = new TreeNode(parseInt(parts[i].trim()));\n            queue.push(node.left);\n        }\n        i++;\n        if (i < parts.length && parts[i].trim() !== \'null\') {\n            node.right = new TreeNode(parseInt(parts[i].trim()));\n            queue.push(node.right);\n        }\n        i++;\n    }\n    return root;\n}\n\nfunction preorderTraversal(root) {\n    const result = [];\n    if (root === null) {\n        return result;\n    }\n    const stack = [root];\n    while (stack.length > 0) {\n        const node = stack.pop();\n        result.push(node.val);\n        if (node.right !== null) {\n            stack.push(node.right);\n        }\n        if (node.left !== null) {\n            stack.push(node.left);\n        }\n    }\n    return result;\n}\n\nclass TreeNode {\n    constructor(val) {\n        this.val = val;\n        this.left = null;\n        this.right = null;\n    }\n}', NULL, 1),
(243, 'PYTHON', 'import sys\nfrom collections import deque\n\nclass TreeNode:\n    def __init__(self, val=0, left=None, right=None):\n        self.val = val\n        self.left = left\n        self.right = right\n\ndef build_tree(parts):\n    if not parts or parts[0] == \"null\":\n        return None\n    root = TreeNode(int(parts[0]))\n    queue = deque([root])\n    i = 1\n    while queue and i < len(parts):\n        node = queue.popleft()\n        if i < len(parts) and parts[i] != \"null\":\n            node.left = TreeNode(int(parts[i]))\n            queue.append(node.left)\n        i += 1\n        if i < len(parts) and parts[i] != \"null\":\n            node.right = TreeNode(int(parts[i]))\n            queue.append(node.right)\n        i += 1\n    return root\n\ndef preorder_traversal(root):\n    result = []\n    if root is None:\n        return result\n    stack = [root]\n    while stack:\n        node = stack.pop()\n        result.append(node.val)\n        if node.right:\n            stack.append(node.right)\n        if node.left:\n            stack.append(node.left)\n    return result\n\ndef main():\n    line = sys.stdin.readline().strip()\n    if not line:\n        print(\"[]\")\n        return\n    line = line[1:-1]\n    parts = [p.strip() for p in line.split(\",\")]\n    root = build_tree(parts)\n    result = preorder_traversal(root)\n    print(str(result).replace(\" \", \"\"))\n\nif __name__ == \"__main__\":\n    main()', NULL, 1),
(244, 'C', '#include <stdio.h>\n#include <stdlib.h>\n#include <string.h>\n\ntypedef struct TreeNode {\n    int val;\n    struct TreeNode *left;\n    struct TreeNode *right;\n} TreeNode;\n\nTreeNode* createNode(int val) {\n    TreeNode* node = (TreeNode*)malloc(sizeof(TreeNode));\n    node->val = val;\n    node->left = NULL;\n    node->right = NULL;\n    return node;\n}\n\nTreeNode* buildTree(int* nums, int* isNull, int len) {\n    if (len == 0 || isNull[0]) return NULL;\n    TreeNode* root = createNode(nums[0]);\n    TreeNode** queue = (TreeNode**)malloc(sizeof(TreeNode*) * len);\n    int front = 0, rear = 0;\n    queue[rear++] = root;\n    int i = 1;\n    while (front < rear && i < len) {\n        TreeNode* node = queue[front++];\n        if (i < len && !isNull[i]) {\n            node->left = createNode(nums[i]);\n            queue[rear++] = node->left;\n        }\n        i++;\n        if (i < len && !isNull[i]) {\n            node->right = createNode(nums[i]);\n            queue[rear++] = node->right;\n        }\n        i++;\n    }\n    free(queue);\n    return root;\n}\n\nint* inorderTraversal(TreeNode* root, int* returnSize) {\n    int* res = (int*)malloc(sizeof(int) * 10000);\n    TreeNode** stack = (TreeNode**)malloc(sizeof(TreeNode*) * 10000);\n    int top = 0;\n    int count = 0;\n    TreeNode* cur = root;\n    while (cur != NULL || top > 0) {\n        while (cur != NULL) {\n            stack[top++] = cur;\n            cur = cur->left;\n        }\n        cur = stack[--top];\n        res[count++] = cur->val;\n        cur = cur->right;\n    }\n    free(stack);\n    *returnSize = count;\n    return res;\n}\n\nint main() {\n    char line[100000];\n    if (fgets(line, sizeof(line), stdin) == NULL) return 0;\n    int len = strlen(line);\n    while (len > 0 && (line[len-1] == \'\\n\' || line[len-1] == \'\\r\')) {\n        line[--len] = \'\\0\';\n    }\n    char* p = line;\n    while (*p == \' \' || *p == \'\\t\') p++;\n    if (*p == \'[\') {\n        p++;\n        char* end = strrchr(p, \']\');\n        if (end) *end = \'\\0\';\n    }\n    if (*p == \'\\0\') {\n        printf(\"[]\\n\");\n        return 0;\n    }\n    int nums[10000];\n    int isNull[10000];\n    int n = 0;\n    char* token = strtok(p, \",\");\n    while (token != NULL) {\n        while (*token == \' \' || *token == \'\\t\') token++;\n        char* e = token + strlen(token) - 1;\n        while (e > token && (*e == \' \' || *e == \'\\t\')) *e-- = \'\\0\';\n        if (strcmp(token, \"null\") == 0) {\n            isNull[n] = 1;\n            nums[n] = 0;\n        } else {\n            isNull[n] = 0;\n            nums[n] = atoi(token);\n        }\n        n++;\n        token = strtok(NULL, \",\");\n    }\n    TreeNode* root = buildTree(nums, isNull, n);\n    int returnSize = 0;\n    int* res = inorderTraversal(root, &returnSize);\n    printf(\"[\");\n    for (int i = 0; i < returnSize; i++) {\n        if (i > 0) printf(\",\");\n        printf(\"%d\", res[i]);\n    }\n    printf(\"]\\n\");\n    free(res);\n    return 0;\n}', NULL, 1),
(244, 'CPP', '#include <iostream>\n#include <string>\n#include <vector>\n#include <queue>\n#include <stack>\n#include <sstream>\n\nusing namespace std;\n\nstruct TreeNode {\n    int val;\n    TreeNode *left;\n    TreeNode *right;\n    TreeNode(int x) : val(x), left(nullptr), right(nullptr) {}\n};\n\nTreeNode* buildTree(const vector<string>& nums) {\n    if (nums.empty() || nums[0] == \"null\") return nullptr;\n    TreeNode* root = new TreeNode(stoi(nums[0]));\n    queue<TreeNode*> q;\n    q.push(root);\n    int i = 1;\n    while (!q.empty() && i < (int)nums.size()) {\n        TreeNode* node = q.front();\n        q.pop();\n        if (i < (int)nums.size() && nums[i] != \"null\") {\n            node->left = new TreeNode(stoi(nums[i]));\n            q.push(node->left);\n        }\n        i++;\n        if (i < (int)nums.size() && nums[i] != \"null\") {\n            node->right = new TreeNode(stoi(nums[i]));\n            q.push(node->right);\n        }\n        i++;\n    }\n    return root;\n}\n\nvector<int> inorderTraversal(TreeNode* root) {\n    vector<int> res;\n    stack<TreeNode*> st;\n    TreeNode* cur = root;\n    while (cur != nullptr || !st.empty()) {\n        while (cur != nullptr) {\n            st.push(cur);\n            cur = cur->left;\n        }\n        cur = st.top();\n        st.pop();\n        res.push_back(cur->val);\n        cur = cur->right;\n    }\n    return res;\n}\n\nint main() {\n    string line;\n    getline(cin, line);\n    while (!line.empty() && (line.back() == \'\\r\' || line.back() == \'\\n\' || line.back() == \' \')) {\n        line.pop_back();\n    }\n    if (!line.empty() && line.front() == \'[\') {\n        line = line.substr(1, line.size() - 2);\n    }\n    if (line.empty()) {\n        cout << \"[]\" << endl;\n        return 0;\n    }\n    vector<string> parts;\n    stringstream ss(line);\n    string token;\n    while (getline(ss, token, \',\')) {\n        size_t start = token.find_first_not_of(\" \\t\");\n        size_t end = token.find_last_not_of(\" \\t\");\n        if (start == string::npos) {\n            parts.push_back(\"\");\n        } else {\n            parts.push_back(token.substr(start, end - start + 1));\n        }\n    }\n    TreeNode* root = buildTree(parts);\n    vector<int> res = inorderTraversal(root);\n    cout << \"[\";\n    for (size_t i = 0; i < res.size(); i++) {\n        if (i > 0) cout << \",\";\n        cout << res[i];\n    }\n    cout << \"]\" << endl;\n    return 0;\n}', NULL, 1),
(244, 'JAVA', 'import java.util.*;\n\npublic class Main {\n    public static void main(String[] args) {\n        Scanner sc = new Scanner(System.in);\n        String line = sc.nextLine().trim();\n        if (line.startsWith(\"[\")) {\n            line = line.substring(1, line.length() - 1);\n        }\n        if (line.isEmpty()) {\n            System.out.println(\"[]\");\n            return;\n        }\n        String[] parts = line.split(\",\");\n        Integer[] nums = new Integer[parts.length];\n        for (int i = 0; i < parts.length; i++) {\n            String s = parts[i].trim();\n            if (s.equals(\"null\")) {\n                nums[i] = null;\n            } else {\n                nums[i] = Integer.parseInt(s);\n            }\n        }\n        TreeNode root = buildTree(nums);\n        List<Integer> res = inorderTraversal(root);\n        StringBuilder sb = new StringBuilder();\n        sb.append(\"[\");\n        for (int i = 0; i < res.size(); i++) {\n            if (i > 0) sb.append(\",\");\n            sb.append(res.get(i));\n        }\n        sb.append(\"]\");\n        System.out.println(sb.toString());\n    }\n\n    private static TreeNode buildTree(Integer[] nums) {\n        if (nums == null || nums.length == 0 || nums[0] == null) return null;\n        TreeNode root = new TreeNode(nums[0]);\n        Queue<TreeNode> queue = new LinkedList<>();\n        queue.offer(root);\n        int i = 1;\n        while (!queue.isEmpty() && i < nums.length) {\n            TreeNode node = queue.poll();\n            if (i < nums.length && nums[i] != null) {\n                node.left = new TreeNode(nums[i]);\n                queue.offer(node.left);\n            }\n            i++;\n            if (i < nums.length && nums[i] != null) {\n                node.right = new TreeNode(nums[i]);\n                queue.offer(node.right);\n            }\n            i++;\n        }\n        return root;\n    }\n\n    private static List<Integer> inorderTraversal(TreeNode root) {\n        List<Integer> res = new ArrayList<>();\n        Deque<TreeNode> stack = new ArrayDeque<>();\n        TreeNode cur = root;\n        while (cur != null || !stack.isEmpty()) {\n            while (cur != null) {\n                stack.push(cur);\n                cur = cur.left;\n            }\n            cur = stack.pop();\n            res.add(cur.val);\n            cur = cur.right;\n        }\n        return res;\n    }\n\n    static class TreeNode {\n        int val;\n        TreeNode left;\n        TreeNode right;\n        TreeNode(int val) {\n            this.val = val;\n        }\n    }\n}', NULL, 1),
(244, 'JAVASCRIPT', 'const readline = require(\'readline\');\n\nconst rl = readline.createInterface({\n    input: process.stdin,\n    output: process.stdout\n});\n\nrl.on(\'line\', (line) => {\n    line = line.trim();\n    if (line.startsWith(\'[\')) {\n        line = line.substring(1, line.length - 1);\n    }\n    if (line.length === 0) {\n        console.log(\'[]\');\n        rl.close();\n        return;\n    }\n    const parts = line.split(\',\');\n    const nums = parts.map(s => {\n        s = s.trim();\n        return s === \'null\' ? null : parseInt(s, 10);\n    });\n    const root = buildTree(nums);\n    const res = inorderTraversal(root);\n    console.log(\'[\' + res.join(\',\') + \']\');\n    rl.close();\n});\n\nfunction buildTree(nums) {\n    if (!nums || nums.length === 0 || nums[0] === null) return null;\n    const root = new TreeNode(nums[0]);\n    const queue = [root];\n    let i = 1;\n    while (queue.length > 0 && i < nums.length) {\n        const node = queue.shift();\n        if (i < nums.length && nums[i] !== null) {\n            node.left = new TreeNode(nums[i]);\n            queue.push(node.left);\n        }\n        i++;\n        if (i < nums.length && nums[i] !== null) {\n            node.right = new TreeNode(nums[i]);\n            queue.push(node.right);\n        }\n        i++;\n    }\n    return root;\n}\n\nfunction inorderTraversal(root) {\n    const res = [];\n    const stack = [];\n    let cur = root;\n    while (cur !== null || stack.length > 0) {\n        while (cur !== null) {\n            stack.push(cur);\n            cur = cur.left;\n        }\n        cur = stack.pop();\n        res.push(cur.val);\n        cur = cur.right;\n    }\n    return res;\n}\n\nclass TreeNode {\n    constructor(val) {\n        this.val = val;\n        this.left = null;\n        this.right = null;\n    }\n}', NULL, 1),
(244, 'PYTHON', 'import sys\nfrom collections import deque\n\nclass TreeNode:\n    def __init__(self, val=0, left=None, right=None):\n        self.val = val\n        self.left = left\n        self.right = right\n\ndef build_tree(nums):\n    if not nums or nums[0] is None:\n        return None\n    root = TreeNode(nums[0])\n    queue = deque([root])\n    i = 1\n    while queue and i < len(nums):\n        node = queue.popleft()\n        if i < len(nums) and nums[i] is not None:\n            node.left = TreeNode(nums[i])\n            queue.append(node.left)\n        i += 1\n        if i < len(nums) and nums[i] is not None:\n            node.right = TreeNode(nums[i])\n            queue.append(node.right)\n        i += 1\n    return root\n\ndef inorder_traversal(root):\n    res = []\n    stack = []\n    cur = root\n    while cur or stack:\n        while cur:\n            stack.append(cur)\n            cur = cur.left\n        cur = stack.pop()\n        res.append(cur.val)\n        cur = cur.right\n    return res\n\ndef main():\n    line = sys.stdin.readline().strip()\n    if line.startswith(\"[\"):\n        line = line[1:-1]\n    if not line:\n        print(\"[]\")\n        return\n    parts = line.split(\",\")\n    nums = []\n    for s in parts:\n        s = s.strip()\n        if s == \"null\":\n            nums.append(None)\n        else:\n            nums.append(int(s))\n    root = build_tree(nums)\n    res = inorder_traversal(root)\n    print(\"[\" + \",\".join(str(x) for x in res) + \"]\")\n\nif __name__ == \"__main__\":\n    main()', NULL, 1),
(245, 'C', '#include <stdio.h>\n#include <stdlib.h>\n#include <string.h>\n#include <stdbool.h>\n\ntypedef struct TreeNode {\n    int val;\n    struct TreeNode *left;\n    struct TreeNode *right;\n} TreeNode;\n\nstatic TreeNode* newTreeNode(int val) {\n    TreeNode* node = (TreeNode*)malloc(sizeof(TreeNode));\n    node->val = val;\n    node->left = NULL;\n    node->right = NULL;\n    return node;\n}\n\nstatic TreeNode* buildTree(int* nums, int* isNull, int len) {\n    if (len == 0 || isNull[0]) return NULL;\n    TreeNode* root = newTreeNode(nums[0]);\n    TreeNode** queue = (TreeNode**)malloc(sizeof(TreeNode*) * len);\n    int front = 0, rear = 0;\n    queue[rear++] = root;\n    int i = 1;\n    while (front < rear && i < len) {\n        TreeNode* node = queue[front++];\n        if (i < len) {\n            if (!isNull[i]) {\n                node->left = newTreeNode(nums[i]);\n                queue[rear++] = node->left;\n            }\n            i++;\n        }\n        if (i < len) {\n            if (!isNull[i]) {\n                node->right = newTreeNode(nums[i]);\n                queue[rear++] = node->right;\n            }\n            i++;\n        }\n    }\n    free(queue);\n    return root;\n}\n\nstatic bool check(TreeNode* left, TreeNode* right) {\n    if (left == NULL && right == NULL) return true;\n    if (left == NULL || right == NULL) return false;\n    if (left->val != right->val) return false;\n    return check(left->left, right->right) && check(left->right, right->left);\n}\n\nstatic bool isSymmetric(TreeNode* root) {\n    if (root == NULL) return true;\n    return check(root->left, root->right);\n}\n\nint main(void) {\n    char line[1000005];\n    if (fgets(line, sizeof(line), stdin) == NULL) {\n        printf(\"true\\n\");\n        return 0;\n    }\n    size_t len = strlen(line);\n    while (len > 0 && (line[len - 1] == \'\\n\' || line[len - 1] == \'\\r\')) {\n        line[--len] = \'\\0\';\n    }\n    if (len == 0) {\n        printf(\"true\\n\");\n        return 0;\n    }\n    if (line[0] == \'[\' && len >= 2 && line[len - 1] == \']\') {\n        memmove(line, line + 1, len - 2);\n        line[len - 2] = \'\\0\';\n        len -= 2;\n    }\n    bool empty = true;\n    for (size_t i = 0; i < len; i++) {\n        if (line[i] != \' \' && line[i] != \'\\t\') {\n            empty = false;\n            break;\n        }\n    }\n    if (empty) {\n        printf(\"true\\n\");\n        return 0;\n    }\n\n    int capacity = 16;\n    int* nums = (int*)malloc(sizeof(int) * capacity);\n    int* isNull = (int*)malloc(sizeof(int) * capacity);\n    int count = 0;\n\n    char* p = line;\n    while (*p) {\n        while (*p == \' \' || *p == \'\\t\') p++;\n        if (*p == \'\\0\') break;\n        char* start = p;\n        while (*p && *p != \',\') p++;\n        char* end = p;\n        while (end > start && (end[-1] == \' \' || end[-1] == \'\\t\')) end--;\n        if (end > start) {\n            if (count >= capacity) {\n                capacity *= 2;\n                nums = (int*)realloc(nums, sizeof(int) * capacity);\n                isNull = (int*)realloc(isNull, sizeof(int) * capacity);\n            }\n            if ((end - start) == 4 && strncmp(start, \"null\", 4) == 0) {\n                nums[count] = 0;\n                isNull[count] = 1;\n            } else {\n                char tmp[64];\n                int l = (int)(end - start);\n                if (l > 63) l = 63;\n                memcpy(tmp, start, l);\n                tmp[l] = \'\\0\';\n                nums[count] = atoi(tmp);\n                isNull[count] = 0;\n            }\n            count++;\n        }\n        if (*p == \',\') p++;\n    }\n\n    TreeNode* root = buildTree(nums, isNull, count);\n    printf(\"%s\\n\", isSymmetric(root) ? \"true\" : \"false\");\n\n    free(nums);\n    free(isNull);\n    return 0;\n}', NULL, 1),
(245, 'CPP', '#include <iostream>\n#include <string>\n#include <vector>\n#include <queue>\n#include <sstream>\nusing namespace std;\n\nstruct TreeNode {\n    int val;\n    TreeNode* left;\n    TreeNode* right;\n    TreeNode(int v) : val(v), left(nullptr), right(nullptr) {}\n};\n\nTreeNode* buildTree(vector<string>& nums) {\n    if (nums.empty() || nums[0] == \"null\") return nullptr;\n    TreeNode* root = new TreeNode(stoi(nums[0]));\n    queue<TreeNode*> q;\n    q.push(root);\n    int i = 1;\n    while (!q.empty() && i < (int)nums.size()) {\n        TreeNode* node = q.front(); q.pop();\n        if (i < (int)nums.size()) {\n            if (nums[i] != \"null\") {\n                node->left = new TreeNode(stoi(nums[i]));\n                q.push(node->left);\n            }\n            i++;\n        }\n        if (i < (int)nums.size()) {\n            if (nums[i] != \"null\") {\n                node->right = new TreeNode(stoi(nums[i]));\n                q.push(node->right);\n            }\n            i++;\n        }\n    }\n    return root;\n}\n\nbool check(TreeNode* left, TreeNode* right) {\n    if (!left && !right) return true;\n    if (!left || !right) return false;\n    if (left->val != right->val) return false;\n    return check(left->left, right->right) && check(left->right, right->left);\n}\n\nbool isSymmetric(TreeNode* root) {\n    if (!root) return true;\n    return check(root->left, root->right);\n}\n\nint main() {\n    string line;\n    getline(cin, line);\n    while (!line.empty() && (line.back() == \'\\r\' || line.back() == \'\\n\')) line.pop_back();\n    if (line.empty()) {\n        cout << \"true\" << endl;\n        return 0;\n    }\n    line = line.substr(1, line.size() - 2);\n    if (line.find_first_not_of(\" \\t\") == string::npos) {\n        cout << \"true\" << endl;\n        return 0;\n    }\n    vector<string> parts;\n    stringstream ss(line);\n    string token;\n    while (getline(ss, token, \',\')) {\n        size_t start = token.find_first_not_of(\" \\t\");\n        size_t end = token.find_last_not_of(\" \\t\");\n        if (start == string::npos) parts.push_back(\"\");\n        else parts.push_back(token.substr(start, end - start + 1));\n    }\n    TreeNode* root = buildTree(parts);\n    cout << (isSymmetric(root) ? \"true\" : \"false\") << endl;\n    return 0;\n}', NULL, 1),
