\n    static boolean check(TreeNode left, TreeNode right) {\n        if (left == null && right == null) return true;\n        if (left == null || right == null) return false;\n        if (left.val != right.val) return false;\n        return check(left.left, right.right) && check(left.right, right.left);\n    }\n}', NULL, 1),
(245, 'JAVASCRIPT', 'const readline = require(\'readline\');\n\nconst rl = readline.createInterface({\n    input: process.stdin,\n    output: process.stdout\n});\n\nrl.on(\'line\', (line) => {\n    line = line.trim();\n    if (line === \'\') {\n        console.log(\'true\');\n        rl.close();\n        return;\n    }\n    line = line.substring(1, line.length - 1);\n    if (line.trim() === \'\') {\n        console.log(\'true\');\n        rl.close();\n        return;\n    }\n    const parts = line.split(\',\');\n    const nums = parts.map(s => {\n        s = s.trim();\n        return s === \'null\' ? null : parseInt(s, 10);\n    });\n    const root = buildTree(nums);\n    console.log(isSymmetric(root));\n    rl.close();\n});\n\nclass TreeNode {\n    constructor(val) {\n        this.val = val;\n        this.left = null;\n        this.right = null;\n    }\n}\n\nfunction buildTree(nums) {\n    if (!nums || nums.length === 0 || nums[0] === null) return null;\n    const root = new TreeNode(nums[0]);\n    const queue = [root];\n    let i = 1;\n    while (queue.length > 0 && i < nums.length) {\n        const node = queue.shift();\n        if (i < nums.length) {\n            if (nums[i] !== null) {\n                node.left = new TreeNode(nums[i]);\n                queue.push(node.left);\n            }\n            i++;\n        }\n        if (i < nums.length) {\n            if (nums[i] !== null) {\n                node.right = new TreeNode(nums[i]);\n                queue.push(node.right);\n            }\n            i++;\n        }\n    }\n    return root;\n}\n\nfunction isSymmetric(root) {\n    if (root === null) return true;\n    return check(root.left, root.right);\n}\n\nfunction check(left, right) {\n    if (left === null && right === null) return true;\n    if (left === null || right === null) return false;\n    if (left.val !== right.val) return false;\n    return check(left.left, right.right) && check(left.right, right.left);\n}', NULL, 1),
(245, 'PYTHON', 'import sys\nfrom collections import deque\n\nclass TreeNode:\n    def __init__(self, val=0, left=None, right=None):\n        self.val = val\n        self.left = left\n        self.right = right\n\ndef build_tree(nums):\n    if not nums or nums[0] is None:\n        return None\n    root = TreeNode(nums[0])\n    queue = deque([root])\n    i = 1\n    while queue and i < len(nums):\n        node = queue.popleft()\n        if i < len(nums):\n            if nums[i] is not None:\n                node.left = TreeNode(nums[i])\n                queue.append(node.left)\n            i += 1\n        if i < len(nums):\n            if nums[i] is not None:\n                node.right = TreeNode(nums[i])\n                queue.append(node.right)\n            i += 1\n    return root\n\ndef is_symmetric(root):\n    if root is None:\n        return True\n    return check(root.left, root.right)\n\ndef check(left, right):\n    if left is None and right is None:\n        return True\n    if left is None or right is None:\n        return False\n    if left.val != right.val:\n        return False\n    return check(left.left, right.right) and check(left.right, right.left)\n\ndef main():\n    line = sys.stdin.readline().strip()\n    if not line:\n        print(\"true\")\n        return\n    line = line[1:-1]\n    if not line.strip():\n        print(\"true\")\n        return\n    parts = line.split(\",\")\n    nums = []\n    for s in parts:\n        s = s.strip()\n        if s == \"null\":\n            nums.append(None)\n        else:\n            nums.append(int(s))\n    root = build_tree(nums)\n    print(\"true\" if is_symmetric(root) else \"false\")\n\nif __name__ == \"__main__\":\n    main()', NULL, 1),
(246, 'C', '#include <stdio.h>\n#include <stdlib.h>\n\nvoid dfs(char **grid, int i, int j, int m, int n) {\n    if (i < 0 || i >= m || j < 0 || j >= n || grid[i][j] != \'1\') {\n        return;\n    }\n    grid[i][j] = \'0\';\n    dfs(grid, i - 1, j, m, n);\n    dfs(grid, i + 1, j, m, n);\n    dfs(grid, i, j - 1, m, n);\n    dfs(grid, i, j + 1, m, n);\n}\n\nint main() {\n    int m, n;\n    scanf(\"%d %d\", &m, &n);\n\n    char **grid = (char **)malloc(m * sizeof(char *));\n    for (int i = 0; i < m; i++) {\n        grid[i] = (char *)malloc((n + 1) * sizeof(char));\n        scanf(\"%s\", grid[i]);\n    }\n\n    int count = 0;\n    for (int i = 0; i < m; i++) {\n        for (int j = 0; j < n; j++) {\n            if (grid[i][j] == \'1\') {\n                count++;\n                dfs(grid, i, j, m, n);\n            }\n        }\n    }\n\n    printf(\"%d\\n\", count);\n\n    for (int i = 0; i < m; i++) {\n        free(grid[i]);\n    }\n    free(grid);\n\n    return 0;\n}', NULL, 1),
(246, 'CPP', '#include <iostream>\n#include <vector>\n#include <string>\nusing namespace std;\n\nvoid dfs(vector<string>& grid, int i, int j, int m, int n) {\n    if (i < 0 || i >= m || j < 0 || j >= n || grid[i][j] != \'1\') {\n        return;\n    }\n    grid[i][j] = \'0\';\n    dfs(grid, i - 1, j, m, n);\n    dfs(grid, i + 1, j, m, n);\n    dfs(grid, i, j - 1, m, n);\n    dfs(grid, i, j + 1, m, n);\n}\n\nint main() {\n    int m, n;\n    cin >> m >> n;\n    cin.ignore();\n    vector<string> grid(m);\n    for (int i = 0; i < m; i++) {\n        getline(cin, grid[i]);\n    }\n    int count = 0;\n    for (int i = 0; i < m; i++) {\n        for (int j = 0; j < n; j++) {\n            if (grid[i][j] == \'1\') {\n                count++;\n                dfs(grid, i, j, m, n);\n            }\n        }\n    }\n    cout << count << endl;\n    return 0;\n}', NULL, 1),
(246, 'JAVA', 'import java.util.Scanner;\n\npublic class Main {\n    public static void main(String[] args) {\n        Scanner sc = new Scanner(System.in);\n        int m = sc.nextInt();\n        int n = sc.nextInt();\n        sc.nextLine();\n        char[][] grid = new char[m][n];\n        for (int i = 0; i < m; i++) {\n            String line = sc.nextLine();\n            grid[i] = line.toCharArray();\n        }\n        int count = 0;\n        for (int i = 0; i < m; i++) {\n            for (int j = 0; j < n; j++) {\n                if (grid[i][j] == \'1\') {\n                    count++;\n                    dfs(grid, i, j, m, n);\n                }\n            }\n        }\n        System.out.println(count);\n    }\n\n    private static void dfs(char[][] grid, int i, int j, int m, int n) {\n        if (i < 0 || i >= m || j < 0 || j >= n || grid[i][j] != \'1\') {\n            return;\n        }\n        grid[i][j] = \'0\';\n        dfs(grid, i + 1, j, m, n);\n        dfs(grid, i - 1, j, m, n);\n        dfs(grid, i, j + 1, m, n);\n        dfs(grid, i, j - 1, m, n);\n    }\n}', NULL, 1),
(246, 'JAVASCRIPT', 'const readline = require(\'readline\');\n\nconst rl = readline.createInterface({\n    input: process.stdin,\n    output: process.stdout\n});\n\nlet lines = [];\nrl.on(\'line\', (line) => {\n    lines.push(line);\n});\n\nrl.on(\'close\', () => {\n    const [m, n] = lines[0].trim().split(/\\s+/).map(Number);\n    const grid = [];\n    for (let i = 0; i < m; i++) {\n        grid.push(lines[i + 1].trim().split(\'\'));\n    }\n\n    let count = 0;\n\n    function dfs(i, j) {\n        if (i < 0 || i >= m || j < 0 || j >= n || grid[i][j] !== \'1\') {\n            return;\n        }\n        grid[i][j] = \'0\';\n        dfs(i - 1, j);\n        dfs(i + 1, j);\n        dfs(i, j - 1);\n        dfs(i, j + 1);\n    }\n\n    for (let i = 0; i < m; i++) {\n        for (let j = 0; j < n; j++) {\n            if (grid[i][j] === \'1\') {\n                count++;\n                dfs(i, j);\n            }\n        }\n    }\n\n    console.log(count);\n});', NULL, 1),
(246, 'PYTHON', 'import sys\n\ndef dfs(grid, i, j, m, n):\n    if i < 0 or i >= m or j < 0 or j >= n or grid[i][j] != \'1\':\n        return\n    grid[i][j] = \'0\'\n    dfs(grid, i - 1, j, m, n)\n    dfs(grid, i + 1, j, m, n)\n    dfs(grid, i, j - 1, m, n)\n    dfs(grid, i, j + 1, m, n)\n\ndef main():\n    data = sys.stdin.read().splitlines()\n    if not data:\n        return\n    m, n = map(int, data[0].split())\n    grid = []\n    for i in range(1, m + 1):\n        grid.append(list(data[i].strip()))\n    count = 0\n    for i in range(m):\n        for j in range(n):\n            if grid[i][j] == \'1\':\n                count += 1\n                dfs(grid, i, j, m, n)\n    print(count)\n\nif __name__ == \"__main__\":\n    main()', NULL, 1),
(247, 'C', '#include <stdio.h>\n#include <stdlib.h>\n\ntypedef struct Node {\n    int val;\n    struct Node* next;\n} Node;\n\nint main() {\n    int numCourses, k;\n    scanf(\"%d %d\", &numCourses, &k);\n\n    Node** graph = (Node**)calloc(numCourses, sizeof(Node*));\n    int* indegree = (int*)calloc(numCourses, sizeof(int));\n\n    for (int i = 0; i < k; i++) {\n        int a, b;\n        scanf(\"%d %d\", &a, &b);\n        Node* node = (Node*)malloc(sizeof(Node));\n        node->val = a;\n        node->next = graph[b];\n        graph[b] = node;\n        indegree[a]++;\n    }\n\n    int* queue = (int*)malloc(numCourses * sizeof(int));\n    int front = 0, rear = 0;\n\n    for (int i = 0; i < numCourses; i++) {\n        if (indegree[i] == 0) {\n            queue[rear++] = i;\n        }\n    }\n\n    int count = 0;\n    while (front < rear) {\n        int cur = queue[front++];\n        count++;\n        Node* p = graph[cur];\n        while (p) {\n            int next = p->val;\n            indegree[next]--;\n            if (indegree[next] == 0) {\n                queue[rear++] = next;\n            }\n            p = p->next;\n        }\n    }\n\n    if (count == numCourses) {\n        printf(\"true\\n\");\n    } else {\n        printf(\"false\\n\");\n    }\n\n    for (int i = 0; i < numCourses; i++) {\n        Node* p = graph[i];\n        while (p) {\n            Node* tmp = p;\n            p = p->next;\n            free(tmp);\n        }\n    }\n    free(graph);\n    free(indegree);\n    free(queue);\n\n    return 0;\n}', NULL, 1),
(247, 'CPP', '#include <iostream>\n#include <vector>\n#include <queue>\nusing namespace std;\n\nint main() {\n    int numCourses, k;\n    cin >> numCourses >> k;\n    vector<vector<int>> graph(numCourses);\n    vector<int> indegree(numCourses, 0);\n    for (int i = 0; i < k; i++) {\n        int a, b;\n        cin >> a >> b;\n        graph[b].push_back(a);\n        indegree[a]++;\n    }\n    queue<int> q;\n    for (int i = 0; i < numCourses; i++) {\n        if (indegree[i] == 0) {\n            q.push(i);\n        }\n    }\n    int count = 0;\n    while (!q.empty()) {\n        int cur = q.front();\n        q.pop();\n        count++;\n        for (int next : graph[cur]) {\n            indegree[next]--;\n            if (indegree[next] == 0) {\n                q.push(next);\n            }\n        }\n    }\n    cout << (count == numCourses ? \"true\" : \"false\") << endl;\n    return 0;\n}', NULL, 1),
(247, 'JAVA', 'import java.util.*;\n\npublic class Main {\n    public static void main(String[] args) {\n        Scanner sc = new Scanner(System.in);\n        int numCourses = sc.nextInt();\n        int k = sc.nextInt();\n        List<List<Integer>> graph = new ArrayList<>();\n        for (int i = 0; i < numCourses; i++) {\n            graph.add(new ArrayList<>());\n        }\n        int[] indegree = new int[numCourses];\n        for (int i = 0; i < k; i++) {\n            int a = sc.nextInt();\n            int b = sc.nextInt();\n            graph.get(b).add(a);\n            indegree[a]++;\n        }\n        Queue<Integer> queue = new LinkedList<>();\n        for (int i = 0; i < numCourses; i++) {\n            if (indegree[i] == 0) {\n                queue.offer(i);\n            }\n        }\n        int count = 0;\n        while (!queue.isEmpty()) {\n            int cur = queue.poll();\n            count++;\n            for (int next : graph.get(cur)) {\n                indegree[next]--;\n                if (indegree[next] == 0) {\n                    queue.offer(next);\n                }\n            }\n        }\n        System.out.println(count == numCourses);\n    }\n}', NULL, 1),
(247, 'JAVASCRIPT', 'const readline = require(\'readline\');\n\nconst rl = readline.createInterface({\n    input: process.stdin,\n    output: process.stdout\n});\n\nlet lines = [];\nrl.on(\'line\', (line) => {\n    lines.push(line.trim());\n});\n\nrl.on(\'close\', () => {\n    if (lines.length === 0) return;\n    const first = lines[0].split(/\\s+/).map(Number);\n    const numCourses = first[0];\n    const k = first[1];\n\n    const graph = Array.from({ length: numCourses }, () => []);\n    const indegree = new Array(numCourses).fill(0);\n\n    for (let i = 1; i <= k; i++) {\n        const [a, b] = lines[i].split(/\\s+/).map(Number);\n        graph[b].push(a);\n        indegree[a]++;\n    }\n\n    const queue = [];\n    for (let i = 0; i < numCourses; i++) {\n        if (indegree[i] === 0) {\n            queue.push(i);\n        }\n    }\n\n    let count = 0;\n    let head = 0;\n    while (head < queue.length) {\n        const cur = queue[head++];\n        count++;\n        for (const next of graph[cur]) {\n            indegree[next]--;\n            if (indegree[next] === 0) {\n                queue.push(next);\n            }\n        }\n    }\n\n    console.log(count === numCourses);\n});', NULL, 1),
(247, 'PYTHON', 'import sys\nfrom collections import deque\n\ndef main():\n    data = sys.stdin.read().strip().split()\n    if not data:\n        return\n    numCourses = int(data[0])\n    k = int(data[1])\n    graph = [[] for _ in range(numCourses)]\n    indegree = [0] * numCourses\n    idx = 2\n    for _ in range(k):\n        a = int(data[idx])\n        b = int(data[idx + 1])\n        idx += 2\n        graph[b].append(a)\n        indegree[a] += 1\n    queue = deque([i for i in range(numCourses) if indegree[i] == 0])\n    count = 0\n    while queue:\n        cur = queue.popleft()\n        count += 1\n        for nxt in graph[cur]:\n            indegree[nxt] -= 1\n            if indegree[nxt] == 0:\n                queue.append(nxt)\n    print(\"true\" if count == numCourses else \"false\")\n\nif __name__ == \"__main__\":\n    main()', NULL, 1),
(248, 'C', '#include <stdio.h>\n#include <stdlib.h>\n#include <string.h>\n\ntypedef struct Node {\n    int val;\n    struct Node** neighbors;\n    int neighborCount;\n    int capacity;\n} Node;\n\nNode* createNode(int val) {\n    Node* node = (Node*)malloc(sizeof(Node));\n    node->val = val;\n    node->neighborCount = 0;\n    node->capacity = 4;\n    node->neighbors = (Node**)malloc(sizeof(Node*) * node->capacity);\n    return node;\n}\n\nvoid addNeighbor(Node* node, Node* neighbor) {\n    if (node->neighborCount >= node->capacity) {\n        node->capacity *= 2;\n        node->neighbors = (Node**)realloc(node->neighbors, sizeof(Node*) * node->capacity);\n    }\n    node->neighbors[node->neighborCount++] = neighbor;\n}\n\nNode* dfs(Node* node, Node** map, int n) {\n    if (node == NULL) return NULL;\n    if (map[node->val] != NULL) return map[node->val];\n    Node* copy = createNode(node->val);\n    map[node->val] = copy;\n    for (int i = 0; i < node->neighborCount; i++) {\n        addNeighbor(copy, dfs(node->neighbors[i], map, n));\n    }\n    return copy;\n}\n\nNode* cloneGraph(Node* node, int n) {\n    if (node == NULL) return NULL;\n    Node** map = (Node**)calloc(n + 1, sizeof(Node*));\n    Node* result = dfs(node, map, n);\n    free(map);\n    return result;\n}\n\nint main() {\n    int n;\n    if (scanf(\"%d\", &n) != 1) return 0;\n    int c;\n    while ((c = getchar()) != \'\\n\' && c != EOF);\n\n    Node** nodes = (Node**)malloc(sizeof(Node*) * (n + 1));\n    for (int i = 1; i <= n; i++) {\n        nodes[i] = createNode(i);\n    }\n\n    char line[100000];\n    for (int i = 1; i <= n; i++) {\n        if (fgets(line, sizeof(line), stdin) == NULL) break;\n        char* p = line;\n        while (*p) {\n            while (*p == \' \' || *p == \'\\t\' || *p == \'\\n\' || *p == \'\\r\') p++;\n            if (*p == \'\\0\') break;\n            int v = 0;\n            while (*p >= \'0\' && *p <= \'9\') {\n                v = v * 10 + (*p - \'0\');\n                p++;\n            }\n            if (v >= 1 && v <= n) {\n                addNeighbor(nodes[i], nodes[v]);\n            }\n        }\n    }\n\n    Node* cloned = cloneGraph(nodes[1], n);\n\n    printf(\"[\");\n    for (int i = 1; i <= n; i++) {\n        printf(\"[\");\n        for (int j = 0; j < nodes[i]->neighborCount; j++) {\n            printf(\"%d\", nodes[i]->neighbors[j]->val);\n            if (j < nodes[i]->neighborCount - 1) printf(\",\");\n        }\n        printf(\"]\");\n        if (i < n) printf(\",\");\n    }\n    printf(\"]\\n\");\n\n    return 0;\n}', NULL, 1),
(248, 'CPP', '#include <iostream>\n#include <vector>\n#include <string>\n#include <sstream>\n#include <unordered_map>\n\nusing namespace std;\n\nstruct Node {\n    int val;\n    vector<Node*> neighbors;\n    Node() : val(0) {}\n    Node(int _val) : val(_val) {}\n    Node(int _val, vector<Node*> _neighbors) : val(_val), neighbors(_neighbors) {}\n};\n\nNode* dfs(Node* node, unordered_map<Node*, Node*>& mp) {\n    if (mp.count(node)) return mp[node];\n    Node* copy = new Node(node->val);\n    mp[node] = copy;\n    for (Node* nei : node->neighbors) {\n        copy->neighbors.push_back(dfs(nei, mp));\n    }\n    return copy;\n}\n\nNode* cloneGraph(Node* node) {\n    if (!node) return nullptr;\n    unordered_map<Node*, Node*> mp;\n    return dfs(node, mp);\n}\n\nint main() {\n    int n;\n    if (!(cin >> n)) return 0;\n    cin.ignore();\n    vector<Node*> nodes;\n    for (int i = 0; i < n; i++) {\n        nodes.push_back(new Node(i + 1));\n    }\n    for (int i = 0; i < n; i++) {\n        string line;\n        getline(cin, line);\n        if (line.empty()) continue;\n        istringstream iss(line);\n        int v;\n        while (iss >> v) {\n            nodes[i]->neighbors.push_back(nodes[v - 1]);\n        }\n    }\n    Node* cloned = cloneGraph(nodes[0]);\n    (void)cloned;\n    stringstream sb;\n    sb << \"[\";\n    for (int i = 0; i < n; i++) {\n        sb << \"[\";\n        vector<Node*>& nei = nodes[i]->neighbors;\n        for (size_t j = 0; j < nei.size(); j++) {\n            sb << nei[j]->val;\n            if (j + 1 < nei.size()) sb << \",\";\n        }\n        sb << \"]\";\n        if (i < n - 1) sb << \",\";\n    }\n    sb << \"]\";\n    cout << sb.str() << endl;\n    return 0;\n}', NULL, 1),
(248, 'JAVA', 'import java.util.*;\n\npublic class Main {\n    static class Node {\n        public int val;\n        public List<Node> neighbors;\n        public Node() {\n            val = 0;\n            neighbors = new ArrayList<>();\n        }\n        public Node(int _val) {\n            val = _val;\n            neighbors = new ArrayList<>();\n        }\n        public Node(int _val, ArrayList<Node> _neighbors) {\n            val = _val;\n            neighbors = _neighbors;\n        }\n    }\n\n    public static void main(String[] args) {\n        Scanner sc = new Scanner(System.in);\n        if (!sc.hasNextInt()) return;\n        int n = sc.nextInt();\n        sc.nextLine();\n\n        Node[] nodes = new Node[n + 1];\n        for (int i = 1; i <= n; i++) {\n            nodes[i] = new Node(i);\n        }\n\n        for (int i = 1; i <= n; i++) {\n            String line = sc.nextLine().trim();\n            if (line.isEmpty()) continue;\n            String[] parts = line.split(\"\\\\s+\");\n            for (String p : parts) {\n                if (p.isEmpty()) continue;\n                int v = Integer.parseInt(p);\n                nodes[i].neighbors.add(nodes[v]);\n            }\n        }\n\n        Node cloned = cloneGraph(nodes[1]);\n\n        List<List<Integer>> result = new ArrayList<>();\n        for (int i = 1; i <= n; i++) {\n            List<Integer> list = new ArrayList<>();\n            for (Node nb : nodes[i].neighbors) {\n                list.add(nb.val);\n            }\n            result.add(list);\n        }\n\n        StringBuilder sb = new StringBuilder();\n        sb.append(\"[\");\n        for (int i = 0; i < result.size(); i++) {\n            sb.append(\"[\");\n            List<Integer> list = result.get(i);\n            for (int j = 0; j < list.size(); j++) {\n                sb.append(list.get(j));\n                if (j < list.size() - 1) sb.append(\",\");\n            }\n            sb.append(\"]\");\n            if (i < result.size() - 1) sb.append(\",\");\n        }\n        sb.append(\"]\");\n        System.out.println(sb.toString());\n    }\n\n    public static Node cloneGraph(Node node) {\n        if (node == null) return null;\n        Map<Node, Node> map = new HashMap<>();\n        return dfs(node, map);\n    }\n\n    private static Node dfs(Node node, Map<Node, Node> map) {\n        if (map.containsKey(node)) return map.get(node);\n        Node copy = new Node(node.val);\n        map.put(node, copy);\n        for (Node nb : node.neighbors) {\n            copy.neighbors.add(dfs(nb, map));\n        }\n        return copy;\n    }\n}', NULL, 1),
(248, 'JAVASCRIPT', 'const readline = require(\'readline\');\n\nclass Node {\n    constructor(val = 0, neighbors = []) {\n        this.val = val;\n        this.neighbors = neighbors;\n    }\n}\n\nfunction cloneGraph(node) {\n    if (node === null) return null;\n    const map = new Map();\n    return dfs(node, map);\n}\n\nfunction dfs(node, map) {\n    if (map.has(node)) return map.get(node);\n    const copy = new Node(node.val);\n    map.set(node, copy);\n    for (const nb of node.neighbors) {\n        copy.neighbors.push(dfs(nb, map));\n    }\n    return copy;\n}\n\nconst rl = readline.createInterface({\n    input: process.stdin,\n    output: process.stdout\n});\n\nlet lines = [];\nrl.on(\'line\', (line) => {\n    lines.push(line);\n});\n\nrl.on(\'close\', () => {\n    if (lines.length === 0) return;\n    let idx = 0;\n    const n = parseInt(lines[idx++].trim());\n    const nodes = new Array(n + 1);\n    for (let i = 1; i <= n; i++) {\n        nodes[i] = new Node(i);\n    }\n    for (let i = 1; i <= n; i++) {\n        const line = (lines[idx++] || \'\').trim();\n        if (line === \'\') continue;\n        const parts = line.split(/\\s+/);\n        for (const p of parts) {\n            if (p === \'\') continue;\n            const v = parseInt(p);\n            nodes[i].neighbors.push(nodes[v]);\n        }\n    }\n\n    cloneGraph(nodes[1]);\n\n    const result = [];\n    for (let i = 1; i <= n; i++) {\n        const list = [];\n        for (const nb of nodes[i].neighbors) {\n            list.push(nb.val);\n        }\n        result.push(list);\n    }\n\n    let sb = \'[\';\n    for (let i = 0; i < result.length; i++) {\n        sb += \'[\';\n        const list = result[i];\n        for (let j = 0; j < list.length; j++) {\n            sb += list[j];\n            if (j < list.length - 1) sb += \',\';\n        }\n        sb += \']\';\n        if (i < result.length - 1) sb += \',\';\n    }\n    sb += \']\';\n    console.log(sb);\n});', NULL, 1),
(248, 'PYTHON', 'import sys\n\nclass Node:\n    def __init__(self, val=0, neighbors=None):\n        self.val = val\n        self.neighbors = neighbors if neighbors is not None else []\n\ndef clone_graph(node, visited):\n    if node is None:\n        return None\n    if node in visited:\n        return visited[node]\n    copy = Node(node.val)\n    visited[node] = copy\n    for nb in node.neighbors:\n        copy.neighbors.append(clone_graph(nb, visited))\n    return copy\n\ndef main():\n    data = sys.stdin.read().splitlines()\n    if not data:\n        return\n    n = int(data[0].strip())\n    nodes = [None] + [Node(i) for i in range(1, n + 1)]\n    for i in range(1, n + 1):\n        if i >= len(data):\n            break\n        line = data[i].strip()\n        if not line:\n            continue\n        for p in line.split():\n            v = int(p)\n            nodes[i].neighbors.append(nodes[v])\n    clone_graph(nodes[1], {})\n    result = []\n    for i in range(1, n + 1):\n        result.append([nb.val for nb in nodes[i].neighbors])\n    out = \"[\" + \",\".join(\"[\" + \",\".join(map(str, lst)) + \"]\" for lst in result) + \"]\"\n    print(out)\n\nif __name__ == \"__main__\":\n    main()', NULL, 1),
(249, 'C', '#include <stdio.h>\n#include <stdlib.h>\n#include <string.h>\n#include <stdbool.h>\n\n#define MAX_WORDS 10000\n#define MAX_LEN 64\n\ntypedef struct {\n    char word[MAX_LEN];\n} Word;\n\nstatic Word dictWords[MAX_WORDS];\nstatic int dictSize = 0;\n\nstatic int findWord(const char *w) {\n    for (int i = 0; i < dictSize; i++) {\n        if (strcmp(dictWords[i].word, w) == 0) return i;\n    }\n    return -1;\n}\n\nint main(void) {\n    char beginWord[MAX_LEN], endWord[MAX_LEN];\n    char line[1000000];\n\n    if (scanf(\"%63s\", beginWord) != 1) return 0;\n    if (scanf(\"%63s\", endWord) != 1) return 0;\n    getchar();\n\n    if (!fgets(line, sizeof(line), stdin)) line[0] = \'\\0\';\n\n    char *p = strtok(line, \" \\t\\r\\n\");\n    while (p) {\n        if (dictSize < MAX_WORDS) {\n            strncpy(dictWords[dictSize].word, p, MAX_LEN - 1);\n            dictWords[dictSize].word[MAX_LEN - 1] = \'\\0\';\n            dictSize++;\n        }\n        p = strtok(NULL, \" \\t\\r\\n\");\n    }\n\n    int endIdx = findWord(endWord);\n    if (endIdx == -1) {\n        printf(\"0\\n\");\n        return 0;\n    }\n\n    int beginIdx = findWord(beginWord);\n    if (beginIdx == -1) {\n        if (dictSize < MAX_WORDS) {\n            strncpy(dictWords[dictSize].word, beginWord, MAX_LEN - 1);\n            dictWords[dictSize].word[MAX_LEN - 1] = \'\\0\';\n            beginIdx = dictSize;\n            dictSize++;\n        }\n    }\n\n    bool visited[MAX_WORDS] = {0};\n    int queue[MAX_WORDS];\n    int front = 0, rear = 0;\n\n    queue[rear++] = beginIdx;\n    visited[beginIdx] = true;\n    int level = 1;\n\n    while (front < rear) {\n        int size = rear - front;\n        for (int i = 0; i < size; i++) {\n            int cur = queue[front++];\n            if (cur == endIdx) {\n                printf(\"%d\\n\", level);\n                return 0;\n            }\n\n            char chars[MAX_LEN];\n            strcpy(chars, dictWords[cur].word);\n            int len = (int)strlen(chars);\n\n            for (int j = 0; j < len; j++) {\n                char old = chars[j];\n                for (char c = \'a\'; c <= \'z\'; c++) {\n                    if (c == old) continue;\n                    chars[j] = c;\n                    int nxt = findWord(chars);\n                    if (nxt != -1 && !visited[nxt]) {\n                        visited[nxt] = true;\n                        queue[rear++] = nxt;\n                    }\n                }\n                chars[j] = old;\n            }\n        }\n        level++;\n    }\n\n    printf(\"0\\n\");\n    return 0;\n}', NULL, 1),
(249, 'CPP', '#include <iostream>\n#include <string>\n#include <vector>\n#include <unordered_set>\n#include <queue>\n#include <sstream>\n\nusing namespace std;\n\nint main() {\n    string beginWord, endWord, line;\n    getline(cin, beginWord);\n    getline(cin, endWord);\n    getline(cin, line);\n\n    auto trim = [](string &s) {\n        size_t start = s.find_first_not_of(\" \\t\\r\\n\");\n        size_t end = s.find_last_not_of(\" \\t\\r\\n\");\n        if (start == string::npos) s = \"\";\n        else s = s.substr(start, end - start + 1);\n    };\n\n    trim(beginWord);\n    trim(endWord);\n    trim(line);\n\n    vector<string> wordList;\n    if (!line.empty()) {\n        stringstream ss(line);\n        string word;\n        while (ss >> word) {\n            wordList.push_back(word);\n        }\n    }\n\n    unordered_set<string> dict(wordList.begin(), wordList.end());\n    if (dict.find(endWord) == dict.end()) {\n        cout << 0 << endl;\n        return 0;\n    }\n\n    queue<string> q;\n    q.push(beginWord);\n    unordered_set<string> visited;\n    visited.insert(beginWord);\n    int level = 1;\n\n    while (!q.empty()) {\n        int size = q.size();\n        for (int i = 0; i < size; i++) {\n            string word = q.front();\n            q.pop();\n\n            if (word == endWord) {\n                cout << level << endl;\n                return 0;\n            }\n\n            for (int j = 0; j < (int)word.size(); j++) {\n                char old = word[j];\n                for (char c = \'a\'; c <= \'z\'; c++) {\n                    if (c == old) continue;\n                    word[j] = c;\n                    if (dict.find(word) != dict.end() && visited.find(word) == visited.end()) {\n                        visited.insert(word);\n                        q.push(word);\n                    }\n                }\n                word[j] = old;\n            }\n        }\n        level++;\n    }\n\n    cout << 0 << endl;\n    return 0;\n}', NULL, 1),
(249, 'JAVA', 'import java.io.*;\nimport java.util.*;\n\npublic class Main {\n    public static void main(String[] args) throws IOException {\n        BufferedReader br = new BufferedReader(new InputStreamReader(System.in));\n        String beginWord = br.readLine().trim();\n        String endWord = br.readLine().trim();\n        String line = br.readLine();\n        if (line == null) line = \"\";\n        line = line.trim();\n        List<String> wordList = new ArrayList<>();\n        if (!line.isEmpty()) {\n            String[] parts = line.split(\"\\\\s+\");\n            for (String p : parts) {\n                if (!p.isEmpty()) wordList.add(p);\n            }\n        }\n\n        Set<String> dict = new HashSet<>(wordList);\n        if (!dict.contains(endWord)) {\n            System.out.println(0);\n            return;\n        }\n\n        Queue<String> queue = new LinkedList<>();\n        queue.offer(beginWord);\n        Set<String> visited = new HashSet<>();\n        visited.add(beginWord);\n        int level = 1;\n\n        while (!queue.isEmpty()) {\n            int size = queue.size();\n            for (int i = 0; i < size; i++) {\n                String word = queue.poll();\n                if (word.equals(endWord)) {\n                    System.out.println(level);\n                    return;\n                }\n                char[] chars = word.toCharArray();\n                for (int j = 0; j < chars.length; j++) {\n                    char old = chars[j];\n                    for (char c = \'a\'; c <= \'z\'; c++) {\n                        if (c == old) continue;\n                        chars[j] = c;\n                        String next = new String(chars);\n                        if (dict.contains(next) && !visited.contains(next)) {\n                            visited.add(next);\n                            queue.offer(next);\n                        }\n                    }\n                    chars[j] = old;\n                }\n            }\n            level++;\n        }\n\n        System.out.println(0);\n    }\n}', NULL, 1),
(249, 'JAVASCRIPT', 'const readline = require(\'readline\');\n\nconst rl = readline.createInterface({\n    input: process.stdin,\n    output: process.stdout\n});\n\nconst lines = [];\nrl.on(\'line\', (line) => {\n    lines.push(line);\n});\n\nrl.on(\'close\', () => {\n    const beginWord = lines[0].trim();\n    const endWord = lines[1].trim();\n    let line = lines[2] || \'\';\n    line = line.trim();\n    const wordList = [];\n    if (line.length > 0) {\n        const parts = line.split(/\\s+/);\n        for (const p of parts) {\n            if (p.length > 0) wordList.push(p);\n        }\n    }\n\n    const dict = new Set(wordList);\n    if (!dict.has(endWord)) {\n        console.log(0);\n        return;\n    }\n\n    const queue = [beginWord];\n    const visited = new Set();\n    visited.add(beginWord);\n    let level = 1;\n\n    while (queue.length > 0) {\n        const size = queue.length;\n        for (let i = 0; i < size; i++) {\n            const word = queue.shift();\n            if (word === endWord) {\n                console.log(level);\n                return;\n            }\n            const chars = word.split(\'\');\n            for (let j = 0; j < chars.length; j++) {\n                const old = chars[j];\n                for (let c = 97; c <= 122; c++) {\n                    const ch = String.fromCharCode(c);\n                    if (ch === old) continue;\n                    chars[j] = ch;\n                    const next = chars.join(\'\');\n                    if (dict.has(next) && !visited.has(next)) {\n                        visited.add(next);\n                        queue.push(next);\n                    }\n                }\n                chars[j] = old;\n            }\n        }\n        level++;\n    }\n\n    console.log(0);\n});', NULL, 1),
(249, 'PYTHON', 'import sys\nfrom collections import deque\n\ndef main():\n    lines = sys.stdin.read().splitlines()\n    if len(lines) < 2:\n        return\n    beginWord = lines[0].strip()\n    endWord = lines[1].strip()\n    line = lines[2].strip() if len(lines) > 2 else \"\"\n    wordList = line.split() if line else []\n\n    dict_set = set(wordList)\n    if endWord not in dict_set:\n        print(0)\n        return\n\n    queue = deque([beginWord])\n    visited = {beginWord}\n    level = 1\n\n    while queue:\n        size = len(queue)\n        for _ in range(size):\n            word = queue.popleft()\n            if word == endWord:\n                print(level)\n                return\n            chars = list(word)\n            for j in range(len(chars)):\n                old = chars[j]\n                for c in range(ord(\'a\'), ord(\'z\') + 1):\n                    ch = chr(c)\n                    if ch == old:\n                        continue\n                    chars[j] = ch\n                    nxt = \'\'.join(chars)\n                    if nxt in dict_set and nxt not in visited:\n                        visited.add(nxt)\n                        queue.append(nxt)\n                chars[j] = old\n        level += 1\n\n    print(0)\n\nif __name__ == \"__main__\":\n    main()', NULL, 1),
(250, 'C', '#include <stdio.h>\n#include <stdlib.h>\n\nvoid dfs(int **isConnected, int *visited, int n, int i) {\n    visited[i] = 1;\n    for (int j = 0; j < n; j++) {\n        if (isConnected[i][j] == 1 && !visited[j]) {\n            dfs(isConnected, visited, n, j);\n        }\n    }\n}\n\nint main() {\n    int n;\n    scanf(\"%d\", &n);\n\n    int **isConnected = (int **)malloc(n * sizeof(int *));\n    for (int i = 0; i < n; i++) {\n        isConnected[i] = (int *)malloc(n * sizeof(int));\n        for (int j = 0; j < n; j++) {\n            scanf(\"%d\", &isConnected[i][j]);\n        }\n    }\n\n    int *visited = (int *)calloc(n, sizeof(int));\n    int provinces = 0;\n\n    for (int i = 0; i < n; i++) {\n        if (!visited[i]) {\n            dfs(isConnected, visited, n, i);\n            provinces++;\n        }\n    }\n\n    printf(\"%d\\n\", provinces);\n\n    for (int i = 0; i < n; i++) {\n        free(isConnected[i]);\n    }\n    free(isConnected);\n    free(visited);\n\n    return 0;\n}', NULL, 1),
(250, 'CPP', '#include <iostream>\n#include <vector>\nusing namespace std;\n\nvoid dfs(const vector<vector<int>>& isConnected, vector<bool>& visited, int i) {\n    visited[i] = true;\n    for (int j = 0; j < (int)isConnected.size(); j++) {\n        if (isConnected[i][j] == 1 && !visited[j]) {\n            dfs(isConnected, visited, j);\n        }\n    }\n}\n\nint main() {\n    int n;\n    cin >> n;\n    vector<vector<int>> isConnected(n, vector<int>(n));\n    for (int i = 0; i < n; i++) {\n        for (int j = 0; j < n; j++) {\n            cin >> isConnected[i][j];\n        }\n    }\n    vector<bool> visited(n, false);\n    int provinces = 0;\n    for (int i = 0; i < n; i++) {\n        if (!visited[i]) {\n            dfs(isConnected, visited, i);\n            provinces++;\n        }\n    }\n    cout << provinces << endl;\n    return 0;\n}', NULL, 1),
(250, 'JAVA', 'import java.util.Scanner;\n\npublic class Main {\n    public static void main(String[] args) {\n        Scanner sc = new Scanner(System.in);\n        int n = sc.nextInt();\n        int[][] isConnected = new int[n][n];\n        for (int i = 0; i < n; i++) {\n            for (int j = 0; j < n; j++) {\n                isConnected[i][j] = sc.nextInt();\n            }\n        }\n        boolean[] visited = new boolean[n];\n        int provinces = 0;\n        for (int i = 0; i < n; i++) {\n            if (!visited[i]) {\n                dfs(isConnected, visited, i);\n                provinces++;\n            }\n        }\n        System.out.println(provinces);\n    }\n\n    private static void dfs(int[][] isConnected, boolean[] visited, int i) {\n        visited[i] = true;\n        for (int j = 0; j < isConnected.length; j++) {\n            if (isConnected[i][j] == 1 && !visited[j]) {\n                dfs(isConnected, visited, j);\n            }\n        }\n    }\n}', NULL, 1),
(250, 'JAVASCRIPT', 'const readline = require(\'readline\');\n\nconst rl = readline.createInterface({\n    input: process.stdin,\n    output: process.stdout\n});\n\nlet lines = [];\nrl.on(\'line\', (line) => {\n    lines.push(line.trim());\n});\n\nrl.on(\'close\', () => {\n    let idx = 0;\n    const n = parseInt(lines[idx++]);\n    const isConnected = [];\n    for (let i = 0; i < n; i++) {\n        isConnected.push(lines[idx++].split(/\\s+/).map(Number));\n    }\n    const visited = new Array(n).fill(false);\n    let provinces = 0;\n\n    function dfs(i) {\n        visited[i] = true;\n        for (let j = 0; j < n; j++) {\n            if (isConnected[i][j] === 1 && !visited[j]) {\n                dfs(j);\n            }\n        }\n    }\n\n    for (let i = 0; i < n; i++) {\n        if (!visited[i]) {\n            dfs(i);\n            provinces++;\n        }\n    }\n\n    console.log(provinces);\n});', NULL, 1),
(250, 'PYTHON', 'import sys\n\ndef dfs(isConnected, visited, i):\n    visited[i] = True\n    for j in range(len(isConnected)):\n        if isConnected[i][j] == 1 and not visited[j]:\n            dfs(isConnected, visited, j)\n\ndef main():\n    data = sys.stdin.read().strip().split()\n    if not data:\n        return\n    n = int(data[0])\n    isConnected = []\n    idx = 1\n    for i in range(n):\n        row = []\n        for j in range(n):\n            row.append(int(data[idx]))\n            idx += 1\n        isConnected.append(row)\n    visited = [False] * n\n    provinces = 0\n    for i in range(n):\n        if not visited[i]:\n            dfs(isConnected, visited, i)\n            provinces += 1\n    print(provinces)\n\nif __name__ == \"__main__\":\n    main()', NULL, 1),
