(313, 'C', '#include <stdio.h>\n\nint main() {\n    int n;\n    scanf(\"%d\", &n);\n    int height[n];\n    for (int i = 0; i < n; i++) {\n        scanf(\"%d\", &height[i]);\n    }\n    int left = 0, right = n - 1;\n    int maxWater = 0;\n    while (left < right) {\n        int h = height[left] < height[right] ? height[left] : height[right];\n        int w = right - left;\n        int water = h * w;\n        if (water > maxWater) {\n            maxWater = water;\n        }\n        if (height[left] < height[right]) {\n            left++;\n        } else {\n            right--;\n        }\n    }\n    printf(\"%d\\n\", maxWater);\n    return 0;\n}', NULL, 1),
(313, 'CPP', '#include <iostream>\n#include <vector>\n#include <algorithm>\nusing namespace std;\n\nint main() {\n    int n;\n    cin >> n;\n    vector<int> height(n);\n    for (int i = 0; i < n; i++) {\n        cin >> height[i];\n    }\n    int left = 0, right = n - 1;\n    int maxWater = 0;\n    while (left < right) {\n        int h = min(height[left], height[right]);\n        int w = right - left;\n        maxWater = max(maxWater, h * w);\n        if (height[left] < height[right]) {\n            left++;\n        } else {\n            right--;\n        }\n    }\n    cout << maxWater << endl;\n    return 0;\n}', NULL, 1),
(313, 'JAVA', 'import java.util.Scanner;\n\npublic class Main {\n    public static void main(String[] args) {\n        Scanner sc = new Scanner(System.in);\n        int n = sc.nextInt();\n        int[] height = new int[n];\n        for (int i = 0; i < n; i++) {\n            height[i] = sc.nextInt();\n        }\n        int left = 0, right = n - 1;\n        int maxWater = 0;\n        while (left < right) {\n            int h = Math.min(height[left], height[right]);\n            int w = right - left;\n            maxWater = Math.max(maxWater, h * w);\n            if (height[left] < height[right]) {\n                left++;\n            } else {\n                right--;\n            }\n        }\n        System.out.println(maxWater);\n    }\n}', NULL, 1),
