(314, 'C', '#include <stdio.h>\n#include <stdlib.h>\n\ntypedef struct {\n    int start;\n    int end;\n} Interval;\n\nint cmp(const void *a, const void *b) {\n    Interval *ia = (Interval *)a;\n    Interval *ib = (Interval *)b;\n    if (ia->start < ib->start) return -1;\n    if (ia->start > ib->start) return 1;\n    return 0;\n}\n\nint main() {\n    int n;\n    scanf(\"%d\", &n);\n\n    Interval *intervals = (Interval *)malloc(n * sizeof(Interval));\n    for (int i = 0; i < n; i++) {\n        scanf(\"%d %d\", &intervals[i].start, &intervals[i].end);\n    }\n\n    qsort(intervals, n, sizeof(Interval), cmp);\n\n    Interval *merged = (Interval *)malloc(n * sizeof(Interval));\n    int m = 0;\n\n    for (int i = 0; i < n; i++) {\n        if (m == 0 || merged[m - 1].end < intervals[i].start) {\n            merged[m++] = intervals[i];\n        } else {\n            if (intervals[i].end > merged[m - 1].end) {\n                merged[m - 1].end = intervals[i].end;\n            }\n        }\n    }\n\n    printf(\"[\");\n    for (int i = 0; i < m; i++) {\n        if (i > 0) printf(\",\");\n        printf(\"[%d,%d]\", merged[i].start, merged[i].end);\n    }\n    printf(\"]\\n\");\n\n    free(intervals);\n    free(merged);\n    return 0;\n}', NULL, 1),
(314, 'CPP', '#include <iostream>\n#include <vector>\n#include <algorithm>\nusing namespace std;\n\nint main() {\n    int n;\n    cin >> n;\n    vector<vector<int>> intervals(n, vector<int>(2));\n    for (int i = 0; i < n; i++) {\n        cin >> intervals[i][0] >> intervals[i][1];\n    }\n    sort(intervals.begin(), intervals.end(), [](const vector<int>& a, const vector<int>& b) {\n        return a[0] < b[0];\n    });\n    vector<vector<int>> merged;\n    for (const auto& interval : intervals) {\n        if (merged.empty() || merged.back()[1] < interval[0]) {\n            merged.push_back({interval[0], interval[1]});\n        } else {\n            merged.back()[1] = max(merged.back()[1], interval[1]);\n        }\n    }\n    cout << \"[\";\n    for (size_t i = 0; i < merged.size(); i++) {\n        if (i > 0) cout << \",\";\n        cout << \"[\" << merged[i][0] << \",\" << merged[i][1] << \"]\";\n    }\n    cout << \"]\" << endl;\n    return 0;\n}', NULL, 1),
(314, 'JAVA', 'import java.util.*;\n\npublic class Main {\n    public static void main(String[] args) {\n        Scanner sc = new Scanner(System.in);\n        int n = sc.nextInt();\n        int[][] intervals = new int[n][2];\n        for (int i = 0; i < n; i++) {\n            intervals[i][0] = sc.nextInt();\n            intervals[i][1] = sc.nextInt();\n        }\n        Arrays.sort(intervals, (a, b) -> Integer.compare(a[0], b[0]));\n        List<int[]> merged = new ArrayList<>();\n        for (int[] interval : intervals) {\n            if (merged.isEmpty() || merged.get(merged.size() - 1)[1] < interval[0]) {\n                merged.add(new int[]{interval[0], interval[1]});\n            } else {\n                merged.get(merged.size() - 1)[1] = Math.max(merged.get(merged.size() - 1)[1], interval[1]);\n            }\n        }\n        StringBuilder sb = new StringBuilder();\n        sb.append(\"[\");\n        for (int i = 0; i < merged.size(); i++) {\n            if (i > 0) sb.append(\",\");\n            sb.append(\"[\").append(merged.get(i)[0]).append(\",\").append(merged.get(i)[1]).append(\"]\");\n        }\n        sb.append(\"]\");\n        System.out.println(sb.toString());\n    }\n}', NULL, 1),
(314, 'JAVASCRIPT', 'const readline = require(\'readline\');\n\nconst rl = readline.createInterface({\n    input: process.stdin,\n    output: process.stdout\n});\n\nlet lines = [];\nrl.on(\'line\', (line) => {\n    lines.push(line.trim());\n});\n\nrl.on(\'close\', () => {\n    const n = parseInt(lines[0]);\n    const intervals = [];\n    for (let i = 1; i <= n; i++) {\n        const [a, b] = lines[i].split(\' \').map(Number);\n        intervals.push([a, b]);\n    }\n    intervals.sort((a, b) => a[0] - b[0]);\n    const merged = [];\n    for (const interval of intervals) {\n        if (merged.length === 0 || merged[merged.length - 1][1] < interval[0]) {\n            merged.push([interval[0], interval[1]]);\n        } else {\n            merged[merged.length - 1][1] = Math.max(merged[merged.length - 1][1], interval[1]);\n        }\n    }\n    let result = \'[\';\n    for (let i = 0; i < merged.length; i++) {\n        if (i > 0) result += \',\';\n        result += \'[\' + merged[i][0] + \',\' + merged[i][1] + \']\';\n    }\n    result += \']\';\n    console.log(result);\n});', NULL, 1),
(314, 'PYTHON', 'import sys\n\ndef main():\n    data = sys.stdin.read().strip().split()\n    if not data:\n        return\n    n = int(data[0])\n    intervals = []\n    idx = 1\n    for _ in range(n):\n        intervals.append([int(data[idx]), int(data[idx + 1])])\n        idx += 2\n\n    intervals.sort(key=lambda x: x[0])\n\n    merged = []\n    for interval in intervals:\n        if not merged or merged[-1][1] < interval[0]:\n            merged.append([interval[0], interval[1]])\n        else:\n            merged[-1][1] = max(merged[-1][1], interval[1])\n\n    result = \"[\" + \",\".join(f\"[{a},{b}]\" for a, b in merged) + \"]\"\n    print(result)\n\nif __name__ == \"__main__\":\n    main()', NULL, 1),
(315, 'C', '#include <stdio.h>\n#include <string.h>\n#include <stdlib.h>\n\nint main(void) {\n    char word1[10005], word2[10005];\n    if (fgets(word1, sizeof(word1), stdin) == NULL) return 0;\n    if (fgets(word2, sizeof(word2), stdin) == NULL) return 0;\n\n    size_t n = strlen(word1);\n    size_t m = strlen(word2);\n    if (n > 0 && word1[n - 1] == \'\\n\') word1[--n] = \'\\0\';\n    if (m > 0 && word2[m - 1] == \'\\n\') word2[--m] = \'\\0\';\n\n    int *prev = (int *)malloc((m + 1) * sizeof(int));\n    int *cur = (int *)malloc((m + 1) * sizeof(int));\n    if (!prev || !cur) return 0;\n\n    for (size_t j = 0; j <= m; ++j) prev[j] = (int)j;\n\n    for (size_t i = 1; i <= n; ++i) {\n        cur[0] = (int)i;\n        for (size_t j = 1; j <= m; ++j) {\n            if (word1[i - 1] == word2[j - 1]) {\n                cur[j] = prev[j - 1];\n            } else {\n                int a = prev[j];\n                int b = cur[j - 1];\n                int c = prev[j - 1];\n                int min = a < b ? a : b;\n                if (c < min) min = c;\n                cur[j] = min + 1;\n            }\n        }\n        int *tmp = prev;\n        prev = cur;\n        cur = tmp;\n    }\n\n    printf(\"%d\\n\", prev[m]);\n\n    free(prev);\n    free(cur);\n    return 0;\n}', NULL, 1),
(315, 'CPP', '#include <iostream>\n#include <string>\n#include <vector>\n#include <algorithm>\n\nusing namespace std;\n\nint main() {\n    string word1, word2;\n    getline(cin, word1);\n    getline(cin, word2);\n    int n = word1.length();\n    int m = word2.length();\n    vector<vector<int>> dp(n + 1, vector<int>(m + 1, 0));\n    for (int i = 0; i <= n; i++) {\n        dp[i][0] = i;\n    }\n    for (int j = 0; j <= m; j++) {\n        dp[0][j] = j;\n    }\n    for (int i = 1; i <= n; i++) {\n        for (int j = 1; j <= m; j++) {\n            if (word1[i - 1] == word2[j - 1]) {\n                dp[i][j] = dp[i - 1][j - 1];\n            } else {\n                dp[i][j] = min(min(dp[i - 1][j], dp[i][j - 1]), dp[i - 1][j - 1]) + 1;\n            }\n        }\n    }\n    cout << dp[n][m] << endl;\n    return 0;\n}', NULL, 1),
(315, 'JAVA', 'import java.util.Scanner;\n\npublic class Main {\n    public static void main(String[] args) {\n        Scanner sc = new Scanner(System.in);\n        String word1 = sc.nextLine();\n        String word2 = sc.nextLine();\n        int n = word1.length();\n        int m = word2.length();\n        int[][] dp = new int[n + 1][m + 1];\n        for (int i = 0; i <= n; i++) {\n            dp[i][0] = i;\n        }\n        for (int j = 0; j <= m; j++) {\n            dp[0][j] = j;\n        }\n        for (int i = 1; i <= n; i++) {\n            for (int j = 1; j <= m; j++) {\n                if (word1.charAt(i - 1) == word2.charAt(j - 1)) {\n                    dp[i][j] = dp[i - 1][j - 1];\n                } else {\n                    dp[i][j] = Math.min(Math.min(dp[i - 1][j], dp[i][j - 1]), dp[i - 1][j - 1]) + 1;\n                }\n            }\n        }\n        System.out.println(dp[n][m]);\n    }\n}', NULL, 1),
(315, 'JAVASCRIPT', 'const readline = require(\'readline\');\n\nconst rl = readline.createInterface({\n    input: process.stdin,\n    output: process.stdout\n});\n\nlet lines = [];\nrl.on(\'line\', (line) => {\n    lines.push(line);\n    if (lines.length === 2) {\n        const word1 = lines[0];\n        const word2 = lines[1];\n        const n = word1.length;\n        const m = word2.length;\n        const dp = Array.from({ length: n + 1 }, () => new Array(m + 1).fill(0));\n        for (let i = 0; i <= n; i++) {\n            dp[i][0] = i;\n        }\n        for (let j = 0; j <= m; j++) {\n            dp[0][j] = j;\n        }\n        for (let i = 1; i <= n; i++) {\n            for (let j = 1; j <= m; j++) {\n                if (word1[i - 1] === word2[j - 1]) {\n                    dp[i][j] = dp[i - 1][j - 1];\n                } else {\n                    dp[i][j] = Math.min(dp[i - 1][j], dp[i][j - 1], dp[i - 1][j - 1]) + 1;\n                }\n            }\n        }\n        console.log(dp[n][m]);\n        rl.close();\n    }\n});', NULL, 1),
(315, 'PYTHON', 'word1 = input()\nword2 = input()\nn = len(word1)\nm = len(word2)\ndp = [[0] * (m + 1) for _ in range(n + 1)]\nfor i in range(n + 1):\n    dp[i][0] = i\nfor j in range(m + 1):\n    dp[0][j] = j\nfor i in range(1, n + 1):\n    for j in range(1, m + 1):\n        if word1[i - 1] == word2[j - 1]:\n            dp[i][j] = dp[i - 1][j - 1]\n        else:\n            dp[i][j] = min(dp[i - 1][j], dp[i][j - 1], dp[i - 1][j - 1]) + 1\nprint(dp[n][m])', NULL, 1),
(316, 'C', '#include <stdio.h>\n\nint main() {\n    int n;\n    scanf(\"%d\", &n);\n    int nums[n];\n    for (int i = 0; i < n; i++) {\n        scanf(\"%d\", &nums[i]);\n    }\n\n    if (n == 0) {\n        printf(\"0\\n\");\n        return 0;\n    }\n    if (n == 1) {\n        printf(\"%d\\n\", nums[0]);\n        return 0;\n    }\n\n    int prev2 = nums[0];\n    int prev1 = nums[0] > nums[1] ? nums[0] : nums[1];\n\n    for (int i = 2; i < n; i++) {\n        int current = prev1 > prev2 + nums[i] ? prev1 : prev2 + nums[i];\n        prev2 = prev1;\n        prev1 = current;\n    }\n\n    printf(\"%d\\n\", prev1);\n    return 0;\n}', NULL, 1),
(316, 'CPP', '#include <iostream>\n#include <vector>\n#include <algorithm>\nusing namespace std;\n\nint main() {\n    int n;\n    cin >> n;\n    vector<int> nums(n);\n    for (int i = 0; i < n; i++) {\n        cin >> nums[i];\n    }\n\n    if (n == 0) {\n        cout << 0 << endl;\n        return 0;\n    }\n    if (n == 1) {\n        cout << nums[0] << endl;\n        return 0;\n    }\n\n    int prev2 = nums[0];\n    int prev1 = max(nums[0], nums[1]);\n\n    for (int i = 2; i < n; i++) {\n        int current = max(prev1, prev2 + nums[i]);\n        prev2 = prev1;\n        prev1 = current;\n    }\n\n    cout << prev1 << endl;\n    return 0;\n}', NULL, 1),
(316, 'JAVA', 'import java.util.Scanner;\n\npublic class Main {\n    public static void main(String[] args) {\n        Scanner scanner = new Scanner(System.in);\n        int n = scanner.nextInt();\n        int[] nums = new int[n];\n        for (int i = 0; i < n; i++) {\n            nums[i] = scanner.nextInt();\n        }\n        \n        if (n == 0) {\n            System.out.println(0);\n            return;\n        }\n        if (n == 1) {\n            System.out.println(nums[0]);\n            return;\n        }\n        \n        int prev2 = nums[0];\n        int prev1 = Math.max(nums[0], nums[1]);\n        \n        for (int i = 2; i < n; i++) {\n            int current = Math.max(prev1, prev2 + nums[i]);\n            prev2 = prev1;\n            prev1 = current;\n        }\n        \n        System.out.println(prev1);\n    }\n}', NULL, 1),
(316, 'JAVASCRIPT', 'const readline = require(\'readline\');\n\nconst rl = readline.createInterface({\n    input: process.stdin,\n    output: process.stdout\n});\n\nlet lines = [];\nrl.on(\'line\', (line) => {\n    lines.push(line.trim());\n});\n\nrl.on(\'close\', () => {\n    const n = parseInt(lines[0]);\n    const nums = lines[1].split(\' \').map(Number);\n\n    if (n === 0) {\n        console.log(0);\n        return;\n    }\n    if (n === 1) {\n        console.log(nums[0]);\n        return;\n    }\n\n    let prev2 = nums[0];\n    let prev1 = Math.max(nums[0], nums[1]);\n\n    for (let i = 2; i < n; i++) {\n        let current = Math.max(prev1, prev2 + nums[i]);\n        prev2 = prev1;\n        prev1 = current;\n    }\n\n    console.log(prev1);\n});', NULL, 1),
(316, 'PYTHON', 'n = int(input())\nnums = list(map(int, input().split()))\n\nif n == 0:\n    print(0)\nelif n == 1:\n    print(nums[0])\nelse:\n    prev2 = nums[0]\n    prev1 = max(nums[0], nums[1])\n    for i in range(2, n):\n        current = max(prev1, prev2 + nums[i])\n        prev2 = prev1\n        prev1 = current\n    print(prev1)', NULL, 1),
(317, 'C', '#include <stdio.h>\n\nvoid swap(int *a, int *b) {\n    int tmp = *a;\n    *a = *b;\n    *b = tmp;\n}\n\nvoid reverse(int *nums, int left, int right) {\n    while (left < right) {\n        swap(&nums[left], &nums[right]);\n        left++;\n        right--;\n    }\n}\n\nvoid nextPermutation(int *nums, int n) {\n    int i = n - 2;\n    while (i >= 0 && nums[i] >= nums[i + 1]) {\n        i--;\n    }\n    if (i >= 0) {\n        int j = n - 1;\n        while (nums[j] <= nums[i]) {\n            j--;\n        }\n        swap(&nums[i], &nums[j]);\n    }\n    reverse(nums, i + 1, n - 1);\n}\n\nint main() {\n    int n;\n    scanf(\"%d\", &n);\n    int nums[n];\n    for (int i = 0; i < n; i++) {\n        scanf(\"%d\", &nums[i]);\n    }\n    nextPermutation(nums, n);\n    for (int i = 0; i < n; i++) {\n        if (i > 0) printf(\" \");\n        printf(\"%d\", nums[i]);\n    }\n    printf(\"\\n\");\n    return 0;\n}', NULL, 1),
(317, 'CPP', '#include <iostream>\n#include <vector>\n#include <algorithm>\nusing namespace std;\n\nvoid nextPermutation(vector<int>& nums) {\n    int i = nums.size() - 2;\n    while (i >= 0 && nums[i] >= nums[i + 1]) {\n        i--;\n    }\n    if (i >= 0) {\n        int j = nums.size() - 1;\n        while (nums[j] <= nums[i]) {\n            j--;\n        }\n        swap(nums[i], nums[j]);\n    }\n    reverse(nums.begin() + i + 1, nums.end());\n}\n\nint main() {\n    int n;\n    cin >> n;\n    vector<int> nums(n);\n    for (int i = 0; i < n; i++) {\n        cin >> nums[i];\n    }\n    nextPermutation(nums);\n    for (int i = 0; i < n; i++) {\n        if (i > 0) cout << \' \';\n        cout << nums[i];\n    }\n    cout << endl;\n    return 0;\n}', NULL, 1),
(317, 'JAVA', 'import java.util.Scanner;\n\npublic class Main {\n    public static void main(String[] args) {\n        Scanner sc = new Scanner(System.in);\n        int n = sc.nextInt();\n        int[] nums = new int[n];\n        for (int i = 0; i < n; i++) {\n            nums[i] = sc.nextInt();\n        }\n        nextPermutation(nums);\n        StringBuilder sb = new StringBuilder();\n        for (int i = 0; i < n; i++) {\n            if (i > 0) sb.append(\' \');\n            sb.append(nums[i]);\n        }\n        System.out.println(sb.toString());\n    }\n\n    private static void nextPermutation(int[] nums) {\n        int i = nums.length - 2;\n        while (i >= 0 && nums[i] >= nums[i + 1]) {\n            i--;\n        }\n        if (i >= 0) {\n            int j = nums.length - 1;\n            while (nums[j] <= nums[i]) {\n                j--;\n            }\n            swap(nums, i, j);\n        }\n        reverse(nums, i + 1, nums.length - 1);\n    }\n\n    private static void swap(int[] nums, int i, int j) {\n        int tmp = nums[i];\n        nums[i] = nums[j];\n        nums[j] = tmp;\n    }\n\n    private static void reverse(int[] nums, int left, int right) {\n        while (left < right) {\n            swap(nums, left, right);\n            left++;\n            right--;\n        }\n    }\n}', NULL, 1),
(317, 'JAVASCRIPT', 'const readline = require(\'readline\');\n\nconst rl = readline.createInterface({\n    input: process.stdin,\n    output: process.stdout\n});\n\nlet lines = [];\nrl.on(\'line\', (line) => {\n    lines.push(line.trim());\n    if (lines.length === 2) {\n        const n = parseInt(lines[0]);\n        const nums = lines[1].split(\' \').map(Number);\n        nextPermutation(nums);\n        console.log(nums.join(\' \'));\n        rl.close();\n    }\n});\n\nfunction nextPermutation(nums) {\n    let i = nums.length - 2;\n    while (i >= 0 && nums[i] >= nums[i + 1]) {\n        i--;\n    }\n    if (i >= 0) {\n        let j = nums.length - 1;\n        while (nums[j] <= nums[i]) {\n            j--;\n        }\n        swap(nums, i, j);\n    }\n    reverse(nums, i + 1, nums.length - 1);\n}\n\nfunction swap(nums, i, j) {\n    let tmp = nums[i];\n    nums[i] = nums[j];\n    nums[j] = tmp;\n}\n\nfunction reverse(nums, left, right) {\n    while (left < right) {\n        swap(nums, left, right);\n        left++;\n        right--;\n    }\n}', NULL, 1),
(317, 'PYTHON', 'import sys\n\ndef next_permutation(nums):\n    i = len(nums) - 2\n    while i >= 0 and nums[i] >= nums[i + 1]:\n        i -= 1\n    if i >= 0:\n        j = len(nums) - 1\n        while nums[j] <= nums[i]:\n            j -= 1\n        nums[i], nums[j] = nums[j], nums[i]\n    left, right = i + 1, len(nums) - 1\n    while left < right:\n        nums[left], nums[right] = nums[right], nums[left]\n        left += 1\n        right -= 1\n\ndef main():\n    data = sys.stdin.read().strip().split()\n    if not data:\n        return\n    n = int(data[0])\n    nums = list(map(int, data[1:1 + n]))\n    next_permutation(nums)\n    print(\' \'.join(map(str, nums)))\n\nif __name__ == \"__main__\":\n    main()', NULL, 1),
(318, 'C', '#include <stdio.h>\n#include <string.h>\n\nint main(void) {\n    int n;\n    if (scanf(\"%d\", &n) != 1) {\n        return 0;\n    }\n    getchar();\n\n    char strs[1000][1000];\n    for (int i = 0; i < n; i++) {\n        if (fgets(strs[i], sizeof(strs[i]), stdin) == NULL) {\n            strs[i][0] = \'\\0\';\n            continue;\n        }\n        size_t len = strlen(strs[i]);\n        if (len > 0 && strs[i][len - 1] == \'\\n\') {\n            strs[i][len - 1] = \'\\0\';\n        }\n    }\n\n    if (n == 0) {\n        printf(\"\\n\");\n        return 0;\n    }\n\n    char prefix[1000];\n    strcpy(prefix, strs[0]);\n\n    for (int i = 1; i < n; i++) {\n        while (strncmp(strs[i], prefix, strlen(prefix)) != 0) {\n            size_t len = strlen(prefix);\n            if (len == 0) {\n                printf(\"\\n\");\n                return 0;\n            }\n            prefix[len - 1] = \'\\0\';\n        }\n    }\n\n    printf(\"%s\\n\", prefix);\n    return 0;\n}', NULL, 1),
(318, 'CPP', '#include <iostream>\n#include <string>\n#include <vector>\n\nusing namespace std;\n\nstring longestCommonPrefix(vector<string>& strs) {\n    if (strs.empty()) {\n        return \"\";\n    }\n    string prefix = strs[0];\n    for (size_t i = 1; i < strs.size(); i++) {\n        while (strs[i].find(prefix) != 0) {\n            prefix = prefix.substr(0, prefix.length() - 1);\n            if (prefix.empty()) {\n                return \"\";\n            }\n        }\n    }\n    return prefix;\n}\n\nint main() {\n    int n;\n    cin >> n;\n    cin.ignore();\n    vector<string> strs(n);\n    for (int i = 0; i < n; i++) {\n        getline(cin, strs[i]);\n    }\n    cout << longestCommonPrefix(strs) << endl;\n    return 0;\n}', NULL, 1),
(318, 'JAVA', 'import java.util.Scanner;\n\npublic class Main {\n    public static void main(String[] args) {\n        Scanner scanner = new Scanner(System.in);\n        int n = Integer.parseInt(scanner.nextLine().trim());\n        String[] strs = new String[n];\n        for (int i = 0; i < n; i++) {\n            strs[i] = scanner.nextLine();\n        }\n        System.out.println(longestCommonPrefix(strs));\n    }\n\n    public static String longestCommonPrefix(String[] strs) {\n        if (strs == null || strs.length == 0) {\n            return \"\";\n        }\n        String prefix = strs[0];\n        for (int i = 1; i < strs.length; i++) {\n            while (strs[i].indexOf(prefix) != 0) {\n                prefix = prefix.substring(0, prefix.length() - 1);\n                if (prefix.isEmpty()) {\n                    return \"\";\n                }\n            }\n        }\n        return prefix;\n    }\n}', NULL, 1),
(318, 'JAVASCRIPT', 'const readline = require(\'readline\');\n\nconst rl = readline.createInterface({\n    input: process.stdin,\n    output: process.stdout\n});\n\nlet lines = [];\nrl.on(\'line\', (line) => {\n    lines.push(line);\n});\n\nrl.on(\'close\', () => {\n    const n = parseInt(lines[0].trim(), 10);\n    const strs = [];\n    for (let i = 0; i < n; i++) {\n        strs.push(lines[i + 1]);\n    }\n    console.log(longestCommonPrefix(strs));\n});\n\nfunction longestCommonPrefix(strs) {\n    if (strs == null || strs.length === 0) {\n        return \"\";\n    }\n    let prefix = strs[0];\n    for (let i = 1; i < strs.length; i++) {\n        while (strs[i].indexOf(prefix) !== 0) {\n            prefix = prefix.substring(0, prefix.length - 1);\n            if (prefix.length === 0) {\n                return \"\";\n            }\n        }\n    }\n    return prefix;\n}', NULL, 1),
(318, 'PYTHON', 'n = int(input().strip())\nstrs = []\nfor _ in range(n):\n    strs.append(input())\n\ndef longestCommonPrefix(strs):\n    if not strs:\n        return \"\"\n    prefix = strs[0]\n    for s in strs[1:]:\n        while not s.startswith(prefix):\n            prefix = prefix[:-1]\n            if not prefix:\n                return \"\"\n    return prefix\n\nprint(longestCommonPrefix(strs))', NULL, 1),
(319, 'C', '#include <stdio.h>\n#include <stdlib.h>\n#include <string.h>\n\n#define MAXN 1000005\n\nint inStack[MAXN], outStack[MAXN];\nint inTop = 0, outTop = 0;\n\nvoid pushIn(int x) {\n    inStack[inTop++] = x;\n}\n\nint popIn() {\n    return inStack[--inTop];\n}\n\nint emptyIn() {\n    return inTop == 0;\n}\n\nvoid pushOut(int x) {\n    outStack[outTop++] = x;\n}\n\nint popOut() {\n    return outStack[--outTop];\n}\n\nint peekOut() {\n    return outStack[outTop - 1];\n}\n\nint emptyOut() {\n    return outTop == 0;\n}\n\nint main() {\n    int m;\n    scanf(\"%d\", &m);\n    getchar();\n\n    char line[100];\n    char output[1000000];\n    int outLen = 0;\n\n    for (int i = 0; i < m; i++) {\n        fgets(line, sizeof(line), stdin);\n        line[strcspn(line, \"\\n\")] = \'\\0\';\n\n        if (strncmp(line, \"push\", 4) == 0) {\n            int x = atoi(line + 5);\n            pushIn(x);\n        } else if (strcmp(line, \"pop\") == 0) {\n            if (emptyOut()) {\n                while (!emptyIn()) {\n                    pushOut(popIn());\n                }\n            }\n            outLen += sprintf(output + outLen, \"%d\\n\", popOut());\n        } else if (strcmp(line, \"peek\") == 0) {\n            if (emptyOut()) {\n                while (!emptyIn()) {\n                    pushOut(popIn());\n                }\n            }\n            outLen += sprintf(output + outLen, \"%d\\n\", peekOut());\n        } else if (strcmp(line, \"empty\") == 0) {\n            outLen += sprintf(output + outLen, \"%s\\n\", (emptyIn() && emptyOut()) ? \"true\" : \"false\");\n        }\n    }\n\n    printf(\"%s\", output);\n    return 0;\n}', NULL, 1),
(319, 'CPP', '#include <iostream>\n#include <stack>\n#include <string>\nusing namespace std;\n\nint main() {\n    ios::sync_with_stdio(false);\n    cin.tie(nullptr);\n\n    int m;\n    cin >> m;\n    stack<int> inStack, outStack;\n    string op;\n\n    while (m--) {\n        cin >> op;\n        if (op == \"push\") {\n            int x;\n            cin >> x;\n            inStack.push(x);\n        } else if (op == \"pop\") {\n            if (outStack.empty()) {\n                while (!inStack.empty()) {\n                    outStack.push(inStack.top());\n                    inStack.pop();\n                }\n            }\n            cout << outStack.top() << \'\\n\';\n            outStack.pop();\n        } else if (op == \"peek\") {\n            if (outStack.empty()) {\n                while (!inStack.empty()) {\n                    outStack.push(inStack.top());\n                    inStack.pop();\n                }\n            }\n            cout << outStack.top() << \'\\n\';\n        } else if (op == \"empty\") {\n            cout << (inStack.empty() && outStack.empty() ? \"true\" : \"false\") << \'\\n\';\n        }\n    }\n\n    return 0;\n}', NULL, 1),
(319, 'JAVA', 'import java.util.*;\nimport java.io.*;\n\npublic class Main {\n    public static void main(String[] args) throws IOException {\n        BufferedReader br = new BufferedReader(new InputStreamReader(System.in));\n        int m = Integer.parseInt(br.readLine().trim());\n        Deque<Integer> inStack = new ArrayDeque<>();\n        Deque<Integer> outStack = new ArrayDeque<>();\n        StringBuilder sb = new StringBuilder();\n\n        for (int i = 0; i < m; i++) {\n            String line = br.readLine().trim();\n            if (line.startsWith(\"push\")) {\n                int x = Integer.parseInt(line.substring(5).trim());\n                inStack.push(x);\n            } else if (line.equals(\"pop\")) {\n                if (outStack.isEmpty()) {\n                    while (!inStack.isEmpty()) {\n                        outStack.push(inStack.pop());\n                    }\n                }\n                sb.append(outStack.pop()).append(\'\\n\');\n            } else if (line.equals(\"peek\")) {\n                if (outStack.isEmpty()) {\n                    while (!inStack.isEmpty()) {\n                        outStack.push(inStack.pop());\n                    }\n                }\n                sb.append(outStack.peek()).append(\'\\n\');\n            } else if (line.equals(\"empty\")) {\n                sb.append(inStack.isEmpty() && outStack.isEmpty() ? \"true\" : \"false\").append(\'\\n\');\n            }\n        }\n\n        System.out.print(sb);\n    }\n}', NULL, 1),
(319, 'JAVASCRIPT', 'const readline = require(\'readline\');\n\nconst rl = readline.createInterface({\n    input: process.stdin,\n    output: process.stdout\n});\n\nlet lines = [];\nrl.on(\'line\', (line) => {\n    lines.push(line.trim());\n});\n\nrl.on(\'close\', () => {\n    const m = parseInt(lines[0]);\n    const inStack = [];\n    const outStack = [];\n    let output = [];\n\n    for (let i = 1; i <= m; i++) {\n        const line = lines[i];\n        if (line.startsWith(\'push\')) {\n            const x = parseInt(line.substring(5).trim());\n            inStack.push(x);\n        } else if (line === \'pop\') {\n            if (outStack.length === 0) {\n                while (inStack.length > 0) {\n                    outStack.push(inStack.pop());\n                }\n            }\n            output.push(outStack.pop());\n        } else if (line === \'peek\') {\n            if (outStack.length === 0) {\n                while (inStack.length > 0) {\n                    outStack.push(inStack.pop());\n                }\n            }\n            output.push(outStack[outStack.length - 1]);\n        } else if (line === \'empty\') {\n            output.push(inStack.length === 0 && outStack.length === 0 ? \'true\' : \'false\');\n        }\n    }\n\n    process.stdout.write(output.join(\'\\n\') + (output.length > 0 ? \'\\n\' : \'\'));\n});', NULL, 1),
(319, 'PYTHON', 'import sys\n\ndef main():\n    input_data = sys.stdin.read().splitlines()\n    m = int(input_data[0].strip())\n    in_stack = []\n    out_stack = []\n    output = []\n\n    for i in range(1, m + 1):\n        line = input_data[i].strip()\n        if line.startswith(\"push\"):\n            x = int(line[5:].strip())\n            in_stack.append(x)\n        elif line == \"pop\":\n            if not out_stack:\n                while in_stack:\n                    out_stack.append(in_stack.pop())\n            output.append(str(out_stack.pop()))\n        elif line == \"peek\":\n            if not out_stack:\n                while in_stack:\n                    out_stack.append(in_stack.pop())\n            output.append(str(out_stack[-1]))\n        elif line == \"empty\":\n            output.append(\"true\" if not in_stack and not out_stack else \"false\")\n\n    sys.stdout.write(\"\\n\".join(output) + (\"\\n\" if output else \"\"))\n\nif __name__ == \"__main__\":\n    main()', NULL, 1),
(320, 'C', '#include <stdio.h>\n#include <stdlib.h>\n#include <string.h>\n\ntypedef struct {\n    int *data;\n    int *minData;\n    int top;\n    int minTop;\n    int capacity;\n} MinStack;\n\nMinStack* minStackCreate(int capacity) {\n    MinStack *obj = (MinStack*)malloc(sizeof(MinStack));\n    obj->data = (int*)malloc(sizeof(int) * capacity);\n    obj->minData = (int*)malloc(sizeof(int) * capacity);\n    obj->top = -1;\n    obj->minTop = -1;\n    obj->capacity = capacity;\n    return obj;\n}\n\nvoid minStackPush(MinStack *obj, int val) {\n    obj->data[++obj->top] = val;\n    if (obj->minTop == -1 || val <= obj->minData[obj->minTop]) {\n        obj->minData[++obj->minTop] = val;\n    }\n}\n\nvoid minStackPop(MinStack *obj) {\n    int val = obj->data[obj->top--];\n    if (val == obj->minData[obj->minTop]) {\n        obj->minTop--;\n    }\n}\n\nint minStackTop(MinStack *obj) {\n    return obj->data[obj->top];\n}\n\nint minStackGetMin(MinStack *obj) {\n    return obj->minData[obj->minTop];\n}\n\nvoid minStackFree(MinStack *obj) {\n    free(obj->data);\n    free(obj->minData);\n    free(obj);\n}\n\nint main() {\n    int m;\n    if (scanf(\"%d\", &m) != 1) return 0;\n\n    MinStack *stack = minStackCreate(m + 5);\n\n    char op[20];\n    int val;\n    char output[1000000];\n    int outPos = 0;\n\n    for (int i = 0; i < m; i++) {\n        scanf(\"%s\", op);\n        if (strcmp(op, \"push\") == 0) {\n            scanf(\"%d\", &val);\n            minStackPush(stack, val);\n        } else if (strcmp(op, \"pop\") == 0) {\n            minStackPop(stack);\n        } else if (strcmp(op, \"top\") == 0) {\n            outPos += sprintf(output + outPos, \"%d\\n\", minStackTop(stack));\n        } else if (strcmp(op, \"getMin\") == 0) {\n            outPos += sprintf(output + outPos, \"%d\\n\", minStackGetMin(stack));\n        }\n    }\n\n    fwrite(output, 1, outPos, stdout);\n\n    minStackFree(stack);\n    return 0;\n}', NULL, 1),
(320, 'CPP', '#include <iostream>\n#include <string>\n#include <stack>\nusing namespace std;\n\nclass MinStack {\nprivate:\n    stack<int> st;\n    stack<int> minSt;\npublic:\n    void push(int val) {\n        st.push(val);\n        if (minSt.empty() || val <= minSt.top()) {\n            minSt.push(val);\n        }\n    }\n    void pop() {\n        int val = st.top();\n        st.pop();\n        if (val == minSt.top()) {\n            minSt.pop();\n        }\n    }\n    int top() {\n        return st.top();\n    }\n    int getMin() {\n        return minSt.top();\n    }\n};\n\nint main() {\n    ios::sync_with_stdio(false);\n    cin.tie(nullptr);\n\n    int m;\n    cin >> m;\n    MinStack stack;\n    string op;\n    for (int i = 0; i < m; ++i) {\n        cin >> op;\n        if (op == \"push\") {\n            int val;\n            cin >> val;\n            stack.push(val);\n        } else if (op == \"pop\") {\n            stack.pop();\n        } else if (op == \"top\") {\n            cout << stack.top() << \'\\n\';\n        } else if (op == \"getMin\") {\n            cout << stack.getMin() << \'\\n\';\n        }\n    }\n    return 0;\n}', NULL, 1),
(320, 'JAVA', 'import java.io.*;\nimport java.util.*;\n\npublic class Main {\n    public static void main(String[] args) throws IOException {\n        BufferedReader br = new BufferedReader(new InputStreamReader(System.in));\n        int m = Integer.parseInt(br.readLine().trim());\n        MinStack stack = new MinStack();\n        StringBuilder sb = new StringBuilder();\n\n        for (int i = 0; i < m; i++) {\n            String line = br.readLine().trim();\n            if (line.startsWith(\"push\")) {\n                int val = Integer.parseInt(line.substring(5).trim());\n                stack.push(val);\n            } else if (line.equals(\"pop\")) {\n                stack.pop();\n            } else if (line.equals(\"top\")) {\n                sb.append(stack.top()).append(\'\\n\');\n            } else if (line.equals(\"getMin\")) {\n                sb.append(stack.getMin()).append(\'\\n\');\n            }\n        }\n\n        System.out.print(sb.toString());\n    }\n\n    static class MinStack {\n        private Deque<Integer> stack;\n        private Deque<Integer> minStack;\n\n        public MinStack() {\n            stack = new ArrayDeque<>();\n            minStack = new ArrayDeque<>();\n        }\n\n        public void push(int val) {\n            stack.push(val);\n            if (minStack.isEmpty() || val <= minStack.peek()) {\n                minStack.push(val);\n            }\n        }\n\n        public void pop() {\n            int val = stack.pop();\n            if (val == minStack.peek()) {\n                minStack.pop();\n            }\n        }\n\n        public int top() {\n            return stack.peek();\n        }\n\n        public int getMin() {\n            return minStack.peek();\n        }\n    }\n}', NULL, 1),
(320, 'JAVASCRIPT', 'const readline = require(\'readline\');\n\nconst rl = readline.createInterface({\n    input: process.stdin,\n    output: process.stdout\n});\n\nclass MinStack {\n    constructor() {\n        this.stack = [];\n        this.minStack = [];\n    }\n\n    push(val) {\n        this.stack.push(val);\n        if (this.minStack.length === 0 || val <= this.minStack[this.minStack.length - 1]) {\n            this.minStack.push(val);\n        }\n    }\n\n    pop() {\n        const val = this.stack.pop();\n        if (val === this.minStack[this.minStack.length - 1]) {\n            this.minStack.pop();\n        }\n    }\n\n    top() {\n        return this.stack[this.stack.length - 1];\n    }\n\n    getMin() {\n        return this.minStack[this.minStack.length - 1];\n    }\n}\n\nlet m = null;\nlet count = 0;\nconst stack = new MinStack();\nconst output = [];\n\nrl.on(\'line\', (line) => {\n    line = line.trim();\n    if (m === null) {\n        m = parseInt(line);\n        return;\n    }\n\n    if (count >= m) return;\n    count++;\n\n    if (line.startsWith(\'push\')) {\n        const val = parseInt(line.substring(5).trim());\n        stack.push(val);\n    } else if (line === \'pop\') {\n        stack.pop();\n    } else if (line === \'top\') {\n        output.push(stack.top());\n    } else if (line === \'getMin\') {\n        output.push(stack.getMin());\n    }\n\n    if (count === m) {\n        console.log(output.join(\'\\n\'));\n        rl.close();\n    }\n});', NULL, 1),
(320, 'PYTHON', 'import sys\n\nclass MinStack:\n    def __init__(self):\n        self.stack = []\n        self.min_stack = []\n\n    def push(self, val):\n        self.stack.append(val)\n        if not self.min_stack or val <= self.min_stack[-1]:\n            self.min_stack.append(val)\n\n    def pop(self):\n        val = self.stack.pop()\n        if val == self.min_stack[-1]:\n            self.min_stack.pop()\n\n    def top(self):\n        return self.stack[-1]\n\n    def getMin(self):\n        return self.min_stack[-1]\n\ndef main():\n    data = sys.stdin.read().strip().split(\'\\n\')\n    if not data:\n        return\n    m = int(data[0].strip())\n    stack = MinStack()\n    out = []\n    for i in range(1, m + 1):\n        line = data[i].strip()\n        if line.startswith(\"push\"):\n            val = int(line[5:].strip())\n            stack.push(val)\n        elif line == \"pop\":\n            stack.pop()\n        elif line == \"top\":\n            out.append(str(stack.top()))\n        elif line == \"getMin\":\n            out.append(str(stack.getMin()))\n    sys.stdout.write(\'\\n\'.join(out))\n\nif __name__ == \"__main__\":\n    main()', NULL, 1),
(321, 'C', '#include <stdio.h>\n#include <stdlib.h>\n#include <string.h>\n\ntypedef struct TreeNode {\n    int val;\n    struct TreeNode *left;\n    struct TreeNode *right;\n} TreeNode;\n\nTreeNode* createNode(int val) {\n    TreeNode* node = (TreeNode*)malloc(sizeof(TreeNode));\n    node->val = val;\n    node->left = NULL;\n    node->right = NULL;\n    return node;\n}\n\nTreeNode* buildTree(char* line) {\n    char* s = line;\n    while (*s == \' \' || *s == \'\\t\') s++;\n    if (*s == \'[\') s++;\n    int len = strlen(s);\n    while (len > 0 && (s[len-1] == \']\' || s[len-1] == \'\\n\' || s[len-1] == \'\\r\' || s[len-1] == \' \' || s[len-1] == \'\\t\')) {\n        s[--len] = \'\\0\';\n    }\n    if (len == 0) return NULL;\n\n    char* parts[10000];\n    int count = 0;\n    char* token = strtok(s, \",\");\n    while (token != NULL) {\n        while (*token == \' \') token++;\n        parts[count++] = token;\n        token = strtok(NULL, \",\");\n    }\n    if (count == 0 || strcmp(parts[0], \"null\") == 0) return NULL;\n\n    TreeNode* root = createNode(atoi(parts[0]));\n    TreeNode* queue[10000];\n    int front = 0, rear = 0;\n    queue[rear++] = root;\n    int i = 1;\n    while (front < rear && i < count) {\n        TreeNode* cur = queue[front++];\n        if (i < count) {\n            char* leftVal = parts[i++];\n            if (strcmp(leftVal, \"null\") != 0) {\n                cur->left = createNode(atoi(leftVal));\n                queue[rear++] = cur->left;\n            }\n        }\n        if (i < count) {\n            char* rightVal = parts[i++];\n            if (strcmp(rightVal, \"null\") != 0) {\n                cur->right = createNode(atoi(rightVal));\n                queue[rear++] = cur->right;\n            }\n        }\n    }\n    return root;\n}\n\nTreeNode* findNode(TreeNode* root, int val) {\n    if (root == NULL) return NULL;\n    if (root->val == val) return root;\n    TreeNode* left = findNode(root->left, val);\n    if (left != NULL) return left;\n    return findNode(root->right, val);\n}\n\nTreeNode* lowestCommonAncestor(TreeNode* root, TreeNode* p, TreeNode* q) {\n    if (root == NULL || root == p || root == q) return root;\n    TreeNode* left = lowestCommonAncestor(root->left, p, q);\n    TreeNode* right = lowestCommonAncestor(root->right, p, q);\n    if (left != NULL && right != NULL) return root;\n    return left != NULL ? left : right;\n}\n\nint main() {\n    char line[100000];\n    if (fgets(line, sizeof(line), stdin) == NULL) return 0;\n    int pVal, qVal;\n    scanf(\"%d\", &pVal);\n    scanf(\"%d\", &qVal);\n\n    TreeNode* root = buildTree(line);\n    TreeNode* p = findNode(root, pVal);\n    TreeNode* q = findNode(root, qVal);\n    TreeNode* lca = lowestCommonAncestor(root, p, q);\n    printf(\"%d\\n\", lca->val);\n    return 0;\n}', NULL, 1),
(321, 'CPP', '#include <bits/stdc++.h>\nusing namespace std;\n\nstruct TreeNode {\n    int val;\n    TreeNode *left;\n    TreeNode *right;\n    TreeNode(int x) : val(x), left(nullptr), right(nullptr) {}\n};\n\nTreeNode* buildTree(const string& line) {\n    string s = line;\n    size_t start = s.find_first_not_of(\" \\t\\r\\n\");\n    size_t end = s.find_last_not_of(\" \\t\\r\\n\");\n    if (start == string::npos) return nullptr;\n    s = s.substr(start, end - start + 1);\n\n    if (!s.empty() && s.front() == \'[\') s.erase(s.begin());\n    if (!s.empty() && s.back() == \']\') s.pop_back();\n\n    if (s.empty()) return nullptr;\n\n    vector<string> parts;\n    stringstream ss(s);\n    string item;\n    while (getline(ss, item, \',\')) {\n        size_t l = item.find_first_not_of(\" \\t\\r\\n\");\n        size_t r = item.find_last_not_of(\" \\t\\r\\n\");\n        if (l == string::npos) parts.push_back(\"\");\n        else parts.push_back(item.substr(l, r - l + 1));\n    }\n\n    if (parts.empty() || parts[0] == \"null\") return nullptr;\n\n    TreeNode* root = new TreeNode(stoi(parts[0]));\n    queue<TreeNode*> q;\n    q.push(root);\n    int i = 1;\n\n    while (!q.empty() && i < (int)parts.size()) {\n        TreeNode* cur = q.front();\n        q.pop();\n\n        if (i < (int)parts.size()) {\n            string leftVal = parts[i++];\n            if (leftVal != \"null\") {\n                cur->left = new TreeNode(stoi(leftVal));\n                q.push(cur->left);\n            }\n        }\n\n        if (i < (int)parts.size()) {\n            string rightVal = parts[i++];\n            if (rightVal != \"null\") {\n                cur->right = new TreeNode(stoi(rightVal));\n                q.push(cur->right);\n            }\n        }\n    }\n\n    return root;\n}\n\nTreeNode* findNode(TreeNode* root, int val) {\n    if (!root) return nullptr;\n    if (root->val == val) return root;\n    TreeNode* left = findNode(root->left, val);\n    if (left) return left;\n    return findNode(root->right, val);\n}\n\nTreeNode* lowestCommonAncestor(TreeNode* root, TreeNode* p, TreeNode* q) {\n    if (!root || root == p || root == q) return root;\n    TreeNode* left = lowestCommonAncestor(root->left, p, q);\n    TreeNode* right = lowestCommonAncestor(root->right, p, q);\n    if (left && right) return root;\n    return left ? left : right;\n}\n\nint main() {\n    ios::sync_with_stdio(false);\n    cin.tie(nullptr);\n\n    string line;\n    getline(cin, line);\n\n    string pLine, qLine;\n    getline(cin, pLine);\n    getline(cin, qLine);\n\n    int pVal = stoi(pLine);\n    int qVal = stoi(qLine);\n\n    TreeNode* root = buildTree(line);\n    TreeNode* p = findNode(root, pVal);\n    TreeNode* q = findNode(root, qVal);\n    TreeNode* lca = lowestCommonAncestor(root, p, q);\n\n    cout << lca->val << \'\\n\';\n    return 0;\n}', NULL, 1),
(321, 'JAVA', 'import java.util.*;\n\npublic class Main {\n    static class TreeNode {\n        int val;\n        TreeNode left;\n        TreeNode right;\n        TreeNode(int x) { val = x; }\n    }\n\n    public static void main(String[] args) {\n        Scanner sc = new Scanner(System.in);\n        String line = sc.nextLine().trim();\n        int pVal = Integer.parseInt(sc.nextLine().trim());\n        int qVal = Integer.parseInt(sc.nextLine().trim());\n\n        TreeNode root = buildTree(line);\n        TreeNode p = findNode(root, pVal);\n        TreeNode q = findNode(root, qVal);\n        TreeNode lca = lowestCommonAncestor(root, p, q);\n        System.out.println(lca.val);\n    }\n\n    private static TreeNode buildTree(String line) {\n        String s = line.trim();\n        if (s.startsWith(\"[\")) s = s.substring(1);\n        if (s.endsWith(\"]\")) s = s.substring(0, s.length() - 1);\n        if (s.isEmpty()) return null;\n\n        String[] parts = s.split(\",\");\n        if (parts.length == 0 || parts[0].trim().equals(\"null\")) return null;\n\n        TreeNode root = new TreeNode(Integer.parseInt(parts[0].trim()));\n        Queue<TreeNode> queue = new LinkedList<>();\n        queue.offer(root);\n        int i = 1;\n        while (!queue.isEmpty() && i < parts.length) {\n            TreeNode cur = queue.poll();\n            if (i < parts.length) {\n                String leftVal = parts[i++].trim();\n                if (!leftVal.equals(\"null\")) {\n                    cur.left = new TreeNode(Integer.parseInt(leftVal));\n                    queue.offer(cur.left);\n                }\n            }\n            if (i < parts.length) {\n                String rightVal = parts[i++].trim();\n                if (!rightVal.equals(\"null\")) {\n                    cur.right = new TreeNode(Integer.parseInt(rightVal));\n                    queue.offer(cur.right);\n                }\n            }\n        }\n        return root;\n    }\n\n    private static TreeNode findNode(TreeNode root, int val) {\n        if (root == null) return null;\n        if (root.val == val) return root;\n        TreeNode left = findNode(root.left, val);\n        if (left != null) return left;\n        return findNode(root.right, val);\n    }\n\n    private static TreeNode lowestCommonAncestor(TreeNode root, TreeNode p, TreeNode q) {\n        if (root == null || root == p || root == q) return root;\n        TreeNode left = lowestCommonAncestor(root.left, p, q);\n        TreeNode right = lowestCommonAncestor(root.right, p, q);\n        if (left != null && right != null) return root;\n        return left != null ? left : right;\n    }\n}', NULL, 1),
(321, 'JAVASCRIPT', 'const readline = require(\'readline\');\n\nclass TreeNode {\n    constructor(val) {\n        this.val = val;\n        this.left = null;\n        this.right = null;\n    }\n}\n\nfunction buildTree(line) {\n    let s = line.trim();\n    if (s.startsWith(\'[\')) s = s.substring(1);\n    if (s.endsWith(\']\')) s = s.substring(0, s.length - 1);\n    if (s.length === 0) return null;\n\n    const parts = s.split(\',\');\n    if (parts.length === 0 || parts[0].trim() === \'null\') return null;\n\n    const root = new TreeNode(parseInt(parts[0].trim(), 10));\n    const queue = [root];\n    let i = 1;\n    while (queue.length > 0 && i < parts.length) {\n        const cur = queue.shift();\n        if (i < parts.length) {\n            const leftVal = parts[i++].trim();\n            if (leftVal !== \'null\') {\n                cur.left = new TreeNode(parseInt(leftVal, 10));\n                queue.push(cur.left);\n            }\n        }\n        if (i < parts.length) {\n            const rightVal = parts[i++].trim();\n            if (rightVal !== \'null\') {\n                cur.right = new TreeNode(parseInt(rightVal, 10));\n                queue.push(cur.right);\n            }\n        }\n    }\n    return root;\n}\n\nfunction findNode(root, val) {\n    if (root === null) return null;\n    if (root.val === val) return root;\n    const left = findNode(root.left, val);\n    if (left !== null) return left;\n    return findNode(root.right, val);\n}\n\nfunction lowestCommonAncestor(root, p, q) {\n    if (root === null || root === p || root === q) return root;\n    const left = lowestCommonAncestor(root.left, p, q);\n    const right = lowestCommonAncestor(root.right, p, q);\n    if (left !== null && right !== null) return root;\n    return left !== null ? left : right;\n}\n\nconst rl = readline.createInterface({\n    input: process.stdin,\n    output: process.stdout\n});\n\nconst lines = [];\nrl.on(\'line\', (line) => {\n    lines.push(line);\n    if (lines.length === 3) {\n        rl.close();\n        const treeLine = lines[0].trim();\n        const pVal = parseInt(lines[1].trim(), 10);\n        const qVal = parseInt(lines[2].trim(), 10);\n\n        const root = buildTree(treeLine);\n        const p = findNode(root, pVal);\n        const q = findNode(root, qVal);\n        const lca = lowestCommonAncestor(root, p, q);\n        console.log(lca.val);\n    }\n});', NULL, 1),
(321, 'PYTHON', 'import sys\nfrom collections import deque\n\nclass TreeNode:\n    def __init__(self, x):\n        self.val = x\n        self.left = None\n        self.right = None\n\ndef build_tree(line):\n    s = line.strip()\n    if s.startswith(\"[\"):\n        s = s[1:]\n    if s.endswith(\"]\"):\n        s = s[:-1]\n    if not s:\n        return None\n    parts = [x.strip() for x in s.split(\",\")]\n    if not parts or parts[0] == \"null\":\n        return None\n    root = TreeNode(int(parts[0]))\n    queue = deque([root])\n    i = 1\n    while queue and i < len(parts):\n        cur = queue.popleft()\n        if i < len(parts):\n            left_val = parts[i]\n            i += 1\n            if left_val != \"null\":\n                cur.left = TreeNode(int(left_val))\n                queue.append(cur.left)\n        if i < len(parts):\n            right_val = parts[i]\n            i += 1\n            if right_val != \"null\":\n                cur.right = TreeNode(int(right_val))\n                queue.append(cur.right)\n    return root\n\ndef find_node(root, val):\n    if root is None:\n        return None\n    if root.val == val:\n        return root\n    left = find_node(root.left, val)\n    if left is not None:\n        return left\n    return find_node(root.right, val)\n\ndef lowest_common_ancestor(root, p, q):\n    if root is None or root is p or root is q:\n        return root\n    left = lowest_common_ancestor(root.left, p, q)\n    right = lowest_common_ancestor(root.right, p, q)\n    if left is not None and right is not None:\n        return root\n    return left if left is not None else right\n\ndef main():\n    line = sys.stdin.readline().strip()\n    p_val = int(sys.stdin.readline().strip())\n    q_val = int(sys.stdin.readline().strip())\n    root = build_tree(line)\n    p = find_node(root, p_val)\n    q = find_node(root, q_val)\n    lca = lowest_common_ancestor(root, p, q)\n    print(lca.val)\n\nif __name__ == \"__main__\":\n    main()', NULL, 1),
(322, 'C', '#include <stdio.h>\n#include <stdlib.h>\n#include <string.h>\n#include <stdbool.h>\n#include <limits.h>\n\ntypedef struct TreeNode {\n    int val;\n    struct TreeNode *left;\n    struct TreeNode *right;\n} TreeNode;\n\nstatic TreeNode* newTreeNode(int val) {\n    TreeNode* node = (TreeNode*)malloc(sizeof(TreeNode));\n    node->val = val;\n    node->left = NULL;\n    node->right = NULL;\n    return node;\n}\n\nstatic TreeNode* buildTree(int* nums, int* isNull, int n) {\n    if (n == 0 || isNull[0]) return NULL;\n    TreeNode* root = newTreeNode(nums[0]);\n    TreeNode** queue = (TreeNode**)malloc(sizeof(TreeNode*) * n);\n    int front = 0, rear = 0;\n    queue[rear++] = root;\n    int i = 1;\n    while (front < rear && i < n) {\n        TreeNode* node = queue[front++];\n        if (i < n && !isNull[i]) {\n            node->left = newTreeNode(nums[i]);\n            queue[rear++] = node->left;\n        }\n        i++;\n        if (i < n && !isNull[i]) {\n            node->right = newTreeNode(nums[i]);\n            queue[rear++] = node->right;\n        }\n        i++;\n    }\n    free(queue);\n    return root;\n}\n\nstatic bool validate(TreeNode* node, long long min, long long max) {\n    if (node == NULL) return true;\n    if (node->val <= min) return false;\n    if (node->val >= max) return false;\n    return validate(node->left, min, node->val) && validate(node->right, node->val, max);\n}\n\nstatic bool isValidBST(TreeNode* root) {\n    return validate(root, LLONG_MIN, LLONG_MAX);\n}\n\nint main(void) {\n    char line[1000005];\n    if (!fgets(line, sizeof(line), stdin)) return 0;\n    size_t len = strlen(line);\n    while (len > 0 && (line[len - 1] == \'\\n\' || line[len - 1] == \'\\r\')) {\n        line[--len] = \'\\0\';\n    }\n    char* s = line;\n    while (*s == \' \' || *s == \'\\t\') s++;\n    if (*s == \'[\') s++;\n    len = strlen(s);\n    while (len > 0 && (s[len - 1] == \' \' || s[len - 1] == \'\\t\')) {\n        s[--len] = \'\\0\';\n    }\n    if (len > 0 && s[len - 1] == \']\') s[--len] = \'\\0\';\n    if (len == 0) {\n        printf(\"true\\n\");\n        return 0;\n    }\n\n    int capacity = 16;\n    int* nums = (int*)malloc(sizeof(int) * capacity);\n    int* isNull = (int*)malloc(sizeof(int) * capacity);\n    int n = 0;\n\n    char* token = strtok(s, \",\");\n    while (token != NULL) {\n        while (*token == \' \' || *token == \'\\t\') token++;\n        size_t tlen = strlen(token);\n        while (tlen > 0 && (token[tlen - 1] == \' \' || token[tlen - 1] == \'\\t\')) {\n            token[--tlen] = \'\\0\';\n        }\n        if (n >= capacity) {\n            capacity *= 2;\n            nums = (int*)realloc(nums, sizeof(int) * capacity);\n            isNull = (int*)realloc(isNull, sizeof(int) * capacity);\n        }\n        if (strcmp(token, \"null\") == 0) {\n            nums[n] = 0;\n            isNull[n] = 1;\n        } else {\n            nums[n] = atoi(token);\n            isNull[n] = 0;\n        }\n        n++;\n        token = strtok(NULL, \",\");\n    }\n\n    TreeNode* root = buildTree(nums, isNull, n);\n    printf(\"%s\\n\", isValidBST(root) ? \"true\" : \"false\");\n\n    free(nums);\n    free(isNull);\n    return 0;\n}', NULL, 1),
(322, 'CPP', '#include <iostream>\n#include <string>\n#include <vector>\n#include <queue>\n#include <sstream>\n#include <climits>\n\nusing namespace std;\n\nstruct TreeNode {\n    int val;\n    TreeNode *left, *right;\n    TreeNode(int v) : val(v), left(nullptr), right(nullptr) {}\n};\n\nTreeNode* buildTree(vector<string>& nums) {\n    if (nums.empty() || nums[0] == \"null\") return nullptr;\n    TreeNode* root = new TreeNode(stoi(nums[0]));\n    queue<TreeNode*> q;\n    q.push(root);\n    int i = 1;\n    while (!q.empty() && i < (int)nums.size()) {\n        TreeNode* node = q.front(); q.pop();\n        if (i < (int)nums.size() && nums[i] != \"null\") {\n            node->left = new TreeNode(stoi(nums[i]));\n            q.push(node->left);\n        }\n        i++;\n        if (i < (int)nums.size() && nums[i] != \"null\") {\n            node->right = new TreeNode(stoi(nums[i]));\n            q.push(node->right);\n        }\n        i++;\n    }\n    return root;\n}\n\nbool validate(TreeNode* node, long long minVal, long long maxVal) {\n    if (!node) return true;\n    if (node->val <= minVal || node->val >= maxVal) return false;\n    return validate(node->left, minVal, node->val) && validate(node->right, node->val, maxVal);\n}\n\nbool isValidBST(TreeNode* root) {\n    return validate(root, LLONG_MIN, LLONG_MAX);\n}\n\nint main() {\n    string line;\n    if (!getline(cin, line)) return 0;\n    while (!line.empty() && (line.back() == \'\\r\' || line.back() == \'\\n\')) line.pop_back();\n    if (!line.empty() && line.front() == \'[\') line = line.substr(1);\n    if (!line.empty() && line.back() == \']\') line.pop_back();\n    if (line.empty()) {\n        cout << \"true\" << endl;\n        return 0;\n    }\n    vector<string> parts;\n    stringstream ss(line);\n    string token;\n    while (getline(ss, token, \',\')) {\n        size_t start = token.find_first_not_of(\" \\t\");\n        size_t end = token.find_last_not_of(\" \\t\");\n        if (start == string::npos) parts.push_back(\"\");\n        else parts.push_back(token.substr(start, end - start + 1));\n    }\n    TreeNode* root = buildTree(parts);\n    cout << (isValidBST(root) ? \"true\" : \"false\") << endl;\n    return 0;\n}', NULL, 1),
(322, 'JAVA', 'import java.util.*;\n\npublic class Main {\n    public static void main(String[] args) {\n        Scanner sc = new Scanner(System.in);\n        if (!sc.hasNextLine()) return;\n        String line = sc.nextLine().trim();\n        if (line.startsWith(\"[\")) line = line.substring(1);\n        if (line.endsWith(\"]\")) line = line.substring(0, line.length() - 1);\n        if (line.isEmpty()) {\n            System.out.println(\"true\");\n            return;\n        }\n        String[] parts = line.split(\",\");\n        Integer[] nums = new Integer[parts.length];\n        for (int i = 0; i < parts.length; i++) {\n            String s = parts[i].trim();\n            if (s.equals(\"null\")) nums[i] = null;\n            else nums[i] = Integer.parseInt(s);\n        }\n        TreeNode root = buildTree(nums);\n        System.out.println(isValidBST(root));\n    }\n\n    static class TreeNode {\n        int val;\n        TreeNode left, right;\n        TreeNode(int val) { this.val = val; }\n    }\n\n    static TreeNode buildTree(Integer[] nums) {\n        if (nums.length == 0 || nums[0] == null) return null;\n        TreeNode root = new TreeNode(nums[0]);\n        Queue<TreeNode> queue = new LinkedList<>();\n        queue.offer(root);\n        int i = 1;\n        while (!queue.isEmpty() && i < nums.length) {\n            TreeNode node = queue.poll();\n            if (i < nums.length && nums[i] != null) {\n                node.left = new TreeNode(nums[i]);\n                queue.offer(node.left);\n            }\n            i++;\n            if (i < nums.length && nums[i] != null) {\n                node.right = new TreeNode(nums[i]);\n                queue.offer(node.right);\n            }\n            i++;\n        }\n        return root;\n    }\n\n    static boolean isValidBST(TreeNode root) {\n        return validate(root, null, null);\n    }\n\n    static boolean validate(TreeNode node, Integer min, Integer max) {\n        if (node == null) return true;\n        if (min != null && node.val <= min) return false;\n        if (max != null && node.val >= max) return false;\n        return validate(node.left, min, node.val) && validate(node.right, node.val, max);\n    }\n}', NULL, 1),
(322, 'JAVASCRIPT', 'const readline = require(\'readline\');\n\nconst rl = readline.createInterface({\n    input: process.stdin,\n    output: process.stdout\n});\n\nrl.on(\'line\', (input) => {\n    let line = input.trim();\n    if (line.startsWith(\'[\')) line = line.substring(1);\n    if (line.endsWith(\']\')) line = line.substring(0, line.length - 1);\n    if (line.length === 0) {\n        console.log(\'true\');\n        rl.close();\n        return;\n    }\n    const parts = line.split(\',\');\n    const nums = parts.map(s => {\n        s = s.trim();\n        return s === \'null\' ? null : parseInt(s, 10);\n    });\n    const root = buildTree(nums);\n    console.log(isValidBST(root));\n    rl.close();\n});\n\nclass TreeNode {\n    constructor(val) {\n        this.val = val;\n        this.left = null;\n        this.right = null;\n    }\n}\n\nfunction buildTree(nums) {\n    if (nums.length === 0 || nums[0] === null) return null;\n    const root = new TreeNode(nums[0]);\n    const queue = [root];\n    let i = 1;\n    while (queue.length > 0 && i < nums.length) {\n        const node = queue.shift();\n        if (i < nums.length && nums[i] !== null) {\n            node.left = new TreeNode(nums[i]);\n            queue.push(node.left);\n        }\n        i++;\n        if (i < nums.length && nums[i] !== null) {\n            node.right = new TreeNode(nums[i]);\n            queue.push(node.right);\n        }\n        i++;\n    }\n    return root;\n}\n\nfunction isValidBST(root) {\n    return validate(root, null, null);\n}\n\nfunction validate(node, min, max) {\n    if (node === null) return true;\n    if (min !== null && node.val <= min) return false;\n    if (max !== null && node.val >= max) return false;\n    return validate(node.left, min, node.val) && validate(node.right, node.val, max);\n}', NULL, 1),
(322, 'PYTHON', 'import sys\nfrom collections import deque\n\nclass TreeNode:\n    def __init__(self, val):\n        self.val = val\n        self.left = None\n        self.right = None\n\ndef build_tree(nums):\n    if not nums or nums[0] is None:\n        return None\n    root = TreeNode(nums[0])\n    queue = deque([root])\n    i = 1\n    while queue and i < len(nums):\n        node = queue.popleft()\n        if i < len(nums) and nums[i] is not None:\n            node.left = TreeNode(nums[i])\n            queue.append(node.left)\n        i += 1\n        if i < len(nums) and nums[i] is not None:\n            node.right = TreeNode(nums[i])\n            queue.append(node.right)\n        i += 1\n    return root\n\ndef validate(node, min_val, max_val):\n    if node is None:\n        return True\n    if min_val is not None and node.val <= min_val:\n        return False\n    if max_val is not None and node.val >= max_val:\n        return False\n    return validate(node.left, min_val, node.val) and validate(node.right, node.val, max_val)\n\ndef main():\n    line = sys.stdin.readline()\n    if not line:\n        return\n    line = line.strip()\n    if line.startswith(\"[\"):\n        line = line[1:]\n    if line.endswith(\"]\"):\n        line = line[:-1]\n    if line == \"\":\n        print(\"true\")\n        return\n    parts = line.split(\",\")\n    nums = []\n    for s in parts:\n        s = s.strip()\n        if s == \"null\":\n            nums.append(None)\n        else:\n            nums.append(int(s))\n    root = build_tree(nums)\n    print(\"true\" if validate(root, None, None) else \"false\")\n\nif __name__ == \"__main__\":\n    main()', NULL, 1),
(323, 'C', '#include <stdio.h>\n#include <stdlib.h>\n#include <string.h>\n\ntypedef struct TreeNode {\n    int val;\n    struct TreeNode *left;\n    struct TreeNode *right;\n} TreeNode;\n\nTreeNode* createNode(int val) {\n    TreeNode* node = (TreeNode*)malloc(sizeof(TreeNode));\n    node->val = val;\n    node->left = NULL;\n    node->right = NULL;\n    return node;\n}\n\nTreeNode* buildTree(char** parts, int partsSize) {\n    if (partsSize == 0 || strcmp(parts[0], \"null\") == 0) return NULL;\n    TreeNode* root = createNode(atoi(parts[0]));\n    TreeNode** queue = (TreeNode**)malloc(sizeof(TreeNode*) * (partsSize + 1));\n    int front = 0, rear = 0;\n    queue[rear++] = root;\n    int i = 1;\n    while (front < rear && i < partsSize) {\n        TreeNode* node = queue[front++];\n        if (i < partsSize) {\n            char* leftVal = parts[i++];\n            if (strcmp(leftVal, \"null\") != 0) {\n                node->left = createNode(atoi(leftVal));\n                queue[rear++] = node->left;\n            }\n        }\n        if (i < partsSize) {\n            char* rightVal = parts[i++];\n            if (strcmp(rightVal, \"null\") != 0) {\n                node->right = createNode(atoi(rightVal));\n                queue[rear++] = node->right;\n            }\n        }\n    }\n    free(queue);\n    return root;\n}\n\nTreeNode* invertTree(TreeNode* root) {\n    if (root == NULL) return NULL;\n    TreeNode* temp = root->left;\n    root->left = invertTree(root->right);\n    root->right = invertTree(temp);\n    return root;\n}\n\nchar* serialize(TreeNode* root) {\n    if (root == NULL) {\n        char* res = (char*)malloc(3);\n        strcpy(res, \"[]\");\n        return res;\n    }\n    int capacity = 1024;\n    char** res = (char**)malloc(sizeof(char*) * capacity);\n    int count = 0;\n    TreeNode** queue = (TreeNode**)malloc(sizeof(TreeNode*) * capacity);\n    int front = 0, rear = 0;\n    queue[rear++] = root;\n    while (front < rear) {\n        TreeNode* node = queue[front++];\n        if (count >= capacity) {\n            capacity *= 2;\n            res = (char**)realloc(res, sizeof(char*) * capacity);\n            queue = (TreeNode**)realloc(queue, sizeof(TreeNode*) * capacity);\n        }\n        if (node == NULL) {\n            res[count] = (char*)malloc(5);\n            strcpy(res[count], \"null\");\n            count++;\n        } else {\n            char* buf = (char*)malloc(16);\n            sprintf(buf, \"%d\", node->val);\n            res[count] = buf;\n            count++;\n            queue[rear++] = node->left;\n            queue[rear++] = node->right;\n        }\n    }\n    while (count > 0 && strcmp(res[count - 1], \"null\") == 0) {\n        count--;\n    }\n    int totalLen = 3;\n    for (int i = 0; i < count; i++) {\n        totalLen += strlen(res[i]) + 1;\n    }\n    char* result = (char*)malloc(totalLen);\n    result[0] = \'\\0\';\n    strcat(result, \"[\");\n    for (int i = 0; i < count; i++) {\n        if (i > 0) strcat(result, \",\");\n        strcat(result, res[i]);\n    }\n    strcat(result, \"]\");\n    for (int i = 0; i < count; i++) free(res[i]);\n    free(res);\n    free(queue);\n    return result;\n}\n\nint main() {\n    char line[100000];\n    if (fgets(line, sizeof(line), stdin) == NULL) return 0;\n    int len = strlen(line);\n    while (len > 0 && (line[len-1] == \'\\n\' || line[len-1] == \'\\r\')) {\n        line[--len] = \'\\0\';\n    }\n    char* start = line;\n    while (*start == \' \' || *start == \'\\t\') start++;\n    int slen = strlen(start);\n    while (slen > 0 && (start[slen-1] == \' \' || start[slen-1] == \'\\t\')) {\n        start[--slen] = \'\\0\';\n    }\n    if (slen >= 2 && start[0] == \'[\') {\n        start[slen-1] = \'\\0\';\n        start++;\n    }\n    char** parts = (char**)malloc(sizeof(char*) * 100000);\n    int partsSize = 0;\n    if (strlen(start) > 0) {\n        char* token = strtok(start, \",\");\n        while (token != NULL) {\n            while (*token == \' \') token++;\n            int tlen = strlen(token);\n            while (tlen > 0 && token[tlen-1] == \' \') token[--tlen] = \'\\0\';\n            parts[partsSize++] = token;\n            token = strtok(NULL, \",\");\n        }\n    }\n    TreeNode* root = buildTree(parts, partsSize);\n    root = invertTree(root);\n    char* output = serialize(root);\n    printf(\"%s\\n\", output);\n    free(output);\n    free(parts);\n    return 0;\n}', NULL, 1),
(323, 'CPP', '#include <bits/stdc++.h>\nusing namespace std;\n\nstruct TreeNode {\n    int val;\n    TreeNode *left;\n    TreeNode *right;\n    TreeNode(int x) : val(x), left(nullptr), right(nullptr) {}\n};\n\nTreeNode* buildTree(const vector<string>& parts) {\n    if (parts.empty() || parts[0] == \"null\") return nullptr;\n    TreeNode* root = new TreeNode(stoi(parts[0]));\n    queue<TreeNode*> q;\n    q.push(root);\n    int i = 1;\n    while (!q.empty() && i < (int)parts.size()) {\n        TreeNode* node = q.front();\n        q.pop();\n        if (i < (int)parts.size()) {\n            string leftVal = parts[i++];\n            if (leftVal != \"null\") {\n                node->left = new TreeNode(stoi(leftVal));\n                q.push(node->left);\n            }\n        }\n        if (i < (int)parts.size()) {\n            string rightVal = parts[i++];\n            if (rightVal != \"null\") {\n                node->right = new TreeNode(stoi(rightVal));\n                q.push(node->right);\n            }\n        }\n    }\n    return root;\n}\n\nTreeNode* invertTree(TreeNode* root) {\n    if (!root) return nullptr;\n    TreeNode* temp = root->left;\n    root->left = invertTree(root->right);\n    root->right = invertTree(temp);\n    return root;\n}\n\nstring serialize(TreeNode* root) {\n    if (!root) return \"[]\";\n    vector<string> res;\n    queue<TreeNode*> q;\n    q.push(root);\n    while (!q.empty()) {\n        TreeNode* node = q.front();\n        q.pop();\n        if (!node) {\n            res.push_back(\"null\");\n        } else {\n            res.push_back(to_string(node->val));\n            q.push(node->left);\n            q.push(node->right);\n        }\n    }\n    while (!res.empty() && res.back() == \"null\") {\n        res.pop_back();\n    }\n    string ans = \"[\";\n    for (int i = 0; i < (int)res.size(); i++) {\n        if (i) ans += \",\";\n        ans += res[i];\n    }\n    ans += \"]\";\n    return ans;\n}\n\nint main() {\n    string line;\n    getline(cin, line);\n    while (!line.empty() && (line.back() == \'\\r\' || line.back() == \'\\n\')) line.pop_back();\n    if (!line.empty() && line.front() == \'[\') line = line.substr(1, line.size() - 2);\n    vector<string> parts;\n    if (!line.empty()) {\n        stringstream ss(line);\n        string item;\n        while (getline(ss, item, \',\')) {\n            while (!item.empty() && item.front() == \' \') item.erase(item.begin());\n            while (!item.empty() && item.back() == \' \') item.pop_back();\n            parts.push_back(item);\n        }\n    }\n    TreeNode* root = buildTree(parts);\n    root = invertTree(root);\n    cout << serialize(root) << endl;\n    return 0;\n}', NULL, 1),
(323, 'JAVA', 'import java.util.*;\n\npublic class Main {\n    static class TreeNode {\n        int val;\n        TreeNode left;\n        TreeNode right;\n        TreeNode(int val) { this.val = val; }\n    }\n\n    public static void main(String[] args) {\n        Scanner sc = new Scanner(System.in);\n        String line = sc.nextLine().trim();\n        if (line.startsWith(\"[\")) line = line.substring(1, line.length() - 1);\n        String[] parts = line.isEmpty() ? new String[0] : line.split(\",\");\n        TreeNode root = buildTree(parts);\n        root = invertTree(root);\n        System.out.println(serialize(root));\n    }\n\n    private static TreeNode buildTree(String[] parts) {\n        if (parts.length == 0 || parts[0].trim().equals(\"null\")) return null;\n        TreeNode root = new TreeNode(Integer.parseInt(parts[0].trim()));\n        Queue<TreeNode> queue = new LinkedList<>();\n        queue.offer(root);\n        int i = 1;\n        while (!queue.isEmpty() && i < parts.length) {\n            TreeNode node = queue.poll();\n            if (i < parts.length) {\n                String leftVal = parts[i++].trim();\n                if (!leftVal.equals(\"null\")) {\n                    node.left = new TreeNode(Integer.parseInt(leftVal));\n                    queue.offer(node.left);\n                }\n            }\n            if (i < parts.length) {\n                String rightVal = parts[i++].trim();\n                if (!rightVal.equals(\"null\")) {\n                    node.right = new TreeNode(Integer.parseInt(rightVal));\n                    queue.offer(node.right);\n                }\n            }\n        }\n        return root;\n    }\n\n    private static TreeNode invertTree(TreeNode root) {\n        if (root == null) return null;\n        TreeNode temp = root.left;\n        root.left = invertTree(root.right);\n        root.right = invertTree(temp);\n        return root;\n    }\n\n    private static String serialize(TreeNode root) {\n        if (root == null) return \"[]\";\n        List<String> res = new ArrayList<>();\n        Queue<TreeNode> queue = new LinkedList<>();\n        queue.offer(root);\n        while (!queue.isEmpty()) {\n            TreeNode node = queue.poll();\n            if (node == null) {\n                res.add(\"null\");\n            } else {\n                res.add(String.valueOf(node.val));\n                queue.offer(node.left);\n                queue.offer(node.right);\n            }\n        }\n        while (!res.isEmpty() && res.get(res.size() - 1).equals(\"null\")) {\n            res.remove(res.size() - 1);\n        }\n        return \"[\" + String.join(\",\", res) + \"]\";\n    }\n}', NULL, 1),
