(323, 'PYTHON', 'import sys\nfrom collections import deque\n\nclass TreeNode:\n    def __init__(self, val=0, left=None, right=None):\n        self.val = val\n        self.left = left\n        self.right = right\n\ndef build_tree(parts):\n    if not parts or parts[0].strip() == \"null\":\n        return None\n    root = TreeNode(int(parts[0].strip()))\n    queue = deque([root])\n    i = 1\n    while queue and i < len(parts):\n        node = queue.popleft()\n        if i < len(parts):\n            left_val = parts[i].strip()\n            i += 1\n            if left_val != \"null\":\n                node.left = TreeNode(int(left_val))\n                queue.append(node.left)\n        if i < len(parts):\n            right_val = parts[i].strip()\n            i += 1\n            if right_val != \"null\":\n                node.right = TreeNode(int(right_val))\n                queue.append(node.right)\n    return root\n\ndef invert_tree(root):\n    if root is None:\n        return None\n    root.left, root.right = invert_tree(root.right), invert_tree(root.left)\n    return root\n\ndef serialize(root):\n    if root is None:\n        return \"[]\"\n    res = []\n    queue = deque([root])\n    while queue:\n        node = queue.popleft()\n        if node is None:\n            res.append(\"null\")\n        else:\n            res.append(str(node.val))\n            queue.append(node.left)\n            queue.append(node.right)\n    while res and res[-1] == \"null\":\n        res.pop()\n    return \"[\" + \",\".join(res) + \"]\"\n\ndef main():\n    line = sys.stdin.readline().strip()\n    if line.startswith(\"[\"):\n        line = line[1:-1]\n    parts = [] if line == \"\" else line.split(\",\")\n    root = build_tree(parts)\n    root = invert_tree(root)\n    print(serialize(root))\n\nif __name__ == \"__main__\":\n    main()', NULL, 1),
(324, 'C', '#include <stdio.h>\n#include <stdlib.h>\n#include <string.h>\n\ntypedef struct TreeNode {\n    int val;\n    struct TreeNode *left;\n    struct TreeNode *right;\n} TreeNode;\n\ntypedef struct {\n    TreeNode **data;\n    int front;\n    int rear;\n    int size;\n    int capacity;\n} Queue;\n\nQueue* createQueue(int capacity) {\n    Queue *q = (Queue*)malloc(sizeof(Queue));\n    q->data = (TreeNode**)malloc(sizeof(TreeNode*) * capacity);\n    q->front = 0;\n    q->rear = 0;\n    q->size = 0;\n    q->capacity = capacity;\n    return q;\n}\n\nvoid enqueue(Queue *q, TreeNode *node) {\n    if (q->size == q->capacity) {\n        q->capacity *= 2;\n        q->data = (TreeNode**)realloc(q->data, sizeof(TreeNode*) * q->capacity);\n    }\n    q->data[q->rear] = node;\n    q->rear = (q->rear + 1) % q->capacity;\n    q->size++;\n}\n\nTreeNode* dequeue(Queue *q) {\n    if (q->size == 0) return NULL;\n    TreeNode *node = q->data[q->front];\n    q->front = (q->front + 1) % q->capacity;\n    q->size--;\n    return node;\n}\n\nint isEmpty(Queue *q) {\n    return q->size == 0;\n}\n\nvoid freeQueue(Queue *q) {\n    free(q->data);\n    free(q);\n}\n\nTreeNode* buildTree(char **parts, int partsSize) {\n    if (partsSize == 0 || strcmp(parts[0], \"null\") == 0) return NULL;\n    TreeNode *root = (TreeNode*)malloc(sizeof(TreeNode));\n    root->val = atoi(parts[0]);\n    root->left = NULL;\n    root->right = NULL;\n    \n    Queue *queue = createQueue(partsSize);\n    enqueue(queue, root);\n    int i = 1;\n    while (!isEmpty(queue) && i < partsSize) {\n        TreeNode *node = dequeue(queue);\n        if (i < partsSize) {\n            char *leftVal = parts[i++];\n            if (strcmp(leftVal, \"null\") != 0) {\n                node->left = (TreeNode*)malloc(sizeof(TreeNode));\n                node->left->val = atoi(leftVal);\n                node->left->left = NULL;\n                node->left->right = NULL;\n                enqueue(queue, node->left);\n            }\n        }\n        if (i < partsSize) {\n            char *rightVal = parts[i++];\n            if (strcmp(rightVal, \"null\") != 0) {\n                node->right = (TreeNode*)malloc(sizeof(TreeNode));\n                node->right->val = atoi(rightVal);\n                node->right->left = NULL;\n                node->right->right = NULL;\n                enqueue(queue, node->right);\n            }\n        }\n    }\n    freeQueue(queue);\n    return root;\n}\n\nint* rightSideView(TreeNode *root, int *returnSize) {\n    *returnSize = 0;\n    if (root == NULL) return NULL;\n    \n    int *res = (int*)malloc(sizeof(int) * 1000);\n    Queue *queue = createQueue(1000);\n    enqueue(queue, root);\n    \n    while (!isEmpty(queue)) {\n        int size = queue->size;\n        for (int i = 0; i < size; i++) {\n            TreeNode *node = dequeue(queue);\n            if (i == size - 1) {\n                res[(*returnSize)++] = node->val;\n            }\n            if (node->left != NULL) enqueue(queue, node->left);\n            if (node->right != NULL) enqueue(queue, node->right);\n        }\n    }\n    freeQueue(queue);\n    return res;\n}\n\nint main() {\n    char line[100000];\n    if (fgets(line, sizeof(line), stdin) == NULL) return 0;\n    \n    int len = strlen(line);\n    while (len > 0 && (line[len-1] == \'\\n\' || line[len-1] == \'\\r\')) {\n        line[--len] = \'\\0\';\n    }\n    \n    if (len > 0 && line[0] == \'[\') {\n        memmove(line, line + 1, len - 1);\n        len--;\n        line[len] = \'\\0\';\n    }\n    if (len > 0 && line[len-1] == \']\') {\n        line[--len] = \'\\0\';\n    }\n    \n    if (len == 0) {\n        printf(\"[]\\n\");\n        return 0;\n    }\n    \n    char *parts[10000];\n    int partsSize = 0;\n    char *token = strtok(line, \",\");\n    while (token != NULL) {\n        while (*token == \' \') token++;\n        char *end = token + strlen(token) - 1;\n        while (end > token && *end == \' \') *end-- = \'\\0\';\n        parts[partsSize++] = token;\n        token = strtok(NULL, \",\");\n    }\n    \n    TreeNode *root = buildTree(parts, partsSize);\n    int returnSize = 0;\n    int *res = rightSideView(root, &returnSize);\n    \n    printf(\"[\");\n    for (int i = 0; i < returnSize; i++) {\n        if (i > 0) printf(\",\");\n        printf(\"%d\", res[i]);\n    }\n    printf(\"]\\n\");\n    \n    free(res);\n    return 0;\n}', NULL, 1),
(324, 'CPP', '#include <iostream>\n#include <string>\n#include <vector>\n#include <queue>\n#include <sstream>\n\nusing namespace std;\n\nstruct TreeNode {\n    int val;\n    TreeNode* left;\n    TreeNode* right;\n    TreeNode(int v) : val(v), left(nullptr), right(nullptr) {}\n};\n\nTreeNode* buildTree(const vector<string>& parts) {\n    if (parts.empty() || parts[0] == \"null\") return nullptr;\n    TreeNode* root = new TreeNode(stoi(parts[0]));\n    queue<TreeNode*> q;\n    q.push(root);\n    int i = 1;\n    while (!q.empty() && i < (int)parts.size()) {\n        TreeNode* node = q.front();\n        q.pop();\n        if (i < (int)parts.size()) {\n            string leftVal = parts[i++];\n            if (leftVal != \"null\") {\n                node->left = new TreeNode(stoi(leftVal));\n                q.push(node->left);\n            }\n        }\n        if (i < (int)parts.size()) {\n            string rightVal = parts[i++];\n            if (rightVal != \"null\") {\n                node->right = new TreeNode(stoi(rightVal));\n                q.push(node->right);\n            }\n        }\n    }\n    return root;\n}\n\nvector<int> rightSideView(TreeNode* root) {\n    vector<int> res;\n    if (!root) return res;\n    queue<TreeNode*> q;\n    q.push(root);\n    while (!q.empty()) {\n        int size = q.size();\n        for (int i = 0; i < size; i++) {\n            TreeNode* node = q.front();\n            q.pop();\n            if (i == size - 1) res.push_back(node->val);\n            if (node->left) q.push(node->left);\n            if (node->right) q.push(node->right);\n        }\n    }\n    return res;\n}\n\nint main() {\n    string line;\n    getline(cin, line);\n    while (!line.empty() && (line.back() == \'\\r\' || line.back() == \'\\n\')) line.pop_back();\n    if (!line.empty() && line.front() == \'[\') line = line.substr(1, line.size() - 2);\n    if (line.empty()) {\n        cout << \"[]\" << endl;\n        return 0;\n    }\n    vector<string> parts;\n    stringstream ss(line);\n    string token;\n    while (getline(ss, token, \',\')) {\n        size_t start = token.find_first_not_of(\" \\t\");\n        size_t end = token.find_last_not_of(\" \\t\");\n        if (start == string::npos) parts.push_back(\"\");\n        else parts.push_back(token.substr(start, end - start + 1));\n    }\n    TreeNode* root = buildTree(parts);\n    vector<int> res = rightSideView(root);\n    cout << \"[\";\n    for (int i = 0; i < (int)res.size(); i++) {\n        if (i > 0) cout << \",\";\n        cout << res[i];\n    }\n    cout << \"]\" << endl;\n    return 0;\n}', NULL, 1),
(324, 'JAVA', 'import java.util.*;\n\npublic class Main {\n    static class TreeNode {\n        int val;\n        TreeNode left;\n        TreeNode right;\n        TreeNode(int val) { this.val = val; }\n    }\n\n    public static void main(String[] args) {\n        Scanner sc = new Scanner(System.in);\n        String line = sc.nextLine().trim();\n        if (line.startsWith(\"[\")) line = line.substring(1, line.length() - 1);\n        if (line.isEmpty()) {\n            System.out.println(\"[]\");\n            return;\n        }\n        String[] parts = line.split(\",\");\n        TreeNode root = buildTree(parts);\n        List<Integer> res = rightSideView(root);\n        StringBuilder sb = new StringBuilder();\n        sb.append(\"[\");\n        for (int i = 0; i < res.size(); i++) {\n            if (i > 0) sb.append(\",\");\n            sb.append(res.get(i));\n        }\n        sb.append(\"]\");\n        System.out.println(sb.toString());\n    }\n\n    static TreeNode buildTree(String[] parts) {\n        if (parts.length == 0 || parts[0].trim().equals(\"null\")) return null;\n        TreeNode root = new TreeNode(Integer.parseInt(parts[0].trim()));\n        Queue<TreeNode> queue = new LinkedList<>();\n        queue.offer(root);\n        int i = 1;\n        while (!queue.isEmpty() && i < parts.length) {\n            TreeNode node = queue.poll();\n            if (i < parts.length) {\n                String leftVal = parts[i++].trim();\n                if (!leftVal.equals(\"null\")) {\n                    node.left = new TreeNode(Integer.parseInt(leftVal));\n                    queue.offer(node.left);\n                }\n            }\n            if (i < parts.length) {\n                String rightVal = parts[i++].trim();\n                if (!rightVal.equals(\"null\")) {\n                    node.right = new TreeNode(Integer.parseInt(rightVal));\n                    queue.offer(node.right);\n                }\n            }\n        }\n        return root;\n    }\n\n    static List<Integer> rightSideView(TreeNode root) {\n        List<Integer> res = new ArrayList<>();\n        if (root == null) return res;\n        Queue<TreeNode> queue = new LinkedList<>();\n        queue.offer(root);\n        while (!queue.isEmpty()) {\n            int size = queue.size();\n            for (int i = 0; i < size; i++) {\n                TreeNode node = queue.poll();\n                if (i == size - 1) res.add(node.val);\n                if (node.left != null) queue.offer(node.left);\n                if (node.right != null) queue.offer(node.right);\n            }\n        }\n        return res;\n    }\n}', NULL, 1),
(324, 'JAVASCRIPT', 'const readline = require(\'readline\');\n\nclass TreeNode {\n    constructor(val) {\n        this.val = val;\n        this.left = null;\n        this.right = null;\n    }\n}\n\nfunction buildTree(parts) {\n    if (parts.length === 0 || parts[0].trim() === \'null\') return null;\n    const root = new TreeNode(parseInt(parts[0].trim()));\n    const queue = [root];\n    let i = 1;\n    while (queue.length > 0 && i < parts.length) {\n        const node = queue.shift();\n        if (i < parts.length) {\n            const leftVal = parts[i++].trim();\n            if (leftVal !== \'null\') {\n                node.left = new TreeNode(parseInt(leftVal));\n                queue.push(node.left);\n            }\n        }\n        if (i < parts.length) {\n            const rightVal = parts[i++].trim();\n            if (rightVal !== \'null\') {\n                node.right = new TreeNode(parseInt(rightVal));\n                queue.push(node.right);\n            }\n        }\n    }\n    return root;\n}\n\nfunction rightSideView(root) {\n    const res = [];\n    if (root === null) return res;\n    const queue = [root];\n    while (queue.length > 0) {\n        const size = queue.length;\n        for (let i = 0; i < size; i++) {\n            const node = queue.shift();\n            if (i === size - 1) res.push(node.val);\n            if (node.left !== null) queue.push(node.left);\n            if (node.right !== null) queue.push(node.right);\n        }\n    }\n    return res;\n}\n\nconst rl = readline.createInterface({\n    input: process.stdin,\n    output: process.stdout\n});\n\nrl.on(\'line\', (line) => {\n    line = line.trim();\n    if (line.startsWith(\'[\')) line = line.substring(1, line.length - 1);\n    if (line.length === 0) {\n        console.log(\'[]\');\n        rl.close();\n        return;\n    }\n    const parts = line.split(\',\');\n    const root = buildTree(parts);\n    const res = rightSideView(root);\n    console.log(\'[\' + res.join(\',\') + \']\');\n    rl.close();\n});', NULL, 1),
(324, 'PYTHON', 'import sys\nfrom collections import deque\n\nclass TreeNode:\n    def __init__(self, val):\n        self.val = val\n        self.left = None\n        self.right = None\n\ndef build_tree(parts):\n    if not parts or parts[0].strip() == \"null\":\n        return None\n    root = TreeNode(int(parts[0].strip()))\n    queue = deque([root])\n    i = 1\n    while queue and i < len(parts):\n        node = queue.popleft()\n        if i < len(parts):\n            left_val = parts[i].strip()\n            i += 1\n            if left_val != \"null\":\n                node.left = TreeNode(int(left_val))\n                queue.append(node.left)\n        if i < len(parts):\n            right_val = parts[i].strip()\n            i += 1\n            if right_val != \"null\":\n                node.right = TreeNode(int(right_val))\n                queue.append(node.right)\n    return root\n\ndef right_side_view(root):\n    res = []\n    if root is None:\n        return res\n    queue = deque([root])\n    while queue:\n        size = len(queue)\n        for i in range(size):\n            node = queue.popleft()\n            if i == size - 1:\n                res.append(node.val)\n            if node.left:\n                queue.append(node.left)\n            if node.right:\n                queue.append(node.right)\n    return res\n\ndef main():\n    line = sys.stdin.readline().strip()\n    if line.startswith(\"[\"):\n        line = line[1:-1]\n    if not line:\n        print(\"[]\")\n        return\n    parts = line.split(\",\")\n    root = build_tree(parts)\n    res = right_side_view(root)\n    print(\"[\" + \",\".join(map(str, res)) + \"]\")\n\nif __name__ == \"__main__\":\n    main()', NULL, 1),
(325, 'C', '#include <stdio.h>\n\nint main() {\n    int n;\n    scanf(\"%d\", &n);\n    int candidate = 0;\n    int count = 0;\n    for (int i = 0; i < n; i++) {\n        int num;\n        scanf(\"%d\", &num);\n        if (count == 0) {\n            candidate = num;\n            count = 1;\n        } else if (num == candidate) {\n            count++;\n        } else {\n            count--;\n        }\n    }\n    printf(\"%d\\n\", candidate);\n    return 0;\n}', NULL, 1),
(325, 'CPP', '#include <iostream>\nusing namespace std;\n\nint main() {\n    int n;\n    cin >> n;\n    int candidate = 0;\n    int count = 0;\n    for (int i = 0; i < n; i++) {\n        int num;\n        cin >> num;\n        if (count == 0) {\n            candidate = num;\n            count = 1;\n        } else if (num == candidate) {\n            count++;\n        } else {\n            count--;\n        }\n    }\n    cout << candidate << endl;\n    return 0;\n}', NULL, 1),
(325, 'JAVA', 'import java.util.Scanner;\n\npublic class Main {\n    public static void main(String[] args) {\n        Scanner sc = new Scanner(System.in);\n        int n = sc.nextInt();\n        int candidate = 0;\n        int count = 0;\n        for (int i = 0; i < n; i++) {\n            int num = sc.nextInt();\n            if (count == 0) {\n                candidate = num;\n                count = 1;\n            } else if (num == candidate) {\n                count++;\n            } else {\n                count--;\n            }\n        }\n        System.out.println(candidate);\n    }\n}', NULL, 1),
(325, 'JAVASCRIPT', 'const readline = require(\'readline\');\n\nconst rl = readline.createInterface({\n    input: process.stdin,\n    output: process.stdout\n});\n\nlet lines = [];\nrl.on(\'line\', (line) => {\n    lines.push(line.trim());\n});\n\nrl.on(\'close\', () => {\n    const n = parseInt(lines[0]);\n    const nums = lines[1].split(/\\s+/).map(Number);\n    let candidate = 0;\n    let count = 0;\n    for (let i = 0; i < n; i++) {\n        const num = nums[i];\n        if (count === 0) {\n            candidate = num;\n            count = 1;\n        } else if (num === candidate) {\n            count++;\n        } else {\n            count--;\n        }\n    }\n    console.log(candidate);\n});', NULL, 1),
