(326, 'C', '#include <stdio.h>\n#include <string.h>\n\nint main(void) {\n    char num1[100005], num2[100005];\n    char result[100010];\n    if (scanf(\"%s\", num1) != 1) return 0;\n    if (scanf(\"%s\", num2) != 1) return 0;\n\n    int i = (int)strlen(num1) - 1;\n    int j = (int)strlen(num2) - 1;\n    int carry = 0;\n    int k = 0;\n\n    while (i >= 0 || j >= 0 || carry != 0) {\n        int x = i >= 0 ? num1[i] - \'0\' : 0;\n        int y = j >= 0 ? num2[j] - \'0\' : 0;\n        int sum = x + y + carry;\n        result[k++] = (char)(\'0\' + sum % 10);\n        carry = sum / 10;\n        i--;\n        j--;\n    }\n\n    for (int left = 0, right = k - 1; left < right; left++, right--) {\n        char tmp = result[left];\n        result[left] = result[right];\n        result[right] = tmp;\n    }\n    result[k] = \'\\0\';\n\n    printf(\"%s\\n\", result);\n    return 0;\n}', NULL, 1),
(326, 'CPP', '#include <iostream>\n#include <string>\n#include <algorithm>\n\nusing namespace std;\n\nstring addStrings(string num1, string num2) {\n    string result;\n    int i = num1.length() - 1;\n    int j = num2.length() - 1;\n    int carry = 0;\n\n    while (i >= 0 || j >= 0 || carry != 0) {\n        int x = i >= 0 ? num1[i] - \'0\' : 0;\n        int y = j >= 0 ? num2[j] - \'0\' : 0;\n        int sum = x + y + carry;\n        result.push_back(\'0\' + sum % 10);\n        carry = sum / 10;\n        i--;\n        j--;\n    }\n\n    reverse(result.begin(), result.end());\n    return result;\n}\n\nint main() {\n    string num1, num2;\n    getline(cin, num1);\n    getline(cin, num2);\n\n    while (!num1.empty() && (num1.back() == \'\\r\' || num1.back() == \'\\n\' || num1.back() == \' \')) {\n        num1.pop_back();\n    }\n    while (!num2.empty() && (num2.back() == \'\\r\' || num2.back() == \'\\n\' || num2.back() == \' \')) {\n        num2.pop_back();\n    }\n\n    cout << addStrings(num1, num2) << endl;\n    return 0;\n}', NULL, 1),
(326, 'JAVA', 'import java.util.Scanner;\n\npublic class Main {\n    public static void main(String[] args) {\n        Scanner sc = new Scanner(System.in);\n        String num1 = sc.nextLine().trim();\n        String num2 = sc.nextLine().trim();\n        System.out.println(addStrings(num1, num2));\n    }\n\n    public static String addStrings(String num1, String num2) {\n        StringBuilder sb = new StringBuilder();\n        int i = num1.length() - 1;\n        int j = num2.length() - 1;\n        int carry = 0;\n\n        while (i >= 0 || j >= 0 || carry != 0) {\n            int x = i >= 0 ? num1.charAt(i) - \'0\' : 0;\n            int y = j >= 0 ? num2.charAt(j) - \'0\' : 0;\n            int sum = x + y + carry;\n            sb.append(sum % 10);\n            carry = sum / 10;\n            i--;\n            j--;\n        }\n\n        return sb.reverse().toString();\n    }\n}', NULL, 1),
(326, 'JAVASCRIPT', 'const readline = require(\'readline\');\n\nconst rl = readline.createInterface({\n    input: process.stdin,\n    output: process.stdout\n});\n\nlet lines = [];\n\nrl.on(\'line\', (line) => {\n    lines.push(line.trim());\n    if (lines.length === 2) {\n        console.log(addStrings(lines[0], lines[1]));\n        rl.close();\n    }\n});\n\nfunction addStrings(num1, num2) {\n    let sb = [];\n    let i = num1.length - 1;\n    let j = num2.length - 1;\n    let carry = 0;\n\n    while (i >= 0 || j >= 0 || carry !== 0) {\n        let x = i >= 0 ? num1.charCodeAt(i) - \'0\'.charCodeAt(0) : 0;\n        let y = j >= 0 ? num2.charCodeAt(j) - \'0\'.charCodeAt(0) : 0;\n        let sum = x + y + carry;\n        sb.push(sum % 10);\n        carry = Math.floor(sum / 10);\n        i--;\n        j--;\n    }\n\n    return sb.reverse().join(\'\');\n}', NULL, 1),
(326, 'PYTHON', 'import sys\n\ndef addStrings(num1, num2):\n    i, j = len(num1) - 1, len(num2) - 1\n    carry = 0\n    res = []\n    while i >= 0 or j >= 0 or carry:\n        x = int(num1[i]) if i >= 0 else 0\n        y = int(num2[j]) if j >= 0 else 0\n        s = x + y + carry\n        res.append(str(s % 10))\n        carry = s // 10\n        i -= 1\n        j -= 1\n    return \'\'.join(reversed(res))\n\ndef main():\n    num1 = sys.stdin.readline().strip()\n    num2 = sys.stdin.readline().strip()\n    print(addStrings(num1, num2))\n\nif __name__ == \"__main__\":\n    main()', NULL, 1),
(327, 'C', '#include <stdio.h>\n#include <limits.h>\n\nint myAtoi(const char *s) {\n    int i = 0;\n    while (s[i] == \' \') {\n        i++;\n    }\n\n    int sign = 1;\n    if (s[i] == \'+\' || s[i] == \'-\') {\n        sign = (s[i] == \'-\') ? -1 : 1;\n        i++;\n    }\n\n    int result = 0;\n    while (s[i] >= \'0\' && s[i] <= \'9\') {\n        int digit = s[i] - \'0\';\n        if (result > (INT_MAX - digit) / 10) {\n            return sign == 1 ? INT_MAX : INT_MIN;\n        }\n        result = result * 10 + digit;\n        i++;\n    }\n\n    return sign * result;\n}\n\nint main(void) {\n    char s[100000];\n    if (fgets(s, sizeof(s), stdin)) {\n        int i = 0;\n        while (s[i] != \'\\0\' && s[i] != \'\\n\') {\n            i++;\n        }\n        s[i] = \'\\0\';\n        printf(\"%d\\n\", myAtoi(s));\n    }\n    return 0;\n}', NULL, 1),
(327, 'CPP', '#include <iostream>\n#include <string>\n#include <climits>\n\nint myAtoi(const std::string& s) {\n    int i = 0, n = s.length();\n    while (i < n && s[i] == \' \') {\n        i++;\n    }\n    int sign = 1;\n    if (i < n && (s[i] == \'+\' || s[i] == \'-\')) {\n        sign = (s[i] == \'-\') ? -1 : 1;\n        i++;\n    }\n    int result = 0;\n    while (i < n && s[i] >= \'0\' && s[i] <= \'9\') {\n        int digit = s[i] - \'0\';\n        if (result > (INT_MAX - digit) / 10) {\n            return sign == 1 ? INT_MAX : INT_MIN;\n        }\n        result = result * 10 + digit;\n        i++;\n    }\n    return sign * result;\n}\n\nint main() {\n    std::string s;\n    if (std::getline(std::cin, s)) {\n        std::cout << myAtoi(s) << std::endl;\n    }\n    return 0;\n}', NULL, 1),
(327, 'JAVA', 'import java.util.Scanner;\n\npublic class Main {\n    public static void main(String[] args) {\n        Scanner sc = new Scanner(System.in);\n        if (sc.hasNextLine()) {\n            String s = sc.nextLine();\n            System.out.println(myAtoi(s));\n        }\n    }\n\n    public static int myAtoi(String s) {\n        int i = 0, n = s.length();\n        while (i < n && s.charAt(i) == \' \') {\n            i++;\n        }\n        int sign = 1;\n        if (i < n && (s.charAt(i) == \'+\' || s.charAt(i) == \'-\')) {\n            sign = s.charAt(i) == \'-\' ? -1 : 1;\n            i++;\n        }\n        int result = 0;\n        while (i < n && Character.isDigit(s.charAt(i))) {\n            int digit = s.charAt(i) - \'0\';\n            if (result > (Integer.MAX_VALUE - digit) / 10) {\n                return sign == 1 ? Integer.MAX_VALUE : Integer.MIN_VALUE;\n            }\n            result = result * 10 + digit;\n            i++;\n        }\n        return sign * result;\n    }\n}', NULL, 1),
(327, 'JAVASCRIPT', 'const readline = require(\'readline\');\n\nconst rl = readline.createInterface({\n    input: process.stdin,\n    output: process.stdout\n});\n\nrl.on(\'line\', (s) => {\n    console.log(myAtoi(s));\n    rl.close();\n});\n\nfunction myAtoi(s) {\n    let i = 0, n = s.length;\n    while (i < n && s[i] === \' \') {\n        i++;\n    }\n    let sign = 1;\n    if (i < n && (s[i] === \'+\' || s[i] === \'-\')) {\n        sign = s[i] === \'-\' ? -1 : 1;\n        i++;\n    }\n    let result = 0;\n    while (i < n && s[i] >= \'0\' && s[i] <= \'9\') {\n        let digit = s.charCodeAt(i) - \'0\'.charCodeAt(0);\n        if (result > (2147483647 - digit) / 10) {\n            return sign === 1 ? 2147483647 : -2147483648;\n        }\n        result = result * 10 + digit;\n        i++;\n    }\n    return sign * result;\n}', NULL, 1),
(327, 'PYTHON', 'import sys\n\ndef myAtoi(s: str) -> int:\n    i, n = 0, len(s)\n    while i < n and s[i] == \' \':\n        i += 1\n    sign = 1\n    if i < n and (s[i] == \'+\' or s[i] == \'-\'):\n        sign = -1 if s[i] == \'-\' else 1\n        i += 1\n    result = 0\n    while i < n and s[i].isdigit():\n        digit = ord(s[i]) - ord(\'0\')\n        if result > (2**31 - 1 - digit) // 10:\n            return 2**31 - 1 if sign == 1 else -2**31\n        result = result * 10 + digit\n        i += 1\n    return sign * result\n\nif __name__ == \"__main__\":\n    line = sys.stdin.readline()\n    if line:\n        s = line.rstrip(\'\\n\')\n        print(myAtoi(s))', NULL, 1),
(328, 'C', '#include <stdio.h>\n#include <ctype.h>\n#include <string.h>\n\nint main() {\n    char s[100005];\n    if (fgets(s, sizeof(s), stdin) == NULL) {\n        return 0;\n    }\n    size_t len = strlen(s);\n    if (len > 0 && s[len - 1] == \'\\n\') {\n        s[len - 1] = \'\\0\';\n        len--;\n    }\n\n    int left = 0, right = (int)len - 1;\n    while (left < right) {\n        while (left < right && !isalnum((unsigned char)s[left])) {\n            left++;\n        }\n        while (left < right && !isalnum((unsigned char)s[right])) {\n            right--;\n        }\n        if (tolower((unsigned char)s[left]) != tolower((unsigned char)s[right])) {\n            printf(\"false\\n\");\n            return 0;\n        }\n        left++;\n        right--;\n    }\n    printf(\"true\\n\");\n    return 0;\n}', NULL, 1),
(328, 'CPP', '#include <iostream>\n#include <string>\n#include <cctype>\nusing namespace std;\n\nint main() {\n    string s;\n    getline(cin, s);\n    int left = 0, right = (int)s.length() - 1;\n    while (left < right) {\n        while (left < right && !isalnum((unsigned char)s[left])) {\n            left++;\n        }\n        while (left < right && !isalnum((unsigned char)s[right])) {\n            right--;\n        }\n        if (tolower((unsigned char)s[left]) != tolower((unsigned char)s[right])) {\n            cout << \"false\" << endl;\n            return 0;\n        }\n        left++;\n        right--;\n    }\n    cout << \"true\" << endl;\n    return 0;\n}', NULL, 1),
(328, 'JAVA', 'import java.util.Scanner;\n\npublic class Main {\n    public static void main(String[] args) {\n        Scanner scanner = new Scanner(System.in);\n        String s = scanner.nextLine();\n        int left = 0, right = s.length() - 1;\n        while (left < right) {\n            while (left < right && !Character.isLetterOrDigit(s.charAt(left))) {\n                left++;\n            }\n            while (left < right && !Character.isLetterOrDigit(s.charAt(right))) {\n                right--;\n            }\n            if (Character.toLowerCase(s.charAt(left)) != Character.toLowerCase(s.charAt(right))) {\n                System.out.println(\"false\");\n                return;\n            }\n            left++;\n            right--;\n        }\n        System.out.println(\"true\");\n    }\n}', NULL, 1),
(328, 'JAVASCRIPT', 'const readline = require(\'readline\');\n\nconst rl = readline.createInterface({\n    input: process.stdin,\n    output: process.stdout\n});\n\nrl.on(\'line\', (s) => {\n    let left = 0, right = s.length - 1;\n    while (left < right) {\n        while (left < right && !/[a-zA-Z0-9]/.test(s[left])) {\n            left++;\n        }\n        while (left < right && !/[a-zA-Z0-9]/.test(s[right])) {\n            right--;\n        }\n        if (s[left].toLowerCase() !== s[right].toLowerCase()) {\n            console.log(\"false\");\n            rl.close();\n            return;\n        }\n        left++;\n        right--;\n    }\n    console.log(\"true\");\n    rl.close();\n});', NULL, 1),
