(329, 'C', '#include <stdio.h>\n#include <stdlib.h>\n\nint main() {\n    int n;\n    scanf(\"%d\", &n);\n\n    int **matrix = (int **)malloc(n * sizeof(int *));\n    for (int i = 0; i < n; i++) {\n        matrix[i] = (int *)malloc(n * sizeof(int));\n        for (int j = 0; j < n; j++) {\n            scanf(\"%d\", &matrix[i][j]);\n        }\n    }\n\n    for (int i = 0; i < n / 2; i++) {\n        for (int j = i; j < n - 1 - i; j++) {\n            int temp = matrix[i][j];\n            matrix[i][j] = matrix[n - 1 - j][i];\n            matrix[n - 1 - j][i] = matrix[n - 1 - i][n - 1 - j];\n            matrix[n - 1 - i][n - 1 - j] = matrix[j][n - 1 - i];\n            matrix[j][n - 1 - i] = temp;\n        }\n    }\n\n    for (int i = 0; i < n; i++) {\n        for (int j = 0; j < n; j++) {\n            printf(\"%d\", matrix[i][j]);\n            if (j < n - 1) {\n                printf(\" \");\n            }\n        }\n        printf(\"\\n\");\n    }\n\n    for (int i = 0; i < n; i++) {\n        free(matrix[i]);\n    }\n    free(matrix);\n\n    return 0;\n}', NULL, 1),
(329, 'CPP', '#include <iostream>\n#include <vector>\nusing namespace std;\n\nint main() {\n    int n;\n    cin >> n;\n    vector<vector<int>> matrix(n, vector<int>(n));\n    for (int i = 0; i < n; i++) {\n        for (int j = 0; j < n; j++) {\n            cin >> matrix[i][j];\n        }\n    }\n\n    for (int i = 0; i < n / 2; i++) {\n        for (int j = i; j < n - 1 - i; j++) {\n            int temp = matrix[i][j];\n            matrix[i][j] = matrix[n - 1 - j][i];\n            matrix[n - 1 - j][i] = matrix[n - 1 - i][n - 1 - j];\n            matrix[n - 1 - i][n - 1 - j] = matrix[j][n - 1 - i];\n            matrix[j][n - 1 - i] = temp;\n        }\n    }\n\n    for (int i = 0; i < n; i++) {\n        for (int j = 0; j < n; j++) {\n            cout << matrix[i][j];\n            if (j < n - 1) {\n                cout << \' \';\n            }\n        }\n        cout << \'\\n\';\n    }\n    return 0;\n}', NULL, 1),
(329, 'JAVA', 'import java.util.Scanner;\n\npublic class Main {\n    public static void main(String[] args) {\n        Scanner sc = new Scanner(System.in);\n        int n = sc.nextInt();\n        int[][] matrix = new int[n][n];\n        for (int i = 0; i < n; i++) {\n            for (int j = 0; j < n; j++) {\n                matrix[i][j] = sc.nextInt();\n            }\n        }\n\n        for (int i = 0; i < n / 2; i++) {\n            for (int j = i; j < n - 1 - i; j++) {\n                int temp = matrix[i][j];\n                matrix[i][j] = matrix[n - 1 - j][i];\n                matrix[n - 1 - j][i] = matrix[n - 1 - i][n - 1 - j];\n                matrix[n - 1 - i][n - 1 - j] = matrix[j][n - 1 - i];\n                matrix[j][n - 1 - i] = temp;\n            }\n        }\n\n        StringBuilder sb = new StringBuilder();\n        for (int i = 0; i < n; i++) {\n            for (int j = 0; j < n; j++) {\n                sb.append(matrix[i][j]);\n                if (j < n - 1) {\n                    sb.append(\' \');\n                }\n            }\n            sb.append(\'\\n\');\n        }\n        System.out.print(sb);\n    }\n}', NULL, 1),
(329, 'JAVASCRIPT', 'const readline = require(\'readline\');\n\nconst rl = readline.createInterface({\n    input: process.stdin,\n    output: process.stdout\n});\n\nlet lines = [];\nrl.on(\'line\', (line) => {\n    lines.push(line.trim());\n});\n\nrl.on(\'close\', () => {\n    let n = parseInt(lines[0]);\n    let matrix = [];\n    for (let i = 0; i < n; i++) {\n        matrix.push(lines[i + 1].split(\' \').map(Number));\n    }\n\n    for (let i = 0; i < Math.floor(n / 2); i++) {\n        for (let j = i; j < n - 1 - i; j++) {\n            let temp = matrix[i][j];\n            matrix[i][j] = matrix[n - 1 - j][i];\n            matrix[n - 1 - j][i] = matrix[n - 1 - i][n - 1 - j];\n            matrix[n - 1 - i][n - 1 - j] = matrix[j][n - 1 - i];\n            matrix[j][n - 1 - i] = temp;\n        }\n    }\n\n    let sb = \'\';\n    for (let i = 0; i < n; i++) {\n        for (let j = 0; j < n; j++) {\n            sb += matrix[i][j];\n            if (j < n - 1) {\n                sb += \' \';\n            }\n        }\n        sb += \'\\n\';\n    }\n    process.stdout.write(sb);\n});', NULL, 1),
(329, 'PYTHON', 'import sys\n\ndef main():\n    data = sys.stdin.read().strip().split()\n    if not data:\n        return\n    n = int(data[0])\n    matrix = []\n    idx = 1\n    for i in range(n):\n        row = []\n        for j in range(n):\n            row.append(int(data[idx]))\n            idx += 1\n        matrix.append(row)\n\n    for i in range(n // 2):\n        for j in range(i, n - 1 - i):\n            temp = matrix[i][j]\n            matrix[i][j] = matrix[n - 1 - j][i]\n            matrix[n - 1 - j][i] = matrix[n - 1 - i][n - 1 - j]\n            matrix[n - 1 - i][n - 1 - j] = matrix[j][n - 1 - i]\n            matrix[j][n - 1 - i] = temp\n\n    out = []\n    for i in range(n):\n        out.append(\' \'.join(map(str, matrix[i])))\n    sys.stdout.write(\'\\n\'.join(out) + \'\\n\')\n\nif __name__ == \"__main__\":\n    main()', NULL, 1),
