(330, 'CPP', '#include <iostream>\n#include <vector>\nusing namespace std;\n\nint main() {\n    int n;\n    cin >> n;\n    vector<int> nums(n);\n    for (int i = 0; i < n; i++) {\n        cin >> nums[i];\n    }\n    for (int i = 0; i < n; i++) {\n        while (nums[i] > 0 && nums[i] <= n && nums[nums[i] - 1] != nums[i]) {\n            int temp = nums[nums[i] - 1];\n            nums[nums[i] - 1] = nums[i];\n            nums[i] = temp;\n        }\n    }\n    for (int i = 0; i < n; i++) {\n        if (nums[i] != i + 1) {\n            cout << i + 1 << endl;\n            return 0;\n        }\n    }\n    cout << n + 1 << endl;\n    return 0;\n}', NULL, 1),
(330, 'JAVA', 'import java.util.Scanner;\n\npublic class Main {\n    public static void main(String[] args) {\n        Scanner sc = new Scanner(System.in);\n        int n = sc.nextInt();\n        int[] nums = new int[n];\n        for (int i = 0; i < n; i++) {\n            nums[i] = sc.nextInt();\n        }\n        for (int i = 0; i < n; i++) {\n            while (nums[i] > 0 && nums[i] <= n && nums[nums[i] - 1] != nums[i]) {\n                int temp = nums[nums[i] - 1];\n                nums[nums[i] - 1] = nums[i];\n                nums[i] = temp;\n            }\n        }\n        for (int i = 0; i < n; i++) {\n            if (nums[i] != i + 1) {\n                System.out.println(i + 1);\n                return;\n            }\n        }\n        System.out.println(n + 1);\n    }\n}', NULL, 1),
(330, 'JAVASCRIPT', 'const readline = require(\'readline\');\n\nconst rl = readline.createInterface({\n    input: process.stdin,\n    output: process.stdout\n});\n\nlet lines = [];\nrl.on(\'line\', (line) => {\n    lines.push(line.trim());\n    if (lines.length === 2) {\n        const n = parseInt(lines[0]);\n        const nums = lines[1].split(\' \').map(Number);\n        \n        for (let i = 0; i < n; i++) {\n            while (nums[i] > 0 && nums[i] <= n && nums[nums[i] - 1] !== nums[i]) {\n                const temp = nums[nums[i] - 1];\n                nums[nums[i] - 1] = nums[i];\n                nums[i] = temp;\n            }\n        }\n        \n        for (let i = 0; i < n; i++) {\n            if (nums[i] !== i + 1) {\n                console.log(i + 1);\n                rl.close();\n                return;\n            }\n        }\n        \n        console.log(n + 1);\n        rl.close();\n    }\n});', NULL, 1),
(330, 'PYTHON', 'n = int(input())\nnums = list(map(int, input().split()))\n\nfor i in range(n):\n    while 0 < nums[i] <= n and nums[nums[i] - 1] != nums[i]:\n        nums[nums[i] - 1], nums[i] = nums[i], nums[nums[i] - 1]\n\nfor i in range(n):\n    if nums[i] != i + 1:\n        print(i + 1)\n        break\nelse:\n    print(n + 1)', NULL, 1),
(331, 'C', '#include <stdio.h>\n\nint main() {\n    int n;\n    scanf(\"%d\", &n);\n    int nums[n];\n    for (int i = 0; i < n; i++) {\n        scanf(\"%d\", &nums[i]);\n    }\n\n    int maxProd = nums[0];\n    int minProd = nums[0];\n    int result = nums[0];\n\n    for (int i = 1; i < n; i++) {\n        int cur = nums[i];\n        int a = maxProd * cur;\n        int b = minProd * cur;\n        int tempMax = cur;\n        if (a > tempMax) tempMax = a;\n        if (b > tempMax) tempMax = b;\n        int tempMin = cur;\n        if (a < tempMin) tempMin = a;\n        if (b < tempMin) tempMin = b;\n        maxProd = tempMax;\n        minProd = tempMin;\n        if (maxProd > result) result = maxProd;\n    }\n\n    printf(\"%d\\n\", result);\n    return 0;\n}', NULL, 1),
(331, 'CPP', '#include <iostream>\n#include <vector>\n#include <algorithm>\nusing namespace std;\n\nint main() {\n    int n;\n    cin >> n;\n    vector<int> nums(n);\n    for (int i = 0; i < n; i++) {\n        cin >> nums[i];\n    }\n\n    int maxProd = nums[0];\n    int minProd = nums[0];\n    int result = nums[0];\n\n    for (int i = 1; i < n; i++) {\n        int cur = nums[i];\n        int tempMax = max(cur, max(maxProd * cur, minProd * cur));\n        int tempMin = min(cur, min(maxProd * cur, minProd * cur));\n        maxProd = tempMax;\n        minProd = tempMin;\n        result = max(result, maxProd);\n    }\n\n    cout << result << endl;\n    return 0;\n}', NULL, 1),
(331, 'JAVA', 'import java.util.Scanner;\n\npublic class Main {\n    public static void main(String[] args) {\n        Scanner sc = new Scanner(System.in);\n        int n = sc.nextInt();\n        int[] nums = new int[n];\n        for (int i = 0; i < n; i++) {\n            nums[i] = sc.nextInt();\n        }\n\n        int maxProd = nums[0];\n        int minProd = nums[0];\n        int result = nums[0];\n\n        for (int i = 1; i < n; i++) {\n            int cur = nums[i];\n            int tempMax = Math.max(cur, Math.max(maxProd * cur, minProd * cur));\n            int tempMin = Math.min(cur, Math.min(maxProd * cur, minProd * cur));\n            maxProd = tempMax;\n            minProd = tempMin;\n            result = Math.max(result, maxProd);\n        }\n\n        System.out.println(result);\n    }\n}', NULL, 1),
(331, 'JAVASCRIPT', 'const readline = require(\'readline\');\n\nconst rl = readline.createInterface({\n    input: process.stdin,\n    output: process.stdout\n});\n\nlet lines = [];\nrl.on(\'line\', (line) => {\n    lines.push(line.trim());\n});\n\nrl.on(\'close\', () => {\n    const n = parseInt(lines[0]);\n    const nums = lines[1].split(/\\s+/).map(Number);\n\n    let maxProd = nums[0];\n    let minProd = nums[0];\n    let result = nums[0];\n\n    for (let i = 1; i < n; i++) {\n        const cur = nums[i];\n        const tempMax = Math.max(cur, Math.max(maxProd * cur, minProd * cur));\n        const tempMin = Math.min(cur, Math.min(maxProd * cur, minProd * cur));\n        maxProd = tempMax;\n        minProd = tempMin;\n        result = Math.max(result, maxProd);\n    }\n\n    console.log(result);\n});', NULL, 1),
(331, 'PYTHON', 'n = int(input())\nnums = list(map(int, input().split()))\n\nmax_prod = nums[0]\nmin_prod = nums[0]\nresult = nums[0]\n\nfor i in range(1, n):\n    cur = nums[i]\n    temp_max = max(cur, max_prod * cur, min_prod * cur)\n    temp_min = min(cur, max_prod * cur, min_prod * cur)\n    max_prod = temp_max\n    min_prod = temp_min\n    result = max(result, max_prod)\n\nprint(result)', NULL, 1),
(332, 'C', '#include <stdio.h>\n#include <stdlib.h>\n#include <string.h>\n\nstruct ListNode {\n    int val;\n    struct ListNode *next;\n};\n\nstruct ListNode* swapPairs(struct ListNode* head) {\n    struct ListNode dummy;\n    dummy.next = head;\n    struct ListNode *prev = &dummy;\n\n    while (prev->next != NULL && prev->next->next != NULL) {\n        struct ListNode *first = prev->next;\n        struct ListNode *second = first->next;\n\n        first->next = second->next;\n        second->next = first;\n        prev->next = second;\n\n        prev = first;\n    }\n\n    return dummy.next;\n}\n\nint main() {\n    char line[100000];\n    if (fgets(line, sizeof(line), stdin) == NULL) {\n        return 0;\n    }\n\n    line[strcspn(line, \"\\r\\n\")] = \'\\0\';\n\n    if (strcmp(line, \"NULL\") == 0) {\n        printf(\"NULL\\n\");\n        return 0;\n    }\n\n    struct ListNode dummy;\n    dummy.next = NULL;\n    struct ListNode *cur = &dummy;\n\n    char *token = strtok(line, \"->\");\n    while (token != NULL) {\n        if (strcmp(token, \"NULL\") == 0) {\n            break;\n        }\n        struct ListNode *node = (struct ListNode *)malloc(sizeof(struct ListNode));\n        node->val = atoi(token);\n        node->next = NULL;\n        cur->next = node;\n        cur = cur->next;\n        token = strtok(NULL, \"->\");\n    }\n\n    struct ListNode *newHead = swapPairs(dummy.next);\n\n    struct ListNode *p = newHead;\n    while (p != NULL) {\n        printf(\"%d->\", p->val);\n        p = p->next;\n    }\n    printf(\"NULL\\n\");\n\n    return 0;\n}', NULL, 1),
(332, 'CPP', '#include <iostream>\n#include <string>\n#include <sstream>\nusing namespace std;\n\nstruct ListNode {\n    int val;\n    ListNode* next;\n    ListNode(int v) : val(v), next(nullptr) {}\n};\n\nListNode* swapPairs(ListNode* head) {\n    ListNode dummy(0);\n    dummy.next = head;\n    ListNode* prev = &dummy;\n\n    while (prev->next != nullptr && prev->next->next != nullptr) {\n        ListNode* first = prev->next;\n        ListNode* second = first->next;\n\n        first->next = second->next;\n        second->next = first;\n        prev->next = second;\n\n        prev = first;\n    }\n\n    return dummy.next;\n}\n\nint main() {\n    ios::sync_with_stdio(false);\n    cin.tie(nullptr);\n\n    string line;\n    if (!getline(cin, line)) return 0;\n\n    if (line == \"NULL\") {\n        cout << \"NULL\\n\";\n        return 0;\n    }\n\n    ListNode dummy(0);\n    ListNode* cur = &dummy;\n\n    size_t pos = 0;\n    while (pos < line.size()) {\n        size_t nextPos = line.find(\"->\", pos);\n        string part;\n        if (nextPos == string::npos) {\n            part = line.substr(pos);\n            pos = line.size();\n        } else {\n            part = line.substr(pos, nextPos - pos);\n            pos = nextPos + 2;\n        }\n\n        if (part == \"NULL\" || part.empty()) break;\n\n        cur->next = new ListNode(stoi(part));\n        cur = cur->next;\n    }\n\n    ListNode* newHead = swapPairs(dummy.next);\n\n    string out;\n    ListNode* p = newHead;\n    while (p != nullptr) {\n        out += to_string(p->val);\n        out += \"->\";\n        p = p->next;\n    }\n    out += \"NULL\";\n\n    cout << out << \'\\n\';\n    return 0;\n}', NULL, 1),
(332, 'JAVA', 'import java.util.Scanner;\n\npublic class Main {\n    static class ListNode {\n        int val;\n        ListNode next;\n        ListNode(int val) {\n            this.val = val;\n        }\n    }\n\n    public static void main(String[] args) {\n        Scanner sc = new Scanner(System.in);\n        String line = sc.nextLine().trim();\n        if (line.equals(\"NULL\")) {\n            System.out.println(\"NULL\");\n            return;\n        }\n\n        String[] parts = line.split(\"->\");\n        ListNode dummy = new ListNode(0);\n        ListNode cur = dummy;\n        for (String part : parts) {\n            if (part.equals(\"NULL\")) {\n                break;\n            }\n            cur.next = new ListNode(Integer.parseInt(part));\n            cur = cur.next;\n        }\n\n        ListNode head = dummy.next;\n        ListNode newHead = swapPairs(head);\n\n        StringBuilder sb = new StringBuilder();\n        ListNode p = newHead;\n        while (p != null) {\n            sb.append(p.val).append(\"->\");\n            p = p.next;\n        }\n        sb.append(\"NULL\");\n        System.out.println(sb.toString());\n    }\n\n    private static ListNode swapPairs(ListNode head) {\n        ListNode dummy = new ListNode(0);\n        dummy.next = head;\n        ListNode prev = dummy;\n\n        while (prev.next != null && prev.next.next != null) {\n            ListNode first = prev.next;\n            ListNode second = first.next;\n\n            first.next = second.next;\n            second.next = first;\n            prev.next = second;\n\n            prev = first;\n        }\n\n        return dummy.next;\n    }\n}', NULL, 1),
(332, 'JAVASCRIPT', 'const readline = require(\'readline\');\n\nclass ListNode {\n    constructor(val) {\n        this.val = val;\n        this.next = null;\n    }\n}\n\nfunction swapPairs(head) {\n    const dummy = new ListNode(0);\n    dummy.next = head;\n    let prev = dummy;\n\n    while (prev.next !== null && prev.next.next !== null) {\n        const first = prev.next;\n        const second = first.next;\n\n        first.next = second.next;\n        second.next = first;\n        prev.next = second;\n\n        prev = first;\n    }\n\n    return dummy.next;\n}\n\nconst rl = readline.createInterface({\n    input: process.stdin,\n    output: process.stdout\n});\n\nrl.on(\'line\', (line) => {\n    line = line.trim();\n    if (line === \'NULL\') {\n        console.log(\'NULL\');\n        rl.close();\n        return;\n    }\n\n    const parts = line.split(\'->\');\n    const dummy = new ListNode(0);\n    let cur = dummy;\n    for (const part of parts) {\n        if (part === \'NULL\') {\n            break;\n        }\n        cur.next = new ListNode(parseInt(part));\n        cur = cur.next;\n    }\n\n    const head = dummy.next;\n    const newHead = swapPairs(head);\n\n    let sb = \'\';\n    let p = newHead;\n    while (p !== null) {\n        sb += p.val + \'->\';\n        p = p.next;\n    }\n    sb += \'NULL\';\n    console.log(sb);\n    rl.close();\n});', NULL, 1),
(332, 'PYTHON', 'import sys\n\nclass ListNode:\n    def __init__(self, val):\n        self.val = val\n        self.next = None\n\ndef swapPairs(head):\n    dummy = ListNode(0)\n    dummy.next = head\n    prev = dummy\n\n    while prev.next is not None and prev.next.next is not None:\n        first = prev.next\n        second = first.next\n\n        first.next = second.next\n        second.next = first\n        prev.next = second\n\n        prev = first\n\n    return dummy.next\n\ndef main():\n    line = sys.stdin.readline().strip()\n    if line == \"NULL\":\n        print(\"NULL\")\n        return\n\n    parts = line.split(\"->\")\n    dummy = ListNode(0)\n    cur = dummy\n    for part in parts:\n        if part == \"NULL\":\n            break\n        cur.next = ListNode(int(part))\n        cur = cur.next\n\n    head = dummy.next\n    new_head = swapPairs(head)\n\n    sb = []\n    p = new_head\n    while p is not None:\n        sb.append(str(p.val))\n        sb.append(\"->\")\n        p = p.next\n    sb.append(\"NULL\")\n    print(\"\".join(sb))\n\nif __name__ == \"__main__\":\n    main()', NULL, 1),
(333, 'C', '#include <stdio.h>\n#include <stdlib.h>\n#include <string.h>\n\ntypedef struct ListNode {\n    int val;\n    struct ListNode *next;\n} ListNode;\n\nint main() {\n    char line[100000];\n    if (fgets(line, sizeof(line), stdin) == NULL) return 0;\n\n    line[strcspn(line, \"\\r\\n\")] = \'\\0\';\n\n    if (strcmp(line, \"NULL\") == 0) {\n        printf(\"NULL\\n\");\n        return 0;\n    }\n\n    ListNode dummy;\n    dummy.val = 0;\n    dummy.next = NULL;\n    ListNode *tail = &dummy;\n\n    char *token = strtok(line, \"->\");\n    while (token != NULL) {\n        if (strcmp(token, \"NULL\") == 0) {\n            break;\n        }\n        int val = atoi(token);\n        if (dummy.next == NULL || tail->val != val) {\n            ListNode *node = (ListNode *)malloc(sizeof(ListNode));\n            node->val = val;\n            node->next = NULL;\n            tail->next = node;\n            tail = node;\n        }\n        token = strtok(NULL, \"->\");\n    }\n\n    ListNode *cur = dummy.next;\n    while (cur != NULL) {\n        printf(\"%d->\", cur->val);\n        cur = cur->next;\n    }\n    printf(\"NULL\\n\");\n\n    cur = dummy.next;\n    while (cur != NULL) {\n        ListNode *tmp = cur;\n        cur = cur->next;\n        free(tmp);\n    }\n\n    return 0;\n}', NULL, 1),
(333, 'CPP', '#include <iostream>\n#include <string>\n#include <sstream>\nusing namespace std;\n\nstruct ListNode {\n    int val;\n    ListNode* next;\n    ListNode(int v) : val(v), next(nullptr) {}\n};\n\nint main() {\n    ios::sync_with_stdio(false);\n    cin.tie(nullptr);\n\n    string line;\n    if (!getline(cin, line)) return 0;\n\n    if (line == \"NULL\") {\n        cout << \"NULL\\n\";\n        return 0;\n    }\n\n    ListNode dummy(0);\n    ListNode* tail = &dummy;\n\n    size_t pos = 0;\n    while (pos < line.size()) {\n        size_t nextPos = line.find(\"->\", pos);\n        string part;\n        if (nextPos == string::npos) {\n            part = line.substr(pos);\n            pos = line.size();\n        } else {\n            part = line.substr(pos, nextPos - pos);\n            pos = nextPos + 2;\n        }\n\n        if (part == \"NULL\") break;\n\n        int val = 0;\n        for (char c : part) {\n            val = val * 10 + (c - \'0\');\n        }\n\n        if (dummy.next == nullptr || tail->val != val) {\n            tail->next = new ListNode(val);\n            tail = tail->next;\n        }\n    }\n\n    ListNode* cur = dummy.next;\n    bool first = true;\n    while (cur != nullptr) {\n        if (!first) cout << \"->\";\n        cout << cur->val;\n        first = false;\n        cur = cur->next;\n    }\n    if (!first) cout << \"->\";\n    cout << \"NULL\\n\";\n\n    return 0;\n}', NULL, 1),
(333, 'JAVA', 'import java.util.Scanner;\n\npublic class Main {\n    static class ListNode {\n        int val;\n        ListNode next;\n        ListNode(int val) {\n            this.val = val;\n        }\n    }\n\n    public static void main(String[] args) {\n        Scanner sc = new Scanner(System.in);\n        String line = sc.nextLine().trim();\n        if (line.equals(\"NULL\")) {\n            System.out.println(\"NULL\");\n            return;\n        }\n\n        String[] parts = line.split(\"->\");\n        ListNode dummy = new ListNode(0);\n        ListNode tail = dummy;\n\n        for (String part : parts) {\n            if (part.equals(\"NULL\")) {\n                break;\n            }\n            int val = Integer.parseInt(part);\n            if (dummy.next == null || tail.val != val) {\n                tail.next = new ListNode(val);\n                tail = tail.next;\n            }\n        }\n\n        StringBuilder sb = new StringBuilder();\n        ListNode cur = dummy.next;\n        while (cur != null) {\n            sb.append(cur.val).append(\"->\");\n            cur = cur.next;\n        }\n        sb.append(\"NULL\");\n        System.out.println(sb.toString());\n    }\n}', NULL, 1),
(333, 'JAVASCRIPT', 'const readline = require(\'readline\');\n\nconst rl = readline.createInterface({\n    input: process.stdin,\n    output: process.stdout\n});\n\nrl.on(\'line\', (line) => {\n    line = line.trim();\n    if (line === \'NULL\') {\n        console.log(\'NULL\');\n        rl.close();\n        return;\n    }\n\n    const parts = line.split(\'->\');\n    const dummy = { val: 0, next: null };\n    let tail = dummy;\n\n    for (const part of parts) {\n        if (part === \'NULL\') {\n            break;\n        }\n        const val = parseInt(part, 10);\n        if (dummy.next === null || tail.val !== val) {\n            tail.next = { val: val, next: null };\n            tail = tail.next;\n        }\n    }\n\n    let result = \'\';\n    let cur = dummy.next;\n    while (cur !== null) {\n        result += cur.val + \'->\';\n        cur = cur.next;\n    }\n    result += \'NULL\';\n    console.log(result);\n    rl.close();\n});', NULL, 1),
(333, 'PYTHON', 'import sys\n\ndef main():\n    line = sys.stdin.readline().strip()\n    if line == \"NULL\":\n        print(\"NULL\")\n        return\n\n    parts = line.split(\"->\")\n    dummy = type(\'ListNode\', (object,), {})()\n    dummy.val = 0\n    dummy.next = None\n    tail = dummy\n\n    for part in parts:\n        if part == \"NULL\":\n            break\n        val = int(part)\n        if dummy.next is None or tail.val != val:\n            node = type(\'ListNode\', (object,), {})()\n            node.val = val\n            node.next = None\n            tail.next = node\n            tail = node\n\n    sb = []\n    cur = dummy.next\n    while cur is not None:\n        sb.append(str(cur.val))\n        sb.append(\"->\")\n        cur = cur.next\n    sb.append(\"NULL\")\n    print(\"\".join(sb))\n\nif __name__ == \"__main__\":\n    main()', NULL, 1),
(334, 'C', '#include <stdio.h>\n#include <stdlib.h>\n\ntypedef struct ListNode {\n    int val;\n    struct ListNode *next;\n} ListNode;\n\nint main() {\n    int n;\n    if (scanf(\"%d\", &n) != 1) return 0;\n\n    int *vals = (int *)malloc(sizeof(int) * (n > 0 ? n : 1));\n    for (int i = 0; i < n; i++) {\n        scanf(\"%d\", &vals[i]);\n    }\n\n    int pos;\n    scanf(\"%d\", &pos);\n\n    if (n == 0) {\n        printf(\"-1\\n\");\n        free(vals);\n        return 0;\n    }\n\n    ListNode **nodes = (ListNode **)malloc(sizeof(ListNode *) * n);\n    for (int i = 0; i < n; i++) {\n        nodes[i] = (ListNode *)malloc(sizeof(ListNode));\n        nodes[i]->val = vals[i];\n        nodes[i]->next = NULL;\n    }\n\n    for (int i = 0; i < n - 1; i++) {\n        nodes[i]->next = nodes[i + 1];\n    }\n\n    if (pos != -1) {\n        nodes[n - 1]->next = nodes[pos];\n    }\n\n    ListNode *head = nodes[0];\n    ListNode *slow = head;\n    ListNode *fast = head;\n    int hasCycle = 0;\n\n    while (fast != NULL && fast->next != NULL) {\n        slow = slow->next;\n        fast = fast->next->next;\n        if (slow == fast) {\n            hasCycle = 1;\n            break;\n        }\n    }\n\n    if (!hasCycle) {\n        printf(\"-1\\n\");\n    } else {\n        slow = head;\n        while (slow != fast) {\n            slow = slow->next;\n            fast = fast->next;\n        }\n\n        int index = 0;\n        ListNode *cur = head;\n        while (cur != slow) {\n            cur = cur->next;\n            index++;\n        }\n        printf(\"%d\\n\", index);\n    }\n\n    for (int i = 0; i < n; i++) {\n        free(nodes[i]);\n    }\n    free(nodes);\n    free(vals);\n\n    return 0;\n}', NULL, 1),
(334, 'CPP', '#include <iostream>\n#include <vector>\nusing namespace std;\n\nstruct ListNode {\n    int val;\n    ListNode* next;\n    ListNode(int v) : val(v), next(nullptr) {}\n};\n\nint main() {\n    int n;\n    cin >> n;\n    vector<int> vals(n);\n    for (int i = 0; i < n; i++) {\n        cin >> vals[i];\n    }\n    int pos;\n    cin >> pos;\n\n    if (n == 0) {\n        cout << -1 << endl;\n        return 0;\n    }\n\n    vector<ListNode*> nodes(n);\n    for (int i = 0; i < n; i++) {\n        nodes[i] = new ListNode(vals[i]);\n    }\n    for (int i = 0; i < n - 1; i++) {\n        nodes[i]->next = nodes[i + 1];\n    }\n    if (pos != -1) {\n        nodes[n - 1]->next = nodes[pos];\n    }\n\n    ListNode* head = nodes[0];\n    ListNode* slow = head;\n    ListNode* fast = head;\n    bool hasCycle = false;\n\n    while (fast != nullptr && fast->next != nullptr) {\n        slow = slow->next;\n        fast = fast->next->next;\n        if (slow == fast) {\n            hasCycle = true;\n            break;\n        }\n    }\n\n    if (!hasCycle) {\n        cout << -1 << endl;\n        return 0;\n    }\n\n    slow = head;\n    while (slow != fast) {\n        slow = slow->next;\n        fast = fast->next;\n    }\n\n    int index = 0;\n    ListNode* cur = head;\n    while (cur != slow) {\n        cur = cur->next;\n        index++;\n    }\n    cout << index << endl;\n\n    return 0;\n}', NULL, 1),
(334, 'JAVA', 'import java.util.Scanner;\n\npublic class Main {\n    static class ListNode {\n        int val;\n        ListNode next;\n        ListNode(int val) {\n            this.val = val;\n        }\n    }\n\n    public static void main(String[] args) {\n        Scanner sc = new Scanner(System.in);\n        int n = sc.nextInt();\n        int[] vals = new int[n];\n        for (int i = 0; i < n; i++) {\n            vals[i] = sc.nextInt();\n        }\n        int pos = sc.nextInt();\n\n        if (n == 0) {\n            System.out.println(-1);\n            return;\n        }\n\n        ListNode[] nodes = new ListNode[n];\n        for (int i = 0; i < n; i++) {\n            nodes[i] = new ListNode(vals[i]);\n        }\n        for (int i = 0; i < n - 1; i++) {\n            nodes[i].next = nodes[i + 1];\n        }\n        if (pos != -1) {\n            nodes[n - 1].next = nodes[pos];\n        }\n\n        ListNode head = nodes[0];\n        ListNode slow = head;\n        ListNode fast = head;\n        boolean hasCycle = false;\n\n        while (fast != null && fast.next != null) {\n            slow = slow.next;\n            fast = fast.next.next;\n            if (slow == fast) {\n                hasCycle = true;\n                break;\n            }\n        }\n\n        if (!hasCycle) {\n            System.out.println(-1);\n            return;\n        }\n\n        slow = head;\n        while (slow != fast) {\n            slow = slow.next;\n            fast = fast.next;\n        }\n\n        int index = 0;\n        ListNode cur = head;\n        while (cur != slow) {\n            cur = cur.next;\n            index++;\n        }\n        System.out.println(index);\n    }\n}', NULL, 1),
(334, 'JAVASCRIPT', 'const readline = require(\'readline\');\n\nconst rl = readline.createInterface({\n    input: process.stdin,\n    output: process.stdout\n});\n\nlet lines = [];\nrl.on(\'line\', (line) => {\n    lines.push(line.trim());\n});\n\nrl.on(\'close\', () => {\n    const n = parseInt(lines[0]);\n    const vals = lines[1] ? lines[1].split(\' \').map(Number) : [];\n    const pos = parseInt(lines[2]);\n\n    if (n === 0) {\n        console.log(-1);\n        return;\n    }\n\n    class ListNode {\n        constructor(val) {\n            this.val = val;\n            this.next = null;\n        }\n    }\n\n    const nodes = [];\n    for (let i = 0; i < n; i++) {\n        nodes.push(new ListNode(vals[i]));\n    }\n    for (let i = 0; i < n - 1; i++) {\n        nodes[i].next = nodes[i + 1];\n    }\n    if (pos !== -1) {\n        nodes[n - 1].next = nodes[pos];\n    }\n\n    const head = nodes[0];\n    let slow = head;\n    let fast = head;\n    let hasCycle = false;\n\n    while (fast !== null && fast.next !== null) {\n        slow = slow.next;\n        fast = fast.next.next;\n        if (slow === fast) {\n            hasCycle = true;\n            break;\n        }\n    }\n\n    if (!hasCycle) {\n        console.log(-1);\n        return;\n    }\n\n    slow = head;\n    while (slow !== fast) {\n        slow = slow.next;\n        fast = fast.next;\n    }\n\n    let index = 0;\n    let cur = head;\n    while (cur !== slow) {\n        cur = cur.next;\n        index++;\n    }\n    console.log(index);\n});', NULL, 1),
(334, 'PYTHON', 'import sys\n\ndef main():\n    data = sys.stdin.read().strip().split()\n    if not data:\n        return\n    n = int(data[0])\n    vals = list(map(int, data[1:1+n]))\n    pos = int(data[1+n])\n\n    if n == 0:\n        print(-1)\n        return\n\n    class ListNode:\n        __slots__ = (\'val\', \'next\')\n        def __init__(self, val):\n            self.val = val\n            self.next = None\n\n    nodes = [ListNode(v) for v in vals]\n    for i in range(n - 1):\n        nodes[i].next = nodes[i + 1]\n    if pos != -1:\n        nodes[n - 1].next = nodes[pos]\n\n    head = nodes[0]\n    slow = head\n    fast = head\n    has_cycle = False\n\n    while fast is not None and fast.next is not None:\n        slow = slow.next\n        fast = fast.next.next\n        if slow is fast:\n            has_cycle = True\n            break\n\n    if not has_cycle:\n        print(-1)\n        return\n\n    slow = head\n    while slow is not fast:\n        slow = slow.next\n        fast = fast.next\n\n    index = 0\n    cur = head\n    while cur is not slow:\n        cur = cur.next\n        index += 1\n    print(index)\n\nif __name__ == \"__main__\":\n    main()', NULL, 1),
(335, 'C', '#include <stdio.h>\n#include <stdlib.h>\n\nstruct ListNode {\n    int val;\n    struct ListNode *next;\n};\n\nint main() {\n    int len;\n    scanf(\"%d\", &len);\n\n    struct ListNode dummy;\n    dummy.val = 0;\n    dummy.next = NULL;\n    struct ListNode *tail = &dummy;\n\n    for (int i = 0; i < len; i++) {\n        int x;\n        scanf(\"%d\", &x);\n        struct ListNode *node = (struct ListNode *)malloc(sizeof(struct ListNode));\n        node->val = x;\n        node->next = NULL;\n        tail->next = node;\n        tail = node;\n    }\n\n    int n;\n    scanf(\"%d\", &n);\n\n    struct ListNode *fast = &dummy;\n    struct ListNode *slow = &dummy;\n\n    for (int i = 0; i <= n; i++) {\n        fast = fast->next;\n    }\n\n    while (fast != NULL) {\n        fast = fast->next;\n        slow = slow->next;\n    }\n\n    struct ListNode *toDelete = slow->next;\n    slow->next = slow->next->next;\n    free(toDelete);\n\n    struct ListNode *cur = dummy.next;\n    while (cur != NULL) {\n        printf(\"%d->\", cur->val);\n        cur = cur->next;\n    }\n    printf(\"NULL\\n\");\n\n    return 0;\n}', NULL, 1),
(335, 'CPP', '#include <iostream>\nusing namespace std;\n\nstruct ListNode {\n    int val;\n    ListNode* next;\n    ListNode(int v) : val(v), next(nullptr) {}\n};\n\nint main() {\n    int len;\n    cin >> len;\n\n    ListNode* dummy = new ListNode(0);\n    ListNode* tail = dummy;\n    for (int i = 0; i < len; ++i) {\n        int x;\n        cin >> x;\n        tail->next = new ListNode(x);\n        tail = tail->next;\n    }\n\n    int n;\n    cin >> n;\n\n    ListNode* fast = dummy;\n    ListNode* slow = dummy;\n    for (int i = 0; i <= n; ++i) {\n        fast = fast->next;\n    }\n    while (fast != nullptr) {\n        fast = fast->next;\n        slow = slow->next;\n    }\n    slow->next = slow->next->next;\n\n    ListNode* cur = dummy->next;\n    while (cur != nullptr) {\n        cout << cur->val << \"->\";\n        cur = cur->next;\n    }\n    cout << \"NULL\" << endl;\n\n    return 0;\n}', NULL, 1),
(335, 'JAVA', 'import java.util.Scanner;\n\npublic class Main {\n    static class ListNode {\n        int val;\n        ListNode next;\n        ListNode(int val) {\n            this.val = val;\n        }\n    }\n\n    public static void main(String[] args) {\n        Scanner sc = new Scanner(System.in);\n        int len = sc.nextInt();\n        ListNode dummy = new ListNode(0);\n        ListNode tail = dummy;\n        for (int i = 0; i < len; i++) {\n            tail.next = new ListNode(sc.nextInt());\n            tail = tail.next;\n        }\n        int n = sc.nextInt();\n\n        ListNode fast = dummy;\n        ListNode slow = dummy;\n        for (int i = 0; i <= n; i++) {\n            fast = fast.next;\n        }\n        while (fast != null) {\n            fast = fast.next;\n            slow = slow.next;\n        }\n        slow.next = slow.next.next;\n\n        StringBuilder sb = new StringBuilder();\n        ListNode cur = dummy.next;\n        while (cur != null) {\n            sb.append(cur.val).append(\"->\");\n            cur = cur.next;\n        }\n        sb.append(\"NULL\");\n        System.out.println(sb.toString());\n    }\n}', NULL, 1),
(335, 'JAVASCRIPT', 'const readline = require(\'readline\');\n\nconst rl = readline.createInterface({\n    input: process.stdin,\n    output: process.stdout\n});\n\nlet lines = [];\nrl.on(\'line\', (line) => {\n    lines.push(line.trim());\n});\n\nrl.on(\'close\', () => {\n    const len = parseInt(lines[0]);\n    const values = lines[1].split(\' \').map(Number);\n    const n = parseInt(lines[2]);\n\n    class ListNode {\n        constructor(val) {\n            this.val = val;\n            this.next = null;\n        }\n    }\n\n    const dummy = new ListNode(0);\n    let tail = dummy;\n    for (let i = 0; i < len; i++) {\n        tail.next = new ListNode(values[i]);\n        tail = tail.next;\n    }\n\n    let fast = dummy;\n    let slow = dummy;\n    for (let i = 0; i <= n; i++) {\n        fast = fast.next;\n    }\n    while (fast !== null) {\n        fast = fast.next;\n        slow = slow.next;\n    }\n    slow.next = slow.next.next;\n\n    let result = \'\';\n    let cur = dummy.next;\n    while (cur !== null) {\n        result += cur.val + \'->\';\n        cur = cur.next;\n    }\n    result += \'NULL\';\n    console.log(result);\n});', NULL, 1),
(335, 'PYTHON', 'import sys\n\nclass ListNode:\n    def __init__(self, val):\n        self.val = val\n        self.next = None\n\ndef main():\n    data = sys.stdin.read().strip().split()\n    if not data:\n        return\n    length = int(data[0])\n    dummy = ListNode(0)\n    tail = dummy\n    idx = 1\n    for _ in range(length):\n        tail.next = ListNode(int(data[idx]))\n        tail = tail.next\n        idx += 1\n    n = int(data[idx])\n\n    fast = dummy\n    slow = dummy\n    for _ in range(n + 1):\n        fast = fast.next\n    while fast is not None:\n        fast = fast.next\n        slow = slow.next\n    slow.next = slow.next.next\n\n    res = []\n    cur = dummy.next\n    while cur is not None:\n        res.append(str(cur.val))\n        cur = cur.next\n    print(\"->\".join(res) + \"->NULL\")\n\nif __name__ == \"__main__\":\n    main()', NULL, 1),
(336, 'C', '#include <stdio.h>\n#include <stdlib.h>\n#include <string.h>\n\ntypedef struct ListNode {\n    int val;\n    struct ListNode *next;\n} ListNode;\n\nListNode* reverse(ListNode* head) {\n    ListNode* prev = NULL;\n    while (head != NULL) {\n        ListNode* next = head->next;\n        head->next = prev;\n        prev = head;\n        head = next;\n    }\n    return prev;\n}\n\nvoid reorderList(ListNode* head) {\n    if (head == NULL || head->next == NULL) return;\n    ListNode *slow = head, *fast = head;\n    while (fast->next != NULL && fast->next->next != NULL) {\n        slow = slow->next;\n        fast = fast->next->next;\n    }\n    ListNode* second = slow->next;\n    slow->next = NULL;\n    second = reverse(second);\n    ListNode* first = head;\n    while (second != NULL) {\n        ListNode* tmp1 = first->next;\n        ListNode* tmp2 = second->next;\n        first->next = second;\n        second->next = tmp1;\n        first = tmp1;\n        second = tmp2;\n    }\n}\n\nint main() {\n    char line[100000];\n    if (fgets(line, sizeof(line), stdin) == NULL) return 0;\n    size_t len = strlen(line);\n    while (len > 0 && (line[len-1] == \'\\n\' || line[len-1] == \'\\r\')) {\n        line[--len] = \'\\0\';\n    }\n    if (len >= 6 && strcmp(line + len - 6, \"->NULL\") == 0) {\n        line[len - 6] = \'\\0\';\n    }\n    if (line[0] == \'\\0\') {\n        printf(\"NULL\\n\");\n        return 0;\n    }\n    ListNode dummy;\n    dummy.val = 0;\n    dummy.next = NULL;\n    ListNode* cur = &dummy;\n    char* token = strtok(line, \"->\");\n    while (token != NULL) {\n        cur->next = (ListNode*)malloc(sizeof(ListNode));\n        cur->next->val = atoi(token);\n        cur->next->next = NULL;\n        cur = cur->next;\n        token = strtok(NULL, \"->\");\n    }\n    ListNode* head = dummy.next;\n    reorderList(head);\n    cur = head;\n    while (cur != NULL) {\n        printf(\"%d->\", cur->val);\n        cur = cur->next;\n    }\n    printf(\"NULL\\n\");\n    return 0;\n}', NULL, 1),
(336, 'CPP', '#include <iostream>\n#include <string>\n#include <sstream>\nusing namespace std;\n\nstruct ListNode {\n    int val;\n    ListNode* next;\n    ListNode(int v) : val(v), next(nullptr) {}\n};\n\nListNode* reverseList(ListNode* head) {\n    ListNode* prev = nullptr;\n    while (head != nullptr) {\n        ListNode* nxt = head->next;\n        head->next = prev;\n        prev = head;\n        head = nxt;\n    }\n    return prev;\n}\n\nvoid reorderList(ListNode* head) {\n    if (head == nullptr || head->next == nullptr) return;\n    ListNode* slow = head;\n    ListNode* fast = head;\n    while (fast->next != nullptr && fast->next->next != nullptr) {\n        slow = slow->next;\n        fast = fast->next->next;\n    }\n    ListNode* second = slow->next;\n    slow->next = nullptr;\n    second = reverseList(second);\n    ListNode* first = head;\n    while (second != nullptr) {\n        ListNode* tmp1 = first->next;\n        ListNode* tmp2 = second->next;\n        first->next = second;\n        second->next = tmp1;\n        first = tmp1;\n        second = tmp2;\n    }\n}\n\nint main() {\n    string line;\n    getline(cin, line);\n    while (!line.empty() && (line.back() == \'\\r\' || line.back() == \'\\n\' || line.back() == \' \')) {\n        line.pop_back();\n    }\n    if (line.size() >= 6 && line.substr(line.size() - 6) == \"->NULL\") {\n        line = line.substr(0, line.size() - 6);\n    }\n    if (line.empty()) {\n        cout << \"NULL\" << endl;\n        return 0;\n    }\n    ListNode dummy(0);\n    ListNode* cur = &dummy;\n    stringstream ss(line);\n    string part;\n    while (getline(ss, part, \'-\')) {\n        if (part == \">\") continue;\n        if (!part.empty() && part[0] == \'>\') part = part.substr(1);\n        if (part.empty()) continue;\n        cur->next = new ListNode(stoi(part));\n        cur = cur->next;\n    }\n    ListNode* head = dummy.next;\n    reorderList(head);\n    ListNode* p = head;\n    while (p != nullptr) {\n        cout << p->val << \"->\";\n        p = p->next;\n    }\n    cout << \"NULL\" << endl;\n    return 0;\n}', NULL, 1),
(336, 'JAVA', 'import java.util.*;\n\npublic class Main {\n    static class ListNode {\n        int val;\n        ListNode next;\n        ListNode(int val) { this.val = val; }\n    }\n\n    public static void main(String[] args) {\n        Scanner sc = new Scanner(System.in);\n        String line = sc.nextLine().trim();\n        if (line.endsWith(\"->NULL\")) {\n            line = line.substring(0, line.length() - 6);\n        }\n        if (line.isEmpty()) {\n            System.out.println(\"NULL\");\n            return;\n        }\n        String[] parts = line.split(\"->\");\n        ListNode dummy = new ListNode(0);\n        ListNode cur = dummy;\n        for (String p : parts) {\n            cur.next = new ListNode(Integer.parseInt(p.trim()));\n            cur = cur.next;\n        }\n        ListNode head = dummy.next;\n        reorderList(head);\n        StringBuilder sb = new StringBuilder();\n        cur = head;\n        while (cur != null) {\n            sb.append(cur.val).append(\"->\");\n            cur = cur.next;\n        }\n        sb.append(\"NULL\");\n        System.out.println(sb.toString());\n    }\n\n    public static void reorderList(ListNode head) {\n        if (head == null || head.next == null) return;\n        ListNode slow = head, fast = head;\n        while (fast.next != null && fast.next.next != null) {\n            slow = slow.next;\n            fast = fast.next.next;\n        }\n        ListNode second = slow.next;\n        slow.next = null;\n        second = reverse(second);\n        ListNode first = head;\n        while (second != null) {\n            ListNode tmp1 = first.next;\n            ListNode tmp2 = second.next;\n            first.next = second;\n            second.next = tmp1;\n            first = tmp1;\n            second = tmp2;\n        }\n    }\n\n    private static ListNode reverse(ListNode head) {\n        ListNode prev = null;\n        while (head != null) {\n            ListNode next = head.next;\n            head.next = prev;\n            prev = head;\n            head = next;\n        }\n        return prev;\n    }\n}', NULL, 1),
(336, 'JAVASCRIPT', 'const readline = require(\'readline\');\n\nclass ListNode {\n    constructor(val) {\n        this.val = val;\n        this.next = null;\n    }\n}\n\nfunction reorderList(head) {\n    if (head === null || head.next === null) return;\n    let slow = head, fast = head;\n    while (fast.next !== null && fast.next.next !== null) {\n        slow = slow.next;\n        fast = fast.next.next;\n    }\n    let second = slow.next;\n    slow.next = null;\n    second = reverse(second);\n    let first = head;\n    while (second !== null) {\n        let tmp1 = first.next;\n        let tmp2 = second.next;\n        first.next = second;\n        second.next = tmp1;\n        first = tmp1;\n        second = tmp2;\n    }\n}\n\nfunction reverse(head) {\n    let prev = null;\n    while (head !== null) {\n        let next = head.next;\n        head.next = prev;\n        prev = head;\n        head = next;\n    }\n    return prev;\n}\n\nconst rl = readline.createInterface({\n    input: process.stdin,\n    output: process.stdout\n});\n\nrl.on(\'line\', (line) => {\n    line = line.trim();\n    if (line.endsWith(\'->NULL\')) {\n        line = line.substring(0, line.length - 6);\n    }\n    if (line === \'\') {\n        console.log(\'NULL\');\n        rl.close();\n        return;\n    }\n    const parts = line.split(\'->\');\n    const dummy = new ListNode(0);\n    let cur = dummy;\n    for (const p of parts) {\n        cur.next = new ListNode(parseInt(p.trim(), 10));\n        cur = cur.next;\n    }\n    const head = dummy.next;\n    reorderList(head);\n    let sb = \'\';\n    cur = head;\n    while (cur !== null) {\n        sb += cur.val + \'->\';\n        cur = cur.next;\n    }\n    sb += \'NULL\';\n    console.log(sb);\n    rl.close();\n});', NULL, 1),
(336, 'PYTHON', 'import sys\n\nclass ListNode:\n    def __init__(self, val=0, next=None):\n        self.val = val\n        self.next = next\n\ndef reorder_list(head):\n    if not head or not head.next:\n        return\n    slow = head\n    fast = head\n    while fast.next and fast.next.next:\n        slow = slow.next\n        fast = fast.next.next\n    second = slow.next\n    slow.next = None\n    second = reverse(second)\n    first = head\n    while second:\n        tmp1 = first.next\n        tmp2 = second.next\n        first.next = second\n        second.next = tmp1\n        first = tmp1\n        second = tmp2\n\ndef reverse(head):\n    prev = None\n    while head:\n        nxt = head.next\n        head.next = prev\n        prev = head\n        head = nxt\n    return prev\n\ndef main():\n    line = sys.stdin.readline().strip()\n    if line.endswith(\"->NULL\"):\n        line = line[:-6]\n    if not line:\n        print(\"NULL\")\n        return\n    parts = line.split(\"->\")\n    dummy = ListNode(0)\n    cur = dummy\n    for p in parts:\n        cur.next = ListNode(int(p.strip()))\n        cur = cur.next\n    head = dummy.next\n    reorder_list(head)\n    sb = []\n    cur = head\n    while cur:\n        sb.append(str(cur.val))\n        sb.append(\"->\")\n        cur = cur.next\n    sb.append(\"NULL\")\n    print(\"\".join(sb))\n\nif __name__ == \"__main__\":\n    main()', NULL, 1),
(337, 'C', '#include <stdio.h>\n#include <stdlib.h>\n#include <string.h>\n\nstruct ListNode {\n    int val;\n    struct ListNode *next;\n};\n\nstruct ListNode* buildList(char *s) {\n    if (s == NULL || s[0] == \'\\0\' || strcmp(s, \"NULL\") == 0) {\n        return NULL;\n    }\n    struct ListNode dummy;\n    dummy.next = NULL;\n    struct ListNode *cur = &dummy;\n    char *token = strtok(s, \"->\");\n    while (token != NULL) {\n        if (strcmp(token, \"NULL\") == 0) {\n            break;\n        }\n        struct ListNode *node = (struct ListNode*)malloc(sizeof(struct ListNode));\n        node->val = atoi(token);\n        node->next = NULL;\n        cur->next = node;\n        cur = cur->next;\n        token = strtok(NULL, \"->\");\n    }\n    return dummy.next;\n}\n\nchar* printList(struct ListNode *head) {\n    char *buf = (char*)malloc(1000000);\n    buf[0] = \'\\0\';\n    struct ListNode *cur = head;\n    while (cur != NULL) {\n        char tmp[32];\n        sprintf(tmp, \"%d->\", cur->val);\n        strcat(buf, tmp);\n        cur = cur->next;\n    }\n    strcat(buf, \"NULL\");\n    return buf;\n}\n\nstruct ListNode* rotateRight(struct ListNode *head, int k) {\n    if (head == NULL || head->next == NULL || k == 0) {\n        return head;\n    }\n\n    int len = 1;\n    struct ListNode *tail = head;\n    while (tail->next != NULL) {\n        tail = tail->next;\n        len++;\n    }\n\n    k = k % len;\n    if (k == 0) {\n        return head;\n    }\n\n    tail->next = head;\n    struct ListNode *newTail = head;\n    for (int i = 0; i < len - k - 1; i++) {\n        newTail = newTail->next;\n    }\n\n    struct ListNode *newHead = newTail->next;\n    newTail->next = NULL;\n    return newHead;\n}\n\nint main() {\n    char line[1000000];\n    int k;\n\n    if (fgets(line, sizeof(line), stdin) == NULL) {\n        return 0;\n    }\n    line[strcspn(line, \"\\r\\n\")] = \'\\0\';\n\n    if (scanf(\"%d\", &k) != 1) {\n        return 0;\n    }\n\n    struct ListNode *head = buildList(line);\n    head = rotateRight(head, k);\n    char *result = printList(head);\n    printf(\"%s\\n\", result);\n\n    free(result);\n    return 0;\n}', NULL, 1),
(337, 'CPP', '#include <iostream>\n#include <string>\n#include <sstream>\nusing namespace std;\n\nstruct ListNode {\n    int val;\n    ListNode* next;\n    ListNode(int v) : val(v), next(nullptr) {}\n};\n\nListNode* buildList(const string& s) {\n    if (s.empty() || s == \"NULL\") return nullptr;\n    ListNode dummy(0);\n    ListNode* cur = &dummy;\n    size_t start = 0;\n    while (start < s.size()) {\n        size_t pos = s.find(\"->\", start);\n        string part;\n        if (pos == string::npos) {\n            part = s.substr(start);\n            start = s.size();\n        } else {\n            part = s.substr(start, pos - start);\n            start = pos + 2;\n        }\n        if (part == \"NULL\") break;\n        cur->next = new ListNode(stoi(part));\n        cur = cur->next;\n    }\n    return dummy.next;\n}\n\nstring printList(ListNode* head) {\n    string res;\n    ListNode* cur = head;\n    while (cur) {\n        res += to_string(cur->val);\n        res += \"->\";\n        cur = cur->next;\n    }\n    res += \"NULL\";\n    return res;\n}\n\nListNode* rotateRight(ListNode* head, int k) {\n    if (!head || !head->next || k == 0) return head;\n\n    int len = 1;\n    ListNode* tail = head;\n    while (tail->next) {\n        tail = tail->next;\n        len++;\n    }\n\n    k %= len;\n    if (k == 0) return head;\n\n    tail->next = head;\n    ListNode* newTail = head;\n    for (int i = 0; i < len - k - 1; i++) {\n        newTail = newTail->next;\n    }\n\n    ListNode* newHead = newTail->next;\n    newTail->next = nullptr;\n    return newHead;\n}\n\nint main() {\n    ios::sync_with_stdio(false);\n    cin.tie(nullptr);\n\n    string line;\n    getline(cin, line);\n    int k;\n    cin >> k;\n\n    ListNode* head = buildList(line);\n    head = rotateRight(head, k);\n    cout << printList(head) << \'\\n\';\n\n    return 0;\n}', NULL, 1),
(337, 'JAVA', 'import java.util.Scanner;\n\npublic class Main {\n    static class ListNode {\n        int val;\n        ListNode next;\n        ListNode(int val) {\n            this.val = val;\n        }\n    }\n\n    public static void main(String[] args) {\n        Scanner sc = new Scanner(System.in);\n        String line = sc.nextLine().trim();\n        int k = Integer.parseInt(sc.nextLine().trim());\n\n        ListNode head = buildList(line);\n        head = rotateRight(head, k);\n        System.out.println(printList(head));\n    }\n\n    private static ListNode buildList(String s) {\n        if (s == null || s.isEmpty() || s.equals(\"NULL\")) {\n            return null;\n        }\n        String[] parts = s.split(\"->\");\n        ListNode dummy = new ListNode(0);\n        ListNode cur = dummy;\n        for (String part : parts) {\n            if (part.equals(\"NULL\")) {\n                break;\n            }\n            cur.next = new ListNode(Integer.parseInt(part));\n            cur = cur.next;\n        }\n        return dummy.next;\n    }\n\n    private static String printList(ListNode head) {\n        StringBuilder sb = new StringBuilder();\n        ListNode cur = head;\n        while (cur != null) {\n            sb.append(cur.val).append(\"->\");\n            cur = cur.next;\n        }\n        sb.append(\"NULL\");\n        return sb.toString();\n    }\n\n    private static ListNode rotateRight(ListNode head, int k) {\n        if (head == null || head.next == null || k == 0) {\n            return head;\n        }\n\n        int len = 1;\n        ListNode tail = head;\n        while (tail.next != null) {\n            tail = tail.next;\n            len++;\n        }\n\n        k = k % len;\n        if (k == 0) {\n            return head;\n        }\n\n        tail.next = head;\n        ListNode newTail = head;\n        for (int i = 0; i < len - k - 1; i++) {\n            newTail = newTail.next;\n        }\n\n        ListNode newHead = newTail.next;\n        newTail.next = null;\n        return newHead;\n    }\n}', NULL, 1),
(337, 'JAVASCRIPT', 'const readline = require(\'readline\');\n\nconst rl = readline.createInterface({\n    input: process.stdin,\n    output: process.stdout\n});\n\nclass ListNode {\n    constructor(val) {\n        this.val = val;\n        this.next = null;\n    }\n}\n\nfunction buildList(s) {\n    if (s === null || s === \'\' || s === \'NULL\') {\n        return null;\n    }\n    const parts = s.split(\'->\');\n    const dummy = new ListNode(0);\n    let cur = dummy;\n    for (const part of parts) {\n        if (part === \'NULL\') {\n            break;\n        }\n        cur.next = new ListNode(parseInt(part));\n        cur = cur.next;\n    }\n    return dummy.next;\n}\n\nfunction printList(head) {\n    let sb = \'\';\n    let cur = head;\n    while (cur !== null) {\n        sb += cur.val + \'->\';\n        cur = cur.next;\n    }\n    sb += \'NULL\';\n    return sb;\n}\n\nfunction rotateRight(head, k) {\n    if (head === null || head.next === null || k === 0) {\n        return head;\n    }\n\n    let len = 1;\n    let tail = head;\n    while (tail.next !== null) {\n        tail = tail.next;\n        len++;\n    }\n\n    k = k % len;\n    if (k === 0) {\n        return head;\n    }\n\n    tail.next = head;\n    let newTail = head;\n    for (let i = 0; i < len - k - 1; i++) {\n        newTail = newTail.next;\n    }\n\n    const newHead = newTail.next;\n    newTail.next = null;\n    return newHead;\n}\n\nlet lines = [];\nrl.on(\'line\', (line) => {\n    lines.push(line.trim());\n    if (lines.length === 2) {\n        const listLine = lines[0];\n        const k = parseInt(lines[1]);\n\n        let head = buildList(listLine);\n        head = rotateRight(head, k);\n        console.log(printList(head));\n        rl.close();\n    }\n});', NULL, 1),
(337, 'PYTHON', 'import sys\n\nclass ListNode:\n    def __init__(self, val):\n        self.val = val\n        self.next = None\n\ndef build_list(s):\n    if s is None or s == \"\" or s == \"NULL\":\n        return None\n    parts = s.split(\"->\")\n    dummy = ListNode(0)\n    cur = dummy\n    for part in parts:\n        if part == \"NULL\":\n            break\n        cur.next = ListNode(int(part))\n        cur = cur.next\n    return dummy.next\n\ndef print_list(head):\n    sb = []\n    cur = head\n    while cur is not None:\n        sb.append(str(cur.val))\n        sb.append(\"->\")\n        cur = cur.next\n    sb.append(\"NULL\")\n    return \"\".join(sb)\n\ndef rotate_right(head, k):\n    if head is None or head.next is None or k == 0:\n        return head\n\n    length = 1\n    tail = head\n    while tail.next is not None:\n        tail = tail.next\n        length += 1\n\n    k = k % length\n    if k == 0:\n        return head\n\n    tail.next = head\n    new_tail = head\n    for _ in range(length - k - 1):\n        new_tail = new_tail.next\n\n    new_head = new_tail.next\n    new_tail.next = None\n    return new_head\n\ndef main():\n    lines = sys.stdin.read().splitlines()\n    if not lines:\n        return\n    line = lines[0].strip()\n    k = int(lines[1].strip())\n\n    head = build_list(line)\n    head = rotate_right(head, k)\n    print(print_list(head))\n\nif __name__ == \"__main__\":\n    main()', NULL, 1),
(338, 'C', '#include <stdio.h>\n#include <stdlib.h>\n#include <string.h>\n\ntypedef struct ListNode {\n    int val;\n    struct ListNode *next;\n} ListNode;\n\ntypedef struct {\n    ListNode **data;\n    int size;\n    int capacity;\n} PriorityQueue;\n\nstatic void pq_init(PriorityQueue *pq, int capacity) {\n    pq->data = (ListNode **)malloc(sizeof(ListNode *) * capacity);\n    pq->size = 0;\n    pq->capacity = capacity;\n}\n\nstatic void pq_free(PriorityQueue *pq) {\n    free(pq->data);\n}\n\nstatic void pq_swap(ListNode **a, ListNode **b) {\n    ListNode *t = *a;\n    *a = *b;\n    *b = t;\n}\n\nstatic void pq_push(PriorityQueue *pq, ListNode *node) {\n    int i = pq->size++;\n    pq->data[i] = node;\n    while (i > 0) {\n        int p = (i - 1) / 2;\n        if (pq->data[p]->val <= pq->data[i]->val) break;\n        pq_swap(&pq->data[p], &pq->data[i]);\n        i = p;\n    }\n}\n\nstatic ListNode *pq_pop(PriorityQueue *pq) {\n    ListNode *res = pq->data[0];\n    pq->data[0] = pq->data[--pq->size];\n    int i = 0;\n    while (1) {\n        int l = i * 2 + 1;\n        int r = i * 2 + 2;\n        int smallest = i;\n        if (l < pq->size && pq->data[l]->val < pq->data[smallest]->val) smallest = l;\n        if (r < pq->size && pq->data[r]->val < pq->data[smallest]->val) smallest = r;\n        if (smallest == i) break;\n        pq_swap(&pq->data[i], &pq->data[smallest]);\n        i = smallest;\n    }\n    return res;\n}\n\nstatic ListNode *parseList(const char *s) {\n    if (s == NULL || s[0] == \'\\0\' || strcmp(s, \"NULL\") == 0) return NULL;\n    char *buf = (char *)malloc(strlen(s) + 1);\n    strcpy(buf, s);\n    ListNode dummy;\n    dummy.val = 0;\n    dummy.next = NULL;\n    ListNode *cur = &dummy;\n    char *token = strtok(buf, \"->\");\n    while (token != NULL) {\n        if (strcmp(token, \"NULL\") == 0) break;\n        ListNode *node = (ListNode *)malloc(sizeof(ListNode));\n        node->val = atoi(token);\n        node->next = NULL;\n        cur->next = node;\n        cur = node;\n        token = strtok(NULL, \"->\");\n    }\n    free(buf);\n    return dummy.next;\n}\n\nstatic char *formatList(ListNode *head) {\n    size_t cap = 1024;\n    size_t len = 0;\n    char *res = (char *)malloc(cap);\n    res[0] = \'\\0\';\n    ListNode *cur = head;\n    while (cur != NULL) {\n        char tmp[32];\n        int n = snprintf(tmp, sizeof(tmp), \"%d->\", cur->val);\n        if (len + (size_t)n + 6 > cap) {\n            cap *= 2;\n            res = (char *)realloc(res, cap);\n        }\n        strcpy(res + len, tmp);\n        len += (size_t)n;\n        cur = cur->next;\n    }\n    if (len + 5 > cap) {\n        cap = len + 5;\n        res = (char *)realloc(res, cap);\n    }\n    strcpy(res + len, \"NULL\");\n    return res;\n}\n\nstatic ListNode *mergeKLists(ListNode **lists, int k) {\n    PriorityQueue pq;\n    pq_init(&pq, k > 0 ? k : 1);\n    for (int i = 0; i < k; i++) {\n        if (lists[i] != NULL) pq_push(&pq, lists[i]);\n    }\n    ListNode dummy;\n    dummy.val = 0;\n    dummy.next = NULL;\n    ListNode *cur = &dummy;\n    while (pq.size > 0) {\n        ListNode *node = pq_pop(&pq);\n        cur->next = node;\n        cur = cur->next;\n        if (node->next != NULL) pq_push(&pq, node->next);\n    }\n    pq_free(&pq);\n    return dummy.next;\n}\n\nint main(void) {\n    int k;\n    if (scanf(\"%d\", &k) != 1) return 0;\n    int c;\n    while ((c = getchar()) != \'\\n\' && c != EOF) {}\n\n    ListNode **lists = (ListNode **)malloc(sizeof(ListNode *) * (k > 0 ? k : 1));\n    for (int i = 0; i < k; i++) {\n        size_t cap = 1024;\n        size_t len = 0;\n        char *line = (char *)malloc(cap);\n        line[0] = \'\\0\';\n        while ((c = getchar()) != \'\\n\' && c != EOF) {\n            if (len + 2 > cap) {\n                cap *= 2;\n                line = (char *)realloc(line, cap);\n            }\n            line[len++] = (char)c;\n            line[len] = \'\\0\';\n        }\n        lists[i] = parseList(line);\n        free(line);\n    }\n\n    ListNode *merged = mergeKLists(lists, k);\n    char *out = formatList(merged);\n    printf(\"%s\\n\", out);\n\n    free(out);\n    free(lists);\n    return 0;\n}', NULL, 1),
(338, 'CPP', '#include <bits/stdc++.h>\nusing namespace std;\n\nstruct ListNode {\n    int val;\n    ListNode *next;\n    ListNode(int x) : val(x), next(nullptr) {}\n};\n\nListNode* parseList(const string& s) {\n    if (s.empty() || s == \"NULL\") return nullptr;\n    ListNode dummy(0);\n    ListNode* cur = &dummy;\n    size_t start = 0;\n    while (start < s.size()) {\n        size_t pos = s.find(\"->\", start);\n        string part;\n        if (pos == string::npos) {\n            part = s.substr(start);\n            start = s.size();\n        } else {\n            part = s.substr(start, pos - start);\n            start = pos + 2;\n        }\n        if (part == \"NULL\") break;\n        cur->next = new ListNode(stoi(part));\n        cur = cur->next;\n    }\n    return dummy.next;\n}\n\nstring formatList(ListNode* head) {\n    string res;\n    ListNode* cur = head;\n    while (cur) {\n        res += to_string(cur->val);\n        res += \"->\";\n        cur = cur->next;\n    }\n    res += \"NULL\";\n    return res;\n}\n\nstruct Compare {\n    bool operator()(ListNode* a, ListNode* b) {\n        return a->val > b->val;\n    }\n};\n\nListNode* mergeKLists(vector<ListNode*>& lists) {\n    priority_queue<ListNode*, vector<ListNode*>, Compare> pq;\n    for (ListNode* node : lists) {\n        if (node) pq.push(node);\n    }\n    ListNode dummy(0);\n    ListNode* cur = &dummy;\n    while (!pq.empty()) {\n        ListNode* node = pq.top();\n        pq.pop();\n        cur->next = node;\n        cur = cur->next;\n        if (node->next) pq.push(node->next);\n    }\n    return dummy.next;\n}\n\nint main() {\n    ios::sync_with_stdio(false);\n    cin.tie(nullptr);\n\n    int k;\n    cin >> k;\n    cin.ignore();\n\n    vector<ListNode*> lists;\n    lists.reserve(k);\n\n    for (int i = 0; i < k; ++i) {\n        string line;\n        getline(cin, line);\n        lists.push_back(parseList(line));\n    }\n\n    ListNode* merged = mergeKLists(lists);\n    cout << formatList(merged) << \'\\n\';\n\n    return 0;\n}', NULL, 1),
(338, 'JAVA', 'import java.util.*;\n\npublic class Main {\n    static class ListNode {\n        int val;\n        ListNode next;\n        ListNode(int val) { this.val = val; }\n    }\n\n    public static void main(String[] args) {\n        Scanner sc = new Scanner(System.in);\n        int k = Integer.parseInt(sc.nextLine().trim());\n        List<ListNode> lists = new ArrayList<>();\n        for (int i = 0; i < k; i++) {\n            String line = sc.nextLine().trim();\n            lists.add(parseList(line));\n        }\n        ListNode merged = mergeKLists(lists);\n        System.out.println(formatList(merged));\n    }\n\n    private static ListNode parseList(String s) {\n        if (s == null || s.isEmpty() || s.equals(\"NULL\")) return null;\n        String[] parts = s.split(\"->\");\n        ListNode dummy = new ListNode(0);\n        ListNode cur = dummy;\n        for (String p : parts) {\n            if (p.equals(\"NULL\")) break;\n            cur.next = new ListNode(Integer.parseInt(p.trim()));\n            cur = cur.next;\n        }\n        return dummy.next;\n    }\n\n    private static String formatList(ListNode head) {\n        StringBuilder sb = new StringBuilder();\n        ListNode cur = head;\n        while (cur != null) {\n            sb.append(cur.val).append(\"->\");\n            cur = cur.next;\n        }\n        sb.append(\"NULL\");\n        return sb.toString();\n    }\n\n    private static ListNode mergeKLists(List<ListNode> lists) {\n        PriorityQueue<ListNode> pq = new PriorityQueue<>(Comparator.comparingInt(a -> a.val));\n        for (ListNode node : lists) {\n            if (node != null) pq.offer(node);\n        }\n        ListNode dummy = new ListNode(0);\n        ListNode cur = dummy;\n        while (!pq.isEmpty()) {\n            ListNode node = pq.poll();\n            cur.next = node;\n            cur = cur.next;\n            if (node.next != null) pq.offer(node.next);\n        }\n        return dummy.next;\n    }\n}', NULL, 1),
(338, 'JAVASCRIPT', 'const readline = require(\'readline\');\n\nclass ListNode {\n    constructor(val) {\n        this.val = val;\n        this.next = null;\n    }\n}\n\nfunction parseList(s) {\n    if (!s || s === \'NULL\') return null;\n    const parts = s.split(\'->\');\n    const dummy = new ListNode(0);\n    let cur = dummy;\n    for (const p of parts) {\n        if (p === \'NULL\') break;\n        cur.next = new ListNode(parseInt(p.trim(), 10));\n        cur = cur.next;\n    }\n    return dummy.next;\n}\n\nfunction formatList(head) {\n    let sb = \'\';\n    let cur = head;\n    while (cur !== null) {\n        sb += cur.val + \'->\';\n        cur = cur.next;\n    }\n    sb += \'NULL\';\n    return sb;\n}\n\nfunction mergeKLists(lists) {\n    const pq = [];\n    const push = (node) => {\n        pq.push(node);\n        let i = pq.length - 1;\n        while (i > 0) {\n            const p = (i - 1) >> 1;\n            if (pq[p].val <= pq[i].val) break;\n            [pq[p], pq[i]] = [pq[i], pq[p]];\n            i = p;\n        }\n    };\n    const pop = () => {\n        const top = pq[0];\n        const last = pq.pop();\n        if (pq.length > 0) {\n            pq[0] = last;\n            let i = 0;\n            while (true) {\n                let l = i * 2 + 1;\n                let r = i * 2 + 2;\n                let smallest = i;\n                if (l < pq.length && pq[l].val < pq[smallest].val) smallest = l;\n                if (r < pq.length && pq[r].val < pq[smallest].val) smallest = r;\n                if (smallest === i) break;\n                [pq[i], pq[smallest]] = [pq[smallest], pq[i]];\n                i = smallest;\n            }\n        }\n        return top;\n    };\n\n    for (const node of lists) {\n        if (node !== null) push(node);\n    }\n\n    const dummy = new ListNode(0);\n    let cur = dummy;\n    while (pq.length > 0) {\n        const node = pop();\n        cur.next = node;\n        cur = cur.next;\n        if (node.next !== null) push(node.next);\n    }\n    return dummy.next;\n}\n\nconst rl = readline.createInterface({\n    input: process.stdin,\n    output: process.stdout\n});\n\nlet lines = [];\nrl.on(\'line\', (line) => {\n    lines.push(line);\n});\n\nrl.on(\'close\', () => {\n    const k = parseInt(lines[0].trim(), 10);\n    const lists = [];\n    for (let i = 0; i < k; i++) {\n        lists.push(parseList(lines[i + 1].trim()));\n    }\n    const merged = mergeKLists(lists);\n    console.log(formatList(merged));\n});', NULL, 1),
(338, 'PYTHON', 'import sys\nimport heapq\n\nclass ListNode:\n    def __init__(self, val=0):\n        self.val = val\n        self.next = None\n\ndef parse_list(s):\n    if s is None or s == \"\" or s == \"NULL\":\n        return None\n    parts = s.split(\"->\")\n    dummy = ListNode(0)\n    cur = dummy\n    for p in parts:\n        if p == \"NULL\":\n            break\n        cur.next = ListNode(int(p.strip()))\n        cur = cur.next\n    return dummy.next\n\ndef format_list(head):\n    sb = []\n    cur = head\n    while cur is not None:\n        sb.append(str(cur.val))\n        sb.append(\"->\")\n        cur = cur.next\n    sb.append(\"NULL\")\n    return \"\".join(sb)\n\ndef merge_k_lists(lists):\n    heap = []\n    for node in lists:\n        if node is not None:\n            heapq.heappush(heap, (node.val, id(node), node))\n    dummy = ListNode(0)\n    cur = dummy\n    while heap:\n        val, _, node = heapq.heappop(heap)\n        cur.next = node\n        cur = cur.next\n        if node.next is not None:\n            heapq.heappush(heap, (node.next.val, id(node.next), node.next))\n    return dummy.next\n\ndef main():\n    data = sys.stdin.read().splitlines()\n    if not data:\n        return\n    k = int(data[0].strip())\n    lists = []\n    for i in range(1, k + 1):\n        line = data[i].strip() if i < len(data) else \"\"\n        lists.append(parse_list(line))\n    merged = merge_k_lists(lists)\n    print(format_list(merged))\n\nif __name__ == \"__main__\":\n    main()', NULL, 1),
(339, 'C', '#include <stdio.h>\n#include <stdlib.h>\n\nstruct ListNode {\n    int val;\n    struct ListNode *next;\n};\n\nstruct ListNode* merge(struct ListNode* l1, struct ListNode* l2) {\n    struct ListNode dummy;\n    struct ListNode* cur = &dummy;\n    dummy.next = NULL;\n    while (l1 != NULL && l2 != NULL) {\n        if (l1->val <= l2->val) {\n            cur->next = l1;\n            l1 = l1->next;\n        } else {\n            cur->next = l2;\n            l2 = l2->next;\n        }\n        cur = cur->next;\n    }\n    cur->next = (l1 != NULL) ? l1 : l2;\n    return dummy.next;\n}\n\nstruct ListNode* sortList(struct ListNode* head) {\n    if (head == NULL || head->next == NULL) return head;\n    struct ListNode *slow = head, *fast = head->next;\n    while (fast != NULL && fast->next != NULL) {\n        slow = slow->next;\n        fast = fast->next->next;\n    }\n    struct ListNode* mid = slow->next;\n    slow->next = NULL;\n    struct ListNode* left = sortList(head);\n    struct ListNode* right = sortList(mid);\n    return merge(left, right);\n}\n\nint main() {\n    int n;\n    scanf(\"%d\", &n);\n    struct ListNode dummy;\n    dummy.next = NULL;\n    struct ListNode* cur = &dummy;\n    for (int i = 0; i < n; i++) {\n        int x;\n        scanf(\"%d\", &x);\n        struct ListNode* node = (struct ListNode*)malloc(sizeof(struct ListNode));\n        node->val = x;\n        node->next = NULL;\n        cur->next = node;\n        cur = cur->next;\n    }\n    struct ListNode* sorted = sortList(dummy.next);\n    while (sorted != NULL) {\n        printf(\"%d->\", sorted->val);\n        sorted = sorted->next;\n    }\n    printf(\"NULL\\n\");\n    return 0;\n}', NULL, 1),
(339, 'CPP', '#include <iostream>\nusing namespace std;\n\nstruct ListNode {\n    int val;\n    ListNode* next;\n    ListNode(int v) : val(v), next(nullptr) {}\n};\n\nListNode* merge(ListNode* l1, ListNode* l2) {\n    ListNode dummy(0);\n    ListNode* cur = &dummy;\n    while (l1 != nullptr && l2 != nullptr) {\n        if (l1->val <= l2->val) {\n            cur->next = l1;\n            l1 = l1->next;\n        } else {\n            cur->next = l2;\n            l2 = l2->next;\n        }\n        cur = cur->next;\n    }\n    cur->next = (l1 != nullptr) ? l1 : l2;\n    return dummy.next;\n}\n\nListNode* sortList(ListNode* head) {\n    if (head == nullptr || head->next == nullptr) return head;\n    ListNode* slow = head;\n    ListNode* fast = head->next;\n    while (fast != nullptr && fast->next != nullptr) {\n        slow = slow->next;\n        fast = fast->next->next;\n    }\n    ListNode* mid = slow->next;\n    slow->next = nullptr;\n    ListNode* left = sortList(head);\n    ListNode* right = sortList(mid);\n    return merge(left, right);\n}\n\nint main() {\n    int n;\n    cin >> n;\n    ListNode dummy(0);\n    ListNode* cur = &dummy;\n    for (int i = 0; i < n; i++) {\n        int x;\n        cin >> x;\n        cur->next = new ListNode(x);\n        cur = cur->next;\n    }\n    ListNode* sorted = sortList(dummy.next);\n    while (sorted != nullptr) {\n        cout << sorted->val << \"->\";\n        sorted = sorted->next;\n    }\n    cout << \"NULL\" << endl;\n    return 0;\n}', NULL, 1),
(339, 'JAVA', 'import java.util.Scanner;\n\npublic class Main {\n    static class ListNode {\n        int val;\n        ListNode next;\n        ListNode(int val) { this.val = val; }\n    }\n\n    public static void main(String[] args) {\n        Scanner sc = new Scanner(System.in);\n        int n = sc.nextInt();\n        ListNode dummy = new ListNode(0);\n        ListNode cur = dummy;\n        for (int i = 0; i < n; i++) {\n            cur.next = new ListNode(sc.nextInt());\n            cur = cur.next;\n        }\n        ListNode sorted = sortList(dummy.next);\n        StringBuilder sb = new StringBuilder();\n        while (sorted != null) {\n            sb.append(sorted.val).append(\"->\");\n            sorted = sorted.next;\n        }\n        sb.append(\"NULL\");\n        System.out.println(sb.toString());\n    }\n\n    public static ListNode sortList(ListNode head) {\n        if (head == null || head.next == null) return head;\n        ListNode slow = head, fast = head.next;\n        while (fast != null && fast.next != null) {\n            slow = slow.next;\n            fast = fast.next.next;\n        }\n        ListNode mid = slow.next;\n        slow.next = null;\n        ListNode left = sortList(head);\n        ListNode right = sortList(mid);\n        return merge(left, right);\n    }\n\n    private static ListNode merge(ListNode l1, ListNode l2) {\n        ListNode dummy = new ListNode(0);\n        ListNode cur = dummy;\n        while (l1 != null && l2 != null) {\n            if (l1.val <= l2.val) {\n                cur.next = l1;\n                l1 = l1.next;\n            } else {\n                cur.next = l2;\n                l2 = l2.next;\n            }\n            cur = cur.next;\n        }\n        cur.next = (l1 != null) ? l1 : l2;\n        return dummy.next;\n    }\n}', NULL, 1),
(339, 'JAVASCRIPT', 'const readline = require(\'readline\');\n\nclass ListNode {\n    constructor(val) {\n        this.val = val;\n        this.next = null;\n    }\n}\n\nfunction sortList(head) {\n    if (head === null || head.next === null) return head;\n    let slow = head, fast = head.next;\n    while (fast !== null && fast.next !== null) {\n        slow = slow.next;\n        fast = fast.next.next;\n    }\n    let mid = slow.next;\n    slow.next = null;\n    let left = sortList(head);\n    let right = sortList(mid);\n    return merge(left, right);\n}\n\nfunction merge(l1, l2) {\n    let dummy = new ListNode(0);\n    let cur = dummy;\n    while (l1 !== null && l2 !== null) {\n        if (l1.val <= l2.val) {\n            cur.next = l1;\n            l1 = l1.next;\n        } else {\n            cur.next = l2;\n            l2 = l2.next;\n        }\n        cur = cur.next;\n    }\n    cur.next = (l1 !== null) ? l1 : l2;\n    return dummy.next;\n}\n\nconst rl = readline.createInterface({\n    input: process.stdin,\n    output: process.stdout\n});\n\nlet lines = [];\nrl.on(\'line\', (line) => {\n    lines.push(line.trim());\n    if (lines.length === 2) {\n        rl.close();\n        const n = parseInt(lines[0]);\n        const values = lines[1].split(\' \').map(Number);\n        let dummy = new ListNode(0);\n        let cur = dummy;\n        for (let i = 0; i < n; i++) {\n            cur.next = new ListNode(values[i]);\n            cur = cur.next;\n        }\n        let sorted = sortList(dummy.next);\n        let sb = \'\';\n        while (sorted !== null) {\n            sb += sorted.val + \'->\';\n            sorted = sorted.next;\n        }\n        sb += \'NULL\';\n        console.log(sb);\n    }\n});', NULL, 1),
(339, 'PYTHON', 'import sys\n\nclass ListNode:\n    __slots__ = (\'val\', \'next\')\n    def __init__(self, val):\n        self.val = val\n        self.next = None\n\ndef sortList(head):\n    if head is None or head.next is None:\n        return head\n    slow = head\n    fast = head.next\n    while fast is not None and fast.next is not None:\n        slow = slow.next\n        fast = fast.next.next\n    mid = slow.next\n    slow.next = None\n    left = sortList(head)\n    right = sortList(mid)\n    return merge(left, right)\n\ndef merge(l1, l2):\n    dummy = ListNode(0)\n    cur = dummy\n    while l1 is not None and l2 is not None:\n        if l1.val <= l2.val:\n            cur.next = l1\n            l1 = l1.next\n        else:\n            cur.next = l2\n            l2 = l2.next\n        cur = cur.next\n    cur.next = l1 if l1 is not None else l2\n    return dummy.next\n\ndef main():\n    data = sys.stdin.read().split()\n    if not data:\n        return\n    n = int(data[0])\n    dummy = ListNode(0)\n    cur = dummy\n    for i in range(n):\n        cur.next = ListNode(int(data[i + 1]))\n        cur = cur.next\n    sorted_head = sortList(dummy.next)\n    parts = []\n    while sorted_head is not None:\n        parts.append(str(sorted_head.val))\n        sorted_head = sorted_head.next\n    parts.append(\"NULL\")\n    sys.stdout.write(\"->\".join(parts))\n\nif __name__ == \"__main__\":\n    main()', NULL, 1),
(340, 'C', '#include <stdio.h>\n#include <stdlib.h>\n#include <string.h>\n#include <limits.h>\n\nstruct TreeNode {\n    int val;\n    struct TreeNode *left;\n    struct TreeNode *right;\n};\n\nstatic int maxSum;\n\nstruct TreeNode* newNode(int val) {\n    struct TreeNode* node = (struct TreeNode*)malloc(sizeof(struct TreeNode));\n    node->val = val;\n    node->left = NULL;\n    node->right = NULL;\n    return node;\n}\n\nstruct TreeNode* buildTree(char** parts, int n) {\n    if (n == 0 || strcmp(parts[0], \"null\") == 0) return NULL;\n    struct TreeNode* root = newNode(atoi(parts[0]));\n    struct TreeNode** queue = (struct TreeNode**)malloc(sizeof(struct TreeNode*) * n);\n    int front = 0, rear = 0;\n    queue[rear++] = root;\n    int i = 1;\n    while (front < rear && i < n) {\n        struct TreeNode* node = queue[front++];\n        if (i < n && strcmp(parts[i], \"null\") != 0) {\n            node->left = newNode(atoi(parts[i]));\n            queue[rear++] = node->left;\n        }\n        i++;\n        if (i < n && strcmp(parts[i], \"null\") != 0) {\n            node->right = newNode(atoi(parts[i]));\n            queue[rear++] = node->right;\n        }\n        i++;\n    }\n    free(queue);\n    return root;\n}\n\nint dfs(struct TreeNode* node) {\n    if (node == NULL) return 0;\n    int left = dfs(node->left);\n    if (left < 0) left = 0;\n    int right = dfs(node->right);\n    if (right < 0) right = 0;\n    int cur = node->val + left + right;\n    if (cur > maxSum) maxSum = cur;\n    int ret = node->val + (left > right ? left : right);\n    return ret;\n}\n\nint main() {\n    char line[100000];\n    if (fgets(line, sizeof(line), stdin) == NULL) return 0;\n    int len = strlen(line);\n    while (len > 0 && (line[len-1] == \'\\n\' || line[len-1] == \'\\r\')) {\n        line[--len] = \'\\0\';\n    }\n    char* s = line;\n    while (*s == \' \' || *s == \'\\t\') s++;\n    if (*s == \'[\') s++;\n    int end = strlen(s) - 1;\n    while (end >= 0 && (s[end] == \' \' || s[end] == \'\\t\')) end--;\n    if (end >= 0 && s[end] == \']\') s[end] = \'\\0\';\n\n    int isEmpty = 1;\n    for (int i = 0; s[i]; i++) {\n        if (s[i] != \' \' && s[i] != \'\\t\') { isEmpty = 0; break; }\n    }\n    if (isEmpty) {\n        printf(\"0\\n\");\n        return 0;\n    }\n\n    char* parts[100000];\n    int n = 0;\n    char* token = strtok(s, \",\");\n    while (token != NULL) {\n        while (*token == \' \' || *token == \'\\t\') token++;\n        int tl = strlen(token);\n        while (tl > 0 && (token[tl-1] == \' \' || token[tl-1] == \'\\t\')) token[--tl] = \'\\0\';\n        parts[n++] = token;\n        token = strtok(NULL, \",\");\n    }\n\n    struct TreeNode* root = buildTree(parts, n);\n    maxSum = INT_MIN;\n    dfs(root);\n    printf(\"%d\\n\", maxSum);\n    return 0;\n}', NULL, 1),
(340, 'CPP', '#include <iostream>\n#include <string>\n#include <vector>\n#include <queue>\n#include <sstream>\n#include <climits>\n#include <algorithm>\n\nusing namespace std;\n\nstruct TreeNode {\n    int val;\n    TreeNode *left;\n    TreeNode *right;\n    TreeNode(int x) : val(x), left(nullptr), right(nullptr) {}\n};\n\nint maxSum = INT_MIN;\n\nTreeNode* buildTree(const vector<string>& parts) {\n    if (parts.empty() || parts[0] == \"null\") return nullptr;\n    TreeNode* root = new TreeNode(stoi(parts[0]));\n    queue<TreeNode*> q;\n    q.push(root);\n    int i = 1;\n    while (!q.empty() && i < (int)parts.size()) {\n        TreeNode* node = q.front();\n        q.pop();\n        if (i < (int)parts.size() && parts[i] != \"null\") {\n            node->left = new TreeNode(stoi(parts[i]));\n            q.push(node->left);\n        }\n        i++;\n        if (i < (int)parts.size() && parts[i] != \"null\") {\n            node->right = new TreeNode(stoi(parts[i]));\n            q.push(node->right);\n        }\n        i++;\n    }\n    return root;\n}\n\nint dfs(TreeNode* node) {\n    if (node == nullptr) return 0;\n    int left = max(0, dfs(node->left));\n    int right = max(0, dfs(node->right));\n    maxSum = max(maxSum, node->val + left + right);\n    return node->val + max(left, right);\n}\n\nint main() {\n    string line;\n    getline(cin, line);\n    if (!line.empty() && line.front() == \'[\') line.erase(0, 1);\n    if (!line.empty() && line.back() == \']\') line.pop_back();\n\n    if (line.find_first_not_of(\" \\t\\r\\n\") == string::npos) {\n        cout << 0 << endl;\n        return 0;\n    }\n\n    vector<string> parts;\n    stringstream ss(line);\n    string token;\n    while (getline(ss, token, \',\')) {\n        size_t start = token.find_first_not_of(\" \\t\\r\\n\");\n        size_t end = token.find_last_not_of(\" \\t\\r\\n\");\n        if (start == string::npos) {\n            parts.push_back(\"\");\n        } else {\n            parts.push_back(token.substr(start, end - start + 1));\n        }\n    }\n\n    TreeNode* root = buildTree(parts);\n    maxSum = INT_MIN;\n    dfs(root);\n    cout << maxSum << endl;\n\n    return 0;\n}', NULL, 1),
(340, 'JAVA', 'import java.util.*;\n\npublic class Main {\n    static class TreeNode {\n        int val;\n        TreeNode left;\n        TreeNode right;\n        TreeNode(int x) { val = x; }\n    }\n\n    static int maxSum = Integer.MIN_VALUE;\n\n    public static void main(String[] args) {\n        Scanner sc = new Scanner(System.in);\n        String line = sc.nextLine().trim();\n        if (line.startsWith(\"[\")) line = line.substring(1);\n        if (line.endsWith(\"]\")) line = line.substring(0, line.length() - 1);\n\n        if (line.trim().isEmpty()) {\n            System.out.println(0);\n            return;\n        }\n\n        String[] parts = line.split(\",\");\n        TreeNode root = buildTree(parts);\n        maxPathSum(root);\n        System.out.println(maxSum);\n    }\n\n    static TreeNode buildTree(String[] parts) {\n        if (parts.length == 0 || parts[0].trim().equals(\"null\")) return null;\n        TreeNode root = new TreeNode(Integer.parseInt(parts[0].trim()));\n        Queue<TreeNode> queue = new LinkedList<>();\n        queue.offer(root);\n        int i = 1;\n        while (!queue.isEmpty() && i < parts.length) {\n            TreeNode node = queue.poll();\n            if (i < parts.length && !parts[i].trim().equals(\"null\")) {\n                node.left = new TreeNode(Integer.parseInt(parts[i].trim()));\n                queue.offer(node.left);\n            }\n            i++;\n            if (i < parts.length && !parts[i].trim().equals(\"null\")) {\n                node.right = new TreeNode(Integer.parseInt(parts[i].trim()));\n                queue.offer(node.right);\n            }\n            i++;\n        }\n        return root;\n    }\n\n    static int maxPathSum(TreeNode root) {\n        maxSum = Integer.MIN_VALUE;\n        dfs(root);\n        return maxSum;\n    }\n\n    static int dfs(TreeNode node) {\n        if (node == null) return 0;\n        int left = Math.max(0, dfs(node.left));\n        int right = Math.max(0, dfs(node.right));\n        maxSum = Math.max(maxSum, node.val + left + right);\n        return node.val + Math.max(left, right);\n    }\n}', NULL, 1),
(340, 'JAVASCRIPT', 'const readline = require(\'readline\');\n\nconst rl = readline.createInterface({\n    input: process.stdin,\n    output: process.stdout\n});\n\nclass TreeNode {\n    constructor(val) {\n        this.val = val;\n        this.left = null;\n        this.right = null;\n    }\n}\n\nlet maxSum = -Infinity;\n\nfunction buildTree(parts) {\n    if (parts.length === 0 || parts[0].trim() === \'null\') return null;\n    const root = new TreeNode(parseInt(parts[0].trim()));\n    const queue = [root];\n    let i = 1;\n    while (queue.length > 0 && i < parts.length) {\n        const node = queue.shift();\n        if (i < parts.length && parts[i].trim() !== \'null\') {\n            node.left = new TreeNode(parseInt(parts[i].trim()));\n            queue.push(node.left);\n        }\n        i++;\n        if (i < parts.length && parts[i].trim() !== \'null\') {\n            node.right = new TreeNode(parseInt(parts[i].trim()));\n            queue.push(node.right);\n        }\n        i++;\n    }\n    return root;\n}\n\nfunction dfs(node) {\n    if (node === null) return 0;\n    const left = Math.max(0, dfs(node.left));\n    const right = Math.max(0, dfs(node.right));\n    maxSum = Math.max(maxSum, node.val + left + right);\n    return node.val + Math.max(left, right);\n}\n\nfunction maxPathSum(root) {\n    maxSum = -Infinity;\n    dfs(root);\n    return maxSum;\n}\n\nrl.on(\'line\', (line) => {\n    line = line.trim();\n    if (line.startsWith(\'[\')) line = line.substring(1);\n    if (line.endsWith(\']\')) line = line.substring(0, line.length - 1);\n\n    if (line.trim() === \'\') {\n        console.log(0);\n        rl.close();\n        return;\n    }\n\n    const parts = line.split(\',\');\n    const root = buildTree(parts);\n    maxPathSum(root);\n    console.log(maxSum);\n    rl.close();\n});', NULL, 1),
(340, 'PYTHON', 'import sys\nfrom collections import deque\n\nclass TreeNode:\n    def __init__(self, val=0):\n        self.val = val\n        self.left = None\n        self.right = None\n\ndef build_tree(parts):\n    if not parts or parts[0].strip() == \"null\":\n        return None\n    root = TreeNode(int(parts[0].strip()))\n    queue = deque([root])\n    i = 1\n    while queue and i < len(parts):\n        node = queue.popleft()\n        if i < len(parts) and parts[i].strip() != \"null\":\n            node.left = TreeNode(int(parts[i].strip()))\n            queue.append(node.left)\n        i += 1\n        if i < len(parts) and parts[i].strip() != \"null\":\n            node.right = TreeNode(int(parts[i].strip()))\n            queue.append(node.right)\n        i += 1\n    return root\n\ndef main():\n    line = sys.stdin.readline().strip()\n    if line.startswith(\"[\"):\n        line = line[1:]\n    if line.endswith(\"]\"):\n        line = line[:-1]\n    if line.strip() == \"\":\n        print(0)\n        return\n    parts = line.split(\",\")\n    root = build_tree(parts)\n    max_sum = float(\"-inf\")\n    def dfs(node):\n        nonlocal max_sum\n        if node is None:\n            return 0\n        left = max(0, dfs(node.left))\n        right = max(0, dfs(node.right))\n        max_sum = max(max_sum, node.val + left + right)\n        return node.val + max(left, right)\n    dfs(root)\n    print(max_sum)\n\nif __name__ == \"__main__\":\n    main()', NULL, 1),
(341, 'C', '#include <stdio.h>\n#include <stdlib.h>\n#include <string.h>\n#include <ctype.h>\n\ntypedef struct TreeNode {\n    int val;\n    struct TreeNode *left;\n    struct TreeNode *right;\n} TreeNode;\n\ntypedef struct {\n    TreeNode **data;\n    int front;\n    int rear;\n    int size;\n    int capacity;\n} Queue;\n\nQueue* createQueue(int capacity) {\n    Queue *q = (Queue*)malloc(sizeof(Queue));\n    q->data = (TreeNode**)malloc(sizeof(TreeNode*) * capacity);\n    q->front = 0;\n    q->rear = 0;\n    q->size = 0;\n    q->capacity = capacity;\n    return q;\n}\n\nvoid enqueue(Queue *q, TreeNode *node) {\n    if (q->size == q->capacity) {\n        q->capacity *= 2;\n        q->data = (TreeNode**)realloc(q->data, sizeof(TreeNode*) * q->capacity);\n    }\n    q->data[q->rear] = node;\n    q->rear = (q->rear + 1) % q->capacity;\n    q->size++;\n}\n\nTreeNode* dequeue(Queue *q) {\n    if (q->size == 0) return NULL;\n    TreeNode *node = q->data[q->front];\n    q->front = (q->front + 1) % q->capacity;\n    q->size--;\n    return node;\n}\n\nint isEmpty(Queue *q) {\n    return q->size == 0;\n}\n\nvoid freeQueue(Queue *q) {\n    free(q->data);\n    free(q);\n}\n\nTreeNode* buildTree(char **parts, int partsSize) {\n    if (partsSize == 0 || strcmp(parts[0], \"null\") == 0) return NULL;\n    TreeNode *root = (TreeNode*)malloc(sizeof(TreeNode));\n    root->val = atoi(parts[0]);\n    root->left = NULL;\n    root->right = NULL;\n    \n    Queue *q = createQueue(partsSize);\n    enqueue(q, root);\n    int i = 1;\n    while (!isEmpty(q) && i < partsSize) {\n        TreeNode *node = dequeue(q);\n        if (i < partsSize) {\n            char *leftVal = parts[i++];\n            if (strcmp(leftVal, \"null\") != 0) {\n                node->left = (TreeNode*)malloc(sizeof(TreeNode));\n                node->left->val = atoi(leftVal);\n                node->left->left = NULL;\n                node->left->right = NULL;\n                enqueue(q, node->left);\n            }\n        }\n        if (i < partsSize) {\n            char *rightVal = parts[i++];\n            if (strcmp(rightVal, \"null\") != 0) {\n                node->right = (TreeNode*)malloc(sizeof(TreeNode));\n                node->right->val = atoi(rightVal);\n                node->right->left = NULL;\n                node->right->right = NULL;\n                enqueue(q, node->right);\n            }\n        }\n    }\n    freeQueue(q);\n    return root;\n}\n\nint** zigzagLevelOrder(TreeNode *root, int *returnSize, int **returnColumnSizes) {\n    if (root == NULL) {\n        *returnSize = 0;\n        return NULL;\n    }\n    \n    int capacity = 100;\n    int **result = (int**)malloc(sizeof(int*) * capacity);\n    *returnColumnSizes = (int*)malloc(sizeof(int) * capacity);\n    *returnSize = 0;\n    \n    Queue *q = createQueue(1000);\n    enqueue(q, root);\n    int leftToRight = 1;\n    \n    while (!isEmpty(q)) {\n        int size = q->size;\n        int *level = (int*)malloc(sizeof(int) * size);\n        int idx = 0;\n        \n        for (int i = 0; i < size; i++) {\n            TreeNode *node = dequeue(q);\n            if (leftToRight) {\n                level[idx++] = node->val;\n            } else {\n                level[size - 1 - idx++] = node->val;\n            }\n            if (node->left) enqueue(q, node->left);\n            if (node->right) enqueue(q, node->right);\n        }\n        \n        if (*returnSize >= capacity) {\n            capacity *= 2;\n            result = (int**)realloc(result, sizeof(int*) * capacity);\n            *returnColumnSizes = (int*)realloc(*returnColumnSizes, sizeof(int) * capacity);\n        }\n        result[*returnSize] = level;\n        (*returnColumnSizes)[*returnSize] = size;\n        (*returnSize)++;\n        leftToRight = !leftToRight;\n    }\n    \n    freeQueue(q);\n    return result;\n}\n\nvoid freeTree(TreeNode *root) {\n    if (root == NULL) return;\n    freeTree(root->left);\n    freeTree(root->right);\n    free(root);\n}\n\nint main() {\n    char line[100000];\n    if (fgets(line, sizeof(line), stdin) == NULL) return 0;\n    \n    int len = strlen(line);\n    while (len > 0 && (line[len-1] == \'\\n\' || line[len-1] == \'\\r\')) {\n        line[--len] = \'\\0\';\n    }\n    \n    char *start = line;\n    while (*start && isspace(*start)) start++;\n    char *end = start + strlen(start) - 1;\n    while (end > start && isspace(*end)) end--;\n    *(end + 1) = \'\\0\';\n    \n    if (*start == \'[\') start++;\n    end = start + strlen(start) - 1;\n    if (*end == \']\') *end = \'\\0\';\n    \n    if (strlen(start) == 0) {\n        printf(\"[]\\n\");\n        return 0;\n    }\n    \n    char *parts[10000];\n    int partsSize = 0;\n    char *token = strtok(start, \",\");\n    while (token != NULL) {\n        while (*token && isspace(*token)) token++;\n        char *tend = token + strlen(token) - 1;\n        while (tend > token && isspace(*tend)) *tend-- = \'\\0\';\n        parts[partsSize++] = token;\n        token = strtok(NULL, \",\");\n    }\n    \n    TreeNode *root = buildTree(parts, partsSize);\n    \n    int returnSize;\n    int *returnColumnSizes;\n    int **result = zigzagLevelOrder(root, &returnSize, &returnColumnSizes);\n    \n    printf(\"[\");\n    for (int i = 0; i < returnSize; i++) {\n        printf(\"[\");\n        for (int j = 0; j < returnColumnSizes[i]; j++) {\n            printf(\"%d\", result[i][j]);\n            if (j < returnColumnSizes[i] - 1) printf(\",\");\n        }\n        printf(\"]\");\n        if (i < returnSize - 1) printf(\",\");\n    }\n    printf(\"]\\n\");\n    \n    for (int i = 0; i < returnSize; i++) {\n        free(result[i]);\n    }\n    free(result);\n    free(returnColumnSizes);\n    freeTree(root);\n    \n    return 0;\n}', NULL, 1),
(341, 'CPP', '#include <iostream>\n#include <string>\n#include <vector>\n#include <queue>\n#include <sstream>\n#include <algorithm>\n\nusing namespace std;\n\nstruct TreeNode {\n    int val;\n    TreeNode *left;\n    TreeNode *right;\n    TreeNode(int x) : val(x), left(nullptr), right(nullptr) {}\n};\n\nTreeNode* buildTree(const vector<string>& parts) {\n    if (parts.empty() || parts[0] == \"null\") return nullptr;\n    TreeNode* root = new TreeNode(stoi(parts[0]));\n    queue<TreeNode*> q;\n    q.push(root);\n    int i = 1;\n    while (!q.empty() && i < (int)parts.size()) {\n        TreeNode* node = q.front();\n        q.pop();\n        if (i < (int)parts.size()) {\n            string leftVal = parts[i++];\n            if (leftVal != \"null\") {\n                node->left = new TreeNode(stoi(leftVal));\n                q.push(node->left);\n            }\n        }\n        if (i < (int)parts.size()) {\n            string rightVal = parts[i++];\n            if (rightVal != \"null\") {\n                node->right = new TreeNode(stoi(rightVal));\n                q.push(node->right);\n            }\n        }\n    }\n    return root;\n}\n\nvector<vector<int>> zigzagLevelOrder(TreeNode* root) {\n    vector<vector<int>> result;\n    if (!root) return result;\n    queue<TreeNode*> q;\n    q.push(root);\n    bool leftToRight = true;\n    while (!q.empty()) {\n        int size = q.size();\n        vector<int> level(size);\n        for (int i = 0; i < size; i++) {\n            TreeNode* node = q.front();\n            q.pop();\n            int index = leftToRight ? i : (size - 1 - i);\n            level[index] = node->val;\n            if (node->left) q.push(node->left);\n            if (node->right) q.push(node->right);\n        }\n        result.push_back(level);\n        leftToRight = !leftToRight;\n    }\n    return result;\n}\n\nstring format(const vector<vector<int>>& result) {\n    string sb = \"[\";\n    for (int i = 0; i < (int)result.size(); i++) {\n        sb += \"[\";\n        const vector<int>& level = result[i];\n        for (int j = 0; j < (int)level.size(); j++) {\n            sb += to_string(level[j]);\n            if (j < (int)level.size() - 1) sb += \",\";\n        }\n        sb += \"]\";\n        if (i < (int)result.size() - 1) sb += \",\";\n    }\n    sb += \"]\";\n    return sb;\n}\n\nint main() {\n    string line;\n    getline(cin, line);\n    while (!line.empty() && (line.back() == \'\\r\' || line.back() == \'\\n\' || line.back() == \' \')) {\n        line.pop_back();\n    }\n    size_t start = line.find_first_not_of(\" \\t\");\n    if (start != string::npos) line = line.substr(start);\n    if (!line.empty() && line.front() == \'[\') line = line.substr(1);\n    if (!line.empty() && line.back() == \']\') line.pop_back();\n    if (line.empty()) {\n        cout << \"[]\" << endl;\n        return 0;\n    }\n    vector<string> parts;\n    stringstream ss(line);\n    string token;\n    while (getline(ss, token, \',\')) {\n        size_t s = token.find_first_not_of(\" \\t\");\n        size_t e = token.find_last_not_of(\" \\t\");\n        if (s == string::npos) {\n            parts.push_back(\"\");\n        } else {\n            parts.push_back(token.substr(s, e - s + 1));\n        }\n    }\n    TreeNode* root = buildTree(parts);\n    vector<vector<int>> result = zigzagLevelOrder(root);\n    cout << format(result) << endl;\n    return 0;\n}', NULL, 1),
(341, 'JAVA', 'import java.util.*;\n\npublic class Main {\n    static class TreeNode {\n        int val;\n        TreeNode left;\n        TreeNode right;\n        TreeNode(int x) { val = x; }\n    }\n\n    public static void main(String[] args) {\n        Scanner sc = new Scanner(System.in);\n        String line = sc.nextLine().trim();\n        if (line.startsWith(\"[\")) line = line.substring(1);\n        if (line.endsWith(\"]\")) line = line.substring(0, line.length() - 1);\n        if (line.isEmpty()) {\n            System.out.println(\"[]\");\n            return;\n        }\n        String[] parts = line.split(\",\");\n        TreeNode root = buildTree(parts);\n        List<List<Integer>> result = zigzagLevelOrder(root);\n        System.out.println(format(result));\n    }\n\n    private static TreeNode buildTree(String[] parts) {\n        if (parts.length == 0 || parts[0].trim().equals(\"null\")) return null;\n        TreeNode root = new TreeNode(Integer.parseInt(parts[0].trim()));\n        Queue<TreeNode> queue = new LinkedList<>();\n        queue.offer(root);\n        int i = 1;\n        while (!queue.isEmpty() && i < parts.length) {\n            TreeNode node = queue.poll();\n            if (i < parts.length) {\n                String leftVal = parts[i++].trim();\n                if (!leftVal.equals(\"null\")) {\n                    node.left = new TreeNode(Integer.parseInt(leftVal));\n                    queue.offer(node.left);\n                }\n            }\n            if (i < parts.length) {\n                String rightVal = parts[i++].trim();\n                if (!rightVal.equals(\"null\")) {\n                    node.right = new TreeNode(Integer.parseInt(rightVal));\n                    queue.offer(node.right);\n                }\n            }\n        }\n        return root;\n    }\n\n    private static List<List<Integer>> zigzagLevelOrder(TreeNode root) {\n        List<List<Integer>> result = new ArrayList<>();\n        if (root == null) return result;\n        Queue<TreeNode> queue = new LinkedList<>();\n        queue.offer(root);\n        boolean leftToRight = true;\n        while (!queue.isEmpty()) {\n            int size = queue.size();\n            LinkedList<Integer> level = new LinkedList<>();\n            for (int i = 0; i < size; i++) {\n                TreeNode node = queue.poll();\n                if (leftToRight) {\n                    level.addLast(node.val);\n                } else {\n                    level.addFirst(node.val);\n                }\n                if (node.left != null) queue.offer(node.left);\n                if (node.right != null) queue.offer(node.right);\n            }\n            result.add(level);\n            leftToRight = !leftToRight;\n        }\n        return result;\n    }\n\n    private static String format(List<List<Integer>> result) {\n        StringBuilder sb = new StringBuilder();\n        sb.append(\"[\");\n        for (int i = 0; i < result.size(); i++) {\n            sb.append(\"[\");\n            List<Integer> level = result.get(i);\n            for (int j = 0; j < level.size(); j++) {\n                sb.append(level.get(j));\n                if (j < level.size() - 1) sb.append(\",\");\n            }\n            sb.append(\"]\");\n            if (i < result.size() - 1) sb.append(\",\");\n        }\n        sb.append(\"]\");\n        return sb.toString();\n    }\n}', NULL, 1),
