f (j < level.length - 1) sb += \',\';\n        }\n        sb += \']\';\n        if (i < result.length - 1) sb += \',\';\n    }\n    sb += \']\';\n    return sb;\n}\n\nconst rl = readline.createInterface({\n    input: process.stdin,\n    output: process.stdout\n});\n\nrl.on(\'line\', (line) => {\n    line = line.trim();\n    if (line.startsWith(\'[\')) line = line.substring(1);\n    if (line.endsWith(\']\')) line = line.substring(0, line.length - 1);\n    if (line.length === 0) {\n        console.log(\'[]\');\n        rl.close();\n        return;\n    }\n    const parts = line.split(\',\');\n    const root = buildTree(parts);\n    const result = zigzagLevelOrder(root);\n    console.log(format(result));\n    rl.close();\n});', NULL, 1),
(341, 'PYTHON', 'import sys\nfrom collections import deque\n\nclass TreeNode:\n    def __init__(self, x):\n        self.val = x\n        self.left = None\n        self.right = None\n\ndef build_tree(parts):\n    if not parts or parts[0].strip() == \"null\":\n        return None\n    root = TreeNode(int(parts[0].strip()))\n    queue = deque([root])\n    i = 1\n    while queue and i < len(parts):\n        node = queue.popleft()\n        if i < len(parts):\n            left_val = parts[i].strip()\n            i += 1\n            if left_val != \"null\":\n                node.left = TreeNode(int(left_val))\n                queue.append(node.left)\n        if i < len(parts):\n            right_val = parts[i].strip()\n            i += 1\n            if right_val != \"null\":\n                node.right = TreeNode(int(right_val))\n                queue.append(node.right)\n    return root\n\ndef zigzag_level_order(root):\n    result = []\n    if root is None:\n        return result\n    queue = deque([root])\n    left_to_right = True\n    while queue:\n        size = len(queue)\n        level = deque()\n        for _ in range(size):\n            node = queue.popleft()\n            if left_to_right:\n                level.append(node.val)\n            else:\n                level.appendleft(node.val)\n            if node.left:\n                queue.append(node.left)\n            if node.right:\n                queue.append(node.right)\n        result.append(list(level))\n        left_to_right = not left_to_right\n    return result\n\ndef format_result(result):\n    sb = []\n    sb.append(\"[\")\n    for i, level in enumerate(result):\n        sb.append(\"[\")\n        for j, val in enumerate(level):\n            sb.append(str(val))\n            if j < len(level) - 1:\n                sb.append(\",\")\n        sb.append(\"]\")\n        if i < len(result) - 1:\n            sb.append(\",\")\n    sb.append(\"]\")\n    return \"\".join(sb)\n\ndef main():\n    line = sys.stdin.readline().strip()\n    if line.startswith(\"[\"):\n        line = line[1:]\n    if line.endswith(\"]\"):\n        line = line[:-1]\n    if not line:\n        print(\"[]\")\n        return\n    parts = line.split(\",\")\n    root = build_tree(parts)\n    result = zigzag_level_order(root)\n    print(format_result(result))\n\nif __name__ == \"__main__\":\n    main()', NULL, 1),
(342, 'C', '#include <stdio.h>\n#include <stdlib.h>\n#include <string.h>\n#include <ctype.h>\n\ntypedef struct TreeNode {\n    int val;\n    struct TreeNode *left;\n    struct TreeNode *right;\n} TreeNode;\n\nstatic TreeNode* newTreeNode(int val) {\n    TreeNode* node = (TreeNode*)malloc(sizeof(TreeNode));\n    node->val = val;\n    node->left = NULL;\n    node->right = NULL;\n    return node;\n}\n\nstatic char* trim(char* s) {\n    while (*s && isspace((unsigned char)*s)) s++;\n    if (*s == \'\\0\') return s;\n    char* end = s + strlen(s) - 1;\n    while (end > s && isspace((unsigned char)*end)) {\n        *end = \'\\0\';\n        end--;\n    }\n    return s;\n}\n\nstatic TreeNode* buildTree(char* line) {\n    if (line == NULL) return NULL;\n    line = trim(line);\n    if (*line == \'\\0\') return NULL;\n\n    if (line[0] == \'[\') line++;\n    size_t len = strlen(line);\n    if (len > 0 && line[len - 1] == \']\') line[len - 1] = \'\\0\';\n    line = trim(line);\n    if (*line == \'\\0\') return NULL;\n\n    char* parts[10000];\n    int count = 0;\n    char* token = strtok(line, \",\");\n    while (token != NULL && count < 10000) {\n        parts[count++] = trim(token);\n        token = strtok(NULL, \",\");\n    }\n\n    if (count == 0 || strcmp(parts[0], \"null\") == 0) return NULL;\n\n    TreeNode* root = newTreeNode(atoi(parts[0]));\n    TreeNode* queue[10000];\n    int front = 0, rear = 0;\n    queue[rear++] = root;\n    int i = 1;\n\n    while (front < rear && i < count) {\n        TreeNode* cur = queue[front++];\n\n        if (i < count) {\n            char* leftVal = parts[i++];\n            if (strcmp(leftVal, \"null\") != 0) {\n                cur->left = newTreeNode(atoi(leftVal));\n                queue[rear++] = cur->left;\n            }\n        }\n\n        if (i < count) {\n            char* rightVal = parts[i++];\n            if (strcmp(rightVal, \"null\") != 0) {\n                cur->right = newTreeNode(atoi(rightVal));\n                queue[rear++] = cur->right;\n            }\n        }\n    }\n\n    return root;\n}\n\nstatic int kthSmallest(TreeNode* root, int k) {\n    TreeNode* stack[10000];\n    int top = 0;\n    TreeNode* cur = root;\n\n    while (cur != NULL || top > 0) {\n        while (cur != NULL) {\n            stack[top++] = cur;\n            cur = cur->left;\n        }\n        cur = stack[--top];\n        k--;\n        if (k == 0) return cur->val;\n        cur = cur->right;\n    }\n\n    return -1;\n}\n\nint main(void) {\n    char line[100000];\n    int k;\n\n    if (fgets(line, sizeof(line), stdin) == NULL) return 0;\n    line[strcspn(line, \"\\r\\n\")] = \'\\0\';\n\n    if (scanf(\"%d\", &k) != 1) return 0;\n\n    TreeNode* root = buildTree(line);\n    printf(\"%d\\n\", kthSmallest(root, k));\n\n    return 0;\n}', NULL, 1),
(342, 'CPP', '#include <iostream>\n#include <string>\n#include <sstream>\n#include <vector>\n#include <queue>\n#include <stack>\n\nusing namespace std;\n\nstruct TreeNode {\n    int val;\n    TreeNode* left;\n    TreeNode* right;\n    TreeNode(int v) : val(v), left(nullptr), right(nullptr) {}\n};\n\nTreeNode* buildTree(const string& line) {\n    if (line.empty()) return nullptr;\n    string s = line;\n    size_t start = s.find_first_not_of(\" \\t\");\n    size_t end = s.find_last_not_of(\" \\t\");\n    if (start == string::npos) return nullptr;\n    s = s.substr(start, end - start + 1);\n    if (s.front() == \'[\') s = s.substr(1);\n    if (s.back() == \']\') s.pop_back();\n    if (s.empty()) return nullptr;\n\n    vector<string> parts;\n    stringstream ss(s);\n    string token;\n    while (getline(ss, token, \',\')) {\n        size_t l = token.find_first_not_of(\" \\t\");\n        size_t r = token.find_last_not_of(\" \\t\");\n        if (l == string::npos) parts.push_back(\"\");\n        else parts.push_back(token.substr(l, r - l + 1));\n    }\n\n    if (parts.empty() || parts[0] == \"null\") return nullptr;\n\n    TreeNode* root = new TreeNode(stoi(parts[0]));\n    queue<TreeNode*> q;\n    q.push(root);\n    int i = 1;\n\n    while (!q.empty() && i < (int)parts.size()) {\n        TreeNode* cur = q.front();\n        q.pop();\n\n        if (i < (int)parts.size()) {\n            string leftVal = parts[i++];\n            if (leftVal != \"null\") {\n                cur->left = new TreeNode(stoi(leftVal));\n                q.push(cur->left);\n            }\n        }\n\n        if (i < (int)parts.size()) {\n            string rightVal = parts[i++];\n            if (rightVal != \"null\") {\n                cur->right = new TreeNode(stoi(rightVal));\n                q.push(cur->right);\n            }\n        }\n    }\n\n    return root;\n}\n\nint kthSmallest(TreeNode* root, int k) {\n    stack<TreeNode*> st;\n    TreeNode* cur = root;\n\n    while (cur != nullptr || !st.empty()) {\n        while (cur != nullptr) {\n            st.push(cur);\n            cur = cur->left;\n        }\n        cur = st.top();\n        st.pop();\n        k--;\n        if (k == 0) return cur->val;\n        cur = cur->right;\n    }\n\n    return -1;\n}\n\nint main() {\n    string line;\n    getline(cin, line);\n    int k;\n    cin >> k;\n\n    TreeNode* root = buildTree(line);\n    cout << kthSmallest(root, k) << endl;\n\n    return 0;\n}', NULL, 1),
(342, 'JAVA', 'import java.util.*;\n\npublic class Main {\n    static class TreeNode {\n        int val;\n        TreeNode left;\n        TreeNode right;\n        TreeNode(int val) { this.val = val; }\n    }\n\n    public static void main(String[] args) {\n        Scanner sc = new Scanner(System.in);\n        String line = sc.nextLine().trim();\n        int k = Integer.parseInt(sc.nextLine().trim());\n\n        TreeNode root = buildTree(line);\n        System.out.println(kthSmallest(root, k));\n    }\n\n    private static TreeNode buildTree(String line) {\n        if (line == null || line.length() == 0) return null;\n        line = line.trim();\n        if (line.startsWith(\"[\")) line = line.substring(1);\n        if (line.endsWith(\"]\")) line = line.substring(0, line.length() - 1);\n        if (line.trim().isEmpty()) return null;\n\n        String[] parts = line.split(\",\");\n        if (parts.length == 0 || parts[0].trim().equals(\"null\")) return null;\n\n        TreeNode root = new TreeNode(Integer.parseInt(parts[0].trim()));\n        Queue<TreeNode> queue = new LinkedList<>();\n        queue.offer(root);\n        int i = 1;\n\n        while (!queue.isEmpty() && i < parts.length) {\n            TreeNode cur = queue.poll();\n\n            if (i < parts.length) {\n                String leftVal = parts[i].trim();\n                i++;\n                if (!leftVal.equals(\"null\")) {\n                    cur.left = new TreeNode(Integer.parseInt(leftVal));\n                    queue.offer(cur.left);\n                }\n            }\n\n            if (i < parts.length) {\n                String rightVal = parts[i].trim();\n                i++;\n                if (!rightVal.equals(\"null\")) {\n                    cur.right = new TreeNode(Integer.parseInt(rightVal));\n                    queue.offer(cur.right);\n                }\n            }\n        }\n\n        return root;\n    }\n\n    private static int kthSmallest(TreeNode root, int k) {\n        Deque<TreeNode> stack = new ArrayDeque<>();\n        TreeNode cur = root;\n\n        while (cur != null || !stack.isEmpty()) {\n            while (cur != null) {\n                stack.push(cur);\n                cur = cur.left;\n            }\n            cur = stack.pop();\n            k--;\n            if (k == 0) return cur.val;\n            cur = cur.right;\n        }\n\n        return -1;\n    }\n}', NULL, 1),
(342, 'JAVASCRIPT', 'const readline = require(\'readline\');\n\nclass TreeNode {\n    constructor(val) {\n        this.val = val;\n        this.left = null;\n        this.right = null;\n    }\n}\n\nfunction buildTree(line) {\n    if (line === null || line.length === 0) return null;\n    line = line.trim();\n    if (line.startsWith(\'[\')) line = line.substring(1);\n    if (line.endsWith(\']\')) line = line.substring(0, line.length - 1);\n    if (line.trim().length === 0) return null;\n\n    const parts = line.split(\',\');\n    if (parts.length === 0 || parts[0].trim() === \'null\') return null;\n\n    const root = new TreeNode(parseInt(parts[0].trim()));\n    const queue = [root];\n    let i = 1;\n\n    while (queue.length > 0 && i < parts.length) {\n        const cur = queue.shift();\n\n        if (i < parts.length) {\n            const leftVal = parts[i].trim();\n            i++;\n            if (leftVal !== \'null\') {\n                cur.left = new TreeNode(parseInt(leftVal));\n                queue.push(cur.left);\n            }\n        }\n\n        if (i < parts.length) {\n            const rightVal = parts[i].trim();\n            i++;\n            if (rightVal !== \'null\') {\n                cur.right = new TreeNode(parseInt(rightVal));\n                queue.push(cur.right);\n            }\n        }\n    }\n\n    return root;\n}\n\nfunction kthSmallest(root, k) {\n    const stack = [];\n    let cur = root;\n\n    while (cur !== null || stack.length > 0) {\n        while (cur !== null) {\n            stack.push(cur);\n            cur = cur.left;\n        }\n        cur = stack.pop();\n        k--;\n        if (k === 0) return cur.val;\n        cur = cur.right;\n    }\n\n    return -1;\n}\n\nconst rl = readline.createInterface({\n    input: process.stdin,\n    output: process.stdout\n});\n\nlet lines = [];\nrl.on(\'line\', (line) => {\n    lines.push(line);\n    if (lines.length === 2) {\n        const treeLine = lines[0].trim();\n        const k = parseInt(lines[1].trim());\n        const root = buildTree(treeLine);\n        console.log(kthSmallest(root, k));\n        rl.close();\n    }\n});', NULL, 1),
(342, 'PYTHON', 'import sys\nfrom collections import deque\n\nclass TreeNode:\n    def __init__(self, val):\n        self.val = val\n        self.left = None\n        self.right = None\n\ndef build_tree(line):\n    if line is None or len(line) == 0:\n        return None\n    line = line.strip()\n    if line.startswith(\"[\"):\n        line = line[1:]\n    if line.endswith(\"]\"):\n        line = line[:-1]\n    if line.strip() == \"\":\n        return None\n\n    parts = line.split(\",\")\n    if len(parts) == 0 or parts[0].strip() == \"null\":\n        return None\n\n    root = TreeNode(int(parts[0].strip()))\n    queue = deque([root])\n    i = 1\n\n    while queue and i < len(parts):\n        cur = queue.popleft()\n\n        if i < len(parts):\n            left_val = parts[i].strip()\n            i += 1\n            if left_val != \"null\":\n                cur.left = TreeNode(int(left_val))\n                queue.append(cur.left)\n\n        if i < len(parts):\n            right_val = parts[i].strip()\n            i += 1\n            if right_val != \"null\":\n                cur.right = TreeNode(int(right_val))\n                queue.append(cur.right)\n\n    return root\n\ndef kth_smallest(root, k):\n    stack = []\n    cur = root\n\n    while cur is not None or stack:\n        while cur is not None:\n            stack.append(cur)\n            cur = cur.left\n        cur = stack.pop()\n        k -= 1\n        if k == 0:\n            return cur.val\n        cur = cur.right\n\n    return -1\n\ndef main():\n    line = sys.stdin.readline().strip()\n    k = int(sys.stdin.readline().strip())\n    root = build_tree(line)\n    print(kth_smallest(root, k))\n\nif __name__ == \"__main__\":\n    main()', NULL, 1),
(343, 'C', '#include <stdio.h>\n#include <stdlib.h>\n\nint main() {\n    int n, k;\n    scanf(\"%d %d\", &n, &k);\n    int *nums = (int *)malloc(n * sizeof(int));\n    for (int i = 0; i < n; i++) {\n        scanf(\"%d\", &nums[i]);\n    }\n\n    int *deque = (int *)malloc(n * sizeof(int));\n    int head = 0, tail = 0;\n    int *result = (int *)malloc((n - k + 1) * sizeof(int));\n    int idx = 0;\n\n    for (int i = 0; i < n; i++) {\n        while (head < tail && deque[head] < i - k + 1) {\n            head++;\n        }\n        while (head < tail && nums[deque[tail - 1]] < nums[i]) {\n            tail--;\n        }\n        deque[tail++] = i;\n        if (i >= k - 1) {\n            result[idx++] = nums[deque[head]];\n        }\n    }\n\n    printf(\"[\");\n    for (int i = 0; i < idx; i++) {\n        if (i > 0) printf(\",\");\n        printf(\"%d\", result[i]);\n    }\n    printf(\"]\\n\");\n\n    free(nums);\n    free(deque);\n    free(result);\n    return 0;\n}', NULL, 1),
(343, 'CPP', '#include <iostream>\n#include <vector>\n#include <deque>\nusing namespace std;\n\nint main() {\n    int n, k;\n    cin >> n >> k;\n    vector<int> nums(n);\n    for (int i = 0; i < n; i++) {\n        cin >> nums[i];\n    }\n\n    deque<int> dq;\n    vector<int> result(n - k + 1);\n    int idx = 0;\n\n    for (int i = 0; i < n; i++) {\n        while (!dq.empty() && dq.front() < i - k + 1) {\n            dq.pop_front();\n        }\n        while (!dq.empty() && nums[dq.back()] < nums[i]) {\n            dq.pop_back();\n        }\n        dq.push_back(i);\n        if (i >= k - 1) {\n            result[idx++] = nums[dq.front()];\n        }\n    }\n\n    cout << \"[\";\n    for (int i = 0; i < (int)result.size(); i++) {\n        if (i > 0) cout << \",\";\n        cout << result[i];\n    }\n    cout << \"]\" << endl;\n\n    return 0;\n}', NULL, 1),
(343, 'JAVA', 'import java.util.*;\n\npublic class Main {\n    public static void main(String[] args) {\n        Scanner sc = new Scanner(System.in);\n        int n = sc.nextInt();\n        int k = sc.nextInt();\n        int[] nums = new int[n];\n        for (int i = 0; i < n; i++) {\n            nums[i] = sc.nextInt();\n        }\n\n        Deque<Integer> deque = new ArrayDeque<>();\n        int[] result = new int[n - k + 1];\n        int idx = 0;\n\n        for (int i = 0; i < n; i++) {\n            while (!deque.isEmpty() && deque.peekFirst() < i - k + 1) {\n                deque.pollFirst();\n            }\n            while (!deque.isEmpty() && nums[deque.peekLast()] < nums[i]) {\n                deque.pollLast();\n            }\n            deque.offerLast(i);\n            if (i >= k - 1) {\n                result[idx++] = nums[deque.peekFirst()];\n            }\n        }\n\n        StringBuilder sb = new StringBuilder();\n        sb.append(\"[\");\n        for (int i = 0; i < result.length; i++) {\n            if (i > 0) sb.append(\",\");\n            sb.append(result[i]);\n        }\n        sb.append(\"]\");\n        System.out.println(sb.toString());\n    }\n}', NULL, 1),
(343, 'JAVASCRIPT', 'const readline = require(\'readline\');\n\nconst rl = readline.createInterface({\n    input: process.stdin,\n    output: process.stdout\n});\n\nlet lines = [];\nrl.on(\'line\', (line) => {\n    lines.push(line.trim());\n});\n\nrl.on(\'close\', () => {\n    const [n, k] = lines[0].split(\' \').map(Number);\n    const nums = lines[1].split(\' \').map(Number);\n\n    const deque = [];\n    const result = [];\n\n    for (let i = 0; i < n; i++) {\n        while (deque.length > 0 && deque[0] < i - k + 1) {\n            deque.shift();\n        }\n        while (deque.length > 0 && nums[deque[deque.length - 1]] < nums[i]) {\n            deque.pop();\n        }\n        deque.push(i);\n        if (i >= k - 1) {\n            result.push(nums[deque[0]]);\n        }\n    }\n\n    console.log(\'[\' + result.join(\',\') + \']\');\n});', NULL, 1),
(343, 'PYTHON', 'import sys\nfrom collections import deque\n\ndef main():\n    data = sys.stdin.read().strip().split()\n    if not data:\n        return\n    n = int(data[0])\n    k = int(data[1])\n    nums = list(map(int, data[2:2 + n]))\n\n    dq = deque()\n    result = []\n\n    for i in range(n):\n        while dq and dq[0] < i - k + 1:\n            dq.popleft()\n        while dq and nums[dq[-1]] < nums[i]:\n            dq.pop()\n        dq.append(i)\n        if i >= k - 1:\n            result.append(nums[dq[0]])\n\n    print(\"[\" + \",\".join(map(str, result)) + \"]\")\n\nif __name__ == \"__main__\":\n    main()', NULL, 1),
(344, 'C', '#include <stdio.h>\n#include <stdlib.h>\n\ntypedef struct {\n    int *data;\n    int size;\n    int capacity;\n} Heap;\n\nvoid heapInit(Heap *h, int capacity) {\n    h->data = (int *)malloc(sizeof(int) * capacity);\n    h->size = 0;\n    h->capacity = capacity;\n}\n\nvoid heapPush(Heap *h, int value) {\n    int i = h->size++;\n    h->data[i] = value;\n    while (i > 0) {\n        int parent = (i - 1) / 2;\n        if (h->data[parent] <= h->data[i]) break;\n        int tmp = h->data[parent];\n        h->data[parent] = h->data[i];\n        h->data[i] = tmp;\n        i = parent;\n    }\n}\n\nint heapPop(Heap *h) {\n    int result = h->data[0];\n    h->data[0] = h->data[--h->size];\n    int i = 0;\n    while (1) {\n        int left = i * 2 + 1;\n        int right = i * 2 + 2;\n        int smallest = i;\n        if (left < h->size && h->data[left] < h->data[smallest]) smallest = left;\n        if (right < h->size && h->data[right] < h->data[smallest]) smallest = right;\n        if (smallest == i) break;\n        int tmp = h->data[i];\n        h->data[i] = h->data[smallest];\n        h->data[smallest] = tmp;\n        i = smallest;\n    }\n    return result;\n}\n\nint main() {\n    int numCourses, m;\n    scanf(\"%d\", &numCourses);\n    scanf(\"%d\", &m);\n\n    int **graph = (int **)malloc(sizeof(int *) * numCourses);\n    int *graphSize = (int *)calloc(numCourses, sizeof(int));\n    int *graphCap = (int *)calloc(numCourses, sizeof(int));\n    for (int i = 0; i < numCourses; i++) {\n        graphCap[i] = 4;\n        graph[i] = (int *)malloc(sizeof(int) * graphCap[i]);\n    }\n\n    int *indegree = (int *)calloc(numCourses, sizeof(int));\n\n    for (int i = 0; i < m; i++) {\n        int ai, bi;\n        scanf(\"%d %d\", &ai, &bi);\n        if (graphSize[bi] == graphCap[bi]) {\n            graphCap[bi] *= 2;\n            graph[bi] = (int *)realloc(graph[bi], sizeof(int) * graphCap[bi]);\n        }\n        graph[bi][graphSize[bi]++] = ai;\n        indegree[ai]++;\n    }\n\n    Heap pq;\n    heapInit(&pq, numCourses);\n    for (int i = 0; i < numCourses; i++) {\n        if (indegree[i] == 0) {\n            heapPush(&pq, i);\n        }\n    }\n\n    int *order = (int *)malloc(sizeof(int) * numCourses);\n    int orderSize = 0;\n\n    while (pq.size > 0) {\n        int cur = heapPop(&pq);\n        order[orderSize++] = cur;\n        for (int i = 0; i < graphSize[cur]; i++) {\n            int next = graph[cur][i];\n            indegree[next]--;\n            if (indegree[next] == 0) {\n                heapPush(&pq, next);\n            }\n        }\n    }\n\n    if (orderSize != numCourses) {\n        printf(\"[]\\n\");\n    } else {\n        for (int i = 0; i < orderSize; i++) {\n            if (i > 0) printf(\" \");\n            printf(\"%d\", order[i]);\n        }\n        printf(\"\\n\");\n    }\n\n    for (int i = 0; i < numCourses; i++) {\n        free(graph[i]);\n    }\n    free(graph);\n    free(graphSize);\n    free(graphCap);\n    free(indegree);\n    free(order);\n    free(pq.data);\n\n    return 0;\n}', NULL, 1),
(344, 'CPP', '#include <iostream>\n#include <vector>\n#include <queue>\nusing namespace std;\n\nint main() {\n    int numCourses, m;\n    cin >> numCourses >> m;\n\n    vector<vector<int>> graph(numCourses);\n    vector<int> indegree(numCourses, 0);\n\n    for (int i = 0; i < m; i++) {\n        int ai, bi;\n        cin >> ai >> bi;\n        graph[bi].push_back(ai);\n        indegree[ai]++;\n    }\n\n    priority_queue<int, vector<int>, greater<int>> pq;\n    for (int i = 0; i < numCourses; i++) {\n        if (indegree[i] == 0) {\n            pq.push(i);\n        }\n    }\n\n    vector<int> order;\n    while (!pq.empty()) {\n        int cur = pq.top();\n        pq.pop();\n        order.push_back(cur);\n        for (int next : graph[cur]) {\n            indegree[next]--;\n            if (indegree[next] == 0) {\n                pq.push(next);\n            }\n        }\n    }\n\n    if ((int)order.size() != numCourses) {\n        cout << \"[]\" << endl;\n    } else {\n        for (int i = 0; i < (int)order.size(); i++) {\n            if (i > 0) cout << \' \';\n            cout << order[i];\n        }\n        cout << endl;\n    }\n\n    return 0;\n}', NULL, 1),
(344, 'JAVA', 'import java.util.*;\n\npublic class Main {\n    public static void main(String[] args) {\n        Scanner sc = new Scanner(System.in);\n        int numCourses = sc.nextInt();\n        int m = sc.nextInt();\n\n        List<List<Integer>> graph = new ArrayList<>();\n        for (int i = 0; i < numCourses; i++) {\n            graph.add(new ArrayList<>());\n        }\n\n        int[] indegree = new int[numCourses];\n\n        for (int i = 0; i < m; i++) {\n            int ai = sc.nextInt();\n            int bi = sc.nextInt();\n            graph.get(bi).add(ai);\n            indegree[ai]++;\n        }\n\n        PriorityQueue<Integer> pq = new PriorityQueue<>();\n        for (int i = 0; i < numCourses; i++) {\n            if (indegree[i] == 0) {\n                pq.offer(i);\n            }\n        }\n\n        List<Integer> order = new ArrayList<>();\n        while (!pq.isEmpty()) {\n            int cur = pq.poll();\n            order.add(cur);\n            for (int next : graph.get(cur)) {\n                indegree[next]--;\n                if (indegree[next] == 0) {\n                    pq.offer(next);\n                }\n            }\n        }\n\n        if (order.size() != numCourses) {\n            System.out.println(\"[]\");\n        } else {\n            StringBuilder sb = new StringBuilder();\n            for (int i = 0; i < order.size(); i++) {\n                if (i > 0) sb.append(\' \');\n                sb.append(order.get(i));\n            }\n            System.out.println(sb.toString());\n        }\n    }\n}', NULL, 1),
(344, 'JAVASCRIPT', 'const readline = require(\'readline\');\n\nconst rl = readline.createInterface({\n    input: process.stdin,\n    output: process.stdout\n});\n\nlet lines = [];\nrl.on(\'line\', (line) => {\n    lines.push(line.trim());\n});\n\nrl.on(\'close\', () => {\n    let idx = 0;\n    const numCourses = parseInt(lines[idx++]);\n    const m = parseInt(lines[idx++]);\n\n    const graph = Array.from({ length: numCourses }, () => []);\n    const indegree = new Array(numCourses).fill(0);\n\n    for (let i = 0; i < m; i++) {\n        const parts = lines[idx++].split(/\\s+/).map(Number);\n        const ai = parts[0];\n        const bi = parts[1];\n        graph[bi].push(ai);\n        indegree[ai]++;\n    }\n\n    const pq = [];\n    const push = (x) => {\n        pq.push(x);\n        let i = pq.length - 1;\n        while (i > 0) {\n            const p = (i - 1) >> 1;\n            if (pq[p] <= pq[i]) break;\n            [pq[p], pq[i]] = [pq[i], pq[p]];\n            i = p;\n        }\n    };\n    const pop = () => {\n        const top = pq[0];\n        const last = pq.pop();\n        if (pq.length > 0) {\n            pq[0] = last;\n            let i = 0;\n            const n = pq.length;\n            while (true) {\n                let smallest = i;\n                const l = 2 * i + 1;\n                const r = 2 * i + 2;\n                if (l < n && pq[l] < pq[smallest]) smallest = l;\n                if (r < n && pq[r] < pq[smallest]) smallest = r;\n                if (smallest === i) break;\n                [pq[i], pq[smallest]] = [pq[smallest], pq[i]];\n                i = smallest;\n            }\n        }\n        return top;\n    };\n\n    for (let i = 0; i < numCourses; i++) {\n        if (indegree[i] === 0) {\n            push(i);\n        }\n    }\n\n    const order = [];\n    while (pq.length > 0) {\n        const cur = pop();\n        order.push(cur);\n        for (const next of graph[cur]) {\n            indegree[next]--;\n            if (indegree[next] === 0) {\n                push(next);\n            }\n        }\n    }\n\n    if (order.length !== numCourses) {\n        console.log(\"[]\");\n    } else {\n        console.log(order.join(\' \'));\n    }\n});', NULL, 1),
(344, 'PYTHON', 'import sys\nimport heapq\n\ndef main():\n    data = sys.stdin.read().strip().split()\n    if not data:\n        return\n    it = iter(data)\n    numCourses = int(next(it))\n    m = int(next(it))\n\n    graph = [[] for _ in range(numCourses)]\n    indegree = [0] * numCourses\n\n    for _ in range(m):\n        ai = int(next(it))\n        bi = int(next(it))\n        graph[bi].append(ai)\n        indegree[ai] += 1\n\n    pq = []\n    for i in range(numCourses):\n        if indegree[i] == 0:\n            heapq.heappush(pq, i)\n\n    order = []\n    while pq:\n        cur = heapq.heappop(pq)\n        order.append(cur)\n        for nxt in graph[cur]:\n            indegree[nxt] -= 1\n            if indegree[nxt] == 0:\n                heapq.heappush(pq, nxt)\n\n    if len(order) != numCourses:\n        print(\"[]\")\n    else:\n        print(\" \".join(map(str, order)))\n\nif __name__ == \"__main__\":\n    main()', NULL, 1),
(345, 'C', '#include <stdio.h>\n#include <string.h>\n\nint main() {\n    char s[100005];\n    if (scanf(\"%s\", s) != 1) return 0;\n    int n = strlen(s);\n    int dp[100005] = {0};\n    int max = 0;\n    for (int i = 1; i < n; i++) {\n        if (s[i] == \')\') {\n            if (s[i - 1] == \'(\') {\n                dp[i] = (i >= 2 ? dp[i - 2] : 0) + 2;\n            } else if (i - dp[i - 1] > 0 && s[i - dp[i - 1] - 1] == \'(\') {\n                dp[i] = dp[i - 1] + ((i - dp[i - 1] >= 2) ? dp[i - dp[i - 1] - 2] : 0) + 2;\n            }\n            if (dp[i] > max) max = dp[i];\n        }\n    }\n    printf(\"%d\\n\", max);\n    return 0;\n}', NULL, 1),
(345, 'CPP', '#include <iostream>\n#include <string>\n#include <vector>\n#include <algorithm>\nusing namespace std;\n\nint main() {\n    string s;\n    getline(cin, s);\n    int n = s.length();\n    vector<int> dp(n, 0);\n    int maxLen = 0;\n    for (int i = 1; i < n; i++) {\n        if (s[i] == \')\') {\n            if (s[i - 1] == \'(\') {\n                dp[i] = (i >= 2 ? dp[i - 2] : 0) + 2;\n            } else if (i - dp[i - 1] > 0 && s[i - dp[i - 1] - 1] == \'(\') {\n                dp[i] = dp[i - 1] + ((i - dp[i - 1] >= 2) ? dp[i - dp[i - 1] - 2] : 0) + 2;\n            }\n            maxLen = max(maxLen, dp[i]);\n        }\n    }\n    cout << maxLen << endl;\n    return 0;\n}', NULL, 1),
(345, 'JAVA', 'import java.util.Scanner;\n\npublic class Main {\n    public static void main(String[] args) {\n        Scanner sc = new Scanner(System.in);\n        String s = sc.nextLine();\n        int n = s.length();\n        int[] dp = new int[n];\n        int max = 0;\n        for (int i = 1; i < n; i++) {\n            if (s.charAt(i) == \')\') {\n                if (s.charAt(i - 1) == \'(\') {\n                    dp[i] = (i >= 2 ? dp[i - 2] : 0) + 2;\n                } else if (i - dp[i - 1] > 0 && s.charAt(i - dp[i - 1] - 1) == \'(\') {\n                    dp[i] = dp[i - 1] + ((i - dp[i - 1] >= 2) ? dp[i - dp[i - 1] - 2] : 0) + 2;\n                }\n                max = Math.max(max, dp[i]);\n            }\n        }\n        System.out.println(max);\n    }\n}', NULL, 1),
