(345, 'PYTHON', 's = input()\nn = len(s)\ndp = [0] * n\nmax_len = 0\nfor i in range(1, n):\n    if s[i] == \')\':\n        if s[i - 1] == \'(\':\n            dp[i] = (dp[i - 2] if i >= 2 else 0) + 2\n        elif i - dp[i - 1] > 0 and s[i - dp[i - 1] - 1] == \'(\':\n            dp[i] = dp[i - 1] + (dp[i - dp[i - 1] - 2] if i - dp[i - 1] >= 2 else 0) + 2\n        max_len = max(max_len, dp[i])\nprint(max_len)', NULL, 1),
(346, 'C', '#include <stdio.h>\n#include <stdbool.h>\n\nint count = 0;\nint n;\n\nvoid dfs(int row, bool col[], bool diag1[], bool diag2[]) {\n    if (row == n) {\n        count++;\n        return;\n    }\n    for (int c = 0; c < n; c++) {\n        int d1 = row + c;\n        int d2 = row - c + n;\n        if (!col[c] && !diag1[d1] && !diag2[d2]) {\n            col[c] = true;\n            diag1[d1] = true;\n            diag2[d2] = true;\n            dfs(row + 1, col, diag1, diag2);\n            col[c] = false;\n            diag1[d1] = false;\n            diag2[d2] = false;\n        }\n    }\n}\n\nint main() {\n    scanf(\"%d\", &n);\n    bool col[n];\n    bool diag1[2 * n];\n    bool diag2[2 * n];\n    for (int i = 0; i < n; i++) col[i] = false;\n    for (int i = 0; i < 2 * n; i++) {\n        diag1[i] = false;\n        diag2[i] = false;\n    }\n    dfs(0, col, diag1, diag2);\n    printf(\"%d\\n\", count);\n    return 0;\n}', NULL, 1),
(346, 'CPP', '#include <iostream>\nusing namespace std;\n\nint count = 0;\nint n;\nbool col[20];\nbool diag1[40];\nbool diag2[40];\n\nvoid dfs(int row) {\n    if (row == n) {\n        count++;\n        return;\n    }\n    for (int c = 0; c < n; c++) {\n        int d1 = row + c;\n        int d2 = row - c + n;\n        if (!col[c] && !diag1[d1] && !diag2[d2]) {\n            col[c] = true;\n            diag1[d1] = true;\n            diag2[d2] = true;\n            dfs(row + 1);\n            col[c] = false;\n            diag1[d1] = false;\n            diag2[d2] = false;\n        }\n    }\n}\n\nint main() {\n    cin >> n;\n    dfs(0);\n    cout << count << endl;\n    return 0;\n}', NULL, 1),
(346, 'JAVA', 'import java.util.Scanner;\n\npublic class Main {\n    static int count = 0;\n    static int n;\n\n    public static void main(String[] args) {\n        Scanner sc = new Scanner(System.in);\n        n = sc.nextInt();\n        boolean[] col = new boolean[n];\n        boolean[] diag1 = new boolean[2 * n];\n        boolean[] diag2 = new boolean[2 * n];\n        dfs(0, col, diag1, diag2);\n        System.out.println(count);\n    }\n\n    static void dfs(int row, boolean[] col, boolean[] diag1, boolean[] diag2) {\n        if (row == n) {\n            count++;\n            return;\n        }\n        for (int c = 0; c < n; c++) {\n            int d1 = row + c;\n            int d2 = row - c + n;\n            if (!col[c] && !diag1[d1] && !diag2[d2]) {\n                col[c] = true;\n                diag1[d1] = true;\n                diag2[d2] = true;\n                dfs(row + 1, col, diag1, diag2);\n                col[c] = false;\n                diag1[d1] = false;\n                diag2[d2] = false;\n            }\n        }\n    }\n}', NULL, 1),
(346, 'JAVASCRIPT', 'const readline = require(\'readline\');\n\nconst rl = readline.createInterface({\n    input: process.stdin,\n    output: process.stdout\n});\n\nlet n;\nlet count = 0;\n\nrl.on(\'line\', (line) => {\n    n = parseInt(line.trim());\n    const col = new Array(n).fill(false);\n    const diag1 = new Array(2 * n).fill(false);\n    const diag2 = new Array(2 * n).fill(false);\n    dfs(0, col, diag1, diag2);\n    console.log(count);\n    rl.close();\n});\n\nfunction dfs(row, col, diag1, diag2) {\n    if (row === n) {\n        count++;\n        return;\n    }\n    for (let c = 0; c < n; c++) {\n        const d1 = row + c;\n        const d2 = row - c + n;\n        if (!col[c] && !diag1[d1] && !diag2[d2]) {\n            col[c] = true;\n            diag1[d1] = true;\n            diag2[d2] = true;\n            dfs(row + 1, col, diag1, diag2);\n            col[c] = false;\n            diag1[d1] = false;\n            diag2[d2] = false;\n        }\n    }\n}', NULL, 1),
(346, 'PYTHON', 'import sys\n\ndef main():\n    data = sys.stdin.read().strip().split()\n    if not data:\n        return\n    n = int(data[0])\n    count = 0\n    col = [False] * n\n    diag1 = [False] * (2 * n)\n    diag2 = [False] * (2 * n)\n\n    def dfs(row):\n        nonlocal count\n        if row == n:\n            count += 1\n            return\n        for c in range(n):\n            d1 = row + c\n            d2 = row - c + n\n            if not col[c] and not diag1[d1] and not diag2[d2]:\n                col[c] = True\n                diag1[d1] = True\n                diag2[d2] = True\n                dfs(row + 1)\n                col[c] = False\n                diag1[d1] = False\n                diag2[d2] = False\n\n    dfs(0)\n    print(count)\n\nif __name__ == \"__main__\":\n    main()', NULL, 1),
(347, 'C', '#include <stdio.h>\n#include <string.h>\n\nint main() {\n    int m, n;\n    scanf(\"%d %d\", &m, &n);\n    getchar();\n\n    char matrix[m][n + 1];\n    for (int i = 0; i < m; i++) {\n        fgets(matrix[i], n + 2, stdin);\n        matrix[i][strcspn(matrix[i], \"\\r\\n\")] = \'\\0\';\n    }\n\n    int dp[m + 1][n + 1];\n    memset(dp, 0, sizeof(dp));\n    int maxSide = 0;\n\n    for (int i = 1; i <= m; i++) {\n        for (int j = 1; j <= n; j++) {\n            if (matrix[i - 1][j - 1] == \'1\') {\n                int min = dp[i - 1][j];\n                if (dp[i][j - 1] < min) min = dp[i][j - 1];\n                if (dp[i - 1][j - 1] < min) min = dp[i - 1][j - 1];\n                dp[i][j] = min + 1;\n                if (dp[i][j] > maxSide) maxSide = dp[i][j];\n            }\n        }\n    }\n\n    printf(\"%d\\n\", maxSide * maxSide);\n    return 0;\n}', NULL, 1),
(347, 'CPP', '#include <iostream>\n#include <vector>\n#include <string>\n#include <algorithm>\nusing namespace std;\n\nint main() {\n    int m, n;\n    cin >> m >> n;\n    cin.ignore();\n    vector<string> matrix(m);\n    for (int i = 0; i < m; i++) {\n        getline(cin, matrix[i]);\n    }\n\n    vector<vector<int>> dp(m + 1, vector<int>(n + 1, 0));\n    int maxSide = 0;\n\n    for (int i = 1; i <= m; i++) {\n        for (int j = 1; j <= n; j++) {\n            if (matrix[i - 1][j - 1] == \'1\') {\n                dp[i][j] = min({dp[i - 1][j], dp[i][j - 1], dp[i - 1][j - 1]}) + 1;\n                maxSide = max(maxSide, dp[i][j]);\n            }\n        }\n    }\n\n    cout << maxSide * maxSide << endl;\n    return 0;\n}', NULL, 1),
(347, 'JAVA', 'import java.util.Scanner;\n\npublic class Main {\n    public static void main(String[] args) {\n        Scanner sc = new Scanner(System.in);\n        int m = sc.nextInt();\n        int n = sc.nextInt();\n        sc.nextLine();\n        char[][] matrix = new char[m][n];\n        for (int i = 0; i < m; i++) {\n            String line = sc.nextLine().trim();\n            matrix[i] = line.toCharArray();\n        }\n\n        int[][] dp = new int[m + 1][n + 1];\n        int maxSide = 0;\n\n        for (int i = 1; i <= m; i++) {\n            for (int j = 1; j <= n; j++) {\n                if (matrix[i - 1][j - 1] == \'1\') {\n                    dp[i][j] = Math.min(Math.min(dp[i - 1][j], dp[i][j - 1]), dp[i - 1][j - 1]) + 1;\n                    maxSide = Math.max(maxSide, dp[i][j]);\n                }\n            }\n        }\n\n        System.out.println(maxSide * maxSide);\n    }\n}', NULL, 1),
