(348, 'C', '#include <stdio.h>\n\nint main() {\n    int n;\n    scanf(\"%d\", &n);\n    int height[n];\n    for (int i = 0; i < n; i++) {\n        scanf(\"%d\", &height[i]);\n    }\n\n    int left = 0, right = n - 1;\n    int leftMax = 0, rightMax = 0;\n    int ans = 0;\n\n    while (left < right) {\n        if (height[left] < height[right]) {\n            if (height[left] >= leftMax) {\n                leftMax = height[left];\n            } else {\n                ans += leftMax - height[left];\n            }\n            left++;\n        } else {\n            if (height[right] >= rightMax) {\n                rightMax = height[right];\n            } else {\n                ans += rightMax - height[right];\n            }\n            right--;\n        }\n    }\n\n    printf(\"%d\\n\", ans);\n    return 0;\n}', NULL, 1),
(348, 'CPP', '#include <iostream>\n#include <vector>\nusing namespace std;\n\nint main() {\n    int n;\n    cin >> n;\n    vector<int> height(n);\n    for (int i = 0; i < n; i++) {\n        cin >> height[i];\n    }\n\n    int left = 0, right = n - 1;\n    int leftMax = 0, rightMax = 0;\n    int ans = 0;\n\n    while (left < right) {\n        if (height[left] < height[right]) {\n            if (height[left] >= leftMax) {\n                leftMax = height[left];\n            } else {\n                ans += leftMax - height[left];\n            }\n            left++;\n        } else {\n            if (height[right] >= rightMax) {\n                rightMax = height[right];\n            } else {\n                ans += rightMax - height[right];\n            }\n            right--;\n        }\n    }\n\n    cout << ans << endl;\n    return 0;\n}', NULL, 1),
(348, 'JAVA', 'import java.util.Scanner;\n\npublic class Main {\n    public static void main(String[] args) {\n        Scanner sc = new Scanner(System.in);\n        int n = sc.nextInt();\n        int[] height = new int[n];\n        for (int i = 0; i < n; i++) {\n            height[i] = sc.nextInt();\n        }\n\n        int left = 0, right = n - 1;\n        int leftMax = 0, rightMax = 0;\n        int ans = 0;\n\n        while (left < right) {\n            if (height[left] < height[right]) {\n                if (height[left] >= leftMax) {\n                    leftMax = height[left];\n                } else {\n                    ans += leftMax - height[left];\n                }\n                left++;\n            } else {\n                if (height[right] >= rightMax) {\n                    rightMax = height[right];\n                } else {\n                    ans += rightMax - height[right];\n                }\n                right--;\n            }\n        }\n\n        System.out.println(ans);\n    }\n}', NULL, 1),
(348, 'JAVASCRIPT', 'const readline = require(\'readline\');\n\nconst rl = readline.createInterface({\n    input: process.stdin,\n    output: process.stdout\n});\n\nlet lines = [];\nrl.on(\'line\', (line) => {\n    lines.push(line.trim());\n});\n\nrl.on(\'close\', () => {\n    const n = parseInt(lines[0]);\n    const height = lines[1].split(\' \').map(Number);\n\n    let left = 0, right = n - 1;\n    let leftMax = 0, rightMax = 0;\n    let ans = 0;\n\n    while (left < right) {\n        if (height[left] < height[right]) {\n            if (height[left] >= leftMax) {\n                leftMax = height[left];\n            } else {\n                ans += leftMax - height[left];\n            }\n            left++;\n        } else {\n            if (height[right] >= rightMax) {\n                rightMax = height[right];\n            } else {\n                ans += rightMax - height[right];\n            }\n            right--;\n        }\n    }\n\n    console.log(ans);\n});', NULL, 1),
(348, 'PYTHON', 'n = int(input())\nheight = list(map(int, input().split()))\n\nleft, right = 0, n - 1\nleftMax, rightMax = 0, 0\nans = 0\n\nwhile left < right:\n    if height[left] < height[right]:\n        if height[left] >= leftMax:\n            leftMax = height[left]\n        else:\n            ans += leftMax - height[left]\n        left += 1\n    else:\n        if height[right] >= rightMax:\n            rightMax = height[right]\n        else:\n            ans += rightMax - height[right]\n        right -= 1\n\nprint(ans)', NULL, 1),
(349, 'C', '#include <stdio.h>\n#include <stdlib.h>\n#include <string.h>\n\nchar *map[] = {\"\", \"\", \"abc\", \"def\", \"ghi\", \"jkl\", \"mno\", \"pqrs\", \"tuv\", \"wxyz\"};\n\nvoid backtrack(char **result, int *count, char *path, int index, char *digits) {\n    if (index == (int)strlen(digits)) {\n        path[index] = \'\\0\';\n        result[*count] = (char *)malloc((strlen(path) + 1) * sizeof(char));\n        strcpy(result[*count], path);\n        (*count)++;\n        return;\n    }\n    char c = digits[index];\n    char *letters = map[c - \'0\'];\n    for (int i = 0; i < (int)strlen(letters); i++) {\n        path[index] = letters[i];\n        backtrack(result, count, path, index + 1, digits);\n    }\n}\n\nint main() {\n    char digits[100];\n    if (scanf(\"%s\", digits) != 1) {\n        return 0;\n    }\n    int len = strlen(digits);\n    if (len == 0) {\n        printf(\"[]\\n\");\n        return 0;\n    }\n    int maxCount = 1;\n    for (int i = 0; i < len; i++) {\n        maxCount *= strlen(map[digits[i] - \'0\']);\n    }\n    char **result = (char **)malloc(maxCount * sizeof(char *));\n    char *path = (char *)malloc((len + 1) * sizeof(char));\n    int count = 0;\n    backtrack(result, &count, path, 0, digits);\n    printf(\"[\");\n    for (int i = 0; i < count; i++) {\n        if (i > 0) printf(\",\");\n        printf(\"\\\"%s\\\"\", result[i]);\n    }\n    printf(\"]\\n\");\n    for (int i = 0; i < count; i++) {\n        free(result[i]);\n    }\n    free(result);\n    free(path);\n    return 0;\n}', NULL, 1),
(349, 'CPP', '#include <iostream>\n#include <string>\n#include <vector>\nusing namespace std;\n\nvoid backtrack(vector<string>& result, string& path, const string& digits, int index, const string map[]) {\n    if (index == (int)digits.length()) {\n        result.push_back(path);\n        return;\n    }\n    char c = digits[index];\n    string letters = map[c - \'0\'];\n    for (int i = 0; i < (int)letters.length(); i++) {\n        path.push_back(letters[i]);\n        backtrack(result, path, digits, index + 1, map);\n        path.pop_back();\n    }\n}\n\nint main() {\n    string digits;\n    getline(cin, digits);\n    while (!digits.empty() && (digits.back() == \'\\r\' || digits.back() == \'\\n\' || digits.back() == \' \' || digits.back() == \'\\t\')) {\n        digits.pop_back();\n    }\n    size_t start = 0;\n    while (start < digits.size() && (digits[start] == \' \' || digits[start] == \'\\t\')) {\n        start++;\n    }\n    if (start > 0) digits = digits.substr(start);\n\n    vector<string> result;\n    if (digits.empty()) {\n        cout << \"[]\" << endl;\n        return 0;\n    }\n    string map[10] = {\n        \"\", \"\", \"abc\", \"def\", \"ghi\", \"jkl\", \"mno\", \"pqrs\", \"tuv\", \"wxyz\"\n    };\n    string path;\n    backtrack(result, path, digits, 0, map);\n    cout << \"[\";\n    for (int i = 0; i < (int)result.size(); i++) {\n        if (i > 0) cout << \",\";\n        cout << \"\\\"\" << result[i] << \"\\\"\";\n    }\n    cout << \"]\" << endl;\n    return 0;\n}', NULL, 1),
(349, 'JAVA', 'import java.util.*;\n\npublic class Main {\n    public static void main(String[] args) {\n        Scanner sc = new Scanner(System.in);\n        String digits = sc.nextLine().trim();\n        List<String> result = new ArrayList<>();\n        if (digits == null || digits.length() == 0) {\n            System.out.println(\"[]\");\n            return;\n        }\n        String[] map = {\n            \"\", \"\", \"abc\", \"def\", \"ghi\", \"jkl\", \"mno\", \"pqrs\", \"tuv\", \"wxyz\"\n        };\n        backtrack(result, new StringBuilder(), digits, 0, map);\n        StringBuilder sb = new StringBuilder();\n        sb.append(\"[\");\n        for (int i = 0; i < result.size(); i++) {\n            if (i > 0) sb.append(\",\");\n            sb.append(\"\\\"\").append(result.get(i)).append(\"\\\"\");\n        }\n        sb.append(\"]\");\n        System.out.println(sb.toString());\n    }\n\n    private static void backtrack(List<String> result, StringBuilder path, String digits, int index, String[] map) {\n        if (index == digits.length()) {\n            result.add(path.toString());\n            return;\n        }\n        char c = digits.charAt(index);\n        String letters = map[c - \'0\'];\n        for (int i = 0; i < letters.length(); i++) {\n            path.append(letters.charAt(i));\n            backtrack(result, path, digits, index + 1, map);\n            path.deleteCharAt(path.length() - 1);\n        }\n    }\n}', NULL, 1),
(349, 'JAVASCRIPT', 'const readline = require(\'readline\');\n\nconst rl = readline.createInterface({\n    input: process.stdin,\n    output: process.stdout\n});\n\nrl.on(\'line\', (line) => {\n    const digits = line.trim();\n    const result = [];\n    if (!digits || digits.length === 0) {\n        console.log(\"[]\");\n        rl.close();\n        return;\n    }\n    const map = [\"\", \"\", \"abc\", \"def\", \"ghi\", \"jkl\", \"mno\", \"pqrs\", \"tuv\", \"wxyz\"];\n    backtrack(result, \"\", digits, 0, map);\n    let sb = \"[\";\n    for (let i = 0; i < result.length; i++) {\n        if (i > 0) sb += \",\";\n        sb += \"\\\"\" + result[i] + \"\\\"\";\n    }\n    sb += \"]\";\n    console.log(sb);\n    rl.close();\n});\n\nfunction backtrack(result, path, digits, index, map) {\n    if (index === digits.length) {\n        result.push(path);\n        return;\n    }\n    const c = digits.charAt(index);\n    const letters = map[c.charCodeAt(0) - \'0\'.charCodeAt(0)];\n    for (let i = 0; i < letters.length; i++) {\n        backtrack(result, path + letters.charAt(i), digits, index + 1, map);\n    }\n}', NULL, 1),
(349, 'PYTHON', 'import sys\n\ndef main():\n    digits = sys.stdin.readline().strip()\n    if not digits:\n        print(\"[]\")\n        return\n    mapping = [\"\", \"\", \"abc\", \"def\", \"ghi\", \"jkl\", \"mno\", \"pqrs\", \"tuv\", \"wxyz\"]\n    result = []\n    def backtrack(index, path):\n        if index == len(digits):\n            result.append(path)\n            return\n        letters = mapping[int(digits[index])]\n        for ch in letters:\n            backtrack(index + 1, path + ch)\n    backtrack(0, \"\")\n    print(\"[\" + \",\".join(f\'\"{s}\"\' for s in result) + \"]\")\n\nif __name__ == \"__main__\":\n    main()', NULL, 1),
(350, 'C', '#include <stdio.h>\n#include <string.h>\n\nint strStr(const char *haystack, const char *needle) {\n    if (needle[0] == \'\\0\') {\n        return 0;\n    }\n    int n = (int)strlen(haystack);\n    int m = (int)strlen(needle);\n    for (int i = 0; i <= n - m; i++) {\n        if (strncmp(haystack + i, needle, m) == 0) {\n            return i;\n        }\n    }\n    return -1;\n}\n\nint main(void) {\n    char haystack[100005];\n    char needle[100005];\n\n    if (fgets(haystack, sizeof(haystack), stdin) == NULL) {\n        return 0;\n    }\n    if (fgets(needle, sizeof(needle), stdin) == NULL) {\n        return 0;\n    }\n\n    size_t len1 = strlen(haystack);\n    if (len1 > 0 && haystack[len1 - 1] == \'\\n\') {\n        haystack[len1 - 1] = \'\\0\';\n    }\n\n    size_t len2 = strlen(needle);\n    if (len2 > 0 && needle[len2 - 1] == \'\\n\') {\n        needle[len2 - 1] = \'\\0\';\n    }\n\n    printf(\"%d\\n\", strStr(haystack, needle));\n    return 0;\n}', NULL, 1),
(350, 'CPP', '#include <iostream>\n#include <string>\nusing namespace std;\n\nint strStr(const string& haystack, const string& needle) {\n    if (needle.empty()) {\n        return 0;\n    }\n    int n = haystack.length();\n    int m = needle.length();\n    for (int i = 0; i <= n - m; i++) {\n        if (haystack.substr(i, m) == needle) {\n            return i;\n        }\n    }\n    return -1;\n}\n\nint main() {\n    string haystack, needle;\n    getline(cin, haystack);\n    getline(cin, needle);\n    cout << strStr(haystack, needle) << endl;\n    return 0;\n}', NULL, 1),
(350, 'JAVA', 'import java.util.Scanner;\n\npublic class Main {\n    public static void main(String[] args) {\n        Scanner scanner = new Scanner(System.in);\n        String haystack = scanner.nextLine();\n        String needle = scanner.nextLine();\n        System.out.println(strStr(haystack, needle));\n    }\n\n    public static int strStr(String haystack, String needle) {\n        if (needle.isEmpty()) {\n            return 0;\n        }\n        int n = haystack.length();\n        int m = needle.length();\n        for (int i = 0; i <= n - m; i++) {\n            if (haystack.substring(i, i + m).equals(needle)) {\n                return i;\n            }\n        }\n        return -1;\n    }\n}', NULL, 1),
