(351, 'C', '#include <stdio.h>\n\nint main() {\n    int m, n;\n    scanf(\"%d %d\", &m, &n);\n    int matrix[m][n];\n    for (int i = 0; i < m; i++) {\n        for (int j = 0; j < n; j++) {\n            scanf(\"%d\", &matrix[i][j]);\n        }\n    }\n    int target;\n    scanf(\"%d\", &target);\n    int left = 0, right = m * n - 1;\n    int found = 0;\n    while (left <= right) {\n        int mid = left + (right - left) / 2;\n        int val = matrix[mid / n][mid % n];\n        if (val == target) {\n            found = 1;\n            break;\n        } else if (val < target) {\n            left = mid + 1;\n        } else {\n            right = mid - 1;\n        }\n    }\n    if (found) {\n        printf(\"true\\n\");\n    } else {\n        printf(\"false\\n\");\n    }\n    return 0;\n}', NULL, 1),
(351, 'CPP', '#include <iostream>\n#include <vector>\nusing namespace std;\n\nint main() {\n    int m, n;\n    cin >> m >> n;\n    vector<vector<int>> matrix(m, vector<int>(n));\n    for (int i = 0; i < m; i++) {\n        for (int j = 0; j < n; j++) {\n            cin >> matrix[i][j];\n        }\n    }\n    int target;\n    cin >> target;\n    int left = 0, right = m * n - 1;\n    bool found = false;\n    while (left <= right) {\n        int mid = left + (right - left) / 2;\n        int val = matrix[mid / n][mid % n];\n        if (val == target) {\n            found = true;\n            break;\n        } else if (val < target) {\n            left = mid + 1;\n        } else {\n            right = mid - 1;\n        }\n    }\n    cout << (found ? \"true\" : \"false\") << endl;\n    return 0;\n}', NULL, 1),
(351, 'JAVA', 'import java.util.Scanner;\n\npublic class Main {\n    public static void main(String[] args) {\n        Scanner sc = new Scanner(System.in);\n        int m = sc.nextInt();\n        int n = sc.nextInt();\n        int[][] matrix = new int[m][n];\n        for (int i = 0; i < m; i++) {\n            for (int j = 0; j < n; j++) {\n                matrix[i][j] = sc.nextInt();\n            }\n        }\n        int target = sc.nextInt();\n        int left = 0, right = m * n - 1;\n        boolean found = false;\n        while (left <= right) {\n            int mid = left + (right - left) / 2;\n            int val = matrix[mid / n][mid % n];\n            if (val == target) {\n                found = true;\n                break;\n            } else if (val < target) {\n                left = mid + 1;\n            } else {\n                right = mid - 1;\n            }\n        }\n        System.out.println(found);\n    }\n}', NULL, 1),
(351, 'JAVASCRIPT', 'const readline = require(\'readline\');\n\nconst rl = readline.createInterface({\n    input: process.stdin,\n    output: process.stdout\n});\n\nlet lines = [];\nrl.on(\'line\', (line) => {\n    lines.push(line.trim());\n});\n\nrl.on(\'close\', () => {\n    let idx = 0;\n    const [m, n] = lines[idx++].split(\' \').map(Number);\n    const matrix = [];\n    for (let i = 0; i < m; i++) {\n        matrix.push(lines[idx++].split(\' \').map(Number));\n    }\n    const target = Number(lines[idx++]);\n\n    let left = 0, right = m * n - 1;\n    let found = false;\n    while (left <= right) {\n        const mid = left + Math.floor((right - left) / 2);\n        const val = matrix[Math.floor(mid / n)][mid % n];\n        if (val === target) {\n            found = true;\n            break;\n        } else if (val < target) {\n            left = mid + 1;\n        } else {\n            right = mid - 1;\n        }\n    }\n    console.log(found);\n});', NULL, 1),
(351, 'PYTHON', 'import sys\n\ndef main():\n    data = sys.stdin.read().strip().split()\n    if not data:\n        return\n    m = int(data[0])\n    n = int(data[1])\n    idx = 2\n    matrix = []\n    for i in range(m):\n        row = []\n        for j in range(n):\n            row.append(int(data[idx]))\n            idx += 1\n        matrix.append(row)\n    target = int(data[idx])\n    \n    left, right = 0, m * n - 1\n    found = False\n    while left <= right:\n        mid = left + (right - left) // 2\n        val = matrix[mid // n][mid % n]\n        if val == target:\n            found = True\n            break\n        elif val < target:\n            left = mid + 1\n        else:\n            right = mid - 1\n    print(\"true\" if found else \"false\")\n\nif __name__ == \"__main__\":\n    main()', NULL, 1),
(352, 'C', '#include <stdio.h>\n#include <stdlib.h>\n\nint main() {\n    int n;\n    scanf(\"%d\", &n);\n    int *nums = (int *)malloc(n * sizeof(int));\n    for (int i = 0; i < n; i++) {\n        scanf(\"%d\", &nums[i]);\n    }\n\n    int low = 0, mid = 0, high = n - 1;\n    while (mid <= high) {\n        if (nums[mid] == 0) {\n            int temp = nums[low];\n            nums[low] = nums[mid];\n            nums[mid] = temp;\n            low++;\n            mid++;\n        } else if (nums[mid] == 1) {\n            mid++;\n        } else {\n            int temp = nums[mid];\n            nums[mid] = nums[high];\n            nums[high] = temp;\n            high--;\n        }\n    }\n\n    for (int i = 0; i < n; i++) {\n        if (i > 0) printf(\" \");\n        printf(\"%d\", nums[i]);\n    }\n    printf(\"\\n\");\n\n    free(nums);\n    return 0;\n}', NULL, 1),
(352, 'CPP', '#include <iostream>\n#include <vector>\nusing namespace std;\n\nint main() {\n    int n;\n    cin >> n;\n    vector<int> nums(n);\n    for (int i = 0; i < n; i++) {\n        cin >> nums[i];\n    }\n\n    int low = 0, mid = 0, high = n - 1;\n    while (mid <= high) {\n        if (nums[mid] == 0) {\n            swap(nums[low], nums[mid]);\n            low++;\n            mid++;\n        } else if (nums[mid] == 1) {\n            mid++;\n        } else {\n            swap(nums[mid], nums[high]);\n            high--;\n        }\n    }\n\n    for (int i = 0; i < n; i++) {\n        if (i > 0) cout << \' \';\n        cout << nums[i];\n    }\n    cout << endl;\n\n    return 0;\n}', NULL, 1),
(352, 'JAVA', 'import java.util.Scanner;\n\npublic class Main {\n    public static void main(String[] args) {\n        Scanner sc = new Scanner(System.in);\n        int n = sc.nextInt();\n        int[] nums = new int[n];\n        for (int i = 0; i < n; i++) {\n            nums[i] = sc.nextInt();\n        }\n\n        int low = 0, mid = 0, high = n - 1;\n        while (mid <= high) {\n            if (nums[mid] == 0) {\n                int temp = nums[low];\n                nums[low] = nums[mid];\n                nums[mid] = temp;\n                low++;\n                mid++;\n            } else if (nums[mid] == 1) {\n                mid++;\n            } else {\n                int temp = nums[mid];\n                nums[mid] = nums[high];\n                nums[high] = temp;\n                high--;\n            }\n        }\n\n        StringBuilder sb = new StringBuilder();\n        for (int i = 0; i < n; i++) {\n            if (i > 0) sb.append(\' \');\n            sb.append(nums[i]);\n        }\n        System.out.println(sb.toString());\n    }\n}', NULL, 1),
