(352, 'PYTHON', 'n = int(input())\nnums = list(map(int, input().split()))\n\nlow, mid, high = 0, 0, n - 1\nwhile mid <= high:\n    if nums[mid] == 0:\n        nums[low], nums[mid] = nums[mid], nums[low]\n        low += 1\n        mid += 1\n    elif nums[mid] == 1:\n        mid += 1\n    else:\n        nums[mid], nums[high] = nums[high], nums[mid]\n        high -= 1\n\nprint(\' \'.join(map(str, nums)))', NULL, 1),
(353, 'C', '#include <stdio.h>\n#include <stdlib.h>\n\nint cmp(const void *a, const void *b) {\n    return (*(int *)a - *(int *)b);\n}\n\nvoid backtrack(int *nums, int n, int start, int *path, int pathSize, int **res, int *returnSize, int **returnColumnSizes) {\n    res[*returnSize] = (int *)malloc(sizeof(int) * pathSize);\n    for (int i = 0; i < pathSize; i++) {\n        res[*returnSize][i] = path[i];\n    }\n    (*returnColumnSizes)[*returnSize] = pathSize;\n    (*returnSize)++;\n\n    for (int i = start; i < n; i++) {\n        if (i > start && nums[i] == nums[i - 1]) continue;\n        path[pathSize] = nums[i];\n        backtrack(nums, n, i + 1, path, pathSize + 1, res, returnSize, returnColumnSizes);\n    }\n}\n\nint main() {\n    int n;\n    scanf(\"%d\", &n);\n    int *nums = (int *)malloc(sizeof(int) * n);\n    for (int i = 0; i < n; i++) {\n        scanf(\"%d\", &nums[i]);\n    }\n    qsort(nums, n, sizeof(int), cmp);\n\n    int maxRes = 1 << n;\n    int **res = (int **)malloc(sizeof(int *) * maxRes);\n    int *returnColumnSizes = (int *)malloc(sizeof(int) * maxRes);\n    int returnSize = 0;\n    int *path = (int *)malloc(sizeof(int) * n);\n\n    backtrack(nums, n, 0, path, 0, res, &returnSize, &returnColumnSizes);\n\n    printf(\"[\");\n    for (int i = 0; i < returnSize; i++) {\n        if (i > 0) printf(\",\");\n        printf(\"[\");\n        for (int j = 0; j < returnColumnSizes[i]; j++) {\n            if (j > 0) printf(\",\");\n            printf(\"%d\", res[i][j]);\n        }\n        printf(\"]\");\n    }\n    printf(\"]\\n\");\n\n    for (int i = 0; i < returnSize; i++) {\n        free(res[i]);\n    }\n    free(res);\n    free(returnColumnSizes);\n    free(path);\n    free(nums);\n\n    return 0;\n}', NULL, 1),
(353, 'CPP', '#include <iostream>\n#include <vector>\n#include <algorithm>\nusing namespace std;\n\nvoid backtrack(vector<int>& nums, int start, vector<int>& path, vector<vector<int>>& res) {\n    res.push_back(path);\n    for (int i = start; i < (int)nums.size(); i++) {\n        if (i > start && nums[i] == nums[i - 1]) continue;\n        path.push_back(nums[i]);\n        backtrack(nums, i + 1, path, res);\n        path.pop_back();\n    }\n}\n\nint main() {\n    int n;\n    cin >> n;\n    vector<int> nums(n);\n    for (int i = 0; i < n; i++) {\n        cin >> nums[i];\n    }\n    sort(nums.begin(), nums.end());\n    vector<vector<int>> res;\n    vector<int> path;\n    backtrack(nums, 0, path, res);\n\n    cout << \"[\";\n    for (int i = 0; i < (int)res.size(); i++) {\n        if (i > 0) cout << \",\";\n        cout << \"[\";\n        for (int j = 0; j < (int)res[i].size(); j++) {\n            if (j > 0) cout << \",\";\n            cout << res[i][j];\n        }\n        cout << \"]\";\n    }\n    cout << \"]\" << endl;\n    return 0;\n}', NULL, 1),
(353, 'JAVA', 'import java.util.*;\n\npublic class Main {\n    public static void main(String[] args) {\n        Scanner sc = new Scanner(System.in);\n        int n = sc.nextInt();\n        int[] nums = new int[n];\n        for (int i = 0; i < n; i++) {\n            nums[i] = sc.nextInt();\n        }\n        Arrays.sort(nums);\n        List<List<Integer>> res = new ArrayList<>();\n        backtrack(nums, 0, new ArrayList<>(), res);\n        System.out.println(format(res));\n    }\n\n    private static void backtrack(int[] nums, int start, List<Integer> path, List<List<Integer>> res) {\n        res.add(new ArrayList<>(path));\n        for (int i = start; i < nums.length; i++) {\n            if (i > start && nums[i] == nums[i - 1]) continue;\n            path.add(nums[i]);\n            backtrack(nums, i + 1, path, res);\n            path.remove(path.size() - 1);\n        }\n    }\n\n    private static String format(List<List<Integer>> res) {\n        StringBuilder sb = new StringBuilder();\n        sb.append(\"[\");\n        for (int i = 0; i < res.size(); i++) {\n            if (i > 0) sb.append(\",\");\n            sb.append(\"[\");\n            List<Integer> list = res.get(i);\n            for (int j = 0; j < list.size(); j++) {\n                if (j > 0) sb.append(\",\");\n                sb.append(list.get(j));\n            }\n            sb.append(\"]\");\n        }\n        sb.append(\"]\");\n        return sb.toString();\n    }\n}', NULL, 1),
(353, 'JAVASCRIPT', 'const readline = require(\'readline\');\n\nconst rl = readline.createInterface({\n    input: process.stdin,\n    output: process.stdout\n});\n\nlet lines = [];\nrl.on(\'line\', (line) => {\n    lines.push(line.trim());\n});\n\nrl.on(\'close\', () => {\n    const n = parseInt(lines[0]);\n    const nums = lines[1].split(\' \').map(Number);\n    nums.sort((a, b) => a - b);\n    const res = [];\n    backtrack(nums, 0, [], res);\n    console.log(format(res));\n});\n\nfunction backtrack(nums, start, path, res) {\n    res.push([...path]);\n    for (let i = start; i < nums.length; i++) {\n        if (i > start && nums[i] === nums[i - 1]) continue;\n        path.push(nums[i]);\n        backtrack(nums, i + 1, path, res);\n        path.pop();\n    }\n}\n\nfunction format(res) {\n    let sb = \'\';\n    sb += \'[\';\n    for (let i = 0; i < res.length; i++) {\n        if (i > 0) sb += \',\';\n        sb += \'[\';\n        const list = res[i];\n        for (let j = 0; j < list.length; j++) {\n            if (j > 0) sb += \',\';\n            sb += list[j];\n        }\n        sb += \']\';\n    }\n    sb += \']\';\n    return sb;\n}', NULL, 1),
(353, 'PYTHON', 'import sys\n\ndef main():\n    data = sys.stdin.read().strip().split()\n    if not data:\n        return\n    n = int(data[0])\n    nums = list(map(int, data[1:1+n]))\n    nums.sort()\n    res = []\n    \n    def backtrack(start, path):\n        res.append(path[:])\n        for i in range(start, len(nums)):\n            if i > start and nums[i] == nums[i-1]:\n                continue\n            path.append(nums[i])\n            backtrack(i + 1, path)\n            path.pop()\n    \n    backtrack(0, [])\n    \n    parts = []\n    for subset in res:\n        parts.append(\"[\" + \",\".join(map(str, subset)) + \"]\")\n    print(\"[\" + \",\".join(parts) + \"]\")\n\nif __name__ == \"__main__\":\n    main()', NULL, 1),
(354, 'C', '#include <stdio.h>\n#include <string.h>\n\nint main() {\n    char s[100005];\n    if (scanf(\"%s\", s) != 1) return 0;\n    int n = strlen(s);\n    if (n == 0) {\n        printf(\"0\\n\");\n        return 0;\n    }\n    int dp[100005];\n    dp[0] = 1;\n    dp[1] = (s[0] == \'0\') ? 0 : 1;\n    for (int i = 2; i <= n; i++) {\n        dp[i] = 0;\n        int one = s[i - 1] - \'0\';\n        int two = (s[i - 2] - \'0\') * 10 + (s[i - 1] - \'0\');\n        if (one >= 1 && one <= 9) {\n            dp[i] += dp[i - 1];\n        }\n        if (two >= 10 && two <= 26) {\n            dp[i] += dp[i - 2];\n        }\n    }\n    printf(\"%d\\n\", dp[n]);\n    return 0;\n}', NULL, 1),
(354, 'CPP', '#include <iostream>\n#include <string>\n#include <vector>\n\nint main() {\n    std::string s;\n    std::getline(std::cin, s);\n    while (!s.empty() && (s.back() == \'\\n\' || s.back() == \'\\r\' || s.back() == \' \' || s.back() == \'\\t\')) {\n        s.pop_back();\n    }\n    size_t start = 0;\n    while (start < s.size() && (s[start] == \' \' || s[start] == \'\\t\')) {\n        ++start;\n    }\n    s = s.substr(start);\n\n    int n = static_cast<int>(s.size());\n    if (n == 0) {\n        std::cout << 0 << std::endl;\n        return 0;\n    }\n\n    std::vector<int> dp(n + 1, 0);\n    dp[0] = 1;\n    dp[1] = (s[0] == \'0\') ? 0 : 1;\n\n    for (int i = 2; i <= n; ++i) {\n        int one = s[i - 1] - \'0\';\n        int two = (s[i - 2] - \'0\') * 10 + (s[i - 1] - \'0\');\n\n        if (one >= 1 && one <= 9) {\n            dp[i] += dp[i - 1];\n        }\n        if (two >= 10 && two <= 26) {\n            dp[i] += dp[i - 2];\n        }\n    }\n\n    std::cout << dp[n] << std::endl;\n    return 0;\n}', NULL, 1),
(354, 'JAVA', 'import java.util.Scanner;\n\npublic class Main {\n    public static void main(String[] args) {\n        Scanner sc = new Scanner(System.in);\n        String s = sc.nextLine().trim();\n        int n = s.length();\n        if (n == 0) {\n            System.out.println(0);\n            return;\n        }\n        int[] dp = new int[n + 1];\n        dp[0] = 1;\n        dp[1] = s.charAt(0) == \'0\' ? 0 : 1;\n        for (int i = 2; i <= n; i++) {\n            int one = s.charAt(i - 1) - \'0\';\n            int two = Integer.parseInt(s.substring(i - 2, i));\n            if (one >= 1 && one <= 9) {\n                dp[i] += dp[i - 1];\n            }\n            if (two >= 10 && two <= 26) {\n                dp[i] += dp[i - 2];\n            }\n        }\n        System.out.println(dp[n]);\n    }\n}', NULL, 1),
(354, 'JAVASCRIPT', 'const readline = require(\'readline\');\n\nconst rl = readline.createInterface({\n    input: process.stdin,\n    output: process.stdout\n});\n\nrl.on(\'line\', (line) => {\n    const s = line.trim();\n    const n = s.length;\n    if (n === 0) {\n        console.log(0);\n        rl.close();\n        return;\n    }\n    const dp = new Array(n + 1).fill(0);\n    dp[0] = 1;\n    dp[1] = s.charAt(0) === \'0\' ? 0 : 1;\n    for (let i = 2; i <= n; i++) {\n        const one = s.charCodeAt(i - 1) - \'0\'.charCodeAt(0);\n        const two = parseInt(s.substring(i - 2, i), 10);\n        if (one >= 1 && one <= 9) {\n            dp[i] += dp[i - 1];\n        }\n        if (two >= 10 && two <= 26) {\n            dp[i] += dp[i - 2];\n        }\n    }\n    console.log(dp[n]);\n    rl.close();\n});', NULL, 1),
(354, 'PYTHON', 's = input().strip()\nn = len(s)\nif n == 0:\n    print(0)\nelse:\n    dp = [0] * (n + 1)\n    dp[0] = 1\n    dp[1] = 0 if s[0] == \'0\' else 1\n    for i in range(2, n + 1):\n        one = int(s[i - 1])\n        two = int(s[i - 2:i])\n        if 1 <= one <= 9:\n            dp[i] += dp[i - 1]\n        if 10 <= two <= 26:\n            dp[i] += dp[i - 2]\n    print(dp[n])', NULL, 1),
(355, 'C', '#include <stdio.h>\n\nint main() {\n    int n;\n    scanf(\"%d\", &n);\n    long long dp[n + 1];\n    dp[0] = 1;\n    for (int i = 1; i <= n; i++) {\n        dp[i] = 0;\n        for (int j = 1; j <= i; j++) {\n            dp[i] += dp[j - 1] * dp[i - j];\n        }\n    }\n    printf(\"%lld\\n\", dp[n]);\n    return 0;\n}', NULL, 1),
(355, 'CPP', '#include <iostream>\n#include <vector>\nusing namespace std;\n\nint main() {\n    int n;\n    cin >> n;\n    vector<long long> dp(n + 1, 0);\n    dp[0] = 1;\n    for (int i = 1; i <= n; i++) {\n        for (int j = 1; j <= i; j++) {\n            dp[i] += dp[j - 1] * dp[i - j];\n        }\n    }\n    cout << dp[n] << endl;\n    return 0;\n}', NULL, 1),
(355, 'JAVA', 'import java.util.Scanner;\n\npublic class Main {\n    public static void main(String[] args) {\n        Scanner sc = new Scanner(System.in);\n        int n = sc.nextInt();\n        long[] dp = new long[n + 1];\n        dp[0] = 1;\n        for (int i = 1; i <= n; i++) {\n            for (int j = 1; j <= i; j++) {\n                dp[i] += dp[j - 1] * dp[i - j];\n            }\n        }\n        System.out.println(dp[n]);\n    }\n}', NULL, 1),
(355, 'JAVASCRIPT', 'const readline = require(\'readline\');\n\nconst rl = readline.createInterface({\n    input: process.stdin,\n    output: process.stdout\n});\n\nrl.on(\'line\', (line) => {\n    const n = parseInt(line.trim(), 10);\n    const dp = new Array(n + 1).fill(0);\n    dp[0] = 1;\n    for (let i = 1; i <= n; i++) {\n        for (let j = 1; j <= i; j++) {\n            dp[i] += dp[j - 1] * dp[i - j];\n        }\n    }\n    console.log(dp[n]);\n    rl.close();\n});', NULL, 1),
