(356, 'C', '#include <stdio.h>\n#include <stdlib.h>\n\nint main() {\n    int n;\n    scanf(\"%d\", &n);\n    int **triangle = (int **)malloc(n * sizeof(int *));\n    for (int i = 0; i < n; i++) {\n        triangle[i] = (int *)malloc(n * sizeof(int));\n        for (int j = 0; j <= i; j++) {\n            scanf(\"%d\", &triangle[i][j]);\n        }\n    }\n    int *dp = (int *)malloc(n * sizeof(int));\n    for (int j = 0; j < n; j++) {\n        dp[j] = triangle[n - 1][j];\n    }\n    for (int i = n - 2; i >= 0; i--) {\n        for (int j = 0; j <= i; j++) {\n            int min = dp[j] < dp[j + 1] ? dp[j] : dp[j + 1];\n            dp[j] = triangle[i][j] + min;\n        }\n    }\n    printf(\"%d\\n\", dp[0]);\n    for (int i = 0; i < n; i++) {\n        free(triangle[i]);\n    }\n    free(triangle);\n    free(dp);\n    return 0;\n}', NULL, 1),
(356, 'CPP', '#include <iostream>\n#include <vector>\n#include <algorithm>\nusing namespace std;\n\nint main() {\n    int n;\n    cin >> n;\n    vector<vector<int>> triangle(n, vector<int>(n));\n    for (int i = 0; i < n; i++) {\n        for (int j = 0; j <= i; j++) {\n            cin >> triangle[i][j];\n        }\n    }\n    vector<int> dp(n);\n    for (int j = 0; j < n; j++) {\n        dp[j] = triangle[n - 1][j];\n    }\n    for (int i = n - 2; i >= 0; i--) {\n        for (int j = 0; j <= i; j++) {\n            dp[j] = triangle[i][j] + min(dp[j], dp[j + 1]);\n        }\n    }\n    cout << dp[0] << endl;\n    return 0;\n}', NULL, 1),
(356, 'JAVA', 'import java.util.Scanner;\n\npublic class Main {\n    public static void main(String[] args) {\n        Scanner sc = new Scanner(System.in);\n        int n = sc.nextInt();\n        int[][] triangle = new int[n][n];\n        for (int i = 0; i < n; i++) {\n            for (int j = 0; j <= i; j++) {\n                triangle[i][j] = sc.nextInt();\n            }\n        }\n        int[] dp = new int[n];\n        for (int j = 0; j < n; j++) {\n            dp[j] = triangle[n - 1][j];\n        }\n        for (int i = n - 2; i >= 0; i--) {\n            for (int j = 0; j <= i; j++) {\n                dp[j] = triangle[i][j] + Math.min(dp[j], dp[j + 1]);\n            }\n        }\n        System.out.println(dp[0]);\n    }\n}', NULL, 1),
(356, 'JAVASCRIPT', 'const readline = require(\'readline\');\n\nconst rl = readline.createInterface({\n    input: process.stdin,\n    output: process.stdout\n});\n\nlet lines = [];\nrl.on(\'line\', (line) => {\n    lines.push(line.trim());\n});\n\nrl.on(\'close\', () => {\n    let idx = 0;\n    const n = parseInt(lines[idx++]);\n    const triangle = [];\n    for (let i = 0; i < n; i++) {\n        const row = lines[idx++].split(\' \').map(Number);\n        triangle.push(row);\n    }\n    const dp = new Array(n);\n    for (let j = 0; j < n; j++) {\n        dp[j] = triangle[n - 1][j];\n    }\n    for (let i = n - 2; i >= 0; i--) {\n        for (let j = 0; j <= i; j++) {\n            dp[j] = triangle[i][j] + Math.min(dp[j], dp[j + 1]);\n        }\n    }\n    console.log(dp[0]);\n});', NULL, 1),
