(357, 'C', '#include <stdio.h>\n#include <stdlib.h>\n#include <string.h>\n#include <stdbool.h>\n\nint main() {\n    char s[10005];\n    if (fgets(s, sizeof(s), stdin) == NULL) return 0;\n    s[strcspn(s, \"\\r\\n\")] = \'\\0\';\n\n    char line[10005];\n    if (fgets(line, sizeof(line), stdin) == NULL) return 0;\n    int n = atoi(line);\n\n    char **wordDict = (char **)malloc(n * sizeof(char *));\n    for (int i = 0; i < n; i++) {\n        wordDict[i] = (char *)malloc(10005 * sizeof(char));\n        if (fgets(wordDict[i], 10005, stdin) == NULL) {\n            wordDict[i][0] = \'\\0\';\n        }\n        wordDict[i][strcspn(wordDict[i], \"\\r\\n\")] = \'\\0\';\n    }\n\n    int len = strlen(s);\n    bool *dp = (bool *)calloc(len + 1, sizeof(bool));\n    dp[0] = true;\n\n    for (int i = 1; i <= len; i++) {\n        for (int j = 0; j < i; j++) {\n            if (dp[j]) {\n                int subLen = i - j;\n                char *sub = (char *)malloc((subLen + 1) * sizeof(char));\n                strncpy(sub, s + j, subLen);\n                sub[subLen] = \'\\0\';\n\n                bool found = false;\n                for (int k = 0; k < n; k++) {\n                    if (strcmp(sub, wordDict[k]) == 0) {\n                        found = true;\n                        break;\n                    }\n                }\n                free(sub);\n\n                if (found) {\n                    dp[i] = true;\n                    break;\n                }\n            }\n        }\n    }\n\n    if (dp[len]) {\n        printf(\"true\\n\");\n    } else {\n        printf(\"false\\n\");\n    }\n\n    for (int i = 0; i < n; i++) {\n        free(wordDict[i]);\n    }\n    free(wordDict);\n    free(dp);\n\n    return 0;\n}', NULL, 1),
(357, 'CPP', '#include <iostream>\n#include <string>\n#include <vector>\n#include <unordered_set>\n\nusing namespace std;\n\nint main() {\n    string s;\n    getline(cin, s);\n\n    string nLine;\n    getline(cin, nLine);\n    int n = stoi(nLine);\n\n    unordered_set<string> wordDict;\n    for (int i = 0; i < n; ++i) {\n        string word;\n        getline(cin, word);\n        wordDict.insert(word);\n    }\n\n    int len = s.length();\n    vector<bool> dp(len + 1, false);\n    dp[0] = true;\n\n    for (int i = 1; i <= len; ++i) {\n        for (int j = 0; j < i; ++j) {\n            if (dp[j] && wordDict.count(s.substr(j, i - j))) {\n                dp[i] = true;\n                break;\n            }\n        }\n    }\n\n    cout << (dp[len] ? \"true\" : \"false\") << endl;\n\n    return 0;\n}', NULL, 1),
(357, 'JAVA', 'import java.util.*;\n\npublic class Main {\n    public static void main(String[] args) {\n        Scanner sc = new Scanner(System.in);\n        String s = sc.nextLine();\n        int n = Integer.parseInt(sc.nextLine().trim());\n        Set<String> wordDict = new HashSet<>();\n        for (int i = 0; i < n; i++) {\n            wordDict.add(sc.nextLine().trim());\n        }\n\n        int len = s.length();\n        boolean[] dp = new boolean[len + 1];\n        dp[0] = true;\n\n        for (int i = 1; i <= len; i++) {\n            for (int j = 0; j < i; j++) {\n                if (dp[j] && wordDict.contains(s.substring(j, i))) {\n                    dp[i] = true;\n                    break;\n                }\n            }\n        }\n\n        System.out.println(dp[len]);\n    }\n}', NULL, 1),
(357, 'JAVASCRIPT', 'const readline = require(\'readline\');\n\nconst rl = readline.createInterface({\n    input: process.stdin,\n    output: process.stdout\n});\n\nlet lines = [];\nrl.on(\'line\', (line) => {\n    lines.push(line);\n});\n\nrl.on(\'close\', () => {\n    const s = lines[0];\n    const n = parseInt(lines[1].trim());\n    const wordDict = new Set();\n    for (let i = 0; i < n; i++) {\n        wordDict.add(lines[2 + i].trim());\n    }\n\n    const len = s.length;\n    const dp = new Array(len + 1).fill(false);\n    dp[0] = true;\n\n    for (let i = 1; i <= len; i++) {\n        for (let j = 0; j < i; j++) {\n            if (dp[j] && wordDict.has(s.substring(j, i))) {\n                dp[i] = true;\n                break;\n            }\n        }\n    }\n\n    console.log(dp[len]);\n});', NULL, 1),
(357, 'PYTHON', 's = input()\nn = int(input().strip())\nwordDict = set()\nfor _ in range(n):\n    wordDict.add(input().strip())\n\nlength = len(s)\ndp = [False] * (length + 1)\ndp[0] = True\n\nfor i in range(1, length + 1):\n    for j in range(i):\n        if dp[j] and s[j:i] in wordDict:\n            dp[i] = True\n            break\n\nprint(str(dp[length]).lower())', NULL, 1),
(358, 'C', '#include <stdio.h>\n#include <stdlib.h>\n\ntypedef struct {\n    int num;\n    int freq;\n} Pair;\n\nint cmp(const void *a, const void *b) {\n    Pair *p1 = (Pair *)a;\n    Pair *p2 = (Pair *)b;\n    if (p1->freq != p2->freq) {\n        return p2->freq - p1->freq;\n    }\n    return p1->num - p2->num;\n}\n\nint main() {\n    int n, k;\n    scanf(\"%d %d\", &n, &k);\n    int *nums = (int *)malloc(n * sizeof(int));\n    for (int i = 0; i < n; i++) {\n        scanf(\"%d\", &nums[i]);\n    }\n\n    Pair *pairs = (Pair *)malloc(n * sizeof(Pair));\n    int size = 0;\n    for (int i = 0; i < n; i++) {\n        int found = 0;\n        for (int j = 0; j < size; j++) {\n            if (pairs[j].num == nums[i]) {\n                pairs[j].freq++;\n                found = 1;\n                break;\n            }\n        }\n        if (!found) {\n            pairs[size].num = nums[i];\n            pairs[size].freq = 1;\n            size++;\n        }\n    }\n\n    qsort(pairs, size, sizeof(Pair), cmp);\n\n    printf(\"[\");\n    for (int i = 0; i < k; i++) {\n        if (i > 0) printf(\",\");\n        printf(\"%d\", pairs[i].num);\n    }\n    printf(\"]\\n\");\n\n    free(nums);\n    free(pairs);\n    return 0;\n}', NULL, 1),
(358, 'CPP', '#include <iostream>\n#include <vector>\n#include <unordered_map>\n#include <algorithm>\nusing namespace std;\n\nint main() {\n    int n, k;\n    cin >> n >> k;\n    vector<int> nums(n);\n    for (int i = 0; i < n; ++i) {\n        cin >> nums[i];\n    }\n\n    unordered_map<int, int> freq;\n    for (int num : nums) {\n        freq[num]++;\n    }\n\n    vector<int> list;\n    for (auto &p : freq) {\n        list.push_back(p.first);\n    }\n\n    sort(list.begin(), list.end(), [&](int a, int b) {\n        int fa = freq[a];\n        int fb = freq[b];\n        if (fa != fb) return fa > fb;\n        return a < b;\n    });\n\n    cout << \"[\";\n    for (int i = 0; i < k; ++i) {\n        if (i > 0) cout << \",\";\n        cout << list[i];\n    }\n    cout << \"]\" << endl;\n\n    return 0;\n}', NULL, 1),
(358, 'JAVA', 'import java.util.*;\nimport java.io.*;\n\npublic class Main {\n    public static void main(String[] args) throws IOException {\n        BufferedReader br = new BufferedReader(new InputStreamReader(System.in));\n        String[] first = br.readLine().trim().split(\"\\\\s+\");\n        int n = Integer.parseInt(first[0]);\n        int k = Integer.parseInt(first[1]);\n        int[] nums = new int[n];\n        String[] second = br.readLine().trim().split(\"\\\\s+\");\n        for (int i = 0; i < n; i++) {\n            nums[i] = Integer.parseInt(second[i]);\n        }\n\n        Map<Integer, Integer> freq = new HashMap<>();\n        for (int num : nums) {\n            freq.put(num, freq.getOrDefault(num, 0) + 1);\n        }\n\n        List<Integer> list = new ArrayList<>(freq.keySet());\n        list.sort((a, b) -> {\n            int fa = freq.get(a);\n            int fb = freq.get(b);\n            if (fa != fb) {\n                return fb - fa;\n            }\n            return a - b;\n        });\n\n        StringBuilder sb = new StringBuilder();\n        sb.append(\"[\");\n        for (int i = 0; i < k; i++) {\n            if (i > 0) sb.append(\",\");\n            sb.append(list.get(i));\n        }\n        sb.append(\"]\");\n        System.out.println(sb.toString());\n    }\n}', NULL, 1),
(358, 'JAVASCRIPT', 'const readline = require(\'readline\');\n\nconst rl = readline.createInterface({\n    input: process.stdin,\n    output: process.stdout\n});\n\nlet lines = [];\nrl.on(\'line\', (line) => {\n    lines.push(line.trim());\n    if (lines.length === 2) {\n        const [n, k] = lines[0].split(/\\s+/).map(Number);\n        const nums = lines[1].split(/\\s+/).map(Number);\n\n        const freq = new Map();\n        for (const num of nums) {\n            freq.set(num, (freq.get(num) || 0) + 1);\n        }\n\n        const list = Array.from(freq.keys());\n        list.sort((a, b) => {\n            const fa = freq.get(a);\n            const fb = freq.get(b);\n            if (fa !== fb) {\n                return fb - fa;\n            }\n            return a - b;\n        });\n\n        const result = list.slice(0, k);\n        console.log(\'[\' + result.join(\',\') + \']\');\n        rl.close();\n    }\n});', NULL, 1),
(358, 'PYTHON', 'import sys\nfrom collections import Counter\n\ndef main():\n    data = sys.stdin.read().strip().split()\n    if not data:\n        return\n    n = int(data[0])\n    k = int(data[1])\n    nums = list(map(int, data[2:2+n]))\n    \n    freq = Counter(nums)\n    items = sorted(freq.keys(), key=lambda x: (-freq[x], x))\n    \n    result = items[:k]\n    print(\"[\" + \",\".join(map(str, result)) + \"]\")\n\nif __name__ == \"__main__\":\n    main()', NULL, 1),
(359, 'C', '#include <stdio.h>\n#include <stdlib.h>\n#include <string.h>\n#include <ctype.h>\n\n#define MAXN 100000\n\ntypedef struct {\n    int count;\n    char *str;\n} StackItem;\n\nchar *decodeString(const char *s) {\n    int len = strlen(s);\n    StackItem countStack[MAXN];\n    int top = 0;\n    char *current = (char *)malloc(MAXN * sizeof(char));\n    int curLen = 0;\n    current[0] = \'\\0\';\n    int k = 0;\n\n    for (int i = 0; i < len; i++) {\n        char c = s[i];\n        if (isdigit(c)) {\n            k = k * 10 + (c - \'0\');\n        } else if (c == \'[\') {\n            countStack[top].count = k;\n            countStack[top].str = (char *)malloc((curLen + 1) * sizeof(char));\n            strcpy(countStack[top].str, current);\n            top++;\n            curLen = 0;\n            current[0] = \'\\0\';\n            k = 0;\n        } else if (c == \']\') {\n            top--;\n            int repeat = countStack[top].count;\n            char *prev = countStack[top].str;\n            int prevLen = strlen(prev);\n            int newLen = prevLen + curLen * repeat;\n            char *newStr = (char *)malloc((newLen + 1) * sizeof(char));\n            strcpy(newStr, prev);\n            for (int j = 0; j < repeat; j++) {\n                strcat(newStr, current);\n            }\n            free(prev);\n            free(current);\n            current = newStr;\n            curLen = newLen;\n        } else {\n            current[curLen++] = c;\n            current[curLen] = \'\\0\';\n        }\n    }\n\n    return current;\n}\n\nint main() {\n    char s[MAXN];\n    if (fgets(s, sizeof(s), stdin)) {\n        size_t len = strlen(s);\n        if (len > 0 && s[len - 1] == \'\\n\') {\n            s[len - 1] = \'\\0\';\n        }\n        char *result = decodeString(s);\n        printf(\"%s\\n\", result);\n        free(result);\n    }\n    return 0;\n}', NULL, 1),
(359, 'CPP', '#include <iostream>\n#include <string>\n#include <stack>\nusing namespace std;\n\nstring decodeString(const string& s) {\n    stack<int> countStack;\n    stack<string> stringStack;\n    string current;\n    int k = 0;\n\n    for (char c : s) {\n        if (isdigit(c)) {\n            k = k * 10 + (c - \'0\');\n        } else if (c == \'[\') {\n            countStack.push(k);\n            stringStack.push(current);\n            current.clear();\n            k = 0;\n        } else if (c == \']\') {\n            int repeat = countStack.top();\n            countStack.pop();\n            string prev = stringStack.top();\n            stringStack.pop();\n            for (int i = 0; i < repeat; i++) {\n                prev += current;\n            }\n            current = prev;\n        } else {\n            current += c;\n        }\n    }\n\n    return current;\n}\n\nint main() {\n    string s;\n    if (getline(cin, s)) {\n        cout << decodeString(s) << endl;\n    }\n    return 0;\n}', NULL, 1),
(359, 'JAVA', 'import java.util.*;\n\npublic class Main {\n    public static void main(String[] args) {\n        Scanner sc = new Scanner(System.in);\n        if (sc.hasNextLine()) {\n            String s = sc.nextLine();\n            System.out.println(decodeString(s));\n        }\n    }\n\n    public static String decodeString(String s) {\n        Deque<Integer> countStack = new ArrayDeque<>();\n        Deque<StringBuilder> stringStack = new ArrayDeque<>();\n        StringBuilder current = new StringBuilder();\n        int k = 0;\n\n        for (char c : s.toCharArray()) {\n            if (Character.isDigit(c)) {\n                k = k * 10 + (c - \'0\');\n            } else if (c == \'[\') {\n                countStack.push(k);\n                stringStack.push(current);\n                current = new StringBuilder();\n                k = 0;\n            } else if (c == \']\') {\n                int repeat = countStack.pop();\n                StringBuilder prev = stringStack.pop();\n                for (int i = 0; i < repeat; i++) {\n                    prev.append(current);\n                }\n                current = prev;\n            } else {\n                current.append(c);\n            }\n        }\n\n        return current.toString();\n    }\n}', NULL, 1),
(359, 'JAVASCRIPT', 'const readline = require(\'readline\');\n\nconst rl = readline.createInterface({\n    input: process.stdin,\n    output: process.stdout\n});\n\nrl.on(\'line\', (line) => {\n    console.log(decodeString(line));\n    rl.close();\n});\n\nfunction decodeString(s) {\n    const countStack = [];\n    const stringStack = [];\n    let current = \'\';\n    let k = 0;\n\n    for (const c of s) {\n        if (c >= \'0\' && c <= \'9\') {\n            k = k * 10 + (c.charCodeAt(0) - \'0\'.charCodeAt(0));\n        } else if (c === \'[\') {\n            countStack.push(k);\n            stringStack.push(current);\n            current = \'\';\n            k = 0;\n        } else if (c === \']\') {\n            const repeat = countStack.pop();\n            const prev = stringStack.pop();\n            current = prev + current.repeat(repeat);\n        } else {\n            current += c;\n        }\n    }\n\n    return current;\n}', NULL, 1),
(359, 'PYTHON', 'import sys\n\ndef decodeString(s: str) -> str:\n    count_stack = []\n    string_stack = []\n    current = []\n    k = 0\n\n    for c in s:\n        if c.isdigit():\n            k = k * 10 + int(c)\n        elif c == \'[\':\n            count_stack.append(k)\n            string_stack.append(current)\n            current = []\n            k = 0\n        elif c == \']\':\n            repeat = count_stack.pop()\n            prev = string_stack.pop()\n            for _ in range(repeat):\n                prev.extend(current)\n            current = prev\n        else:\n            current.append(c)\n\n    return \'\'.join(current)\n\nif __name__ == \"__main__\":\n    line = sys.stdin.readline()\n    if line:\n        s = line.rstrip(\'\\n\')\n        print(decodeString(s))', NULL, 1),
(360, 'C', '#include <stdio.h>\n#include <stdbool.h>\n\nint main() {\n    int n;\n    scanf(\"%d\", &n);\n    int nums[n];\n    int sum = 0;\n    for (int i = 0; i < n; i++) {\n        scanf(\"%d\", &nums[i]);\n        sum += nums[i];\n    }\n    if (sum % 2 != 0) {\n        printf(\"false\\n\");\n        return 0;\n    }\n    int target = sum / 2;\n    bool dp[target + 1];\n    for (int i = 0; i <= target; i++) {\n        dp[i] = false;\n    }\n    dp[0] = true;\n    for (int i = 0; i < n; i++) {\n        int num = nums[i];\n        for (int j = target; j >= num; j--) {\n            dp[j] = dp[j] || dp[j - num];\n        }\n    }\n    if (dp[target]) {\n        printf(\"true\\n\");\n    } else {\n        printf(\"false\\n\");\n    }\n    return 0;\n}', NULL, 1),
(360, 'CPP', '#include <iostream>\n#include <vector>\nusing namespace std;\n\nint main() {\n    int n;\n    cin >> n;\n    vector<int> nums(n);\n    int sum = 0;\n    for (int i = 0; i < n; i++) {\n        cin >> nums[i];\n        sum += nums[i];\n    }\n    if (sum % 2 != 0) {\n        cout << \"false\" << endl;\n        return 0;\n    }\n    int target = sum / 2;\n    vector<bool> dp(target + 1, false);\n    dp[0] = true;\n    for (int num : nums) {\n        for (int j = target; j >= num; j--) {\n            dp[j] = dp[j] || dp[j - num];\n        }\n    }\n    cout << (dp[target] ? \"true\" : \"false\") << endl;\n    return 0;\n}', NULL, 1),
(360, 'JAVA', 'import java.util.Scanner;\n\npublic class Main {\n    public static void main(String[] args) {\n        Scanner sc = new Scanner(System.in);\n        int n = sc.nextInt();\n        int[] nums = new int[n];\n        int sum = 0;\n        for (int i = 0; i < n; i++) {\n            nums[i] = sc.nextInt();\n            sum += nums[i];\n        }\n        if (sum % 2 != 0) {\n            System.out.println(false);\n            return;\n        }\n        int target = sum / 2;\n        boolean[] dp = new boolean[target + 1];\n        dp[0] = true;\n        for (int num : nums) {\n            for (int j = target; j >= num; j--) {\n                dp[j] = dp[j] || dp[j - num];\n            }\n        }\n        System.out.println(dp[target]);\n    }\n}', NULL, 1),
(360, 'JAVASCRIPT', 'const readline = require(\'readline\');\n\nconst rl = readline.createInterface({\n    input: process.stdin,\n    output: process.stdout\n});\n\nlet lines = [];\nrl.on(\'line\', (line) => {\n    lines.push(line.trim());\n});\n\nrl.on(\'close\', () => {\n    const n = parseInt(lines[0]);\n    const nums = lines[1].split(\' \').map(Number);\n    let sum = 0;\n    for (let i = 0; i < n; i++) {\n        sum += nums[i];\n    }\n    if (sum % 2 !== 0) {\n        console.log(false);\n        return;\n    }\n    const target = sum / 2;\n    const dp = new Array(target + 1).fill(false);\n    dp[0] = true;\n    for (const num of nums) {\n        for (let j = target; j >= num; j--) {\n            dp[j] = dp[j] || dp[j - num];\n        }\n    }\n    console.log(dp[target]);\n});', NULL, 1),
(360, 'PYTHON', 'n = int(input())\nnums = list(map(int, input().split()))\ntotal = sum(nums)\nif total % 2 != 0:\n    print(\"false\")\nelse:\n    target = total // 2\n    dp = [False] * (target + 1)\n    dp[0] = True\n    for num in nums:\n        for j in range(target, num - 1, -1):\n            dp[j] = dp[j] or dp[j - num]\n    print(\"true\" if dp[target] else \"false\")', NULL, 1),
(361, 'C', '#include <stdio.h>\n#include <stdlib.h>\n\nint main() {\n    int n;\n    scanf(\"%d\", &n);\n    int *nums = (int *)malloc((n + 1) * sizeof(int));\n    for (int i = 0; i <= n; i++) {\n        scanf(\"%d\", &nums[i]);\n    }\n    int slow = nums[0];\n    int fast = nums[0];\n    do {\n        slow = nums[slow];\n        fast = nums[nums[fast]];\n    } while (slow != fast);\n    slow = nums[0];\n    while (slow != fast) {\n        slow = nums[slow];\n        fast = nums[fast];\n    }\n    printf(\"%d\\n\", slow);\n    free(nums);\n    return 0;\n}', NULL, 1),
(361, 'CPP', '#include <iostream>\n#include <vector>\nusing namespace std;\n\nint main() {\n    int n;\n    cin >> n;\n    vector<int> nums(n + 1);\n    for (int i = 0; i <= n; i++) {\n        cin >> nums[i];\n    }\n    int slow = nums[0];\n    int fast = nums[0];\n    do {\n        slow = nums[slow];\n        fast = nums[nums[fast]];\n    } while (slow != fast);\n    slow = nums[0];\n    while (slow != fast) {\n        slow = nums[slow];\n        fast = nums[fast];\n    }\n    cout << slow << endl;\n    return 0;\n}', NULL, 1),
(361, 'JAVA', 'import java.util.Scanner;\n\npublic class Main {\n    public static void main(String[] args) {\n        Scanner sc = new Scanner(System.in);\n        int n = sc.nextInt();\n        int[] nums = new int[n + 1];\n        for (int i = 0; i <= n; i++) {\n            nums[i] = sc.nextInt();\n        }\n        int slow = nums[0];\n        int fast = nums[0];\n        do {\n            slow = nums[slow];\n            fast = nums[nums[fast]];\n        } while (slow != fast);\n        slow = nums[0];\n        while (slow != fast) {\n            slow = nums[slow];\n            fast = nums[fast];\n        }\n        System.out.println(slow);\n    }\n}', NULL, 1),
(361, 'JAVASCRIPT', 'const readline = require(\'readline\');\n\nconst rl = readline.createInterface({\n    input: process.stdin,\n    output: process.stdout\n});\n\nlet lines = [];\nrl.on(\'line\', (line) => {\n    lines.push(line.trim());\n});\n\nrl.on(\'close\', () => {\n    const n = parseInt(lines[0]);\n    const nums = lines[1].split(\' \').map(Number);\n\n    let slow = nums[0];\n    let fast = nums[0];\n\n    do {\n        slow = nums[slow];\n        fast = nums[nums[fast]];\n    } while (slow !== fast);\n\n    slow = nums[0];\n    while (slow !== fast) {\n        slow = nums[slow];\n        fast = nums[fast];\n    }\n\n    console.log(slow);\n});', NULL, 1),
