(362, 'C', '#include <stdio.h>\n#include <limits.h>\n\nint main() {\n    int n;\n    scanf(\"%d\", &n);\n    int dp[n + 1];\n    dp[0] = 0;\n    for (int i = 1; i <= n; i++) {\n        dp[i] = INT_MAX;\n        for (int j = 1; j * j <= i; j++) {\n            if (dp[i - j * j] + 1 < dp[i]) {\n                dp[i] = dp[i - j * j] + 1;\n            }\n        }\n    }\n    printf(\"%d\\n\", dp[n]);\n    return 0;\n}', NULL, 1),
(362, 'CPP', '#include <iostream>\n#include <vector>\n#include <algorithm>\n#include <climits>\n\nint main() {\n    int n;\n    std::cin >> n;\n    std::vector<int> dp(n + 1);\n    for (int i = 1; i <= n; i++) {\n        dp[i] = INT_MAX;\n        for (int j = 1; j * j <= i; j++) {\n            dp[i] = std::min(dp[i], dp[i - j * j] + 1);\n        }\n    }\n    std::cout << dp[n] << std::endl;\n    return 0;\n}', NULL, 1),
(362, 'JAVA', 'import java.util.Scanner;\n\npublic class Main {\n    public static void main(String[] args) {\n        Scanner sc = new Scanner(System.in);\n        int n = sc.nextInt();\n        int[] dp = new int[n + 1];\n        for (int i = 1; i <= n; i++) {\n            dp[i] = Integer.MAX_VALUE;\n            for (int j = 1; j * j <= i; j++) {\n                dp[i] = Math.min(dp[i], dp[i - j * j] + 1);\n            }\n        }\n        System.out.println(dp[n]);\n    }\n}', NULL, 1),
(362, 'JAVASCRIPT', 'const readline = require(\'readline\');\n\nconst rl = readline.createInterface({\n    input: process.stdin,\n    output: process.stdout\n});\n\nrl.on(\'line\', (line) => {\n    const n = parseInt(line.trim(), 10);\n    const dp = new Array(n + 1).fill(0);\n    for (let i = 1; i <= n; i++) {\n        dp[i] = Number.MAX_SAFE_INTEGER;\n        for (let j = 1; j * j <= i; j++) {\n            dp[i] = Math.min(dp[i], dp[i - j * j] + 1);\n        }\n    }\n    console.log(dp[n]);\n    rl.close();\n});', NULL, 1),
