(363, 'C', '#include <stdio.h>\n#include <string.h>\n\nint main() {\n    char s[1005];\n    if (scanf(\"%s\", s) != 1) return 0;\n    int n = (int)strlen(s);\n    if (n == 0) {\n        printf(\"0\\n\");\n        return 0;\n    }\n\n    static int dp[1005][1005];\n    for (int i = 0; i < n; i++) {\n        dp[i][i] = 1;\n    }\n\n    for (int len = 2; len <= n; len++) {\n        for (int i = 0; i + len - 1 < n; i++) {\n            int j = i + len - 1;\n            if (s[i] == s[j]) {\n                if (len == 2) dp[i][j] = 2;\n                else dp[i][j] = dp[i + 1][j - 1] + 2;\n            } else {\n                int a = dp[i + 1][j];\n                int b = dp[i][j - 1];\n                dp[i][j] = a > b ? a : b;\n            }\n        }\n    }\n\n    printf(\"%d\\n\", dp[0][n - 1]);\n    return 0;\n}', NULL, 1),
(363, 'CPP', '#include <iostream>\n#include <string>\n#include <vector>\n#include <algorithm>\nusing namespace std;\n\nint main() {\n    string s;\n    getline(cin, s);\n    int n = s.length();\n    vector<vector<int>> dp(n, vector<int>(n, 0));\n    for (int i = 0; i < n; i++) {\n        dp[i][i] = 1;\n    }\n    for (int len = 2; len <= n; len++) {\n        for (int i = 0; i + len - 1 < n; i++) {\n            int j = i + len - 1;\n            if (s[i] == s[j]) {\n                dp[i][j] = dp[i + 1][j - 1] + 2;\n            } else {\n                dp[i][j] = max(dp[i + 1][j], dp[i][j - 1]);\n            }\n        }\n    }\n    cout << dp[0][n - 1] << endl;\n    return 0;\n}', NULL, 1),
(363, 'JAVA', 'import java.util.Scanner;\n\npublic class Main {\n    public static void main(String[] args) {\n        Scanner sc = new Scanner(System.in);\n        String s = sc.nextLine();\n        int n = s.length();\n        int[][] dp = new int[n][n];\n        for (int i = 0; i < n; i++) {\n            dp[i][i] = 1;\n        }\n        for (int len = 2; len <= n; len++) {\n            for (int i = 0; i + len - 1 < n; i++) {\n                int j = i + len - 1;\n                if (s.charAt(i) == s.charAt(j)) {\n                    dp[i][j] = dp[i + 1][j - 1] + 2;\n                } else {\n                    dp[i][j] = Math.max(dp[i + 1][j], dp[i][j - 1]);\n                }\n            }\n        }\n        System.out.println(dp[0][n - 1]);\n    }\n}', NULL, 1),
(363, 'JAVASCRIPT', 'const readline = require(\'readline\');\n\nconst rl = readline.createInterface({\n    input: process.stdin,\n    output: process.stdout\n});\n\nrl.on(\'line\', (s) => {\n    const n = s.length;\n    const dp = Array.from({ length: n }, () => new Array(n).fill(0));\n    for (let i = 0; i < n; i++) {\n        dp[i][i] = 1;\n    }\n    for (let len = 2; len <= n; len++) {\n        for (let i = 0; i + len - 1 < n; i++) {\n            const j = i + len - 1;\n            if (s[i] === s[j]) {\n                dp[i][j] = dp[i + 1][j - 1] + 2;\n            } else {\n                dp[i][j] = Math.max(dp[i + 1][j], dp[i][j - 1]);\n            }\n        }\n    }\n    console.log(dp[0][n - 1]);\n    rl.close();\n});', NULL, 1),
(363, 'PYTHON', 's = input().strip()\nn = len(s)\ndp = [[0] * n for _ in range(n)]\nfor i in range(n):\n    dp[i][i] = 1\nfor length in range(2, n + 1):\n    for i in range(n - length + 1):\n        j = i + length - 1\n        if s[i] == s[j]:\n            dp[i][j] = dp[i + 1][j - 1] + 2\n        else:\n            dp[i][j] = max(dp[i + 1][j], dp[i][j - 1])\nprint(dp[0][n - 1])', NULL, 1),
(364, 'C', '#include <stdio.h>\n#include <stdlib.h>\n\nint cmp(const void *a, const void *b) {\n    return (*(int *)a - *(int *)b);\n}\n\nint main() {\n    int n1, n2;\n    scanf(\"%d\", &n1);\n    int *nums1 = (int *)malloc(n1 * sizeof(int));\n    for (int i = 0; i < n1; i++) {\n        scanf(\"%d\", &nums1[i]);\n    }\n    scanf(\"%d\", &n2);\n    int *nums2 = (int *)malloc(n2 * sizeof(int));\n    for (int i = 0; i < n2; i++) {\n        scanf(\"%d\", &nums2[i]);\n    }\n\n    qsort(nums1, n1, sizeof(int), cmp);\n    qsort(nums2, n2, sizeof(int), cmp);\n\n    int *res = (int *)malloc((n1 < n2 ? n1 : n2) * sizeof(int));\n    int i = 0, j = 0, k = 0;\n    while (i < n1 && j < n2) {\n        if (nums1[i] < nums2[j]) {\n            i++;\n        } else if (nums1[i] > nums2[j]) {\n            j++;\n        } else {\n            res[k++] = nums1[i];\n            i++;\n            j++;\n        }\n    }\n\n    printf(\"[\");\n    for (int t = 0; t < k; t++) {\n        printf(\"%d\", res[t]);\n        if (t != k - 1) {\n            printf(\",\");\n        }\n    }\n    printf(\"]\\n\");\n\n    free(nums1);\n    free(nums2);\n    free(res);\n    return 0;\n}', NULL, 1),
(364, 'CPP', '#include <iostream>\n#include <vector>\n#include <unordered_map>\n#include <algorithm>\nusing namespace std;\n\nint main() {\n    int n1;\n    cin >> n1;\n    vector<int> nums1(n1);\n    for (int i = 0; i < n1; i++) {\n        cin >> nums1[i];\n    }\n\n    int n2;\n    cin >> n2;\n    vector<int> nums2(n2);\n    for (int i = 0; i < n2; i++) {\n        cin >> nums2[i];\n    }\n\n    unordered_map<int, int> map;\n    for (int num : nums1) {\n        map[num]++;\n    }\n\n    vector<int> res;\n    for (int num : nums2) {\n        if (map[num] > 0) {\n            res.push_back(num);\n            map[num]--;\n        }\n    }\n\n    sort(res.begin(), res.end());\n\n    cout << \"[\";\n    for (int i = 0; i < (int)res.size(); i++) {\n        cout << res[i];\n        if (i != (int)res.size() - 1) {\n            cout << \",\";\n        }\n    }\n    cout << \"]\" << endl;\n\n    return 0;\n}', NULL, 1),
(364, 'JAVA', 'import java.util.*;\n\npublic class Main {\n    public static void main(String[] args) {\n        Scanner sc = new Scanner(System.in);\n        int n1 = sc.nextInt();\n        int[] nums1 = new int[n1];\n        for (int i = 0; i < n1; i++) {\n            nums1[i] = sc.nextInt();\n        }\n        int n2 = sc.nextInt();\n        int[] nums2 = new int[n2];\n        for (int i = 0; i < n2; i++) {\n            nums2[i] = sc.nextInt();\n        }\n\n        Map<Integer, Integer> map = new HashMap<>();\n        for (int num : nums1) {\n            map.put(num, map.getOrDefault(num, 0) + 1);\n        }\n\n        List<Integer> res = new ArrayList<>();\n        for (int num : nums2) {\n            if (map.getOrDefault(num, 0) > 0) {\n                res.add(num);\n                map.put(num, map.get(num) - 1);\n            }\n        }\n\n        Collections.sort(res);\n\n        StringBuilder sb = new StringBuilder();\n        sb.append(\"[\");\n        for (int i = 0; i < res.size(); i++) {\n            sb.append(res.get(i));\n            if (i != res.size() - 1) {\n                sb.append(\",\");\n            }\n        }\n        sb.append(\"]\");\n        System.out.println(sb.toString());\n    }\n}', NULL, 1),
(364, 'JAVASCRIPT', 'const readline = require(\'readline\');\n\nconst rl = readline.createInterface({\n    input: process.stdin,\n    output: process.stdout\n});\n\nlet lines = [];\nrl.on(\'line\', (line) => {\n    lines.push(line.trim());\n});\n\nrl.on(\'close\', () => {\n    const n1 = parseInt(lines[0]);\n    const nums1 = lines[1].split(\' \').map(Number);\n    const n2 = parseInt(lines[2]);\n    const nums2 = lines[3].split(\' \').map(Number);\n\n    const map = new Map();\n    for (const num of nums1) {\n        map.set(num, (map.get(num) || 0) + 1);\n    }\n\n    const res = [];\n    for (const num of nums2) {\n        if ((map.get(num) || 0) > 0) {\n            res.push(num);\n            map.set(num, map.get(num) - 1);\n        }\n    }\n\n    res.sort((a, b) => a - b);\n\n    let sb = \'[\';\n    for (let i = 0; i < res.length; i++) {\n        sb += res[i];\n        if (i !== res.length - 1) {\n            sb += \',\';\n        }\n    }\n    sb += \']\';\n    console.log(sb);\n});', NULL, 1),
(364, 'PYTHON', 'import sys\nfrom collections import Counter\n\ndef main():\n    data = sys.stdin.read().split()\n    if not data:\n        return\n    idx = 0\n    n1 = int(data[idx]); idx += 1\n    nums1 = list(map(int, data[idx:idx+n1])); idx += n1\n    n2 = int(data[idx]); idx += 1\n    nums2 = list(map(int, data[idx:idx+n2])); idx += n2\n\n    count = Counter(nums1)\n    res = []\n    for num in nums2:\n        if count.get(num, 0) > 0:\n            res.append(num)\n            count[num] -= 1\n\n    res.sort()\n    print(\"[\" + \",\".join(map(str, res)) + \"]\")\n\nif __name__ == \"__main__\":\n    main()', NULL, 1),
(365, 'C', '#include <stdio.h>\n#include <stdlib.h>\n#include <string.h>\n\ntypedef struct ListNode {\n    int val;\n    struct ListNode *next;\n} ListNode;\n\nListNode* parseList(const char *s) {\n    if (s == NULL || s[0] == \'\\0\' || strcmp(s, \"NULL\") == 0) {\n        return NULL;\n    }\n    char *copy = strdup(s);\n    ListNode dummy = {0, NULL};\n    ListNode *cur = &dummy;\n    char *token = strtok(copy, \"->\");\n    while (token != NULL) {\n        if (strcmp(token, \"NULL\") == 0) {\n            break;\n        }\n        ListNode *node = (ListNode*)malloc(sizeof(ListNode));\n        node->val = atoi(token);\n        node->next = NULL;\n        cur->next = node;\n        cur = cur->next;\n        token = strtok(NULL, \"->\");\n    }\n    free(copy);\n    return dummy.next;\n}\n\nchar* formatList(ListNode *head) {\n    char *buf = (char*)malloc(100000);\n    buf[0] = \'\\0\';\n    ListNode *cur = head;\n    char temp[32];\n    while (cur != NULL) {\n        sprintf(temp, \"%d->\", cur->val);\n        strcat(buf, temp);\n        cur = cur->next;\n    }\n    strcat(buf, \"NULL\");\n    return buf;\n}\n\nListNode* addTwoNumbers(ListNode *l1, ListNode *l2) {\n    ListNode dummy = {0, NULL};\n    ListNode *cur = &dummy;\n    int carry = 0;\n    while (l1 != NULL || l2 != NULL || carry != 0) {\n        int x = (l1 != NULL) ? l1->val : 0;\n        int y = (l2 != NULL) ? l2->val : 0;\n        int sum = x + y + carry;\n        carry = sum / 10;\n        ListNode *node = (ListNode*)malloc(sizeof(ListNode));\n        node->val = sum % 10;\n        node->next = NULL;\n        cur->next = node;\n        cur = cur->next;\n        if (l1 != NULL) l1 = l1->next;\n        if (l2 != NULL) l2 = l2->next;\n    }\n    return dummy.next;\n}\n\nint main() {\n    char line1[100000];\n    char line2[100000];\n    if (fgets(line1, sizeof(line1), stdin) == NULL) return 0;\n    if (fgets(line2, sizeof(line2), stdin) == NULL) return 0;\n    line1[strcspn(line1, \"\\r\\n\")] = \'\\0\';\n    line2[strcspn(line2, \"\\r\\n\")] = \'\\0\';\n\n    ListNode *l1 = parseList(line1);\n    ListNode *l2 = parseList(line2);\n\n    ListNode *result = addTwoNumbers(l1, l2);\n    char *out = formatList(result);\n    printf(\"%s\\n\", out);\n\n    free(out);\n    return 0;\n}', NULL, 1),
(365, 'CPP', '#include <iostream>\n#include <string>\n#include <sstream>\nusing namespace std;\n\nstruct ListNode {\n    int val;\n    ListNode* next;\n    ListNode(int x) : val(x), next(nullptr) {}\n};\n\nListNode* parseList(const string& s) {\n    if (s.empty() || s == \"NULL\") return nullptr;\n    string str = s;\n    string token;\n    stringstream ss(str);\n    ListNode dummy(0);\n    ListNode* cur = &dummy;\n    while (getline(ss, token, \'-\')) {\n        if (token.empty() || token == \">\") continue;\n        if (token == \">NULL\" || token == \"NULL\") break;\n        if (token[0] == \'>\') token = token.substr(1);\n        if (token == \"NULL\") break;\n        cur->next = new ListNode(stoi(token));\n        cur = cur->next;\n    }\n    return dummy.next;\n}\n\nstring formatList(ListNode* head) {\n    string res;\n    ListNode* cur = head;\n    while (cur) {\n        res += to_string(cur->val) + \"->\";\n        cur = cur->next;\n    }\n    res += \"NULL\";\n    return res;\n}\n\nListNode* addTwoNumbers(ListNode* l1, ListNode* l2) {\n    ListNode dummy(0);\n    ListNode* cur = &dummy;\n    int carry = 0;\n    while (l1 || l2 || carry) {\n        int x = l1 ? l1->val : 0;\n        int y = l2 ? l2->val : 0;\n        int sum = x + y + carry;\n        carry = sum / 10;\n        cur->next = new ListNode(sum % 10);\n        cur = cur->next;\n        if (l1) l1 = l1->next;\n        if (l2) l2 = l2->next;\n    }\n    return dummy.next;\n}\n\nint main() {\n    string line1, line2;\n    getline(cin, line1);\n    getline(cin, line2);\n\n    ListNode* l1 = parseList(line1);\n    ListNode* l2 = parseList(line2);\n\n    ListNode* result = addTwoNumbers(l1, l2);\n    cout << formatList(result) << endl;\n\n    return 0;\n}', NULL, 1),
(365, 'JAVA', 'import java.util.Scanner;\n\npublic class Main {\n    static class ListNode {\n        int val;\n        ListNode next;\n        ListNode(int val) { this.val = val; }\n    }\n\n    public static void main(String[] args) {\n        Scanner sc = new Scanner(System.in);\n        String line1 = sc.nextLine().trim();\n        String line2 = sc.nextLine().trim();\n\n        ListNode l1 = parseList(line1);\n        ListNode l2 = parseList(line2);\n\n        ListNode result = addTwoNumbers(l1, l2);\n        System.out.println(formatList(result));\n    }\n\n    private static ListNode parseList(String s) {\n        if (s == null || s.isEmpty() || s.equals(\"NULL\")) {\n            return null;\n        }\n        String[] parts = s.split(\"->\");\n        ListNode dummy = new ListNode(0);\n        ListNode cur = dummy;\n        for (String part : parts) {\n            if (part.equals(\"NULL\")) {\n                break;\n            }\n            cur.next = new ListNode(Integer.parseInt(part.trim()));\n            cur = cur.next;\n        }\n        return dummy.next;\n    }\n\n    private static String formatList(ListNode head) {\n        StringBuilder sb = new StringBuilder();\n        ListNode cur = head;\n        while (cur != null) {\n            sb.append(cur.val).append(\"->\");\n            cur = cur.next;\n        }\n        sb.append(\"NULL\");\n        return sb.toString();\n    }\n\n    private static ListNode addTwoNumbers(ListNode l1, ListNode l2) {\n        ListNode dummy = new ListNode(0);\n        ListNode cur = dummy;\n        int carry = 0;\n        while (l1 != null || l2 != null || carry != 0) {\n            int x = (l1 != null) ? l1.val : 0;\n            int y = (l2 != null) ? l2.val : 0;\n            int sum = x + y + carry;\n            carry = sum / 10;\n            cur.next = new ListNode(sum % 10);\n            cur = cur.next;\n            if (l1 != null) l1 = l1.next;\n            if (l2 != null) l2 = l2.next;\n        }\n        return dummy.next;\n    }\n}', NULL, 1),
(365, 'JAVASCRIPT', 'const readline = require(\'readline\');\n\nclass ListNode {\n    constructor(val) {\n        this.val = val;\n        this.next = null;\n    }\n}\n\nfunction parseList(s) {\n    if (!s || s === \'NULL\') return null;\n    const parts = s.split(\'->\');\n    const dummy = new ListNode(0);\n    let cur = dummy;\n    for (const part of parts) {\n        if (part === \'NULL\') break;\n        cur.next = new ListNode(parseInt(part.trim(), 10));\n        cur = cur.next;\n    }\n    return dummy.next;\n}\n\nfunction formatList(head) {\n    let sb = \'\';\n    let cur = head;\n    while (cur !== null) {\n        sb += cur.val + \'->\';\n        cur = cur.next;\n    }\n    sb += \'NULL\';\n    return sb;\n}\n\nfunction addTwoNumbers(l1, l2) {\n    const dummy = new ListNode(0);\n    let cur = dummy;\n    let carry = 0;\n    while (l1 !== null || l2 !== null || carry !== 0) {\n        const x = l1 !== null ? l1.val : 0;\n        const y = l2 !== null ? l2.val : 0;\n        const sum = x + y + carry;\n        carry = Math.floor(sum / 10);\n        cur.next = new ListNode(sum % 10);\n        cur = cur.next;\n        if (l1 !== null) l1 = l1.next;\n        if (l2 !== null) l2 = l2.next;\n    }\n    return dummy.next;\n}\n\nconst rl = readline.createInterface({\n    input: process.stdin,\n    output: process.stdout\n});\n\nconst lines = [];\nrl.on(\'line\', (line) => {\n    lines.push(line.trim());\n    if (lines.length === 2) {\n        const l1 = parseList(lines[0]);\n        const l2 = parseList(lines[1]);\n        const result = addTwoNumbers(l1, l2);\n        console.log(formatList(result));\n        rl.close();\n    }\n});', NULL, 1),
(365, 'PYTHON', 'import sys\n\nclass ListNode:\n    def __init__(self, val=0):\n        self.val = val\n        self.next = None\n\ndef parse_list(s):\n    if s is None or s == \"\" or s == \"NULL\":\n        return None\n    parts = s.split(\"->\")\n    dummy = ListNode(0)\n    cur = dummy\n    for part in parts:\n        if part == \"NULL\":\n            break\n        cur.next = ListNode(int(part.strip()))\n        cur = cur.next\n    return dummy.next\n\ndef format_list(head):\n    sb = []\n    cur = head\n    while cur is not None:\n        sb.append(str(cur.val))\n        sb.append(\"->\")\n        cur = cur.next\n    sb.append(\"NULL\")\n    return \"\".join(sb)\n\ndef add_two_numbers(l1, l2):\n    dummy = ListNode(0)\n    cur = dummy\n    carry = 0\n    while l1 is not None or l2 is not None or carry != 0:\n        x = l1.val if l1 is not None else 0\n        y = l2.val if l2 is not None else 0\n        total = x + y + carry\n        carry = total // 10\n        cur.next = ListNode(total % 10)\n        cur = cur.next\n        if l1 is not None:\n            l1 = l1.next\n        if l2 is not None:\n            l2 = l2.next\n    return dummy.next\n\ndef main():\n    lines = sys.stdin.read().strip().splitlines()\n    line1 = lines[0].strip()\n    line2 = lines[1].strip()\n\n    l1 = parse_list(line1)\n    l2 = parse_list(line2)\n\n    result = add_two_numbers(l1, l2)\n    print(format_list(result))\n\nif __name__ == \"__main__\":\n    main()', NULL, 1),
(366, 'C', '#include <stdio.h>\n#include <stdlib.h>\n\ntypedef struct {\n    int *data;\n    int size;\n    int capacity;\n} HashSet;\n\nunsigned int hash(int x) {\n    return (unsigned int)x * 2654435761u;\n}\n\nHashSet* createHashSet(int capacity) {\n    HashSet *set = (HashSet*)malloc(sizeof(HashSet));\n    set->capacity = capacity;\n    set->size = 0;\n    set->data = (int*)calloc(capacity, sizeof(int));\n    for (int i = 0; i < capacity; i++) {\n        set->data[i] = 0;\n    }\n    return set;\n}\n\nvoid freeHashSet(HashSet *set) {\n    free(set->data);\n    free(set);\n}\n\nint contains(HashSet *set, int x) {\n    unsigned int h = hash(x) % set->capacity;\n    while (set->data[h] != 0) {\n        if (set->data[h] == x) return 1;\n        h = (h + 1) % set->capacity;\n    }\n    return 0;\n}\n\nvoid add(HashSet *set, int x) {\n    if (contains(set, x)) return;\n    unsigned int h = hash(x) % set->capacity;\n    while (set->data[h] != 0) {\n        h = (h + 1) % set->capacity;\n    }\n    set->data[h] = x;\n    set->size++;\n}\n\nint main() {\n    int n;\n    scanf(\"%d\", &n);\n    int *nums = (int*)malloc(n * sizeof(int));\n    for (int i = 0; i < n; i++) {\n        scanf(\"%d\", &nums[i]);\n    }\n\n    HashSet *set = createHashSet(n * 2 + 1);\n    for (int i = 0; i < n; i++) {\n        add(set, nums[i]);\n    }\n\n    int maxLength = 0;\n    for (int i = 0; i < n; i++) {\n        int num = nums[i];\n        if (!contains(set, num - 1)) {\n            int currentNum = num;\n            int currentLength = 1;\n            while (contains(set, currentNum + 1)) {\n                currentNum++;\n                currentLength++;\n            }\n            if (currentLength > maxLength) {\n                maxLength = currentLength;\n            }\n        }\n    }\n\n    printf(\"%d\\n\", maxLength);\n\n    freeHashSet(set);\n    free(nums);\n    return 0;\n}', NULL, 1),
(366, 'CPP', '#include <iostream>\n#include <vector>\n#include <unordered_set>\n#include <algorithm>\n\nusing namespace std;\n\nint main() {\n    int n;\n    cin >> n;\n    vector<int> nums(n);\n    for (int i = 0; i < n; i++) {\n        cin >> nums[i];\n    }\n\n    unordered_set<int> set(nums.begin(), nums.end());\n\n    int maxLength = 0;\n    for (int num : set) {\n        if (set.find(num - 1) == set.end()) {\n            int currentNum = num;\n            int currentLength = 1;\n            while (set.find(currentNum + 1) != set.end()) {\n                currentNum++;\n                currentLength++;\n            }\n            maxLength = max(maxLength, currentLength);\n        }\n    }\n\n    cout << maxLength << endl;\n\n    return 0;\n}', NULL, 1),
(366, 'JAVA', 'import java.util.HashSet;\nimport java.util.Scanner;\nimport java.util.Set;\n\npublic class Main {\n    public static void main(String[] args) {\n        Scanner scanner = new Scanner(System.in);\n        int n = scanner.nextInt();\n        int[] nums = new int[n];\n        for (int i = 0; i < n; i++) {\n            nums[i] = scanner.nextInt();\n        }\n        scanner.close();\n\n        Set<Integer> set = new HashSet<>();\n        for (int num : nums) {\n            set.add(num);\n        }\n\n        int maxLength = 0;\n        for (int num : set) {\n            if (!set.contains(num - 1)) {\n                int currentNum = num;\n                int currentLength = 1;\n                while (set.contains(currentNum + 1)) {\n                    currentNum++;\n                    currentLength++;\n                }\n                maxLength = Math.max(maxLength, currentLength);\n            }\n        }\n\n        System.out.println(maxLength);\n    }\n}', NULL, 1),
(366, 'JAVASCRIPT', 'const readline = require(\'readline\');\n\nconst rl = readline.createInterface({\n    input: process.stdin,\n    output: process.stdout\n});\n\nlet lines = [];\nrl.on(\'line\', (line) => {\n    lines.push(line.trim());\n});\n\nrl.on(\'close\', () => {\n    const n = parseInt(lines[0]);\n    const nums = lines[1].split(\' \').map(Number);\n\n    const set = new Set(nums);\n\n    let maxLength = 0;\n    for (const num of set) {\n        if (!set.has(num - 1)) {\n            let currentNum = num;\n            let currentLength = 1;\n            while (set.has(currentNum + 1)) {\n                currentNum++;\n                currentLength++;\n            }\n            maxLength = Math.max(maxLength, currentLength);\n        }\n    }\n\n    console.log(maxLength);\n});', NULL, 1),
(366, 'PYTHON', 'n = int(input())\nnums = list(map(int, input().split()))\n\nnum_set = set(nums)\nmax_length = 0\n\nfor num in num_set:\n    if num - 1 not in num_set:\n        current_num = num\n        current_length = 1\n        while current_num + 1 in num_set:\n            current_num += 1\n            current_length += 1\n        max_length = max(max_length, current_length)\n\nprint(max_length)', NULL, 1),
(367, 'C', '#include <stdio.h>\n\nint main() {\n    int m, n;\n    scanf(\"%d %d\", &m, &n);\n    int nums1[m + n];\n    int nums2[n];\n    for (int i = 0; i < m; i++) {\n        scanf(\"%d\", &nums1[i]);\n    }\n    for (int i = 0; i < n; i++) {\n        scanf(\"%d\", &nums2[i]);\n    }\n    int i = m - 1, j = n - 1, k = m + n - 1;\n    while (i >= 0 && j >= 0) {\n        if (nums1[i] > nums2[j]) {\n            nums1[k--] = nums1[i--];\n        } else {\n            nums1[k--] = nums2[j--];\n        }\n    }\n    while (j >= 0) {\n        nums1[k--] = nums2[j--];\n    }\n    for (int x = 0; x < m + n; x++) {\n        if (x > 0) printf(\" \");\n        printf(\"%d\", nums1[x]);\n    }\n    printf(\"\\n\");\n    return 0;\n}', NULL, 1),
(367, 'CPP', '#include <iostream>\n#include <vector>\nusing namespace std;\n\nint main() {\n    int m, n;\n    cin >> m >> n;\n    vector<int> nums1(m + n);\n    vector<int> nums2(n);\n    for (int i = 0; i < m; i++) {\n        cin >> nums1[i];\n    }\n    for (int i = 0; i < n; i++) {\n        cin >> nums2[i];\n    }\n    int i = m - 1, j = n - 1, k = m + n - 1;\n    while (i >= 0 && j >= 0) {\n        if (nums1[i] > nums2[j]) {\n            nums1[k--] = nums1[i--];\n        } else {\n            nums1[k--] = nums2[j--];\n        }\n    }\n    while (j >= 0) {\n        nums1[k--] = nums2[j--];\n    }\n    for (int x = 0; x < m + n; x++) {\n        if (x > 0) cout << \' \';\n        cout << nums1[x];\n    }\n    cout << endl;\n    return 0;\n}', NULL, 1),
(367, 'JAVA', 'import java.util.Scanner;\n\npublic class Main {\n    public static void main(String[] args) {\n        Scanner sc = new Scanner(System.in);\n        int m = sc.nextInt();\n        int n = sc.nextInt();\n        int[] nums1 = new int[m + n];\n        int[] nums2 = new int[n];\n        for (int i = 0; i < m; i++) {\n            nums1[i] = sc.nextInt();\n        }\n        for (int i = 0; i < n; i++) {\n            nums2[i] = sc.nextInt();\n        }\n        int i = m - 1, j = n - 1, k = m + n - 1;\n        while (i >= 0 && j >= 0) {\n            if (nums1[i] > nums2[j]) {\n                nums1[k--] = nums1[i--];\n            } else {\n                nums1[k--] = nums2[j--];\n            }\n        }\n        while (j >= 0) {\n            nums1[k--] = nums2[j--];\n        }\n        StringBuilder sb = new StringBuilder();\n        for (int x = 0; x < m + n; x++) {\n            if (x > 0) sb.append(\' \');\n            sb.append(nums1[x]);\n        }\n        System.out.println(sb.toString());\n    }\n}', NULL, 1),
(367, 'JAVASCRIPT', 'const readline = require(\'readline\');\n\nconst rl = readline.createInterface({\n    input: process.stdin,\n    output: process.stdout\n});\n\nlet lines = [];\nrl.on(\'line\', (line) => {\n    lines.push(line.trim());\n});\n\nrl.on(\'close\', () => {\n    const [m, n] = lines[0].split(\' \').map(Number);\n    const nums1 = new Array(m + n).fill(0);\n    const nums2 = new Array(n).fill(0);\n\n    if (m > 0) {\n        const arr1 = lines[1].split(\' \').map(Number);\n        for (let i = 0; i < m; i++) {\n            nums1[i] = arr1[i];\n        }\n    }\n\n    if (n > 0) {\n        const arr2 = lines[2].split(\' \').map(Number);\n        for (let i = 0; i < n; i++) {\n            nums2[i] = arr2[i];\n        }\n    }\n\n    let i = m - 1, j = n - 1, k = m + n - 1;\n    while (i >= 0 && j >= 0) {\n        if (nums1[i] > nums2[j]) {\n            nums1[k--] = nums1[i--];\n        } else {\n            nums1[k--] = nums2[j--];\n        }\n    }\n    while (j >= 0) {\n        nums1[k--] = nums2[j--];\n    }\n\n    let result = \'\';\n    for (let x = 0; x < m + n; x++) {\n        if (x > 0) result += \' \';\n        result += nums1[x];\n    }\n    console.log(result);\n});', NULL, 1),
(367, 'PYTHON', 'import sys\n\ndef main():\n    data = sys.stdin.read().split()\n    if not data:\n        return\n    m = int(data[0])\n    n = int(data[1])\n    nums1 = [0] * (m + n)\n    nums2 = [0] * n\n    idx = 2\n    for i in range(m):\n        nums1[i] = int(data[idx])\n        idx += 1\n    for i in range(n):\n        nums2[i] = int(data[idx])\n        idx += 1\n\n    i = m - 1\n    j = n - 1\n    k = m + n - 1\n    while i >= 0 and j >= 0:\n        if nums1[i] > nums2[j]:\n            nums1[k] = nums1[i]\n            i -= 1\n        else:\n            nums1[k] = nums2[j]\n            j -= 1\n        k -= 1\n    while j >= 0:\n        nums1[k] = nums2[j]\n        j -= 1\n        k -= 1\n\n    print(\' \'.join(map(str, nums1)))\n\nif __name__ == \"__main__\":\n    main()', NULL, 1),
(368, 'C', '#include <stdio.h>\n#include <stdlib.h>\n\nint main() {\n    int n;\n    scanf(\"%d\", &n);\n\n    int **matrix = (int **)malloc(n * sizeof(int *));\n    for (int i = 0; i < n; i++) {\n        matrix[i] = (int *)malloc(n * sizeof(int));\n    }\n\n    int top = 0, bottom = n - 1, left = 0, right = n - 1;\n    int num = 1;\n\n    while (num <= n * n) {\n        for (int i = left; i <= right; i++) {\n            matrix[top][i] = num++;\n        }\n        top++;\n        for (int i = top; i <= bottom; i++) {\n            matrix[i][right] = num++;\n        }\n        right--;\n        for (int i = right; i >= left; i--) {\n            matrix[bottom][i] = num++;\n        }\n        bottom--;\n        for (int i = bottom; i >= top; i--) {\n            matrix[i][left] = num++;\n        }\n        left++;\n    }\n\n    for (int i = 0; i < n; i++) {\n        for (int j = 0; j < n; j++) {\n            printf(\"%d\", matrix[i][j]);\n            if (j < n - 1) {\n                printf(\" \");\n            }\n        }\n        printf(\"\\n\");\n    }\n\n    for (int i = 0; i < n; i++) {\n        free(matrix[i]);\n    }\n    free(matrix);\n\n    return 0;\n}', NULL, 1),
(368, 'CPP', '#include <iostream>\n#include <vector>\nusing namespace std;\n\nint main() {\n    int n;\n    cin >> n;\n    vector<vector<int>> matrix(n, vector<int>(n));\n    int top = 0, bottom = n - 1, left = 0, right = n - 1;\n    int num = 1;\n    while (num <= n * n) {\n        for (int i = left; i <= right; i++) {\n            matrix[top][i] = num++;\n        }\n        top++;\n        for (int i = top; i <= bottom; i++) {\n            matrix[i][right] = num++;\n        }\n        right--;\n        for (int i = right; i >= left; i--) {\n            matrix[bottom][i] = num++;\n        }\n        bottom--;\n        for (int i = bottom; i >= top; i--) {\n            matrix[i][left] = num++;\n        }\n        left++;\n    }\n    for (int i = 0; i < n; i++) {\n        for (int j = 0; j < n; j++) {\n            cout << matrix[i][j];\n            if (j < n - 1) {\n                cout << \' \';\n            }\n        }\n        cout << \'\\n\';\n    }\n    return 0;\n}', NULL, 1),
(368, 'JAVA', 'import java.util.Scanner;\n\npublic class Main {\n    public static void main(String[] args) {\n        Scanner sc = new Scanner(System.in);\n        int n = sc.nextInt();\n        int[][] matrix = new int[n][n];\n        int top = 0, bottom = n - 1, left = 0, right = n - 1;\n        int num = 1;\n        while (num <= n * n) {\n            for (int i = left; i <= right; i++) {\n                matrix[top][i] = num++;\n            }\n            top++;\n            for (int i = top; i <= bottom; i++) {\n                matrix[i][right] = num++;\n            }\n            right--;\n            for (int i = right; i >= left; i--) {\n                matrix[bottom][i] = num++;\n            }\n            bottom--;\n            for (int i = bottom; i >= top; i--) {\n                matrix[i][left] = num++;\n            }\n            left++;\n        }\n        StringBuilder sb = new StringBuilder();\n        for (int i = 0; i < n; i++) {\n            for (int j = 0; j < n; j++) {\n                sb.append(matrix[i][j]);\n                if (j < n - 1) {\n                    sb.append(\' \');\n                }\n            }\n            sb.append(\'\\n\');\n        }\n        System.out.print(sb);\n    }\n}', NULL, 1),
(368, 'JAVASCRIPT', 'const readline = require(\'readline\');\n\nconst rl = readline.createInterface({\n    input: process.stdin,\n    output: process.stdout\n});\n\nrl.on(\'line\', (line) => {\n    const n = parseInt(line.trim());\n    const matrix = Array.from({ length: n }, () => new Array(n).fill(0));\n    let top = 0, bottom = n - 1, left = 0, right = n - 1;\n    let num = 1;\n    while (num <= n * n) {\n        for (let i = left; i <= right; i++) {\n            matrix[top][i] = num++;\n        }\n        top++;\n        for (let i = top; i <= bottom; i++) {\n            matrix[i][right] = num++;\n        }\n        right--;\n        for (let i = right; i >= left; i--) {\n            matrix[bottom][i] = num++;\n        }\n        bottom--;\n        for (let i = bottom; i >= top; i--) {\n            matrix[i][left] = num++;\n        }\n        left++;\n    }\n    let sb = \'\';\n    for (let i = 0; i < n; i++) {\n        for (let j = 0; j < n; j++) {\n            sb += matrix[i][j];\n            if (j < n - 1) {\n                sb += \' \';\n            }\n        }\n        sb += \'\\n\';\n    }\n    process.stdout.write(sb);\n    rl.close();\n});', NULL, 1),
(368, 'PYTHON', 'n = int(input())\nmatrix = [[0] * n for _ in range(n)]\ntop, bottom, left, right = 0, n - 1, 0, n - 1\nnum = 1\nwhile num <= n * n:\n    for i in range(left, right + 1):\n        matrix[top][i] = num\n        num += 1\n    top += 1\n    for i in range(top, bottom + 1):\n        matrix[i][right] = num\n        num += 1\n    right -= 1\n    for i in range(right, left - 1, -1):\n        matrix[bottom][i] = num\n        num += 1\n    bottom -= 1\n    for i in range(bottom, top - 1, -1):\n        matrix[i][left] = num\n        num += 1\n    left += 1\n\nfor i in range(n):\n    print(\' \'.join(map(str, matrix[i])))', NULL, 1),
(369, 'C', '#include <stdio.h>\n\nint main() {\n    int n;\n    scanf(\"%d\", &n);\n    int nums[n];\n    for (int i = 0; i < n; i++) {\n        scanf(\"%d\", &nums[i]);\n    }\n    int jumps = 0;\n    int currentEnd = 0;\n    int farthest = 0;\n    for (int i = 0; i < n - 1; i++) {\n        if (i + nums[i] > farthest) {\n            farthest = i + nums[i];\n        }\n        if (i == currentEnd) {\n            jumps++;\n            currentEnd = farthest;\n        }\n    }\n    printf(\"%d\\n\", jumps);\n    return 0;\n}', NULL, 1),
(369, 'CPP', '#include <iostream>\n#include <vector>\n#include <algorithm>\nusing namespace std;\n\nint main() {\n    int n;\n    cin >> n;\n    vector<int> nums(n);\n    for (int i = 0; i < n; i++) {\n        cin >> nums[i];\n    }\n    int jumps = 0;\n    int currentEnd = 0;\n    int farthest = 0;\n    for (int i = 0; i < n - 1; i++) {\n        farthest = max(farthest, i + nums[i]);\n        if (i == currentEnd) {\n            jumps++;\n            currentEnd = farthest;\n        }\n    }\n    cout << jumps << endl;\n    return 0;\n}', NULL, 1),
(369, 'JAVA', 'import java.util.Scanner;\n\npublic class Main {\n    public static void main(String[] args) {\n        Scanner sc = new Scanner(System.in);\n        int n = sc.nextInt();\n        int[] nums = new int[n];\n        for (int i = 0; i < n; i++) {\n            nums[i] = sc.nextInt();\n        }\n        int jumps = 0;\n        int currentEnd = 0;\n        int farthest = 0;\n        for (int i = 0; i < n - 1; i++) {\n            farthest = Math.max(farthest, i + nums[i]);\n            if (i == currentEnd) {\n                jumps++;\n                currentEnd = farthest;\n            }\n        }\n        System.out.println(jumps);\n    }\n}', NULL, 1),
(369, 'JAVASCRIPT', 'const readline = require(\'readline\');\n\nconst rl = readline.createInterface({\n    input: process.stdin,\n    output: process.stdout\n});\n\nlet lines = [];\nrl.on(\'line\', (line) => {\n    lines.push(line.trim());\n});\n\nrl.on(\'close\', () => {\n    const n = parseInt(lines[0]);\n    const nums = lines[1].split(\' \').map(Number);\n    let jumps = 0;\n    let currentEnd = 0;\n    let farthest = 0;\n    for (let i = 0; i < n - 1; i++) {\n        farthest = Math.max(farthest, i + nums[i]);\n        if (i === currentEnd) {\n            jumps++;\n            currentEnd = farthest;\n        }\n    }\n    console.log(jumps);\n});', NULL, 1),
