(370, 'C', '#include <stdio.h>\n#include <stdlib.h>\n\nint cmp(const void *a, const void *b) {\n    return (*(int *)a - *(int *)b);\n}\n\nint main() {\n    int n;\n    scanf(\"%d\", &n);\n    int *nums = (int *)malloc(n * sizeof(int));\n    for (int i = 0; i < n; i++) {\n        scanf(\"%d\", &nums[i]);\n    }\n\n    int cand1 = 0, cand2 = 0;\n    int count1 = 0, count2 = 0;\n\n    for (int i = 0; i < n; i++) {\n        int num = nums[i];\n        if (num == cand1) {\n            count1++;\n        } else if (num == cand2) {\n            count2++;\n        } else if (count1 == 0) {\n            cand1 = num;\n            count1 = 1;\n        } else if (count2 == 0) {\n            cand2 = num;\n            count2 = 1;\n        } else {\n            count1--;\n            count2--;\n        }\n    }\n\n    count1 = 0;\n    count2 = 0;\n    for (int i = 0; i < n; i++) {\n        if (nums[i] == cand1) count1++;\n        else if (nums[i] == cand2) count2++;\n    }\n\n    int result[2];\n    int size = 0;\n    if (count1 > n / 3) result[size++] = cand1;\n    if (count2 > n / 3) result[size++] = cand2;\n\n    qsort(result, size, sizeof(int), cmp);\n\n    printf(\"[\");\n    for (int i = 0; i < size; i++) {\n        if (i > 0) printf(\",\");\n        printf(\"%d\", result[i]);\n    }\n    printf(\"]\\n\");\n\n    free(nums);\n    return 0;\n}', NULL, 1),
(370, 'CPP', '#include <iostream>\n#include <vector>\n#include <algorithm>\nusing namespace std;\n\nint main() {\n    int n;\n    cin >> n;\n    vector<int> nums(n);\n    for (int i = 0; i < n; i++) {\n        cin >> nums[i];\n    }\n\n    int cand1 = 0, cand2 = 0;\n    int count1 = 0, count2 = 0;\n\n    for (int num : nums) {\n        if (num == cand1) {\n            count1++;\n        } else if (num == cand2) {\n            count2++;\n        } else if (count1 == 0) {\n            cand1 = num;\n            count1 = 1;\n        } else if (count2 == 0) {\n            cand2 = num;\n            count2 = 1;\n        } else {\n            count1--;\n            count2--;\n        }\n    }\n\n    count1 = 0;\n    count2 = 0;\n    for (int num : nums) {\n        if (num == cand1) count1++;\n        else if (num == cand2) count2++;\n    }\n\n    vector<int> result;\n    if (count1 > n / 3) result.push_back(cand1);\n    if (count2 > n / 3) result.push_back(cand2);\n\n    sort(result.begin(), result.end());\n\n    cout << \"[\";\n    for (int i = 0; i < (int)result.size(); i++) {\n        if (i > 0) cout << \",\";\n        cout << result[i];\n    }\n    cout << \"]\" << endl;\n\n    return 0;\n}', NULL, 1),
(370, 'JAVA', 'import java.util.*;\n\npublic class Main {\n    public static void main(String[] args) {\n        Scanner sc = new Scanner(System.in);\n        int n = sc.nextInt();\n        int[] nums = new int[n];\n        for (int i = 0; i < n; i++) {\n            nums[i] = sc.nextInt();\n        }\n\n        int cand1 = 0, cand2 = 0;\n        int count1 = 0, count2 = 0;\n\n        for (int num : nums) {\n            if (num == cand1) {\n                count1++;\n            } else if (num == cand2) {\n                count2++;\n            } else if (count1 == 0) {\n                cand1 = num;\n                count1 = 1;\n            } else if (count2 == 0) {\n                cand2 = num;\n                count2 = 1;\n            } else {\n                count1--;\n                count2--;\n            }\n        }\n\n        count1 = 0;\n        count2 = 0;\n        for (int num : nums) {\n            if (num == cand1) count1++;\n            else if (num == cand2) count2++;\n        }\n\n        List<Integer> result = new ArrayList<>();\n        if (count1 > n / 3) result.add(cand1);\n        if (count2 > n / 3) result.add(cand2);\n\n        Collections.sort(result);\n\n        StringBuilder sb = new StringBuilder();\n        sb.append(\"[\");\n        for (int i = 0; i < result.size(); i++) {\n            if (i > 0) sb.append(\",\");\n            sb.append(result.get(i));\n        }\n        sb.append(\"]\");\n        System.out.println(sb.toString());\n    }\n}', NULL, 1),
(370, 'JAVASCRIPT', 'const readline = require(\'readline\');\n\nconst rl = readline.createInterface({\n  input: process.stdin,\n  output: process.stdout\n});\n\nlet lines = [];\nrl.on(\'line\', (line) => {\n  lines.push(line.trim());\n});\n\nrl.on(\'close\', () => {\n  const n = parseInt(lines[0]);\n  const nums = lines[1].split(/\\s+/).map(Number);\n\n  let cand1 = 0, cand2 = 0;\n  let count1 = 0, count2 = 0;\n\n  for (let num of nums) {\n    if (num === cand1) {\n      count1++;\n    } else if (num === cand2) {\n      count2++;\n    } else if (count1 === 0) {\n      cand1 = num;\n      count1 = 1;\n    } else if (count2 === 0) {\n      cand2 = num;\n      count2 = 1;\n    } else {\n      count1--;\n      count2--;\n    }\n  }\n\n  count1 = 0;\n  count2 = 0;\n  for (let num of nums) {\n    if (num === cand1) count1++;\n    else if (num === cand2) count2++;\n  }\n\n  let result = [];\n  if (count1 > Math.floor(n / 3)) result.push(cand1);\n  if (count2 > Math.floor(n / 3)) result.push(cand2);\n\n  result.sort((a, b) => a - b);\n\n  console.log(\'[\' + result.join(\',\') + \']\');\n});', NULL, 1),
(370, 'PYTHON', 'n = int(input())\nnums = list(map(int, input().split()))\n\ncand1, cand2 = 0, 0\ncount1, count2 = 0, 0\n\nfor num in nums:\n    if num == cand1:\n        count1 += 1\n    elif num == cand2:\n        count2 += 1\n    elif count1 == 0:\n        cand1 = num\n        count1 = 1\n    elif count2 == 0:\n        cand2 = num\n        count2 = 1\n    else:\n        count1 -= 1\n        count2 -= 1\n\ncount1 = 0\ncount2 = 0\nfor num in nums:\n    if num == cand1:\n        count1 += 1\n    elif num == cand2:\n        count2 += 1\n\nresult = []\nif count1 > n // 3:\n    result.append(cand1)\nif count2 > n // 3:\n    result.append(cand2)\n\nresult.sort()\n\nprint(\"[\" + \",\".join(map(str, result)) + \"]\")', NULL, 1),
(371, 'C', '#include <stdio.h>\n#include <stdlib.h>\n\nint main() {\n    int m, n;\n    scanf(\"%d %d\", &m, &n);\n    \n    int **board = (int **)malloc(m * sizeof(int *));\n    for (int i = 0; i < m; i++) {\n        board[i] = (int *)malloc(n * sizeof(int));\n    }\n    \n    char *line = (char *)malloc((n + 2) * sizeof(char));\n    for (int i = 0; i < m; i++) {\n        scanf(\"%s\", line);\n        for (int j = 0; j < n; j++) {\n            board[i][j] = line[j] - \'0\';\n        }\n    }\n    \n    int **next = (int **)malloc(m * sizeof(int *));\n    for (int i = 0; i < m; i++) {\n        next[i] = (int *)malloc(n * sizeof(int));\n    }\n    \n    int dx[] = {-1, -1, -1, 0, 0, 1, 1, 1};\n    int dy[] = {-1, 0, 1, -1, 1, -1, 0, 1};\n    \n    for (int i = 0; i < m; i++) {\n        for (int j = 0; j < n; j++) {\n            int liveNeighbors = 0;\n            for (int k = 0; k < 8; k++) {\n                int ni = i + dx[k];\n                int nj = j + dy[k];\n                if (ni >= 0 && ni < m && nj >= 0 && nj < n) {\n                    liveNeighbors += board[ni][nj];\n                }\n            }\n            if (board[i][j] == 1) {\n                if (liveNeighbors == 2 || liveNeighbors == 3) {\n                    next[i][j] = 1;\n                } else {\n                    next[i][j] = 0;\n                }\n            } else {\n                if (liveNeighbors == 3) {\n                    next[i][j] = 1;\n                } else {\n                    next[i][j] = 0;\n                }\n            }\n        }\n    }\n    \n    for (int i = 0; i < m; i++) {\n        for (int j = 0; j < n; j++) {\n            printf(\"%d\", next[i][j]);\n        }\n        if (i < m - 1) {\n            printf(\"\\n\");\n        }\n    }\n    \n    for (int i = 0; i < m; i++) {\n        free(board[i]);\n        free(next[i]);\n    }\n    free(board);\n    free(next);\n    free(line);\n    \n    return 0;\n}', NULL, 1),
(371, 'CPP', '#include <iostream>\n#include <vector>\n#include <string>\nusing namespace std;\n\nint main() {\n    int m, n;\n    cin >> m >> n;\n    cin.ignore();\n    vector<vector<int>> board(m, vector<int>(n));\n    for (int i = 0; i < m; i++) {\n        string line;\n        getline(cin, line);\n        while (!line.empty() && (line.back() == \'\\r\' || line.back() == \'\\n\' || line.back() == \' \')) {\n            line.pop_back();\n        }\n        for (int j = 0; j < n; j++) {\n            board[i][j] = line[j] - \'0\';\n        }\n    }\n\n    vector<vector<int>> next(m, vector<int>(n));\n    int dx[8] = {-1, -1, -1, 0, 0, 1, 1, 1};\n    int dy[8] = {-1, 0, 1, -1, 1, -1, 0, 1};\n\n    for (int i = 0; i < m; i++) {\n        for (int j = 0; j < n; j++) {\n            int liveNeighbors = 0;\n            for (int k = 0; k < 8; k++) {\n                int ni = i + dx[k];\n                int nj = j + dy[k];\n                if (ni >= 0 && ni < m && nj >= 0 && nj < n) {\n                    liveNeighbors += board[ni][nj];\n                }\n            }\n            if (board[i][j] == 1) {\n                if (liveNeighbors == 2 || liveNeighbors == 3) {\n                    next[i][j] = 1;\n                } else {\n                    next[i][j] = 0;\n                }\n            } else {\n                if (liveNeighbors == 3) {\n                    next[i][j] = 1;\n                } else {\n                    next[i][j] = 0;\n                }\n            }\n        }\n    }\n\n    for (int i = 0; i < m; i++) {\n        for (int j = 0; j < n; j++) {\n            cout << next[i][j];\n        }\n        if (i < m - 1) {\n            cout << \'\\n\';\n        }\n    }\n    return 0;\n}', NULL, 1),
(371, 'JAVA', 'import java.util.Scanner;\n\npublic class Main {\n    public static void main(String[] args) {\n        Scanner sc = new Scanner(System.in);\n        int m = sc.nextInt();\n        int n = sc.nextInt();\n        sc.nextLine();\n        int[][] board = new int[m][n];\n        for (int i = 0; i < m; i++) {\n            String line = sc.nextLine().trim();\n            for (int j = 0; j < n; j++) {\n                board[i][j] = line.charAt(j) - \'0\';\n            }\n        }\n\n        int[][] next = new int[m][n];\n        int[] dx = {-1, -1, -1, 0, 0, 1, 1, 1};\n        int[] dy = {-1, 0, 1, -1, 1, -1, 0, 1};\n\n        for (int i = 0; i < m; i++) {\n            for (int j = 0; j < n; j++) {\n                int liveNeighbors = 0;\n                for (int k = 0; k < 8; k++) {\n                    int ni = i + dx[k];\n                    int nj = j + dy[k];\n                    if (ni >= 0 && ni < m && nj >= 0 && nj < n) {\n                        liveNeighbors += board[ni][nj];\n                    }\n                }\n                if (board[i][j] == 1) {\n                    if (liveNeighbors == 2 || liveNeighbors == 3) {\n                        next[i][j] = 1;\n                    } else {\n                        next[i][j] = 0;\n                    }\n                } else {\n                    if (liveNeighbors == 3) {\n                        next[i][j] = 1;\n                    } else {\n                        next[i][j] = 0;\n                    }\n                }\n            }\n        }\n\n        StringBuilder sb = new StringBuilder();\n        for (int i = 0; i < m; i++) {\n            for (int j = 0; j < n; j++) {\n                sb.append(next[i][j]);\n            }\n            if (i < m - 1) {\n                sb.append(\'\\n\');\n            }\n        }\n        System.out.print(sb.toString());\n    }\n}', NULL, 1),
(371, 'JAVASCRIPT', 'const readline = require(\'readline\');\n\nconst rl = readline.createInterface({\n    input: process.stdin,\n    output: process.stdout\n});\n\nlet lines = [];\nrl.on(\'line\', (line) => {\n    lines.push(line);\n});\n\nrl.on(\'close\', () => {\n    const firstLine = lines[0].trim().split(/\\s+/);\n    const m = parseInt(firstLine[0], 10);\n    const n = parseInt(firstLine[1], 10);\n\n    const board = [];\n    for (let i = 0; i < m; i++) {\n        const line = lines[i + 1].trim();\n        const row = [];\n        for (let j = 0; j < n; j++) {\n            row.push(line.charCodeAt(j) - 48);\n        }\n        board.push(row);\n    }\n\n    const next = [];\n    for (let i = 0; i < m; i++) {\n        next.push(new Array(n).fill(0));\n    }\n\n    const dx = [-1, -1, -1, 0, 0, 1, 1, 1];\n    const dy = [-1, 0, 1, -1, 1, -1, 0, 1];\n\n    for (let i = 0; i < m; i++) {\n        for (let j = 0; j < n; j++) {\n            let liveNeighbors = 0;\n            for (let k = 0; k < 8; k++) {\n                const ni = i + dx[k];\n                const nj = j + dy[k];\n                if (ni >= 0 && ni < m && nj >= 0 && nj < n) {\n                    liveNeighbors += board[ni][nj];\n                }\n            }\n            if (board[i][j] === 1) {\n                if (liveNeighbors === 2 || liveNeighbors === 3) {\n                    next[i][j] = 1;\n                } else {\n                    next[i][j] = 0;\n                }\n            } else {\n                if (liveNeighbors === 3) {\n                    next[i][j] = 1;\n                } else {\n                    next[i][j] = 0;\n                }\n            }\n        }\n    }\n\n    let sb = \'\';\n    for (let i = 0; i < m; i++) {\n        for (let j = 0; j < n; j++) {\n            sb += next[i][j];\n        }\n        if (i < m - 1) {\n            sb += \'\\n\';\n        }\n    }\n    process.stdout.write(sb);\n});', NULL, 1),
(371, 'PYTHON', 'import sys\n\ndef main():\n    data = sys.stdin.read().splitlines()\n    if not data:\n        return\n    m, n = map(int, data[0].split())\n    board = []\n    for i in range(1, m + 1):\n        line = data[i].strip()\n        board.append([int(c) for c in line])\n\n    next_board = [[0] * n for _ in range(m)]\n    dx = [-1, -1, -1, 0, 0, 1, 1, 1]\n    dy = [-1, 0, 1, -1, 1, -1, 0, 1]\n\n    for i in range(m):\n        for j in range(n):\n            live_neighbors = 0\n            for k in range(8):\n                ni = i + dx[k]\n                nj = j + dy[k]\n                if 0 <= ni < m and 0 <= nj < n:\n                    live_neighbors += board[ni][nj]\n            if board[i][j] == 1:\n                if live_neighbors == 2 or live_neighbors == 3:\n                    next_board[i][j] = 1\n                else:\n                    next_board[i][j] = 0\n            else:\n                if live_neighbors == 3:\n                    next_board[i][j] = 1\n                else:\n                    next_board[i][j] = 0\n\n    output = []\n    for i in range(m):\n        output.append(\'\'.join(str(x) for x in next_board[i]))\n    sys.stdout.write(\'\\n\'.join(output))\n\nif __name__ == \"__main__\":\n    main()', NULL, 1),
(372, 'C', '#include <stdio.h>\n#include <stdlib.h>\n#include <string.h>\n#include <ctype.h>\n\nint main() {\n    char s[1000005];\n    if (fgets(s, sizeof(s), stdin) == NULL) return 0;\n    int len = strlen(s);\n    while (len > 0 && (s[len-1] == \'\\n\' || s[len-1] == \'\\r\')) {\n        s[--len] = \'\\0\';\n    }\n\n    int *stack = (int *)malloc(sizeof(int) * (len + 1));\n    int top = 0;\n    int num = 0;\n    char op = \'+\';\n\n    for (int i = 0; i < len; i++) {\n        char c = s[i];\n        if (isdigit((unsigned char)c)) {\n            num = num * 10 + (c - \'0\');\n        }\n        if ((!isdigit((unsigned char)c) && c != \' \') || i == len - 1) {\n            if (op == \'+\') {\n                stack[top++] = num;\n            } else if (op == \'-\') {\n                stack[top++] = -num;\n            } else if (op == \'*\') {\n                stack[top - 1] *= num;\n            } else if (op == \'/\') {\n                stack[top - 1] /= num;\n            }\n            op = c;\n            num = 0;\n        }\n    }\n\n    int res = 0;\n    for (int i = 0; i < top; i++) {\n        res += stack[i];\n    }\n    printf(\"%d\\n\", res);\n\n    free(stack);\n    return 0;\n}', NULL, 1),
(372, 'CPP', '#include <iostream>\n#include <string>\n#include <stack>\nusing namespace std;\n\nint main() {\n    string s;\n    getline(cin, s);\n    stack<int> st;\n    int num = 0;\n    char op = \'+\';\n    for (int i = 0; i < (int)s.length(); i++) {\n        char c = s[i];\n        if (isdigit(c)) {\n            num = num * 10 + (c - \'0\');\n        }\n        if ((!isdigit(c) && c != \' \') || i == (int)s.length() - 1) {\n            if (op == \'+\') {\n                st.push(num);\n            } else if (op == \'-\') {\n                st.push(-num);\n            } else if (op == \'*\') {\n                int top = st.top();\n                st.pop();\n                st.push(top * num);\n            } else if (op == \'/\') {\n                int top = st.top();\n                st.pop();\n                st.push(top / num);\n            }\n            op = c;\n            num = 0;\n        }\n    }\n    int res = 0;\n    while (!st.empty()) {\n        res += st.top();\n        st.pop();\n    }\n    cout << res << endl;\n    return 0;\n}', NULL, 1),
(372, 'JAVA', 'import java.util.*;\n\npublic class Main {\n    public static void main(String[] args) {\n        Scanner sc = new Scanner(System.in);\n        String s = sc.nextLine();\n        Deque<Integer> stack = new ArrayDeque<>();\n        int num = 0;\n        char op = \'+\';\n        for (int i = 0; i < s.length(); i++) {\n            char c = s.charAt(i);\n            if (Character.isDigit(c)) {\n                num = num * 10 + (c - \'0\');\n            }\n            if ((!Character.isDigit(c) && c != \' \') || i == s.length() - 1) {\n                if (op == \'+\') {\n                    stack.push(num);\n                } else if (op == \'-\') {\n                    stack.push(-num);\n                } else if (op == \'*\') {\n                    stack.push(stack.pop() * num);\n                } else if (op == \'/\') {\n                    stack.push(stack.pop() / num);\n                }\n                op = c;\n                num = 0;\n            }\n        }\n        int res = 0;\n        while (!stack.isEmpty()) {\n            res += stack.pop();\n        }\n        System.out.println(res);\n    }\n}', NULL, 1),
(372, 'JAVASCRIPT', 'const readline = require(\'readline\');\n\nconst rl = readline.createInterface({\n    input: process.stdin,\n    output: process.stdout\n});\n\nrl.on(\'line\', (s) => {\n    const stack = [];\n    let num = 0;\n    let op = \'+\';\n    for (let i = 0; i < s.length; i++) {\n        const c = s[i];\n        if (c >= \'0\' && c <= \'9\') {\n            num = num * 10 + (c.charCodeAt(0) - \'0\'.charCodeAt(0));\n        }\n        if ((!(c >= \'0\' && c <= \'9\') && c !== \' \') || i === s.length - 1) {\n            if (op === \'+\') {\n                stack.push(num);\n            } else if (op === \'-\') {\n                stack.push(-num);\n            } else if (op === \'*\') {\n                stack.push(stack.pop() * num);\n            } else if (op === \'/\') {\n                stack.push(Math.trunc(stack.pop() / num));\n            }\n            op = c;\n            num = 0;\n        }\n    }\n    let res = 0;\n    while (stack.length > 0) {\n        res += stack.pop();\n    }\n    console.log(res);\n    rl.close();\n});', NULL, 1),
(372, 'PYTHON', 's = input()\nstack = []\nnum = 0\nop = \'+\'\nfor i, c in enumerate(s):\n    if c.isdigit():\n        num = num * 10 + int(c)\n    if (not c.isdigit() and c != \' \') or i == len(s) - 1:\n        if op == \'+\':\n            stack.append(num)\n        elif op == \'-\':\n            stack.append(-num)\n        elif op == \'*\':\n            stack.append(stack.pop() * num)\n        elif op == \'/\':\n            stack.append(int(stack.pop() / num))\n        op = c\n        num = 0\nprint(sum(stack))', NULL, 1),
(373, 'C', '#include <stdio.h>\n#include <stdlib.h>\n\nlong long countInversions(int arr[], int left, int right);\nlong long mergeAndCount(int arr[], int left, int mid, int right);\n\nint main(void) {\n    int n;\n    if (scanf(\"%d\", &n) != 1) return 0;\n    int *arr = (int *)malloc(sizeof(int) * n);\n    for (int i = 0; i < n; i++) {\n        scanf(\"%d\", &arr[i]);\n    }\n    printf(\"%lld\\n\", countInversions(arr, 0, n - 1));\n    free(arr);\n    return 0;\n}\n\nlong long countInversions(int arr[], int left, int right) {\n    if (left >= right) return 0;\n    int mid = left + (right - left) / 2;\n    long long count = 0;\n    count += countInversions(arr, left, mid);\n    count += countInversions(arr, mid + 1, right);\n    count += mergeAndCount(arr, left, mid, right);\n    return count;\n}\n\nlong long mergeAndCount(int arr[], int left, int mid, int right) {\n    int *temp = (int *)malloc(sizeof(int) * (right - left + 1));\n    int i = left, j = mid + 1, k = 0;\n    long long count = 0;\n    while (i <= mid && j <= right) {\n        if (arr[i] <= arr[j]) {\n            temp[k++] = arr[i++];\n        } else {\n            temp[k++] = arr[j++];\n            count += mid - i + 1;\n        }\n    }\n    while (i <= mid) temp[k++] = arr[i++];\n    while (j <= right) temp[k++] = arr[j++];\n    for (int t = 0; t < k; t++) {\n        arr[left + t] = temp[t];\n    }\n    free(temp);\n    return count;\n}', NULL, 1),
(373, 'CPP', '#include <iostream>\n#include <vector>\nusing namespace std;\n\nlong long mergeAndCount(vector<int>& arr, int left, int mid, int right) {\n    vector<int> temp(right - left + 1);\n    int i = left, j = mid + 1, k = 0;\n    long long count = 0;\n    while (i <= mid && j <= right) {\n        if (arr[i] <= arr[j]) {\n            temp[k++] = arr[i++];\n        } else {\n            temp[k++] = arr[j++];\n            count += mid - i + 1;\n        }\n    }\n    while (i <= mid) temp[k++] = arr[i++];\n    while (j <= right) temp[k++] = arr[j++];\n    for (int p = 0; p < temp.size(); ++p) {\n        arr[left + p] = temp[p];\n    }\n    return count;\n}\n\nlong long countInversions(vector<int>& arr, int left, int right) {\n    if (left >= right) return 0;\n    int mid = left + (right - left) / 2;\n    long long count = 0;\n    count += countInversions(arr, left, mid);\n    count += countInversions(arr, mid + 1, right);\n    count += mergeAndCount(arr, left, mid, right);\n    return count;\n}\n\nint main() {\n    int n;\n    if (!(cin >> n)) return 0;\n    vector<int> arr(n);\n    for (int i = 0; i < n; ++i) {\n        cin >> arr[i];\n    }\n    cout << countInversions(arr, 0, n - 1) << endl;\n    return 0;\n}', NULL, 1),
(373, 'JAVA', 'import java.io.BufferedReader;\nimport java.io.IOException;\nimport java.io.InputStreamReader;\nimport java.util.StringTokenizer;\n\npublic class Main {\n    public static void main(String[] args) throws IOException {\n        BufferedReader br = new BufferedReader(new InputStreamReader(System.in));\n        String line = br.readLine();\n        if (line == null) return;\n        int n = Integer.parseInt(line.trim());\n        int[] arr = new int[n];\n        StringTokenizer st = new StringTokenizer(br.readLine());\n        for (int i = 0; i < n; i++) {\n            arr[i] = Integer.parseInt(st.nextToken());\n        }\n        System.out.println(countInversions(arr, 0, n - 1));\n    }\n\n    private static long countInversions(int[] arr, int left, int right) {\n        if (left >= right) return 0;\n        int mid = left + (right - left) / 2;\n        long count = 0;\n        count += countInversions(arr, left, mid);\n        count += countInversions(arr, mid + 1, right);\n        count += mergeAndCount(arr, left, mid, right);\n        return count;\n    }\n\n    private static long mergeAndCount(int[] arr, int left, int mid, int right) {\n        int[] temp = new int[right - left + 1];\n        int i = left, j = mid + 1, k = 0;\n        long count = 0;\n        while (i <= mid && j <= right) {\n            if (arr[i] <= arr[j]) {\n                temp[k++] = arr[i++];\n            } else {\n                temp[k++] = arr[j++];\n                count += mid - i + 1;\n            }\n        }\n        while (i <= mid) temp[k++] = arr[i++];\n        while (j <= right) temp[k++] = arr[j++];\n        System.arraycopy(temp, 0, arr, left, temp.length);\n        return count;\n    }\n}', NULL, 1),
(373, 'JAVASCRIPT', 'const readline = require(\'readline\');\n\nconst rl = readline.createInterface({\n    input: process.stdin,\n    output: process.stdout\n});\n\nlet lines = [];\nrl.on(\'line\', (line) => {\n    lines.push(line);\n    if (lines.length === 2) {\n        rl.close();\n    }\n});\n\nrl.on(\'close\', () => {\n    const n = parseInt(lines[0].trim());\n    const arr = lines[1].trim().split(/\\s+/).map(Number);\n    console.log(countInversions(arr, 0, n - 1));\n});\n\nfunction countInversions(arr, left, right) {\n    if (left >= right) return 0;\n    const mid = left + Math.floor((right - left) / 2);\n    let count = 0;\n    count += countInversions(arr, left, mid);\n    count += countInversions(arr, mid + 1, right);\n    count += mergeAndCount(arr, left, mid, right);\n    return count;\n}\n\nfunction mergeAndCount(arr, left, mid, right) {\n    const temp = new Array(right - left + 1);\n    let i = left, j = mid + 1, k = 0;\n    let count = 0;\n    while (i <= mid && j <= right) {\n        if (arr[i] <= arr[j]) {\n            temp[k++] = arr[i++];\n        } else {\n            temp[k++] = arr[j++];\n            count += mid - i + 1;\n        }\n    }\n    while (i <= mid) temp[k++] = arr[i++];\n    while (j <= right) temp[k++] = arr[j++];\n    for (let p = 0; p < temp.length; p++) {\n        arr[left + p] = temp[p];\n    }\n    return count;\n}', NULL, 1),
(373, 'PYTHON', 'import sys\n\ndef count_inversions(arr, left, right):\n    if left >= right:\n        return 0\n    mid = left + (right - left) // 2\n    count = 0\n    count += count_inversions(arr, left, mid)\n    count += count_inversions(arr, mid + 1, right)\n    count += merge_and_count(arr, left, mid, right)\n    return count\n\ndef merge_and_count(arr, left, mid, right):\n    temp = [0] * (right - left + 1)\n    i, j, k = left, mid + 1, 0\n    count = 0\n    while i <= mid and j <= right:\n        if arr[i] <= arr[j]:\n            temp[k] = arr[i]\n            i += 1\n        else:\n            temp[k] = arr[j]\n            j += 1\n            count += mid - i + 1\n        k += 1\n    while i <= mid:\n        temp[k] = arr[i]\n        i += 1\n        k += 1\n    while j <= right:\n        temp[k] = arr[j]\n        j += 1\n        k += 1\n    arr[left:right + 1] = temp\n    return count\n\ndef main():\n    data = sys.stdin.read().strip().split()\n    if not data:\n        return\n    n = int(data[0])\n    arr = list(map(int, data[1:1 + n]))\n    print(count_inversions(arr, 0, n - 1))\n\nif __name__ == \"__main__\":\n    main()', NULL, 1),
(374, 'C', '#include <stdio.h>\n#include <stdlib.h>\n\nint cmp(const void *a, const void *b) {\n    return (*(int *)a - *(int *)b);\n}\n\nint main() {\n    int n, k;\n    scanf(\"%d %d\", &n, &k);\n    int *arr = (int *)malloc(n * sizeof(int));\n    for (int i = 0; i < n; i++) {\n        scanf(\"%d\", &arr[i]);\n    }\n    qsort(arr, n, sizeof(int), cmp);\n    for (int i = 0; i < k; i++) {\n        if (i > 0) printf(\" \");\n        printf(\"%d\", arr[i]);\n    }\n    printf(\"\\n\");\n    free(arr);\n    return 0;\n}', NULL, 1),
(374, 'CPP', '#include <iostream>\n#include <vector>\n#include <algorithm>\nusing namespace std;\n\nint main() {\n    int n, k;\n    cin >> n >> k;\n    vector<int> arr(n);\n    for (int i = 0; i < n; i++) {\n        cin >> arr[i];\n    }\n    sort(arr.begin(), arr.end());\n    for (int i = 0; i < k; i++) {\n        if (i > 0) cout << \' \';\n        cout << arr[i];\n    }\n    cout << endl;\n    return 0;\n}', NULL, 1),
(374, 'JAVA', 'import java.util.*;\nimport java.io.*;\n\npublic class Main {\n    public static void main(String[] args) throws IOException {\n        BufferedReader br = new BufferedReader(new InputStreamReader(System.in));\n        String[] first = br.readLine().trim().split(\"\\\\s+\");\n        int n = Integer.parseInt(first[0]);\n        int k = Integer.parseInt(first[1]);\n        int[] arr = new int[n];\n        String[] second = br.readLine().trim().split(\"\\\\s+\");\n        for (int i = 0; i < n; i++) {\n            arr[i] = Integer.parseInt(second[i]);\n        }\n        Arrays.sort(arr);\n        StringBuilder sb = new StringBuilder();\n        for (int i = 0; i < k; i++) {\n            if (i > 0) sb.append(\' \');\n            sb.append(arr[i]);\n        }\n        System.out.println(sb.toString());\n    }\n}', NULL, 1),
(374, 'JAVASCRIPT', 'const readline = require(\'readline\');\n\nconst rl = readline.createInterface({\n    input: process.stdin,\n    output: process.stdout\n});\n\nlet lines = [];\nrl.on(\'line\', (line) => {\n    lines.push(line.trim());\n    if (lines.length === 2) {\n        const [n, k] = lines[0].split(/\\s+/).map(Number);\n        const arr = lines[1].split(/\\s+/).map(Number);\n        arr.sort((a, b) => a - b);\n        const result = arr.slice(0, k).join(\' \');\n        console.log(result);\n        rl.close();\n    }\n});', NULL, 1),
(374, 'PYTHON', 'import sys\n\ndef main():\n    data = sys.stdin.read().strip().split()\n    if not data:\n        return\n    n = int(data[0])\n    k = int(data[1])\n    arr = list(map(int, data[2:2 + n]))\n    arr.sort()\n    print(\' \'.join(map(str, arr[:k])))\n\nif __name__ == \"__main__\":\n    main()', NULL, 1),
(375, 'C', '#include <stdio.h>\n#include <stdlib.h>\n\nint dfs(int **grid, int m, int n, int i, int j) {\n    if (i < 0 || i >= m || j < 0 || j >= n || grid[i][j] == 0) {\n        return 0;\n    }\n    grid[i][j] = 0;\n    int area = 1;\n    area += dfs(grid, m, n, i + 1, j);\n    area += dfs(grid, m, n, i - 1, j);\n    area += dfs(grid, m, n, i, j + 1);\n    area += dfs(grid, m, n, i, j - 1);\n    return area;\n}\n\nint main(void) {\n    int m, n;\n    scanf(\"%d %d\", &m, &n);\n\n    int **grid = (int **)malloc(m * sizeof(int *));\n    for (int i = 0; i < m; i++) {\n        grid[i] = (int *)malloc(n * sizeof(int));\n    }\n\n    char *line = (char *)malloc((n + 2) * sizeof(char));\n    for (int i = 0; i < m; i++) {\n        scanf(\"%s\", line);\n        for (int j = 0; j < n; j++) {\n            grid[i][j] = line[j] - \'0\';\n        }\n    }\n\n    int maxArea = 0;\n    for (int i = 0; i < m; i++) {\n        for (int j = 0; j < n; j++) {\n            if (grid[i][j] == 1) {\n                int area = dfs(grid, m, n, i, j);\n                if (area > maxArea) {\n                    maxArea = area;\n                }\n            }\n        }\n    }\n\n    printf(\"%d\\n\", maxArea);\n\n    for (int i = 0; i < m; i++) {\n        free(grid[i]);\n    }\n    free(grid);\n    free(line);\n\n    return 0;\n}', NULL, 1),
(375, 'CPP', '#include <iostream>\n#include <vector>\n#include <string>\n#include <algorithm>\n\nusing namespace std;\n\nint dfs(vector<vector<int>>& grid, int i, int j) {\n    int m = grid.size();\n    int n = grid[0].size();\n    if (i < 0 || i >= m || j < 0 || j >= n || grid[i][j] == 0) {\n        return 0;\n    }\n    grid[i][j] = 0;\n    int area = 1;\n    area += dfs(grid, i + 1, j);\n    area += dfs(grid, i - 1, j);\n    area += dfs(grid, i, j + 1);\n    area += dfs(grid, i, j - 1);\n    return area;\n}\n\nint main() {\n    int m, n;\n    cin >> m >> n;\n    cin.ignore();\n    vector<vector<int>> grid(m, vector<int>(n));\n    for (int i = 0; i < m; i++) {\n        string line;\n        getline(cin, line);\n        while (!line.empty() && (line.back() == \'\\r\' || line.back() == \'\\n\')) {\n            line.pop_back();\n        }\n        for (int j = 0; j < n; j++) {\n            grid[i][j] = line[j] - \'0\';\n        }\n    }\n\n    int maxArea = 0;\n    for (int i = 0; i < m; i++) {\n        for (int j = 0; j < n; j++) {\n            if (grid[i][j] == 1) {\n                maxArea = max(maxArea, dfs(grid, i, j));\n            }\n        }\n    }\n\n    cout << maxArea << endl;\n    return 0;\n}', NULL, 1),
(375, 'JAVA', 'import java.util.*;\n\npublic class Main {\n    public static void main(String[] args) {\n        Scanner sc = new Scanner(System.in);\n        int m = sc.nextInt();\n        int n = sc.nextInt();\n        sc.nextLine();\n        int[][] grid = new int[m][n];\n        for (int i = 0; i < m; i++) {\n            String line = sc.nextLine().trim();\n            for (int j = 0; j < n; j++) {\n                grid[i][j] = line.charAt(j) - \'0\';\n            }\n        }\n\n        int maxArea = 0;\n        for (int i = 0; i < m; i++) {\n            for (int j = 0; j < n; j++) {\n                if (grid[i][j] == 1) {\n                    maxArea = Math.max(maxArea, dfs(grid, i, j));\n                }\n            }\n        }\n\n        System.out.println(maxArea);\n    }\n\n    private static int dfs(int[][] grid, int i, int j) {\n        int m = grid.length;\n        int n = grid[0].length;\n        if (i < 0 || i >= m || j < 0 || j >= n || grid[i][j] == 0) {\n            return 0;\n        }\n        grid[i][j] = 0;\n        int area = 1;\n        area += dfs(grid, i + 1, j);\n        area += dfs(grid, i - 1, j);\n        area += dfs(grid, i, j + 1);\n        area += dfs(grid, i, j - 1);\n        return area;\n    }\n}', NULL, 1),
(375, 'JAVASCRIPT', 'const readline = require(\'readline\');\n\nconst rl = readline.createInterface({\n    input: process.stdin,\n    output: process.stdout\n});\n\nlet lines = [];\nrl.on(\'line\', (line) => {\n    lines.push(line);\n});\n\nrl.on(\'close\', () => {\n    const [m, n] = lines[0].trim().split(/\\s+/).map(Number);\n    const grid = [];\n    for (let i = 0; i < m; i++) {\n        const row = [];\n        const line = lines[i + 1].trim();\n        for (let j = 0; j < n; j++) {\n            row.push(line.charCodeAt(j) - 48);\n        }\n        grid.push(row);\n    }\n\n    let maxArea = 0;\n    for (let i = 0; i < m; i++) {\n        for (let j = 0; j < n; j++) {\n            if (grid[i][j] === 1) {\n                maxArea = Math.max(maxArea, dfs(grid, i, j));\n            }\n        }\n    }\n\n    console.log(maxArea);\n});\n\nfunction dfs(grid, i, j) {\n    const m = grid.length;\n    const n = grid[0].length;\n    if (i < 0 || i >= m || j < 0 || j >= n || grid[i][j] === 0) {\n        return 0;\n    }\n    grid[i][j] = 0;\n    let area = 1;\n    area += dfs(grid, i + 1, j);\n    area += dfs(grid, i - 1, j);\n    area += dfs(grid, i, j + 1);\n    area += dfs(grid, i, j - 1);\n    return area;\n}', NULL, 1),
(375, 'PYTHON', 'import sys\n\ndef main():\n    data = sys.stdin.read().strip().split()\n    if not data:\n        return\n    m = int(data[0])\n    n = int(data[1])\n    grid = []\n    idx = 2\n    for i in range(m):\n        line = data[idx]\n        idx += 1\n        grid.append([int(c) for c in line])\n\n    def dfs(i, j):\n        if i < 0 or i >= m or j < 0 or j >= n or grid[i][j] == 0:\n            return 0\n        grid[i][j] = 0\n        area = 1\n        area += dfs(i + 1, j)\n        area += dfs(i - 1, j)\n        area += dfs(i, j + 1)\n        area += dfs(i, j - 1)\n        return area\n\n    max_area = 0\n    for i in range(m):\n        for j in range(n):\n            if grid[i][j] == 1:\n                max_area = max(max_area, dfs(i, j))\n\n    print(max_area)\n\nif __name__ == \"__main__\":\n    main()', NULL, 1)
