-- ⚠️ 注意：题目编号已整体改为从 1 开始（原 206~375 → 现 1~170）。
--    本文件是按【旧编号】写的，直接执行会串到别的题上。
--    请改用 12-problem-bank.sql（与当前库一致）。

-- =============================================
-- 题目-已验证参考答案（多语言）
-- =============================================
-- 说明：
--   1. 每道代码题都配了 Java / C++ / C / Python / JavaScript 五份答案，
--      每一份都提交判题机跑过，全部 ACCEPTED（共 600 份，独立复核 600/600 通过）。
--   2. 八股文概念题用 language='TEXT' 存讲解、SQL 题用 language='SQL' 存语句，
--      这两类不是可运行代码，算法哥只会把它们讲出来、不会往编辑器里写。
--   3. 算法哥代写代码时直接取这张表，不再让大模型现编，从根上杜绝写错。
--   4. 可重复执行。
-- =============================================

CREATE TABLE IF NOT EXISTS `problem_solution` (
  `id` BIGINT NOT NULL AUTO_INCREMENT COMMENT '主键',
  `problem_id` BIGINT NOT NULL COMMENT '题目ID',
  `language` VARCHAR(20) NOT NULL COMMENT '语言：JAVA/CPP/C/PYTHON/JAVASCRIPT/SQL/TEXT',
  `code` MEDIUMTEXT COMMENT '已验证的完整代码（或讲解 / SQL）',
  `note` VARCHAR(255) DEFAULT NULL COMMENT '算法哥写之前的一句话',
  `verified` TINYINT NOT NULL DEFAULT 0 COMMENT '是否已提交验证通过',
  `create_time` DATETIME NOT NULL DEFAULT CURRENT_TIMESTAMP,
  `update_time` DATETIME NOT NULL DEFAULT CURRENT_TIMESTAMP ON UPDATE CURRENT_TIMESTAMP,
  PRIMARY KEY (`id`),
  UNIQUE KEY `uk_problem_lang` (`problem_id`, `language`)
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci COMMENT='题目-已验证参考答案（多语言）';

ON DUPLICATE KEY UPDATE `code`=VALUES(`code`), `note`=VALUES(`note`), `verified`=VALUES(`verified`);
